// --- router ---------------------------------------------------------------
//
// This is the real fetch handler, but it isn't the exported one -- see the
// export default { fetch(...) {...} } wrapper at the very end of
// 26_api-creator-and-admin-routes.js (this function's body actually spans
// both files; build.ps1 just concatenates them back into one). The wrapper
// exists purely to run every response back through withSecurityHeaders
// (02_http-and-creator-utils.js) on the way out, without needing to touch
// any of the dozens of individual `new Response(...)` call sites below.
// /api/poster-badge only ever receives a `poster` value this add-on put
// there itself (see applyBadgedPostersToMetas, 05_catalog-core.js) --
// every source fetcher resolves posters to one of these three image hosts
// (TMDB, the Cinemeta/metahub IMDb-poster fallback, or Simkl's own
// artwork host); nothing in this codebase ever lets a user supply a raw
// poster URL. A request that names any other host, or a non-https scheme,
// isn't a real poster -- it's someone probing the endpoint directly, and
// gets rejected before either the redirect or the fetch further down.
const POSTER_IMAGE_HOSTS = new Set([
  "image.tmdb.org",
  "images.metahub.space",
  "simkl.in",
]);

function isAllowedPosterUrl(raw) {
  let u;
  try {
    u = new URL(String(raw || ""));
  } catch {
    return false;
  }
  if (u.protocol !== "https:") return false;
  return POSTER_IMAGE_HOSTS.has(u.hostname.toLowerCase());
}

async function handleFetch(request, env, ctx) {
    // Populate the env-backed API key globals declared in 00_constants.js
    // for this request. Every helper function elsewhere in this add-on
    // already references these five by name (TMDB_API_KEY, TRAKT_CLIENT_ID,
    // etc.) -- this is the one place, run first, that actually connects
    // them to whatever this Worker owner configured (or left unset, which
    // is fine: every feature gated on one of these degrades to a clear
    // in-app error message rather than a crash -- see each one's usage for
    // that message). `|| ""` guards against `env` not having the property
    // at all, same as a missing Worker secret/var normally reads as
    // undefined rather than an empty string.
    TMDB_API_KEY = (env && env.TMDB_API_KEY) || "";
    TRAKT_CLIENT_ID = (env && env.TRAKT_CLIENT_ID) || "";
    SIMKL_CLIENT_ID = (env && env.SIMKL_CLIENT_ID) || "";
    SIMKL_CLIENT_SECRET = (env && env.SIMKL_CLIENT_SECRET) || "";
    MDBLIST_API_KEY = (env && env.MDBLIST_API_KEY) || "";
    MDBLIST_POPULAR_KEY = (env && env.MDBLIST_POPULAR_KEY) || "";
    MDBLIST_CLIENT_ID = (env && env.MDBLIST_CLIENT_ID) || "";

    const url = new URL(request.url);
    const path = url.pathname;

    if (request.method === "OPTIONS") {
      if (isPublicCorsPath(path)) {
        return new Response(null, { headers: corsHeaders() });
      }
      return new Response(null, { status: 204 });
    }

    if (path === "/" || path === "") {
      ctx.waitUntil(bumpStat(env, "pageviews"));
      // Memoized per origin and answered with a 304 when the browser
      // already holds this exact build -- see htmlPageResponse and
      // renderBuilderCached (02_http-and-creator-utils.js). Previously this
      // rebuilt and resent ~1.6MB on every navigation, with no validator at
      // all, which also left the browser free to heuristically cache a copy
      // it had no way to check.
      return await htmlPageResponse(request, renderBuilderCached(url.origin, {}));
    }

    // add-on icon, served straight from this Worker
    if (path === "/icon.png") {
      const bin = atob(ICON_BASE64 );
      const bytes = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
      return new Response(bytes, {
        headers: {
          "Content-Type": "image/png",
          "Cache-Control": "public, max-age=86400",
          ...corsHeaders(),
        },
      });
    }

    // Poster-shaped placeholder shown in place of a real catalog when a
    // source fails and there's no stale last-known-good data to fall back
    // on (see the catalog route below). Generated on the fly rather than
    // stored as an asset -- it's just text on a flat background.
    if (path === "/unavailable-poster.svg") {
      const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="300" height="450" viewBox="0 0 300 450">
        <rect width="300" height="450" fill="#161a2e"/>
        <rect x="0.5" y="0.5" width="299" height="449" fill="none" stroke="#2a2f4a"/>
        <text x="150" y="205" text-anchor="middle" font-family="sans-serif" font-size="42" fill="#5865a8">\u26a0</text>
        <text x="150" y="250" text-anchor="middle" font-family="sans-serif" font-size="17" fill="#c7cde6">Temporarily</text>
        <text x="150" y="274" text-anchor="middle" font-family="sans-serif" font-size="17" fill="#c7cde6">unavailable</text>
      </svg>`;
      return new Response(svg, {
        headers: {
          "Content-Type": "image/svg+xml",
          "Cache-Control": "public, max-age=86400",
          ...corsHeaders(),
        },
      });
    }

    // /api/poster-badge -> Dynamic badged SVG poster for Stremio / Nuvio
    if (path === "/api/poster-badge") {
      const posterUrl = url.searchParams.get("poster") || "";
      const rawAirDate = url.searchParams.get("airDate") || "";
      const isAired = rawAirDate && typeof isEpisodeAired === "function" && isEpisodeAired(rawAirDate);
      const airDate = !isAired ? rawAirDate : "";
      const isPremiere = !isAired && url.searchParams.get("premiere") === "1";
      const isFinale = !isAired && url.searchParams.get("finale") === "1";
      const rawFinaleDate = url.searchParams.get("finaleDate") || "";
      const isFinaleAired = rawFinaleDate && typeof isEpisodeAired === "function" && isEpisodeAired(rawFinaleDate);
      const finaleDate = !isFinaleAired ? rawFinaleDate : "";

      if (!posterUrl || !isAllowedPosterUrl(posterUrl)) {
        // Missing entirely, or not one of the image hosts this add-on
        // itself ever puts in a `poster` field (see isAllowedPosterUrl).
        // This is a public, CORS-open, unauthenticated endpoint -- without
        // this check it was both an open redirect (Response.redirect
        // below, with no badge params) and an SSRF/open image proxy (the
        // fetch further down, with any badge param present): a caller
        // could point `poster=` at any http(s) URL and have this Worker
        // either send a visitor's browser there directly, or fetch it
        // server-side and echo the response back embedded in the SVG.
        return new Response(null, { status: 404 });
      }

      // If no badges are requested or all dates have aired, redirect straight to the original poster
      if (!airDate && !isPremiere && !isFinale && !finaleDate) {
        return Response.redirect(posterUrl, 302);
      }

      let embeddedPosterDataUri = "";
      try {
        const imgRes = await fetch(posterUrl, {
          headers: { "User-Agent": "my-list-addon/1.14" },
          cf: { cacheTtl: 86400, cacheEverything: true }
        });
        if (imgRes.ok) {
          const contentType = imgRes.headers.get("content-type") || "image/jpeg";
          const buffer = await imgRes.arrayBuffer();
          const bytes = new Uint8Array(buffer);
          let binary = "";
          const len = bytes.byteLength;
          for (let i = 0; i < len; i++) {
            binary += String.fromCharCode(bytes[i]);
          }
          const base64 = btoa(binary);
          embeddedPosterDataUri = `data:${contentType};base64,${base64}`;
        }
      } catch (e) {}

      if (!embeddedPosterDataUri) {
        // Fallback: If fetching/inlining image fails, redirect to original untouched poster
        return Response.redirect(posterUrl, 302);
      }

      // Format air date tag text (e.g. WED, SEP 16)
      let airDateText = "";
      if (airDate && typeof formatAirDateBadge === "function") {
        airDateText = formatAirDateBadge(airDate);
      } else if (airDate) {
        try {
          const d = new Date(airDate + "T00:00:00Z");
          const m = d.toLocaleDateString("en-US", { month: "short", timeZone: "UTC" }).toUpperCase();
          const day = d.getUTCDate();
          airDateText = `${m} ${day}`;
        } catch (e) {
          airDateText = airDate;
        }
      }

      // Format bottom badge text
      let bottomText = "";
      let bottomBg = "#30d158"; // Green for premiere
      let bottomBorder = "rgba(48, 209, 88, 0.4)";
      let bottomColor = "#ffffff";

      if (isPremiere) {
        bottomText = "Season Premiere";
        bottomBg = "#28a745";
        bottomBorder = "rgba(40, 167, 69, 0.6)";
        bottomColor = "#ffffff";
      } else if (isFinale) {
        bottomText = "Season Finale";
        bottomBg = "#ff9500";
        bottomBorder = "rgba(255, 149, 0, 0.7)";
        bottomColor = "#ffffff";
      } else if (finaleDate) {
        let fText = "";
        if (typeof formatAirDateBadge === "function") {
          fText = formatAirDateBadge(finaleDate);
        } else {
          try {
            const d = new Date(finaleDate + "T00:00:00Z");
            const m = d.toLocaleDateString("en-US", { month: "short", timeZone: "UTC" });
            const day = d.getUTCDate();
            fText = `${m} ${day}`;
          } catch (e) {
            fText = finaleDate;
          }
        }
        bottomText = fText ? `Finale: ${fText}` : "Season Finale";
        bottomBg = "rgba(18, 18, 24, 0.94)";
        bottomBorder = "rgba(255, 159, 10, 0.75)";
        bottomColor = "#ffd166";
      }

      const svg = generateBadgedPosterSvg({
        posterUrl: embeddedPosterDataUri,
        airDateText,
        bottomText,
        bottomBg,
        bottomBorder,
        bottomColor,
      });

      return new Response(svg, {
        headers: {
          "Content-Type": "image/svg+xml; charset=utf-8",
          "Cache-Control": "public, max-age=86400, s-maxage=604800, stale-while-revalidate=86400",
          ...corsHeaders(),
        },
      });
    }

    // /:config/configure  -> opened by wako itself when the user taps
    // "Configure" on the already-installed add-on
    let m = path.match(/^\/([^/]+)\/configure$/);
    if (m) {
      ctx.waitUntil(bumpStat(env, "pageviews"));
      const { entries, tmdbKey, mdblistKey, mdblistAccessToken, traktKey, traktUsername, traktAccessToken, shuffleShelves, shuffleItems, region, hideNonDigitalReleases } = await resolveConfig(m[1], env);
      // The one page that still sends no-store (it renders the person's own
      // API keys -- see the note on the headers below), but it should not
      // also be re-sending the 1.3MB client bundle every time. The split
      // separates the two concerns exactly: the small page that carries the
      // keys stays uncacheable, while the bundle it references is the same
      // shared, immutable /app.js everyone else already has.
      return new Response(
        await pageWithExternalBundle(renderBuilder(url.origin, {
          initialEntries: entries,
          initialKeys: { tmdbKey, mdblistKey, mdblistAccessToken, traktKey, traktUsername, traktAccessToken, shuffleShelves, shuffleItems, region, hideNonDigitalReleases },
          isConfigureMode: true,
        })),
        // The one builder page that deliberately keeps no-store rather than
        // moving to an ETag like the rest: this variant renders the user's
        // own API keys (TMDB/MDBList/Trakt) straight into the HTML, and
        // no-store is what keeps that out of the browser's on-disk cache
        // and out of any intermediary. Saving a round trip is not worth
        // writing somebody's keys to disk.
        { headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store" } }
      );
    }

    // bare /configure (no config yet) -> same builder, empty/default state
    if (path === "/configure") {
      ctx.waitUntil(bumpStat(env, "pageviews"));
      return await htmlPageResponse(
        request,
        renderBuilderCached(url.origin, { isConfigureMode: true })
      );
    }

    // /lists/<slug>  (single segment, no second "/") -> a clean, shareable
    // url for one of the native/official charts (see CHART_SLUG_ENTRIES,
    // 08_quickadd-chart-data.js) -- resolves the slug and serves the same
    // builder page, but with that chart pre-opened in the list-details view
    // (see SERVER_DEEP_LINK_LIST, 09_page-shell.js, and
    // handleInitialDeepLink, 24_client-backup-restore-presets.js). This is
    // distinct from /lists/:username/:listname below (always two segments,
    // a person's own published Custom List) -- an unrecognized slug here
    // just lands on the normal default builder page rather than a hard
    // /lists/public.json or /api/public-lists.json -> JSON directory of all published public lists
    if (path === "/lists/public.json" || path === "/api/public-lists.json") {
      if (!env || !env.CONFIGS) {
        return json({ ok: true, lists: [] }, 200, { "Cache-Control": "public, max-age=60", ...corsHeaders() });
      }
      // Preferred path: one KV read of the maintained index, no per-list
      // gets, no truncation at 150 keys. Falls back to the legacy bounded
      // scan below only while the index is being built for the first time.
      const indexEntries = await getPublicListIndex(env, ctx);
      if (indexEntries) {
        const limitParam = parseInt(url.searchParams.get("limit") || "", 10);
        const offset = Math.max(0, parseInt(url.searchParams.get("offset") || "0", 10) || 0);
        // Default page stays 100 to match the previous response size;
        // callers can page through the rest instead of silently losing it.
        const pageSize = Math.min(Math.max(limitParam || 100, 1), 500);
        const page = indexEntries.slice(offset, offset + pageSize);
        const lists = page.map((e) => {
          const cleanSlug = e.slug || slugifyServer(e.name) || "list";
          const username = e.isCreator ? e.username : "user";
          return {
            name: e.name,
            slug: cleanSlug,
            creator: e.isCreator ? e.username : "Anonymous",
            type: e.type || "mixed",
            itemCount: e.itemCount || 0,
            likes: e.likes || 0,
            updatedAt: e.updatedAt || null,
            url: `${url.origin}/lists/${username}/${cleanSlug}`,
            jsonUrl: `${url.origin}/lists/${username}/${cleanSlug}.json`,
          };
        });
        return json(
          { ok: true, count: lists.length, total: indexEntries.length, offset, lists },
          200,
          { "Cache-Control": "public, max-age=120", ...corsHeaders() }
        );
      }

      const fetchLimit = 150;
      const [pubRes, creatorRes] = await Promise.all([
        env.CONFIGS.list({ prefix: "publishedlist:user:", limit: fetchLimit }),
        env.CONFIGS.list({ prefix: "creatorlist:", limit: fetchLimit }),
      ]);
      const listKeys = [];
      (pubRes.keys || []).forEach(k => listKeys.push({ key: k.name, isCreator: false }));
      (creatorRes.keys || []).forEach(k => {
        const rest = k.name.slice("creatorlist:".length);
        if (rest.includes(":")) listKeys.push({ key: k.name, isCreator: true });
      });

      const listPromises = listKeys.slice(0, 100).map(async ({ key, isCreator }) => {
        const raw = await env.CONFIGS.get(key);
        if (!raw) return null;
        try {
          const l = JSON.parse(raw);
          await stampListVisibilityIfNeeded(env, key, l);
          if (!isPublicListVisibility(l.visibility)) return null;
          let username = "Anonymous";
          let slug = l.slug || "";
          if (isCreator) {
            const parts = key.slice("creatorlist:".length).split(":");
            username = parts[0] || "creator";
            slug = parts[1] || slug;
          } else {
            slug = key.slice("publishedlist:user:".length);
          }
          const cleanSlug = slug || slugifyServer(l.name) || "list";
          return {
            name: l.name,
            slug: cleanSlug,
            creator: username,
            type: l.type || "mixed",
            itemCount: Array.isArray(l.items) ? l.items.length : (l.itemCount || 0),
            likes: l.likes || 0,
            updatedAt: l.updatedAt || l.createdAt || null,
            url: `${url.origin}/lists/${username}/${cleanSlug}`,
            jsonUrl: `${url.origin}/lists/${username}/${cleanSlug}.json`,
          };
        } catch {
          return null;
        }
      });

      const lists = (await Promise.all(listPromises)).filter(Boolean);
      return json({ ok: true, count: lists.length, lists }, 200, {
        "Cache-Control": "public, max-age=120",
        ...corsHeaders(),
      });
    }

    m = path.match(/^\/lists\/curated\/([A-Za-z0-9-]+)$/);
    if (m) {
      ctx.waitUntil(bumpStat(env, "pageviews"));
      const slug = m[1];
      const title = isShow ? "Recommended Shows" : "Recommended Movies";
      return await htmlPageResponse(
        request,
        renderBuilder(url.origin, { deepLinkList: { name: title, type: isShow ? "series" : "movie", url: "custom:curated:" + slug } })
      );
    }

    m = path.match(/^\/lists\/([A-Za-z0-9-]+)$/);
    if (m) {
      ctx.waitUntil(bumpStat(env, "pageviews"));
      let chart = resolveChartSlug(m[1]);
      if (!chart) {
        const slugLower = m[1].toLowerCase();
        if (slugLower === "continue-watching" || slugLower === "continue_watching") chart = { name: "Continue Watching", movieUrl: "autotrack:continue-watching", showUrl: "autotrack:continue-watching", type: "series" };
        if (slugLower === "watch-history" || slugLower === "watch_history") chart = { name: "Watch History", movieUrl: "autotrack:watch-history", showUrl: "autotrack:watch-history", type: "movie" };
        if (slugLower === "watchlist") chart = { name: "Watchlist", movieUrl: "autotrack:watchlist", showUrl: "autotrack:watchlist", type: "mixed" };
        if (slugLower === "new-movies") chart = { name: "New Releases", movieUrl: "tmdb:chart:new_movies", showUrl: "tmdb:chart:new_movies", type: "movie" };
        if (slugLower === "new-shows") chart = { name: "New Releases", movieUrl: "tmdb:chart:new_shows", showUrl: "tmdb:chart:new_shows", type: "series" };
      }
      return await htmlPageResponse(
        request,
        chart
          ? renderBuilder(url.origin, { deepLinkList: { name: chart.name, type: chart.type || ((chart.showUrl && chart.showUrl.includes('shows')) ? "series" : "movie"), url: chart.movieUrl } })
          : renderBuilderCached(url.origin, {})
      );
    }

    // Catch-all for browser navigation on provider/custom list paths (e.g. /lists/mdblist/..., /lists/trakt/..., /lists/tmdb/..., /lists/simkl/..., /lists/custom/...)
    // Note: Creator/user public lists (/lists/:user/:slug) and .json endpoints pass through to creator routes.
    if (path.startsWith("/lists/") && !path.endsWith(".json") && (path.startsWith("/lists/mdblist/") || path.startsWith("/lists/trakt/") || path.startsWith("/lists/tmdb/") || path.startsWith("/lists/simkl/") || path.startsWith("/lists/custom/") || path.startsWith("/lists/curated/"))) {
      ctx.waitUntil(bumpStat(env, "pageviews"));
      return await htmlPageResponse(request, renderBuilderCached(url.origin, {}));
    }

    // Browser navigation for channels (/channels/:slug)
    if (path.startsWith("/channels/")) {
      ctx.waitUntil(bumpStat(env, "pageviews"));
      return await htmlPageResponse(request, renderBuilderCached(url.origin, {}));
    }

    // /:config/manifest.json
    m = path.match(/^\/([^/]+)\/manifest\.json$/);
    if (m) {
      // If this looks like a browser page-load (e.g. wako sent you here for
      // "Configure") rather than a JSON fetch by the app, send the user to
      // the actual editable configure page instead of showing raw JSON.
      if (isBrowserNavigation(request)) {
        return Response.redirect(`${url.origin}/${m[1]}/configure`, 302);
      }
      const { entries, track, shuffleShelves } = await resolveConfig(m[1], env);
      return jsonPublic(buildManifest(entries, url.origin, track, shuffleShelves, m[1]));
    }

    // bare manifest.json with no config
    if (path === "/manifest.json") {
      if (isBrowserNavigation(request)) {
        return Response.redirect(`${url.origin}/configure`, 302);
      }
      return jsonPublic(buildManifest([], url.origin));
    }

    // /:config/subtitles/:type/:id.json -- see buildManifest's comment
    // above on why wako/Stremio calls this even though the addon has no
    // real subtitles to offer. type is "movie" or "series"; id is a plain
    // "tt1234567" for a movie, or "tt1234567:5:10" (imdbId:season:episode)
    // for an episode -- Stremio's own id convention for TV, nothing
    // specific to this addon. The trailing (?:\/[^/]+)? tolerates the extra
    // videoHash=...&videoSize=...&filename=... path segment real Stremio
    // (as opposed to hand-built test requests) appends before .json when a
    // stream actually has that metadata -- without it, every genuine
    // Stremio playback ping 404'd here and never reached
    // handleSubtitlesTrack below, so Auto-track Playback looked broken
    // specifically on Stremio even though it worked fine against a bare
    // .../subtitles/movie/tt1234567.json test call.
    m = path.match(/^\/([^/]+)\/subtitles\/(movie|series)\/([^/]+?)(?:\/[^/]+)?\.json$/);
    if (m) {
      const [, configParam, stremioType, rawId] = m;
      // Answer immediately with an empty subtitle list regardless of what
      // happens below -- there's nothing to show wako/Stremio either way,
      // and the actual tracking write (a TMDB lookup plus a KV read/write)
      // shouldn't hold up how fast this responds. ctx.waitUntil lets it
      // keep running after the response is already on its way.
      ctx.waitUntil(handleSubtitlesTrack(configParam, stremioType, decodeURIComponent(rawId), env, request));
      return jsonPublic({ subtitles: [] });
    }

    if (path === "/app.webmanifest") {
      // background_color (the splash-screen fill while the PWA cold-starts)
      // and theme_color (the OS status bar / task-switcher chrome color for
      // an installed PWA) are both static -- the manifest spec has no dark
      // mode variant, unlike the page's own <meta name="theme-color">,
      // which 09_page-shell.js already flips between light/dark on load and
      // on toggleTheme(). So these match that page-level light default
      // (#F2F2F7) instead of the button accent blue (#007AFF) they were set
      // to before, which is what showed up as a flat blue bar at launch
      // regardless of theme -- a dark-theme user still gets the correct
      // dark chrome within a frame or two, once that in-page script runs.
      const manifest = {
        name: "My Lists",
        short_name: "My Lists",
        start_url: "/",
        display: "standalone",
        background_color: "#F2F2F7",
        theme_color: "#F2F2F7",
        icons: [
          { src: "/icon.png", sizes: "192x192", type: "image/png" },
          { src: "/icon.png", sizes: "512x512", type: "image/png" }
        ]
      };
      return new Response(JSON.stringify(manifest), {
        headers: { "Content-Type": "application/manifest+json; charset=utf-8" }
      });
    }

    if (path === "/robots.txt") {
      // Only the plain / install page is meant to be publicly
      // discoverable -- see seoHeadHtml's comment in 09_page-shell.js for
      // why /:config/configure pages (personal base64 config, and any
      // personal API keys the user pasted in, baked straight into the
      // URL) get an explicit noindex there too, on top of being
      // Disallow'd here. /admin is a password-protected dashboard with
      // no business being crawled at all, and everything under /api/ and
      // the manifest/catalog/subtitles endpoints are raw JSON data
      // routes, not content.
      const robots = `User-agent: *
Allow: /$
Disallow: /admin
Disallow: /api/
Disallow: /*/configure
Disallow: /*/manifest.json
Disallow: /*/catalog/
Disallow: /*/subtitles/

Sitemap: ${url.origin}/sitemap.xml`;
      return new Response(robots, {
        headers: { "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "public, max-age=86400" }
      });
    }

    if (path === "/sitemap.xml") {
      // The plain install page and /guide (see the route just below) are
      // the only two URLs on this whole deployment meant to be indexed
      // (see /robots.txt just above) -- everything else either needs a
      // personal config in its own URL to mean anything, or is a raw
      // JSON/API endpoint rather than a page.
      const sitemap = `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
  <url>
    <loc>${url.origin}/</loc>
    <changefreq>weekly</changefreq>
    <priority>1.0</priority>
  </url>
  <url>
    <loc>${url.origin}/guide</loc>
    <changefreq>monthly</changefreq>
    <priority>0.8</priority>
  </url>
</urlset>`;
      return new Response(sitemap, {
        headers: { "Content-Type": "application/xml; charset=utf-8", "Cache-Control": "public, max-age=86400" }
      });
    }

    // Standalone SEO/content page, not the interactive builder -- see
    // renderGuidePage's own comment (end of 24_client-backup-restore-
    // presets.js, right after renderBuilder closes) for why it's a
    // separate, lightweight template literal rather than reusing
    // renderBuilder's app stylesheet.
    if (path === "/guide") {
      return new Response(renderGuidePage(url.origin), {
        headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "public, max-age=3600" }
      });
    }

    // /app.js?v=<hash> -> the client bundle lifted out of the builder page.
    // See splitAppBundle (02_http-and-creator-utils.js) for what is in it
    // and why it can be shared. The URL is content-hashed, so it is safe to
    // tell the browser to keep it forever: a deploy that changes the bundle
    // changes the hash, which changes the src in the page, which changes the
    // page's own ETag -- so nobody can be left holding a stale one.
    // /app.css?v=<hash> -> the stylesheet lifted out of the builder page.
    // Same content-addressed, immutable contract as /app.js below.
    if (path === "/app.css") {
      const sheet = await getAppCss(url.origin);
      if (!sheet) {
        return new Response("/* app stylesheet unavailable */", {
          status: 503,
          headers: { "Content-Type": "text/css; charset=utf-8", "Cache-Control": "no-store" },
        });
      }
      const isCurrent = (url.searchParams.get("v") || "") === sheet.hash;
      const etag = `"${sheet.hash}"`;
      const inm = request.headers.get("If-None-Match") || "";
      const headers = {
        "Content-Type": "text/css; charset=utf-8",
        "Cache-Control": isCurrent ? "public, max-age=31536000, immutable" : "no-cache",
        "ETag": etag,
      };
      if (inm.split(",").some((s) => s.trim().replace(/^W\//, "") === etag)) {
        return new Response(null, { status: 304, headers });
      }
      return new Response(sheet.css, { headers });
    }

    if (path === "/app.js") {
      const bundle = await getAppBundle(url.origin);
      if (!bundle) {
        // Markers missing (should be impossible -- the verification suite
        // asserts they render). 503 rather than an empty 200, so a broken
        // deploy is loud instead of a silently dead page.
        return new Response("/* app bundle unavailable */", {
          status: 503,
          headers: { "Content-Type": "application/javascript; charset=utf-8", "Cache-Control": "no-store" },
        });
      }
      const askedFor = url.searchParams.get("v") || "";
      // Only the hash we are actually serving may be cached immutably. A
      // request for some older hash still gets a working bundle -- better
      // than a broken page -- but must not be allowed to pin today's bytes
      // under yesterday's URL forever.
      const isCurrent = askedFor === bundle.hash;
      const etag = `"${bundle.hash}"`;
      const inm = request.headers.get("If-None-Match") || "";
      const headers = {
        "Content-Type": "application/javascript; charset=utf-8",
        "Cache-Control": isCurrent ? "public, max-age=31536000, immutable" : "no-cache",
        "ETag": etag,
      };
      if (inm.split(",").some((s) => s.trim().replace(/^W\//, "") === etag)) {
        return new Response(null, { status: 304, headers });
      }
      return new Response(bundle.js, { headers });
    }

    if (path === "/sw.js") {
      // The previous version of this worker was a no-op that still cost
      // something: it intercepted every request, re-issued it, and on
      // failure fell back to caches.match() -- against a cache nothing ever
      // wrote to, so that fallback could never hit.
      //
      // It now does one useful thing and nothing else. /app.js?v=<hash> is
      // content-addressed, so cache-first is safe by construction: a bundle
      // that changes gets a different URL, and this cache is never consulted
      // for it. Exactly one entry is kept, so old bundles cannot accumulate
      // after repeated deploys. Every other request is passed straight
      // through, untouched.
      const sw = `
const APP_CACHE = 'mylists-app-v1';
self.addEventListener('install', e => e.waitUntil(self.skipWaiting()));
self.addEventListener('activate', e => e.waitUntil(self.clients.claim()));
self.addEventListener('fetch', e => {
  const url = new URL(e.request.url);
  const isBundle = e.request.method === 'GET'
    && url.origin === self.location.origin
    && url.pathname === '/app.js'
    && url.searchParams.get('v');
  if (!isBundle) return; // everything else: no interception at all
  e.respondWith((async () => {
    try {
      const cache = await caches.open(APP_CACHE);
      const hit = await cache.match(e.request.url);
      if (hit) return hit;
      const res = await fetch(e.request);
      if (res && res.ok) {
        // Keep one bundle only -- a new deploy means a new URL, and the
        // previous entry is dead weight the moment it stops being requested.
        for (const key of await cache.keys()) await cache.delete(key);
        await cache.put(e.request.url, res.clone());
      }
      return res;
    } catch (err) {
      return fetch(e.request);
    }
  })());
});
      `;
      return new Response(sw.trim(), {
        headers: { "Content-Type": "application/javascript; charset=utf-8", "Cache-Control": "no-cache" }
      });
    }

    // /:config/catalog/:type/:id.json  (optionally /:config/catalog/:type/:id/skip=N.json)
    m = path.match(/^\/([^/]+)\/catalog\/([^/]+)\/(.+)\.json$/);
    if (m) {
      const [, config, type, idWithExtra] = m;
      const [id, extraStr] = idWithExtra.split("/");
      const extra = Object.fromEntries(new URLSearchParams(extraStr || ""));
      const skip = parseInt(extra.skip, 10) || 0;

      const { entries, tmdbKey, mdblistKey, mdblistAccessToken, traktKey, traktAccessToken, simklKey, simklAccessToken, shuffleItems, trackCreatorName, region, hideNonDigitalReleases, showBadgesStremio, showBadgesStremioAiringNext, showBadgesStremioContinueWatching, showBadgesStremioCatalogs } = await resolveConfig(config, env);
      const entry = entries.find((e) => e.id === id && e.type === type);
      if (!entry || entry.enabled === false) return jsonPublic({ metas: [] });

      const source = detectSource(entry.url);
      const isAutoTrack = source === "autotrack";
      const isUserPersonal = isAutoTrack || source === "simkl-user" || source === "trakt-watchlist" || source === "trakt-history" || source === "mdblist-watchlist" || source === "mdblist-history";

      // Graceful degradation only applies to the first page (skip === 0):
      // that's the case that makes a whole shelf silently vanish from the
      // home screen, whereas a failure deeper into pagination (scrolling
      // for "load more") is far less disruptive to just show as empty, like
      // before. Only active when a CONFIGS KV namespace is bound (optional,
      // same as the short-link feature) -- without one this behaves exactly
      // as it did previously.
      const staleKey = env && env.CONFIGS && !isAutoTrack && !isUserPersonal ? `lastgood:${config}:${type}:${id}` : null;

      try {
        const metas = await fetchCatalog(entry, skip, { tmdbKey, mdblistKey, mdblistAccessToken, traktKey, traktAccessToken, simklKey, simklAccessToken, shuffleItems, configParam: config, trackCreatorName, region, hideNonDigitalReleases, isStremioCatalog: true, showBadgesStremio, showBadgesStremioAiringNext, showBadgesStremioContinueWatching, showBadgesStremioCatalogs, env, ctx, origin: url.origin });
        if (staleKey && skip === 0 && metas.length > 0) {
          // Fire-and-forget -- the response doesn't wait on this write.
          ctx.waitUntil(
            env.CONFIGS.put(staleKey, JSON.stringify(metas), { expirationTtl: 2592000 })
          );
        }
        if (isUserPersonal) {
          return jsonPublic({ metas }, 200, { "Cache-Control": "no-cache, no-store, must-revalidate, max-age=0" });
        }
        return jsonPublic({ metas }, 200, { "Cache-Control": "public, max-age=86400, s-maxage=86400" });
      } catch (err) {
        const errMsg = safeErrorMessage(err);
        if (isUserPersonal) {
          console.error("User personal catalog fetch error:", errMsg);
          return jsonPublic({ metas: [] }, 200, { "Cache-Control": "no-cache, no-store, must-revalidate, max-age=0" });
        }

        if (skip === 0 && staleKey) {
          try {
            const stale = await env.CONFIGS.get(staleKey);
            if (stale) {
              // Genuine last-known-good data -- real "tt" ids, renders
              // exactly like a normal successful load. `stale` is
              // informational only (visible when debugging via curl), not
              // read by wako/Stremio itself.
              return jsonPublic({ metas: JSON.parse(stale), stale: true, error: errMsg });
            }
          } catch {
            // KV read/parse failed -- fall through to the placeholder below.
          }
          // No last-known-good data to fall back on (this list has never
          // successfully loaded, or KV isn't bound) -- show one placeholder
          // tile so the row still appears instead of silently disappearing.
          // Uses a dummy "tt"-prefixed id since the manifest declares
          // idPrefixes: ["tt", ...] and some clients filter out anything else.
          return jsonPublic({
            metas: [
              {
                id: "tt0000000",
                type: entry.type,
                name: (entry.name || "This list") + " \u2014 temporarily unavailable",
                poster: `${url.origin}/unavailable-poster.svg`,
              },
            ],
            error: errMsg,
          });
        }

        // Metas stays empty so wako/Stremio just shows an empty row instead
        // of erroring out, but the reason is still visible if you curl this
        // URL directly while debugging.
        return jsonPublic({ metas: [], error: errMsg }, 200);
      }
    }

    // /api/track-install  (POST)  { groups?: { [groupName]: count } } -> { ok: true }
    // Fire-and-forget beacon the builder page calls right when "Generate
    // install link"/"Update" produces a link -- that action is otherwise
    // entirely client-side (it's just base64-encoding the current config
    // into a URL, no server round trip), so this is the one place a count
    // of "an install link was generated" can be recorded at all. No
    // identifying info sent or stored, just a counter bump for the
    // admin-only dashboard below. The optional groups breakdown feeds the
    // same dashboard's "sources people actually use" table -- see
    // bumpStatBy/sanitizeStatGroupName above.
    if (path === "/api/track-install" && request.method === "POST") {
      ctx.waitUntil(bumpStat(env, "installs"));
      try {
        const body = await request.json();
        if (body && body.groups && typeof body.groups === "object") {
          const entries = Object.entries(body.groups).slice(0, 30);
          for (const [rawGroup, rawCount] of entries) {
            const group = sanitizeStatGroupName(rawGroup);
            const count = Math.max(0, Math.min(1000, parseInt(rawCount, 10) || 0));
            if (group && count) ctx.waitUntil(bumpStatBy(env, `sourcegroup:${group}`, count));
          }
        }
      } catch {
        // no body, or not JSON -- the plain install counter above still
        // recorded either way, this part is just best-effort extra detail
      }
      return json({ ok: true });
    }

    // /api/preview -> GET with ?url=...&type=movie|series[&tmdbKey=...&mdblistKey=...&sample=N&skip=N],
    // or POST with the same fields as a JSON body. Used by the "Test"
    // button in the builder page to check a list (or the watchlist quick-
    // add), by Live Preview to render a row's actual shelf and its "See
    // All" infinite-scroll view, and by the search results' "View list"
    // button. Always uncached (unlike the shared json() helper's default
    // hour-long cache) since all of those should reflect the current live
    // state, not a stale result from before some earlier fix. sample
    // defaults to 5 (the original/Test-button size); Live Preview and View
    // List ask for more (100, a full catalog page) and page through with
    // skip for infinite scroll -- the same skip fetchCatalog already
    // supports for the real /:config/catalog/:type/:id/skip=N.json route
    // below, reused as-is.
    //
    // POST exists because a Channel's own url can be enormous (hundreds of
    // episodes' worth of embedded JSON) -- passed as a GET query string
    // that routinely exceeded URL length limits and failed outright before
    // ever reaching this handler, which is exactly what surfaced as "no
    // streams"-style network errors previewing a Channel. GET is kept for
    // callers with a normal-sized url (a plain mdblist/trakt/tmdb list
    // link is never going to hit that limit).
    if (path === "/api/preview") {
      let testUrl, type, tmdbKey, mdblistKey, mdblistAccessToken, traktKey, traktAccessToken, simklKey, simklAccessToken, sampleSize, skip, creatorName, hideNonDigitalReleases;
      if (request.method === "POST") {
        let reqBody;
        try {
          reqBody = await request.json();
        } catch {
          reqBody = {};
        }
        testUrl = reqBody.url || "";
        type = reqBody.type === "series" ? "series" : (reqBody.type === "movie" ? "movie" : "mixed");
        tmdbKey = reqBody.tmdbKey || "";
        mdblistKey = reqBody.mdblistKey || "";
        mdblistAccessToken = reqBody.mdblistAccessToken || "";
        traktKey = reqBody.traktKey || "";
        traktAccessToken = reqBody.traktAccessToken || "";
        simklKey = reqBody.simklKey || "";
        simklAccessToken = reqBody.simklAccessToken || "";
        creatorName = reqBody.creatorName || "";
        hideNonDigitalReleases = !!reqBody.hideNonDigitalReleases;
        sampleSize = Math.max(1, Math.min(PAGE_SIZE, parseInt(reqBody.sample, 10) || 5));
        skip = Math.max(0, parseInt(reqBody.skip, 10) || 0);
      } else {
        testUrl = url.searchParams.get("url") || "";
        const rawType = url.searchParams.get("type") || "";
        type = rawType === "series" ? "series" : (rawType === "movie" ? "movie" : "mixed");
        tmdbKey = url.searchParams.get("tmdbKey") || "";
        mdblistKey = url.searchParams.get("mdblistKey") || "";
        mdblistAccessToken = url.searchParams.get("mdblistAccessToken") || "";
        traktKey = url.searchParams.get("traktKey") || "";
        traktAccessToken = url.searchParams.get("traktAccessToken") || "";
        simklKey = url.searchParams.get("simklKey") || "";
        simklAccessToken = url.searchParams.get("simklAccessToken") || "";
        creatorName = url.searchParams.get("creatorName") || "";
        hideNonDigitalReleases = url.searchParams.get("hideNonDigitalReleases") === "1";
        sampleSize = Math.max(1, Math.min(PAGE_SIZE, parseInt(url.searchParams.get("sample"), 10) || 5));
        skip = Math.max(0, parseInt(url.searchParams.get("skip"), 10) || 0);
      }

      // Unauthenticated and heavyweight: each call can fan out to TMDB /
      // Trakt / MDBList. Same IP-keyed KV slot as create/restore/feedback
      // -- 80/minute is enough for Live Preview paging a shelf, not enough
      // to use this as a free outbound scanner.
      const ip = clientIpKey(request);
      if (!ip) return json({ ok: false, error: "Couldn't load that list." }, 400, { "Cache-Control": "no-store" });
      if (env && env.CONFIGS) {
        const rateKey = `ratelimit:preview:${ip}`;
        const n = parseInt((await env.CONFIGS.get(rateKey)) || "0", 10) || 0;
        if (n >= 80) {
          return json({ ok: false, error: "Couldn't load that list." }, 429, { "Cache-Control": "no-store" });
        }
        ctx.waitUntil(env.CONFIGS.put(rateKey, String(n + 1), { expirationTtl: 60 }));
      }

      const sourceUrls = previewSourceUrls(testUrl);
      if (!sourceUrls.length || !sourceUrls.every(isAllowedCatalogSourceUrl)) {
        return json({ ok: false, error: "That URL isn't a supported list source." }, 400, { "Cache-Control": "no-store" });
      }

      let body;
      try {
        const metas = await fetchCatalog({ url: testUrl, type }, skip, { tmdbKey, mdblistKey, mdblistAccessToken, traktKey, traktAccessToken, simklKey, simklAccessToken, creatorName, hideNonDigitalReleases, env, ctx, origin: url.origin });
        const totalItems = (typeof metas.totalItems === "number") ? metas.totalItems : (metas.length < PAGE_SIZE && skip === 0 ? metas.length : null);
        body = {
          ok: true,
          count: metas.length,
          totalItems: totalItems,
          maybeMore: totalItems != null ? (skip + metas.length < totalItems) : (metas.length >= PAGE_SIZE),
          sample: metas.slice(0, sampleSize).map((m) => ({
            id: m.id,
            type: m.type || (m.mediatype === "show" || m.mediatype === "series" || m.mediatype === "tv" ? "series" : (m.mediatype === "episode" ? "episode" : (type === "series" ? "series" : "movie"))),
            name: m.name,
            poster: m.poster,
            year: m.releaseInfo,
            showTitle: m.showTitle,
            posterShape: m.posterShape,
            season: m.season,
            episode: m.episode,
          })),
        };
      } catch (err) {
        console.error("preview failed:", err);
        body = { ok: false, error: "Couldn't load that list." };
      }

      return new Response(JSON.stringify(body), {
        headers: {
          "Content-Type": "application/json; charset=utf-8",
          "Cache-Control": "no-store",
          ...corsHeaders(),
        },
      });
    }

    // /api/channel-poster -> Returns branded SVG channel poster or landscape backdrop
    if (path === "/api/channel-poster") {
      const name = url.searchParams.get("name") || "TV Channel";
      const bg = url.searchParams.get("bg") || "";
      const format = url.searchParams.get("format") || "";
      const svg = format === "landscape"
        ? generateChannelBackdropSvg(name, bg)
        : generateChannelPosterSvg(name, bg);
      return new Response(svg, {
        headers: {
          "Content-Type": "image/svg+xml; charset=utf-8",
          "Cache-Control": "no-cache, no-store, must-revalidate",
          "Pragma": "no-cache",
          "Expires": "0",
          ...corsHeaders(),
        },
      });
    }

    // /api/scrobble (and subpaths /api/scrobble/webhook, /api/scrobble/plex, /api/scrobble/jellyfin, /api/scrobble/emby)
    // Automated scrobbling endpoint for media servers (Plex, Jellyfin, Emby)
    if (path.startsWith("/api/scrobble")) {
      if (request.method === "OPTIONS") {
        return new Response(null, { headers: corsHeaders() });
      }
      return handleMediaServerScrobble(request, url, env, ctx);
    }

    // /:config/meta/:type/:id.json (or /meta/:type/:id.json)
    // Resolves metadata for Channels (channel_*) and standard IMDb titles (tt*).
    // Provides full metadata (posters, backgrounds, overviews, ratings, cast, and
    // full episode lists) so clients without dedicated metadata addons (like Nuvio)
    // automatically render complete detail and playback pages.
    m = path.match(/^(?:\/([^/]+))?\/meta\/([^/]+)\/(.+)\.json$/);
    if (m) {
      const [, config, metaType, idRaw] = m;
      const id = decodeURIComponent(idRaw);

      // 1. Synthetic meta for Channels
      if (id.startsWith("channel_")) {
        if (metaType !== "series") return jsonPublic({ meta: null });
        const wantedChannelId = id.slice("channel_".length);
        try {
          const { entries } = await resolveConfig(config, env);
          let matchedEntry = null;
          for (const e of entries) {
            if (e.enabled === false) continue;
            const subUrls = String(e.url || "").split("\n").map((s) => s.trim()).filter(Boolean);
            for (const subUrl of subUrls) {
              const payload = parseChannelPayload(subUrl);
              if (!payload) continue;
              if ((payload.channelId || e.id) === wantedChannelId) {
                matchedEntry = { ...e, url: subUrl };
                break;
              }
            }
            if (matchedEntry) break;
          }
          if (!matchedEntry) return jsonPublic({ meta: null });
          const meta = buildChannelMeta(matchedEntry, url.origin);
          return jsonPublic({ meta: meta || null });
        } catch (err) {
          return jsonPublic({ meta: null, error: safeErrorMessage(err) });
        }
      }

      // 2. Standard title metadata for IMDb ids ("tt...") or TMDB ids ("tmdb:...")
      if (id.startsWith("tt") || id.startsWith("tmdb:")) {
        try {
          const { tmdbKey } = config ? await resolveConfig(config, env) : { tmdbKey: null };
          const effectiveKey = tmdbKey || TMDB_API_KEY;
          const meta = await fetchStandardItemMeta(id, metaType, effectiveKey, env, ctx);
          if (!meta) return jsonPublic({ meta: null });
          return jsonPublic(
            { meta },
            200,
            { "Cache-Control": "public, max-age=86400, stale-while-revalidate=604800" }
          );
        } catch (err) {
          return jsonPublic({ meta: null, error: safeErrorMessage(err) });
        }
      }

      return jsonPublic({ meta: null });
    }

    // /api/channel-logo?path=...[&format=landscape]
    // Generates a self-contained SVG channel poster with the network's official
    // logo. Uses format=landscape for 16:9 widescreen banners (600x338) and default
    // for vertical 2:3 posters (600x900). Uses embedded base64 so it renders reliably across
    // Stremio, Nuvio, wako, and web clients without CORS issues.
    if (path === "/api/channel-logo") {
      const logoPath = url.searchParams.get("path");
      const format = url.searchParams.get("format") || "";
      if (!logoPath) return new Response("Missing path", { status: 400 });
      try {
        const tmdbUrl = `https://image.tmdb.org/t/p/w500${logoPath.startsWith("/") ? logoPath : "/" + logoPath}`;
        const tmdbRes = await fetch(tmdbUrl, {
          headers: { "User-Agent": `my-lists-addon/${ADDON_VERSION}` },
          cf: { cacheTtl: 604800, cacheEverything: true },
        });
        if (!tmdbRes.ok) return new Response("Image not found", { status: 404 });
        const arrayBuffer = await tmdbRes.arrayBuffer();
        const contentType = tmdbRes.headers.get("content-type") || "image/png";
        const bytes = new Uint8Array(arrayBuffer);
        let binary = "";
        const len = bytes.byteLength;
        for (let i = 0; i < len; i++) {
          binary += String.fromCharCode(bytes[i]);
        }
        const base64 = btoa(binary);
        const dataUri = `data:${contentType};base64,${base64}`;

        const svg = format === "landscape"
          ? `<svg xmlns="http://www.w3.org/2000/svg" width="600" height="338" viewBox="0 0 600 338">
  <defs>
    <linearGradient id="bgGradL" x1="0%" y1="0%" x2="100%" y2="100%">
      <stop offset="0%" stop-color="#0b0d14"/>
      <stop offset="50%" stop-color="#131726"/>
      <stop offset="100%" stop-color="#06070a"/>
    </linearGradient>
  </defs>
  <rect width="600" height="338" fill="url(#bgGradL)"/>
  <rect x="12" y="12" width="576" height="314" rx="20" fill="none" stroke="rgba(255,255,255,0.18)" stroke-width="2"/>
  <image x="150" y="69" width="300" height="200" preserveAspectRatio="xMidYMid meet" href="${dataUri}"/>
</svg>`
          : `<svg xmlns="http://www.w3.org/2000/svg" width="600" height="900" viewBox="0 0 600 900">
  <defs>
    <linearGradient id="bgGradP" x1="0%" y1="0%" x2="100%" y2="100%">
      <stop offset="0%" stop-color="#0b0d14"/>
      <stop offset="50%" stop-color="#131726"/>
      <stop offset="100%" stop-color="#06070a"/>
    </linearGradient>
    <linearGradient id="accentGradP" x1="0%" y1="0%" x2="100%" y2="0%">
      <stop offset="0%" stop-color="#007AFF"/>
      <stop offset="50%" stop-color="#5856D6"/>
      <stop offset="100%" stop-color="#AF52DE"/>
    </linearGradient>
    <filter id="glowP" x="-30%" y="-30%" width="160%" height="160%">
      <feGaussianBlur stdDeviation="16" result="blur"/>
      <feComposite in="SourceGraphic" in2="blur" operator="over"/>
    </filter>
  </defs>
  <rect width="600" height="900" fill="url(#bgGradP)"/>
  <rect x="20" y="20" width="560" height="860" rx="32" fill="none" stroke="rgba(255,255,255,0.18)" stroke-width="3"/>
  <rect x="80" y="280" width="440" height="280" rx="24" fill="#141829" stroke="rgba(0,122,255,0.4)" stroke-width="2"/>
  <image x="100" y="300" width="400" height="240" preserveAspectRatio="xMidYMid meet" href="${dataUri}"/>
  <g transform="translate(300, 780)">
    <rect x="-120" y="-20" width="240" height="40" rx="20" fill="url(#accentGradP)"/>
    <text x="0" y="6" font-family="-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" font-size="15" font-weight="900" fill="#FFFFFF" text-anchor="middle" letter-spacing="2.5">TV CHANNEL</text>
  </g>
</svg>`;

        return new Response(svg, {
          headers: {
            "Content-Type": "image/svg+xml; charset=utf-8",
            "Cache-Control": "no-cache, no-store, must-revalidate",
            "Pragma": "no-cache",
            "Expires": "0",
            ...corsHeaders(),
          },
        });
      } catch (err) {
        return new Response("Error generating logo", { status: 500 });
      }
    }

    // /api/toplists
    // -> powers the "Popular Lists" browser in the builder page. Proxies
    // mdblist.com's own top-lists endpoint so people can add lists from
    // https://mdblist.com/toplists/ with a click instead of copy-pasting URLs.
    // Uses the fixed MDBLIST_POPULAR_KEY (see top of file) — no per-user key
    // needed for this, since it's the same public data for everyone.
    if (path === "/api/toplists") {
      try {
        // Always the shared key here -- no per-user override exists for
        // this endpoint (see the comment above).
        ctx.waitUntil(bumpStat(env, "apiuse:mdblistpopular"));
        const lists = await fetchTopLists(MDBLIST_POPULAR_KEY, env, ctx);
        return json({ ok: true, lists });
      } catch (err) {
        return json({ ok: false, error: safeErrorMessage(err) });
      }
    }

      // /api/season (GET) -> { ok: true, season: { episodes: [...] } }
      if (path === "/api/season") {
        const q = url.searchParams;
        const imdbId = q.get("imdbId");
        const seasonNum = q.get("seasonNum");
        const tmdbKeyParam = q.get("tmdbKey") || "";
        const tmdbKey = tmdbKeyParam || TMDB_API_KEY;
        if (!tmdbKeyParam) ctx.waitUntil(bumpStat(env, "apiuse:tmdb"));
        // Optional -- when the caller already resolved this show's tmdbId
        // (e.g. from the same /api/details response that gave it
        // imdbId/seasonsData in the first place), passing it straight
        // through skips a redundant imdbId -> tmdbId /find lookup here.
        // Matters most when several seasons of the same show are being
        // fetched concurrently (see markShowWatched's own comment): without
        // this, each one redundantly re-resolves the same show, and those
        // concurrent /find calls racing to fill a cold cache entry for a
        // show TMDB hasn't been asked about yet can come back empty under
        // that burst, silently dropping that season's episodes.
        const knownTmdbId = q.get("tmdbId") || null;
        
        if (!imdbId || !seasonNum) return json({ ok: false, error: "Missing imdbId or seasonNum" }, 400);
        
        const seasonData = await fetchTmdbSeasonDetails(imdbId, seasonNum, tmdbKey, knownTmdbId, env, ctx);
        if (!seasonData) return json({ ok: false, error: "Not found or TMDB error" }, 404);
        
        // A short max-age (not json()'s 3600s default) -- this response's
        // shape has changed before (the tmdbId passthrough above is a
        // recent example) and a stale hour-old browser cache of the old
        // shape is exactly the kind of thing that looks like "the fix
        // didn't work" for anyone re-testing a show/season they'd already
        // opened recently. The actual TMDB calls are still cached for a
        // full week at Cloudflare's edge (see fetchTmdbSeasonDetails's own
        // cf.cacheTtl) regardless of this -- this only governs how long
        // the browser reuses its own copy of this specific JSON reply.
        return json({ ok: true, season: seasonData }, 200, { "Cache-Control": "max-age=60" });
      }

    // /api/title-search?q=...&type=movie|tv
    // -> powers the "Search a show/movie" box in the Channel builder and the Search tab.
    // When no query is provided, returns the top 20 trending/popular titles for that category.
    // When a query is provided, fetches all relevant matching results across pages.
    if (path === "/api/title-search") {
      const q = (url.searchParams.get("q") || "").trim();
      const kind = url.searchParams.get("type") === "movie" ? "movie" : "tv";
      try {
        // Always the shared key -- no per-user override for this endpoint.
        ctx.waitUntil(bumpStat(env, "apiuse:tmdb"));
        if (!q) {
          // When no query is provided, return the top 20 trending/popular titles
          const src = `https://api.themoviedb.org/3/trending/${kind}/week?api_key=${encodeURIComponent(TMDB_API_KEY)}&page=1`;
          const res = await fetch(src, {
            headers: { "User-Agent": `my-lists-addon/${ADDON_VERSION}` },
            cf: { cacheTtl: 3600, cacheEverything: true },
          });
          if (!res.ok) return json({ ok: false, error: `TMDB lookup failed (HTTP ${res.status}).` });
          const data = await res.json();
          const results = (data.results || []).slice(0, 20).map((it) => ({
            tmdbId: it.id,
            title: it.title || it.name,
            year: (it.release_date || it.first_air_date || "").slice(0, 4),
            poster: it.poster_path ? `https://image.tmdb.org/t/p/w200${it.poster_path}` : null,
            backdrop: it.backdrop_path ? `https://image.tmdb.org/t/p/w780${it.backdrop_path}` : null,
            rating: typeof it.vote_average === "number" ? Math.round(it.vote_average * 10) / 10 : null,
            genreIds: Array.isArray(it.genre_ids) ? it.genre_ids : [],
            type: kind,
          }));
          return json({ ok: true, results });
        }

        // Active search: fetch all relevant search results across pages
        if (env && env.CONFIGS && typeof recordSearchQuery === "function") {
          ctx.waitUntil(recordSearchQuery(env, q));
        }

        const page1Src = `https://api.themoviedb.org/3/search/${kind}?api_key=${encodeURIComponent(
          TMDB_API_KEY
        )}&query=${encodeURIComponent(q)}&include_adult=false&page=1`;
        const page1Res = await fetch(page1Src, {
          headers: { "User-Agent": `my-lists-addon/${ADDON_VERSION}` },
          cf: { cacheTtl: 3600, cacheEverything: true },
        });
        if (!page1Res.ok) return json({ ok: false, error: `TMDB search failed (HTTP ${page1Res.status}).` });
        const page1Data = await page1Res.json();
        let allRawItems = Array.isArray(page1Data.results) ? [...page1Data.results] : [];
        const totalPages = typeof page1Data.total_pages === "number" ? page1Data.total_pages : 1;

        if (totalPages > 1) {
          const maxExtraPages = Math.min(totalPages, 5); // Up to 5 pages (100 relevant items)
          const extraPageNums = [];
          for (let p = 2; p <= maxExtraPages; p++) {
            extraPageNums.push(p);
          }
          const extraResults = await Promise.all(
            extraPageNums.map(async (p) => {
              try {
                const pSrc = `https://api.themoviedb.org/3/search/${kind}?api_key=${encodeURIComponent(
                  TMDB_API_KEY
                )}&query=${encodeURIComponent(q)}&include_adult=false&page=${p}`;
                const pRes = await fetch(pSrc, {
                  headers: { "User-Agent": `my-lists-addon/${ADDON_VERSION}` },
                  cf: { cacheTtl: 3600, cacheEverything: true },
                });
                if (!pRes.ok) return [];
                const pData = await pRes.json();
                return Array.isArray(pData.results) ? pData.results : [];
              } catch {
                return [];
              }
            })
          );
          for (const pageItems of extraResults) {
            allRawItems = allRawItems.concat(pageItems);
          }
        }

        // Deduplicate by TMDB ID
        const seenIds = new Set();
        const rawResults = [];
        for (const it of allRawItems) {
          if (!it || !it.id || seenIds.has(it.id)) continue;
          seenIds.add(it.id);
          rawResults.push(it);
        }

        const results = await Promise.all(
          rawResults.map(async (it) => {
            let poster = it.poster_path ? `https://image.tmdb.org/t/p/w200${it.poster_path}` : null;
            const backdrop = it.backdrop_path ? `https://image.tmdb.org/t/p/w780${it.backdrop_path}` : null;

            // If TMDB poster is missing, try backdrop or Cinemeta fallback
            if (!poster) {
              if (backdrop) {
                poster = backdrop;
              } else if (it.title || it.name) {
                try {
                  const cSearchRes = await fetch(
                    `https://v3-cinemeta.strem.io/catalog/${kind === "tv" ? "series" : "movie"}/top/search=${encodeURIComponent(
                      it.title || it.name
                    )}.json`,
                    { cf: { cacheTtl: 86400, cacheEverything: true } }
                  );
                  if (cSearchRes.ok) {
                    const cData = await cSearchRes.json();
                    const metas = Array.isArray(cData.metas) ? cData.metas : [];
                    const exact = metas.find(
                      (m) => m.name && m.name.toLowerCase() === (it.title || it.name).toLowerCase() && m.poster
                    );
                    poster = (exact && exact.poster) || (metas[0] && metas[0].poster) || null;
                  }
                } catch {}
              }
            }

            return {
              tmdbId: it.id,
              title: it.title || it.name,
              year: (it.release_date || it.first_air_date || "").slice(0, 4),
              poster: poster || null,
              backdrop: backdrop || poster || null,
              rating: typeof it.vote_average === "number" ? Math.round(it.vote_average * 10) / 10 : null,
              genreIds: Array.isArray(it.genre_ids) ? it.genre_ids : [],
              type: kind,
            };
          })
        );

        return json({ ok: true, results });
      } catch (err) {
        return json({ ok: false, error: safeErrorMessage(err) });
      }
    }

    // /api/poster-fallback?title=...&year=...&type=movie|series|tv&tmdbId=...&imdbId=...
    // Resolves missing posters via Cinemeta, Metahub, TMDB external IDs, or backdrops
    if (path === "/api/poster-fallback") {
      const title = (url.searchParams.get("title") || "").trim();
      const type = (url.searchParams.get("type") || "movie").toLowerCase();
      const kind = (type === "tv" || type === "series") ? "series" : "movie";
      const tmdbKind = (type === "tv" || type === "series") ? "tv" : "movie";
      const tmdbId = (url.searchParams.get("tmdbId") || "").replace(/^tmdb:/, "").trim();
      const rawImdbId = (url.searchParams.get("imdbId") || "").trim();

      const cacheKey = `cache:poster_fallback:${tmdbId || rawImdbId || `${kind}:${title.toLowerCase()}`}`;
      if (env && env.CONFIGS) {
        try {
          const cached = await env.CONFIGS.get(cacheKey);
          if (cached) return json({ ok: true, poster: cached });
        } catch {}
      }

      let resolvedPoster = null;
      let imdbId = rawImdbId.startsWith("tt") ? rawImdbId : null;

      // 1. If tmdbId is provided and no imdbId yet, lookup TMDB details for external_ids/images
      if (tmdbId && !imdbId) {
        try {
          const detRes = await fetch(
            `https://api.themoviedb.org/3/${tmdbKind}/${encodeURIComponent(tmdbId)}?api_key=${encodeURIComponent(
              TMDB_API_KEY
            )}&append_to_response=external_ids,images`,
            {
              headers: { "User-Agent": `my-lists-addon/${ADDON_VERSION}` },
              cf: { cacheTtl: 86400, cacheEverything: true },
            }
          );
          if (detRes.ok) {
            const det = await detRes.json();
            if (det.images && Array.isArray(det.images.posters) && det.images.posters.length > 0) {
              resolvedPoster = `https://image.tmdb.org/t/p/w500${det.images.posters[0].file_path}`;
            } else if (det.external_ids && det.external_ids.imdb_id) {
              imdbId = det.external_ids.imdb_id;
            } else if (det.backdrop_path) {
              resolvedPoster = `https://image.tmdb.org/t/p/w780${det.backdrop_path}`;
            }
          }
        } catch {}
      }

      // 2. If we have an IMDb ID, query Cinemeta and fallback to Metahub
      if (!resolvedPoster && imdbId) {
        try {
          const cRes = await fetch(`https://v3-cinemeta.strem.io/meta/${kind}/${imdbId}.json`, {
            cf: { cacheTtl: 86400, cacheEverything: true },
          });
          if (cRes.ok) {
            const cData = await cRes.json();
            if (cData.meta && cData.meta.poster) resolvedPoster = cData.meta.poster;
          }
        } catch {}
        if (!resolvedPoster) {
          resolvedPoster = `https://images.metahub.space/poster/medium/${imdbId}/img`;
        }
      }

      // 3. If still no poster, query Cinemeta catalog search by title
      if (!resolvedPoster && title) {
        try {
          const cSearchRes = await fetch(
            `https://v3-cinemeta.strem.io/catalog/${kind}/top/search=${encodeURIComponent(title)}.json`,
            { cf: { cacheTtl: 86400, cacheEverything: true } }
          );
          if (cSearchRes.ok) {
            const cData = await cSearchRes.json();
            const metas = Array.isArray(cData.metas) ? cData.metas : [];
            const exact = metas.find(
              (m) => m.name && m.name.toLowerCase() === title.toLowerCase() && m.poster
            );
            resolvedPoster = (exact && exact.poster) || (metas[0] && metas[0].poster) || null;
          }
        } catch {}
      }

      // 4. If still no poster, query TMDB search by title
      if (!resolvedPoster && title) {
        try {
          const tmdbSearch = await fetch(`https://api.themoviedb.org/3/search/${tmdbKind}?api_key=${encodeURIComponent(TMDB_API_KEY)}&query=${encodeURIComponent(title)}&page=1`, {
            headers: { "User-Agent": `my-lists-addon/${ADDON_VERSION}` },
            cf: { cacheTtl: 86400, cacheEverything: true }
          });
          if (tmdbSearch.ok) {
            const sd = await tmdbSearch.json();
            if (sd.results && sd.results.length > 0) {
              const first = sd.results[0];
              if (first.poster_path) resolvedPoster = `https://image.tmdb.org/t/p/w500${first.poster_path}`;
              else if (first.backdrop_path) resolvedPoster = `https://image.tmdb.org/t/p/w780${first.backdrop_path}`;
            }
          }
        } catch {}
      }

      if (resolvedPoster && env && env.CONFIGS) {
        ctx.waitUntil(env.CONFIGS.put(cacheKey, resolvedPoster, { expirationTtl: 604800 })); // 7-day cache
      }

      return json({ ok: !!resolvedPoster, poster: resolvedPoster });
    }

    // /api/show-seasons?tmdbId=...
    // -> once a show is picked in the Channel builder, lists its seasons so
    // the person can drill into one. Also resolves the show's IMDB id up
    // front (reusing fetchTmdbDetails -- same combined external_ids+videos
    // call every other TMDB path here already makes) since every episode
    // picked from this show will need it to build a resolvable stream id.
    if (path === "/api/show-seasons") {
      const tmdbId = url.searchParams.get("tmdbId") || "";
      if (!tmdbId) return json({ ok: false, error: "Missing tmdbId." }, 400);
      try {
        // Always the shared key -- 2 outbound TMDB calls per request.
        ctx.waitUntil(bumpStatBy(env, "apiuse:tmdb", 2));
        const [details, showRes] = await Promise.all([
          fetchTmdbDetails(tmdbId, "tv", TMDB_API_KEY),
          fetch(`https://api.themoviedb.org/3/tv/${tmdbId}?api_key=${encodeURIComponent(TMDB_API_KEY)}`, {
            headers: { "User-Agent": `my-lists-addon/${ADDON_VERSION}` },
            cf: { cacheTtl: 3600, cacheEverything: true },
          }),
        ]);
        if (!details.imdbId) {
          return json({ ok: false, error: "Couldn't resolve an IMDB id for this show, so streams likely won't work for any episode picked from it." });
        }
        if (!showRes.ok) return json({ ok: false, error: `TMDB show lookup failed (HTTP ${showRes.status}).` });
        const data = await showRes.json();
        const seasons = (data.seasons || [])
          .filter((s) => s.season_number > 0) // skip "Specials" (season 0)
          .map((s) => ({ season: s.season_number, name: s.name, episodeCount: s.episode_count }));
        return json({
          ok: true,
          imdbId: details.imdbId,
          name: data.name,
          poster: data.poster_path ? `https://image.tmdb.org/t/p/w500${data.poster_path}` : null,
          backdrop: data.backdrop_path ? `https://image.tmdb.org/t/p/w780${data.backdrop_path}` : null,
          seasons,
        });
      } catch (err) {
        return json({ ok: false, error: safeErrorMessage(err) });
      }
    }

    // /api/show-episodes?tmdbId=...&season=...
    // -> the actual episode checklist for one season, once picked in the
    // Channel builder.
    if (path === "/api/show-episodes") {
      const tmdbId = url.searchParams.get("tmdbId") || "";
      const season = url.searchParams.get("season") || "";
      if (!tmdbId || !season) return json({ ok: false, error: "Missing tmdbId or season." }, 400);
      try {
        // Always the shared key.
        ctx.waitUntil(bumpStat(env, "apiuse:tmdb"));
        const src = `https://api.themoviedb.org/3/tv/${tmdbId}/season/${encodeURIComponent(
          season
        )}?api_key=${encodeURIComponent(TMDB_API_KEY)}`;
        const res = await fetch(src, {
          headers: { "User-Agent": `my-lists-addon/${ADDON_VERSION}` },
          cf: { cacheTtl: 3600, cacheEverything: true },
        });
        if (!res.ok) return json({ ok: false, error: `TMDB season lookup failed (HTTP ${res.status}).` });
        const data = await res.json();
        const episodes = (data.episodes || []).map((e) => ({
          episode: e.episode_number,
          name: e.name,
          released: e.air_date || null,
          thumbnail: e.still_path ? `https://image.tmdb.org/t/p/w780${e.still_path}` : null,
        }));
        return json({ ok: true, episodes });
      } catch (err) {
        return json({ ok: false, error: safeErrorMessage(err) });
      }
    }

    // /api/quick-channel-shows?url=<any supported list url>  OR  ?networkId=<TMDB network id>
    // -> powers the Channels panel's "Quick Add Channel" buttons (CBS, NBC,
    // ABC, FOX, The CW, HBO, etc.) and "Import from link": resolves a source
    // of shows to TMDB ids, so the client can then loop them through the
    // same /api/show-seasons + /api/show-episodes endpoints the manual
    // picker already uses. Deliberately split from that per-show/per-season
    // fetching (rather than one giant server-side request that builds the
    // whole channel) -- a full network lineup could mean dozens of shows
    // and hundreds of TMDB calls, comfortably over what a single Worker
    // request should be doing; spreading that across many small
    // client-driven requests keeps each one fast and avoids leaning on
    // Cloudflare's per-request subrequest ceiling.
    if (path === "/api/channel-preset") {
      const networkId = url.searchParams.get("networkId") || "";
      const name = url.searchParams.get("name") || "TV Channel";
      if (!networkId) return json({ ok: false, error: "Missing networkId." }, 400);

      const cacheKey = `channel:preset:v2:${networkId}`;
      try {
        if (env && env.CONFIGS) {
          const cached = await env.CONFIGS.get(cacheKey);
          if (cached) {
            const parsed = JSON.parse(cached);
            if (parsed && Array.isArray(parsed.items) && parsed.items.length) {
              return json({ ok: true, channel: parsed }, 200, { "Cache-Control": "public, max-age=86400, s-maxage=86400" });
            }
          }
        }
      } catch (e) {}

      try {
        const discoverRes = await fetch(
          `https://api.themoviedb.org/3/discover/tv?api_key=${encodeURIComponent(TMDB_API_KEY)}` +
            `&with_networks=${encodeURIComponent(networkId)}&sort_by=popularity.desc&page=1&include_adult=false`,
          { headers: { "User-Agent": `my-lists-addon/${ADDON_VERSION}` }, cf: { cacheTtl: 86400, cacheEverything: true } }
        );
        if (!discoverRes.ok) return json({ ok: false, error: "TMDB network request failed." }, 502);
        const discoverData = await discoverRes.json();
        let topShows = (discoverData.results || []).slice(0, 10);
        const nameLower = name.toLowerCase();
        if (!topShows.length) {
          if (nameLower.includes("metv")) {
            topShows = [{ id: 4607 }, { id: 735 }, { id: 1403 }, { id: 2098 }, { id: 2287 }, { id: 873 }, { id: 253 }, { id: 914 }, { id: 2101 }, { id: 2289 }, { id: 2099 }, { id: 2100 }, { id: 2344 }, { id: 2103 }];
          } else if (nameLower.includes("food")) {
            topShows = [{ id: 2382 }, { id: 17855 }, { id: 62326 }, { id: 2383 }, { id: 63278 }, { id: 44006 }, { id: 11822 }, { id: 67070 }];
          } else if (nameLower.includes("ion")) {
            topShows = [{ id: 62741 }, { id: 1408 }, { id: 1418 }, { id: 4614 }, { id: 62688 }, { id: 2734 }];
          }
        }
        if (!topShows.length) return json({ ok: false, error: "No shows found for that network." });

        let networkLogo = null;
        try {
          const networkRes = await fetch(
            `https://api.themoviedb.org/3/network/${encodeURIComponent(networkId)}?api_key=${encodeURIComponent(TMDB_API_KEY)}`,
            { headers: { "User-Agent": `my-lists-addon/${ADDON_VERSION}` }, cf: { cacheTtl: 604800, cacheEverything: true } }
          );
          if (networkRes.ok) {
            const networkData = await networkRes.json();
            if (networkData.logo_path) networkLogo = `${url.origin}/api/channel-logo?path=${encodeURIComponent(networkData.logo_path)}`;
          }
        } catch (e) {}

        const allEpisodes = [];
        let poster = networkLogo;
        let backdrop = null;

        const assembleFromShows = async (showsList) => {
          await mapWithConcurrency(showsList, 4, async (show) => {
            if (allEpisodes.length >= 200) return;
            try {
              const showRes = await fetch(
                `https://api.themoviedb.org/3/tv/${encodeURIComponent(show.id)}?api_key=${encodeURIComponent(TMDB_API_KEY)}&append_to_response=external_ids`,
                { headers: { "User-Agent": `my-lists-addon/${ADDON_VERSION}` }, cf: { cacheTtl: 86400, cacheEverything: true } }
              );
              if (!showRes.ok) return;
              const fullShow = await showRes.json();
              const imdbId = (fullShow.external_ids && fullShow.external_ids.imdb_id) || fullShow.imdb_id || (`tmdb:${show.id}`);

              if (!poster && fullShow.poster_path) poster = `https://image.tmdb.org/t/p/w500${fullShow.poster_path}`;
              if (!backdrop && fullShow.backdrop_path) backdrop = `https://image.tmdb.org/t/p/w780${fullShow.backdrop_path}`;

              const showPosterUrl = fullShow.poster_path ? `https://image.tmdb.org/t/p/w500${fullShow.poster_path}` : "";
              const validSeasons = (fullShow.seasons || []).filter((s) => s.season_number > 0).slice(0, 3);

              for (const s of validSeasons) {
                if (allEpisodes.length >= 200) break;
                const sRes = await fetch(
                  `https://api.themoviedb.org/3/tv/${encodeURIComponent(show.id)}/season/${s.season_number}?api_key=${encodeURIComponent(TMDB_API_KEY)}`,
                  { headers: { "User-Agent": `my-lists-addon/${ADDON_VERSION}` }, cf: { cacheTtl: 86400, cacheEverything: true } }
                );
                if (!sRes.ok) continue;
                const sData = await sRes.json();
                for (const ep of (sData.episodes || [])) {
                  if (allEpisodes.length >= 200) break;
                  const stillUrl = ep.still_path ? `https://image.tmdb.org/t/p/w500${ep.still_path}` : "";
                  allEpisodes.push({
                    kind: "episode",
                    imdbId: imdbId,
                    season: s.season_number,
                    episode: ep.episode_number,
                    showName: fullShow.name || show.name || "",
                    epName: ep.name || (`Episode ${ep.episode_number}`),
                    title: `${fullShow.name || show.name} S${s.season_number}E${ep.episode_number} \u2014 ${ep.name || (`Episode ${ep.episode_number}`)}`,
                    released: ep.air_date || "",
                    thumbnail: stillUrl || showPosterUrl,
                    poster: showPosterUrl || stillUrl,
                    showPoster: showPosterUrl,
                  });
                }
              }
            } catch (e) {}
          });
        };

        await assembleFromShows(topShows);

        if (!allEpisodes.length && (nameLower.includes("metv") || nameLower.includes("food") || nameLower.includes("ion"))) {
          let fallbackShows = [];
          if (nameLower.includes("metv")) {
            fallbackShows = [{ id: 4607 }, { id: 735 }, { id: 1403 }, { id: 2098 }, { id: 2287 }, { id: 873 }, { id: 253 }, { id: 914 }, { id: 2101 }, { id: 2289 }, { id: 2099 }, { id: 2100 }, { id: 2344 }, { id: 2103 }];
          } else if (nameLower.includes("food")) {
            fallbackShows = [{ id: 2382 }, { id: 17855 }, { id: 62326 }, { id: 2383 }, { id: 63278 }, { id: 44006 }, { id: 11822 }, { id: 67070 }];
          } else if (nameLower.includes("ion")) {
            fallbackShows = [{ id: 62741 }, { id: 1408 }, { id: 1418 }, { id: 4614 }, { id: 62688 }, { id: 2734 }];
          }
          await assembleFromShows(fallbackShows);
        }

        if (!allEpisodes.length) return json({ ok: false, error: "Could not assemble episodes for this network." });

        const channelPayload = {
          name: name,
          poster: poster || (url.origin + "/icon.png"),
          backdrop: backdrop || poster || (url.origin + "/icon.png"),
          items: allEpisodes,
          shuffle: false,
          dailyRotate: true,
        };

        if (env && env.CONFIGS && ctx && typeof ctx.waitUntil === "function") {
          ctx.waitUntil(env.CONFIGS.put(cacheKey, JSON.stringify(channelPayload), { expirationTtl: 86400 }));
        }
        return json({ ok: true, channel: channelPayload }, 200, { "Cache-Control": "public, max-age=86400, s-maxage=86400" });
      } catch (err) {
        return json({ ok: false, error: err.message || "Failed to build network channel preset." }, 500);
      }
    }

    //
    // Three sources feed this: any mdblist.com/trakt.tv/themoviedb.org list
    // link (someone else's hand-picked lineup, or "Import from link"'s own
    // pasted URL), a TMDB network id directly (TMDB's own current/popular
    // shows for that network, e.g. FOX/The CW/HBO -- doesn't depend on any
    // third party's list existing or staying maintained), or -- implicitly,
    // via the url branch -- a mixed movies+shows list, since requesting
    // type "series" from the generic catalog fetch below silently drops any
    // movies rather than erroring out (Channels are shows-only).
    if (path === "/api/quick-channel-shows") {
      const listUrl = url.searchParams.get("url") || "";
      const networkId = url.searchParams.get("networkId") || "";
      const mdblistKey = url.searchParams.get("mdblistKey") || "";
      const traktKey = url.searchParams.get("traktKey") || "";
      const traktAccessToken = url.searchParams.get("traktAccessToken") || "";
      if (!listUrl && !networkId) return json({ ok: false, error: "Missing url or networkId." }, 400);
      try {
        let showRefs; // [{ id: <imdb id>, name, poster }]
        if (networkId) {
          const discoverResults = [];
          // Up to 10 pages (200 shows) -- a much bigger candidate pool to
          // shuffle from than before, but safe to raise: CHANNEL_MAX_TOTAL_ITEMS
          // below already bounds how much actually gets processed regardless
          // of pool size, and this loop still stops early via total_pages
          // for any network with genuinely fewer than 10 pages of results.
          let discoverPagesFetched = 0;
          for (let page = 1; page <= 10; page++) {
            discoverPagesFetched++;
            const discoverRes = await fetch(
              `https://api.themoviedb.org/3/discover/tv?api_key=${encodeURIComponent(TMDB_API_KEY)}` +
                `&with_networks=${encodeURIComponent(networkId)}&sort_by=popularity.desc&page=${page}&include_adult=false`,
              { headers: { "User-Agent": `my-lists-addon/${ADDON_VERSION}` }, cf: { cacheTtl: 3600, cacheEverything: true } }
            );
            if (!discoverRes.ok) break;
            const discoverData = await discoverRes.json();
            discoverResults.push(...(discoverData.results || []));
            if (page >= (discoverData.total_pages || 1)) break;
          }
          if (!discoverResults.length) return json({ ok: false, error: "No shows found for that network." });
          // The network's own logo (e.g. the CBS eye) -- a much more
          // fitting default poster for a channel built to represent that
          // whole network than an arbitrary single show's poster, which is
          // what this fell back to before. Best-effort: if TMDB doesn't
          // have a logo for this network id, the client already has its
          // own fallback (the first show's poster) for that case.
          let networkLogo = null;
          try {
            const networkRes = await fetch(
              `https://api.themoviedb.org/3/network/${encodeURIComponent(networkId)}?api_key=${encodeURIComponent(TMDB_API_KEY)}`,
              { headers: { "User-Agent": `my-lists-addon/${ADDON_VERSION}` }, cf: { cacheTtl: 604800, cacheEverything: true } }
            );
            if (networkRes.ok) {
              const networkData = await networkRes.json();
              // A specific size (not "original") is required here --
              // TMDB serves the network's raw uploaded logo file at
              // "original", which for many networks is an .svg, and
              // Stremio/wako can't render an SVG as a poster (this was the
              // actual cause of the logo silently never showing and
              // falling back to a show's poster instead). Any fixed pixel
              // size forces TMDB to rasterize it to PNG first.
              if (networkData.logo_path) networkLogo = `${url.origin}/api/channel-logo?path=${encodeURIComponent(networkData.logo_path)}`;
            }
          } catch {
            // best-effort -- fall through with networkLogo left null
          }
          const shows = await mapWithConcurrency(discoverResults, 8, async (show) => {
            const details = await fetchTmdbDetails(show.id, "tv", TMDB_API_KEY);
            if (!details.imdbId) return null;
            return {
              imdbId: details.imdbId,
              tmdbId: show.id,
              name: show.name,
              poster: show.poster_path ? `https://image.tmdb.org/t/p/w500${show.poster_path}` : null,
              backdrop: show.backdrop_path ? `https://image.tmdb.org/t/p/w780${show.backdrop_path}` : null,
            };
          });
          // Always the shared key -- the discover page loop
          // (discoverPagesFetched), the network logo lookup (1), and one
          // fetchTmdbDetails call per discovered show all landed above.
          ctx.waitUntil(bumpStatBy(env, "apiuse:tmdb", discoverPagesFetched + 1 + discoverResults.length));
          const resolved = shows.filter(Boolean);
          if (!resolved.length) return json({ ok: false, error: "Couldn't resolve any shows for that network to IMDB." });
          return json({ ok: true, shows: resolved, networkLogo });
        }

        // A pasted list link can be any of this add-on's supported sources
        // (mdblist/trakt/tmdb) and can be mixed movies+shows -- requesting
        // type "series" specifically both narrows to just the shows
        // (silently dropping any movies in the same list) and reuses the
        // exact same fetchCatalog dispatch every other list source already
        // goes through, instead of this route only ever understanding
        // mdblist's own JSON shape like it used to.
        let metas;
        try {
          metas = await fetchCatalog({ url: listUrl, type: "series" }, 0, { mdblistKey, traktKey, traktAccessToken, env, ctx, origin: url.origin });
        } catch (err) {
          return json({ ok: false, error: `Could not read that list: ${err.message || err}` });
        }
        if (!metas.length) {
          return json({ ok: false, error: "That list has no shows in it (Channels are shows-only -- any movies are skipped)." });
        }

        const shows = await mapWithConcurrency(metas, 8, async (m) => {
          try {
            const findRes = await fetch(
              `https://api.themoviedb.org/3/find/${m.id}?api_key=${encodeURIComponent(TMDB_API_KEY)}&external_source=imdb_id`,
              { headers: { "User-Agent": `my-lists-addon/${ADDON_VERSION}` }, cf: { cacheTtl: 604800, cacheEverything: true } }
            );
            if (!findRes.ok) return null;
            const findData = await findRes.json();
            const match = (findData.tv_results || [])[0];
            if (!match) return null;
            return {
              imdbId: m.id,
              tmdbId: match.id,
              name: m.name,
              poster: m.poster || (match.poster_path ? `https://image.tmdb.org/t/p/w500${match.poster_path}` : null),
              backdrop: match.backdrop_path ? `https://image.tmdb.org/t/p/w780${match.backdrop_path}` : (m.poster || null),
            };
          } catch {
            return null;
          }
        });
        // Always the shared key -- one TMDB find call per item in the list.
        ctx.waitUntil(bumpStatBy(env, "apiuse:tmdb", metas.length));
        const resolved = shows.filter(Boolean);
        if (!resolved.length) return json({ ok: false, error: "Couldn't resolve any shows in that list to TMDB." });
        return json({ ok: true, shows: resolved });
      } catch (err) {
        return json({ ok: false, error: safeErrorMessage(err) });
      }
    }

    // /api/resolve-movie?tmdbId=...
    // -> resolves a movie's IMDB id when it's added to a Custom List.
    if (path === "/api/resolve-movie") {
      const tmdbId = url.searchParams.get("tmdbId") || "";
      if (!tmdbId) return json({ ok: false, error: "Missing tmdbId." }, 400);
      try {
        ctx.waitUntil(bumpStat(env, "apiuse:tmdb"));
        const details = await fetchTmdbDetails(tmdbId, "movie", TMDB_API_KEY);
        if (!details.imdbId) return json({ ok: false, error: "Couldn't resolve an IMDB id for this movie." });
        return json({ ok: true, imdbId: details.imdbId });
      } catch (err) {
        return json({ ok: false, error: safeErrorMessage(err) });
      }
    }

    // /api/resolve-show?tmdbId=...
    // -> resolves a show's IMDB id when it's added to a Custom List (a
    // whole-show pick, not per-episode -- that's the Channels panel).
    if (path === "/api/resolve-show") {
      const tmdbId = url.searchParams.get("tmdbId") || "";
      if (!tmdbId) return json({ ok: false, error: "Missing tmdbId." }, 400);
      try {
        ctx.waitUntil(bumpStat(env, "apiuse:tmdb"));
        const details = await fetchTmdbDetails(tmdbId, "tv", TMDB_API_KEY);
        if (!details.imdbId) return json({ ok: false, error: "Couldn't resolve an IMDB id for this show." });
        return json({ ok: true, imdbId: details.imdbId });
      } catch (err) {
        return json({ ok: false, error: safeErrorMessage(err) });
      }
    }

    // /api/recommendations  (POST)  { movieIds: [...], showIds: [...] } -> { ok, movies: [...], shows: [...] }
    // Generates personalized movie and show recommendations from TMDB based on user watch history.
    if (path === "/api/recommendations" && request.method === "POST") {
      let body;
      try {
        body = await request.json();
      } catch {
        return json({ ok: false, error: "Invalid JSON body." }, 400);
      }
      const movieIds = Array.isArray(body.movieIds) ? body.movieIds.slice(0, 12) : [];
      const showIds = Array.isArray(body.showIds) ? body.showIds.slice(0, 12) : [];
      const tmdbKey = body.tmdbKey || TMDB_API_KEY;
      // Up to 24 ids, each costing a find + a recommendations call, so a
      // single request is ~48 TMDB calls. Limited only when it falls back
      // to the shared key, same reasoning as /api/details/batch above.
      // The Discover tab issues one of these per load, so 30/minute is far
      // more than any real session needs.
      if (!body.tmdbKey) {
        const recIp = clientIpKey(request);
        if (!recIp) return json({ ok: false, error: "Could not load recommendations." }, 400);
        if (await consumeRateLimit(env, ctx, "recommendations", recIp, 30)) {
          return json({ ok: false, error: "Too many requests just now. Please wait a minute and try again." }, 429);
        }
      }

      const [movieLists, showLists] = await Promise.all([
        Promise.all(movieIds.map(async (rawId) => {
          try {
            let tmdbId = "";
            let strId = String(rawId || "").trim();
            if (strId.startsWith("tmdb:")) strId = strId.slice(5);
            const baseId = strId.split(":")[0];
            if (/^\d+$/.test(baseId)) {
              tmdbId = baseId;
            } else {
              const findRes = await fetch(`https://api.themoviedb.org/3/find/${encodeURIComponent(baseId)}?api_key=${encodeURIComponent(tmdbKey)}&external_source=imdb_id`, {
                cf: { cacheTtl: 86400, cacheEverything: true }
              });
              const findData = await findRes.json();
              if (findData.movie_results && findData.movie_results[0]) {
                tmdbId = findData.movie_results[0].id;
              }
            }
            if (!tmdbId) return [];
            const recRes = await fetch(`https://api.themoviedb.org/3/movie/${encodeURIComponent(tmdbId)}/recommendations?api_key=${encodeURIComponent(tmdbKey)}&page=1`, {
              cf: { cacheTtl: 86400, cacheEverything: true }
            });
            const recData = await recRes.json();
            let list = recData.results || [];
            if (!list.length) {
              const simRes = await fetch(`https://api.themoviedb.org/3/movie/${encodeURIComponent(tmdbId)}/similar?api_key=${encodeURIComponent(tmdbKey)}&page=1`, {
                cf: { cacheTtl: 86400, cacheEverything: true }
              });
              const simData = await simRes.json();
              list = simData.results || [];
            }
            return list;
          } catch {
            return [];
          }
        })),
        Promise.all(showIds.map(async (rawId) => {
          try {
            let tmdbId = "";
            let strId = String(rawId || "").trim();
            if (strId.startsWith("tmdb:")) strId = strId.slice(5);
            const baseId = strId.split(":")[0];
            if (/^\d+$/.test(baseId)) {
              tmdbId = baseId;
            } else {
              const findRes = await fetch(`https://api.themoviedb.org/3/find/${encodeURIComponent(baseId)}?api_key=${encodeURIComponent(tmdbKey)}&external_source=imdb_id`, {
                cf: { cacheTtl: 86400, cacheEverything: true }
              });
              const findData = await findRes.json();
              if (findData.tv_results && findData.tv_results[0]) {
                tmdbId = findData.tv_results[0].id;
              }
            }
            if (!tmdbId) return [];
            const recRes = await fetch(`https://api.themoviedb.org/3/tv/${encodeURIComponent(tmdbId)}/recommendations?api_key=${encodeURIComponent(tmdbKey)}&page=1`, {
              cf: { cacheTtl: 86400, cacheEverything: true }
            });
            const recData = await recRes.json();
            let list = recData.results || [];
            if (!list.length) {
              const simRes = await fetch(`https://api.themoviedb.org/3/tv/${encodeURIComponent(tmdbId)}/similar?api_key=${encodeURIComponent(tmdbKey)}&page=1`, {
                cf: { cacheTtl: 86400, cacheEverything: true }
              });
              const simData = await simRes.json();
              list = simData.results || [];
            }
            return list;
          } catch {
            return [];
          }
        }))
      ]);

      const seenMovieIds = new Set();
      const recMovies = [];
      for (const list of movieLists) {
        for (const m of list) {
          if (m && m.id && !seenMovieIds.has(m.id) && m.poster_path) {
            seenMovieIds.add(m.id);
            recMovies.push({
              id: "tmdb:" + m.id,
              tmdbId: String(m.id),
              name: m.title || "Movie",
              poster: "https://image.tmdb.org/t/p/w500" + m.poster_path,
              year: (m.release_date || "").slice(0, 4),
              type: "movie",
              rating: m.vote_average ? m.vote_average.toFixed(1) : null
            });
          }
        }
      }

      if (recMovies.length < 10) {
        try {
          const popRes = await fetch(`https://api.themoviedb.org/3/trending/movie/week?api_key=${encodeURIComponent(tmdbKey)}`, {
            cf: { cacheTtl: 86400, cacheEverything: true }
          });
          const popData = await popRes.json();
          for (const m of (popData.results || [])) {
            if (m && m.id && !seenMovieIds.has(m.id) && m.poster_path) {
              seenMovieIds.add(m.id);
              recMovies.push({
                id: "tmdb:" + m.id,
                tmdbId: String(m.id),
                name: m.title || "Movie",
                poster: "https://image.tmdb.org/t/p/w500" + m.poster_path,
                year: (m.release_date || "").slice(0, 4),
                type: "movie",
                rating: m.vote_average ? m.vote_average.toFixed(1) : null
              });
            }
          }
        } catch {}
      }

      const seenShowIds = new Set();
      const recShows = [];
      for (const list of showLists) {
        for (const s of list) {
          if (s && s.id && !seenShowIds.has(s.id) && s.poster_path) {
            seenShowIds.add(s.id);
            recShows.push({
              id: "tmdb:" + s.id,
              tmdbId: String(s.id),
              name: s.name || "Show",
              poster: "https://image.tmdb.org/t/p/w500" + s.poster_path,
              year: (s.first_air_date || "").slice(0, 4),
              type: "series",
              rating: s.vote_average ? s.vote_average.toFixed(1) : null
            });
          }
        }
      }

      if (recShows.length < 10) {
        try {
          const popRes = await fetch(`https://api.themoviedb.org/3/trending/tv/week?api_key=${encodeURIComponent(tmdbKey)}`, {
            cf: { cacheTtl: 86400, cacheEverything: true }
          });
          const popData = await popRes.json();
          for (const s of (popData.results || [])) {
            if (s && s.id && !seenShowIds.has(s.id) && s.poster_path) {
              seenShowIds.add(s.id);
              recShows.push({
                id: "tmdb:" + s.id,
                tmdbId: String(s.id),
                name: s.name || "Show",
                poster: "https://image.tmdb.org/t/p/w500" + s.poster_path,
                year: (s.first_air_date || "").slice(0, 4),
                type: "series",
                rating: s.vote_average ? s.vote_average.toFixed(1) : null
              });
            }
          }
        } catch {}
      }

      // CURATED_RECOMMENDATION_LIMIT, not a literal -- fetchCuratedCatalog
      // (05_catalog-core.js) serves the catalog row for this same list and
      // has to cut it to exactly the same length, or the Discover card and
      // the shelf it adds disagree about how many items the list has.
      return json({
        ok: true,
        movies: recMovies.slice(0, CURATED_RECOMMENDATION_LIMIT),
        shows: recShows.slice(0, CURATED_RECOMMENDATION_LIMIT),
      });
    }

    // /api/tmdb-search-lists?q=...[&tmdbKey=...]
    // -> searches TMDB for Franchise Collections (e.g. Marvel, Harry Potter, Star Wars)
    // and matching TMDB Official Charts (Popular, Top Rated, Streaming Channels, etc.)
    if (path === "/api/tmdb-search-lists") {
      const q = (url.searchParams.get("q") || "").trim();
      const tmdbKeyParam = url.searchParams.get("tmdbKey") || "";
      const tmdbKey = tmdbKeyParam || TMDB_API_KEY;
      if (!q || !tmdbKey) {
        return json({ ok: true, lists: [] });
      }

      try {
        if (!tmdbKeyParam) ctx.waitUntil(bumpStat(env, "apiuse:tmdb"));
        const qLower = q.toLowerCase();
        const results = [];

        // 1. Search TMDB Collections
        const collRes = await fetch(
          `https://api.themoviedb.org/3/search/collection?api_key=${encodeURIComponent(tmdbKey)}&query=${encodeURIComponent(q)}`,
          {
            headers: { "User-Agent": "my-list-addon/1.14" },
            cf: { cacheTtl: 86400, cacheEverything: true },
          }
        );

        if (collRes.ok) {
          const collData = await collRes.json();
          const collections = Array.isArray(collData.results) ? collData.results : [];
          for (const c of collections.slice(0, 15)) {
            if (!c || !c.id) continue;
            results.push({
              name: c.name || "Unnamed Collection",
              user: "TMDB Franchise",
              url: `https://www.themoviedb.org/collection/${c.id}`,
              type: "movie",
              items: "Franchise",
              poster: c.poster_path ? `https://image.tmdb.org/t/p/w500${c.poster_path}` : undefined,
              likes: 0,
              isCollection: true,
            });
          }
        }

        // 2. Check TMDB Official Charts matching query
        const builtinTmdbCharts = [
          { name: "TMDB Trending Movies", url: "tmdb:chart:trending", type: "movie", tags: ["trending", "popular", "top", "tmdb"] },
          { name: "TMDB Trending Shows", url: "tmdb:chart:trending", type: "series", tags: ["trending", "popular", "top", "tv", "shows", "tmdb"] },
          { name: "TMDB Popular Movies", url: "tmdb:chart:popular", type: "movie", tags: ["popular", "top", "movies", "tmdb"] },
          { name: "TMDB Popular Shows", url: "tmdb:chart:popular", type: "series", tags: ["popular", "top", "shows", "tv", "tmdb"] },
          { name: "TMDB Top Rated Movies", url: "tmdb:chart:top_rated", type: "movie", tags: ["top rated", "best", "movies", "tmdb"] },
          { name: "TMDB Top Rated Shows", url: "tmdb:chart:top_rated", type: "series", tags: ["top rated", "best", "shows", "tv", "tmdb"] },
          { name: "TMDB Now Playing", url: "tmdb:chart:now_playing", type: "movie", tags: ["now playing", "theater", "cinema", "new", "tmdb"] },
          { name: "TMDB Upcoming Movies", url: "tmdb:chart:upcoming", type: "movie", tags: ["upcoming", "coming soon", "future", "tmdb"] },
          { name: "Netflix Movies", url: "tmdb:chart:netflix", type: "movie", tags: ["netflix", "streaming"] },
          { name: "Netflix Shows", url: "tmdb:chart:netflix", type: "series", tags: ["netflix", "streaming", "shows"] },
          { name: "Apple TV+ Movies", url: "tmdb:chart:appletv", type: "movie", tags: ["apple", "apple tv", "streaming"] },
          { name: "Apple TV+ Shows", url: "tmdb:chart:appletv", type: "series", tags: ["apple", "apple tv", "streaming", "shows"] },
          { name: "Disney+ Movies", url: "tmdb:chart:disney", type: "movie", tags: ["disney", "disney plus", "streaming", "marvel", "star wars"] },
          { name: "Disney+ Shows", url: "tmdb:chart:disney", type: "series", tags: ["disney", "disney plus", "streaming", "shows"] },
          { name: "HBO Max Movies", url: "tmdb:chart:hbomax", type: "movie", tags: ["hbo", "hbo max", "max", "warner"] },
          { name: "HBO Max Shows", url: "tmdb:chart:hbomax", type: "series", tags: ["hbo", "hbo max", "max", "warner", "shows"] },
          { name: "Hulu Movies", url: "tmdb:chart:hulu", type: "movie", tags: ["hulu", "streaming"] },
          { name: "Hulu Shows", url: "tmdb:chart:hulu", type: "series", tags: ["hulu", "streaming", "shows"] },
          { name: "Prime Video Movies", url: "tmdb:chart:primevideo", type: "movie", tags: ["amazon", "prime", "prime video"] },
          { name: "Prime Video Shows", url: "tmdb:chart:primevideo", type: "series", tags: ["amazon", "prime", "prime video", "shows"] },
          { name: "Paramount+ Movies", url: "tmdb:chart:paramount", type: "movie", tags: ["paramount", "paramount plus"] },
          { name: "Paramount+ Shows", url: "tmdb:chart:paramount", type: "series", tags: ["paramount", "paramount plus", "shows"] },
          { name: "Peacock Movies", url: "tmdb:chart:peacock", type: "movie", tags: ["peacock", "nbc"] },
          { name: "Peacock Shows", url: "tmdb:chart:peacock", type: "series", tags: ["peacock", "nbc", "shows"] },
          { name: "Hidden Gems", url: "tmdb:hidden-gems", type: "movie", tags: ["hidden gems", "underrated", "gems", "cult"] },
          { name: "Kids Movies", url: "tmdb:kids:movie", type: "movie", tags: ["kids", "children", "family", "animation", "disney"] },
          { name: "Kids Shows", url: "tmdb:kids:tv", type: "series", tags: ["kids", "children", "family", "animation", "cartoons"] },
          { name: "Family Movies", url: "tmdb:genre:family", type: "movie", tags: ["family", "genre", "newest", "tmdb"] },
          { name: "Family Shows", url: "tmdb:genre:family", type: "series", tags: ["family", "genre", "newest", "shows", "tv", "tmdb"] },
          { name: "Fantasy Movies", url: "tmdb:genre:fantasy", type: "movie", tags: ["fantasy", "genre", "newest", "tmdb"] },
          { name: "Fantasy Shows", url: "tmdb:genre:fantasy", type: "series", tags: ["fantasy", "genre", "newest", "shows", "tv", "tmdb"] },
          { name: "History Movies", url: "tmdb:genre:history", type: "movie", tags: ["history", "historical", "genre", "newest", "tmdb"] },
          { name: "History Shows", url: "tmdb:genre:history", type: "series", tags: ["history", "historical", "genre", "newest", "shows", "tv", "tmdb"] },
          { name: "Horror Movies", url: "tmdb:genre:horror", type: "movie", tags: ["horror", "scary", "genre", "newest", "tmdb"] },
          { name: "Horror Shows", url: "tmdb:genre:horror", type: "series", tags: ["horror", "scary", "genre", "newest", "shows", "tv", "tmdb"] },
          { name: "Mystery Movies", url: "tmdb:genre:mystery", type: "movie", tags: ["mystery", "detective", "genre", "newest", "tmdb"] },
          { name: "Mystery Shows", url: "tmdb:genre:mystery", type: "series", tags: ["mystery", "detective", "genre", "newest", "shows", "tv", "tmdb"] },
          { name: "Romance Movies", url: "tmdb:genre:romance", type: "movie", tags: ["romance", "romantic", "love", "genre", "newest", "tmdb"] },
          { name: "Romance Shows", url: "tmdb:genre:romance", type: "series", tags: ["romance", "romantic", "love", "genre", "newest", "shows", "tv", "tmdb"] },
          { name: "Science Fiction Movies", url: "tmdb:genre:science-fiction", type: "movie", tags: ["science fiction", "scifi", "sci-fi", "genre", "newest", "tmdb"] },
          { name: "Science Fiction Shows", url: "tmdb:genre:science-fiction", type: "series", tags: ["science fiction", "scifi", "sci-fi", "genre", "newest", "shows", "tv", "tmdb"] },
          { name: "Stream Releases Movies", url: "tmdb:genre:stream-releases", type: "movie", tags: ["stream releases", "streaming", "newest", "tmdb"] },
          { name: "Stream Releases Shows", url: "tmdb:genre:stream-releases", type: "series", tags: ["stream releases", "streaming", "newest", "shows", "tv", "tmdb"] },
          { name: "Thriller Movies", url: "tmdb:genre:thriller", type: "movie", tags: ["thriller", "suspense", "genre", "newest", "tmdb"] },
          { name: "Thriller Shows", url: "tmdb:genre:thriller", type: "series", tags: ["thriller", "suspense", "genre", "newest", "shows", "tv", "tmdb"] },
          { name: "War Movies", url: "tmdb:genre:war", type: "movie", tags: ["war", "military", "genre", "newest", "tmdb"] },
          { name: "War Shows", url: "tmdb:genre:war", type: "series", tags: ["war", "military", "genre", "newest", "shows", "tv", "tmdb"] },
          { name: "Western Movies", url: "tmdb:genre:western", type: "movie", tags: ["western", "cowboy", "genre", "newest", "tmdb"] },
          { name: "Western Shows", url: "tmdb:genre:western", type: "series", tags: ["western", "cowboy", "genre", "newest", "shows", "tv", "tmdb"] },
          { name: "Simkl Anime Trending", url: "simkl:anime:trending", type: "series", source: "Simkl", user: "Simkl Official", tags: ["simkl", "anime", "trending", "animation", "japanese", "otaku", "charts"] },
          { name: "Simkl Top 50 Anime", url: "simkl:anime:top", type: "series", source: "Simkl", user: "Simkl Official", tags: ["simkl", "anime", "top", "best", "popular", "animation", "charts"] },
          { name: "Simkl Airing Anime", url: "simkl:anime:airing", type: "series", source: "Simkl", user: "Simkl Official", tags: ["simkl", "anime", "airing", "new", "season", "charts"] },
          { name: "Simkl Trending Shows", url: "simkl:shows:trending", type: "series", source: "Simkl", user: "Simkl Official", tags: ["simkl", "shows", "trending", "tv", "popular", "charts"] },
          { name: "Simkl Trending Movies", url: "simkl:movies:trending", type: "movie", source: "Simkl", user: "Simkl Official", tags: ["simkl", "movies", "trending", "popular", "charts"] },
        ];

        for (const chart of builtinTmdbCharts) {
          const matchName = chart.name.toLowerCase().includes(qLower);
          const matchTag = chart.tags.some((t) => t.includes(qLower) || qLower.includes(t));
          const matchUser = chart.user && chart.user.toLowerCase().includes(qLower);
          if (matchName || matchTag || matchUser) {
            results.push({
              name: chart.name,
              user: chart.user || "TMDB Official",
              url: chart.url,
              type: chart.type,
              items: "Chart",
              likes: 0,
              source: chart.source || "TMDB",
            });
          }
        }

        return json({ ok: true, lists: results.slice(0, 30) });
      } catch (err) {
        return json({ ok: false, error: safeErrorMessage(err), lists: [] });
      }
    }

    // /api/trakt-search?q=...
    // -> powers the "Search Trakt Lists" box in the builder page. Proxies
    // trakt.tv's public list-search endpoint so people can find and add
    // public trakt.tv lists with a click instead of copy-pasting URLs.
    if (path === "/api/trakt-search") {
      const q = url.searchParams.get("q") || "";
      const traktKey = url.searchParams.get("traktKey") || "";

      try {
        const lists = await searchTraktLists(q, traktKey);
        if (!traktKey) ctx.waitUntil(bumpStatBy(env, "apiuse:trakt", 1 + lists.length));
        return json({ ok: true, lists });
      } catch (err) {
        return json({ ok: false, error: safeErrorMessage(err) });
      }
    }

    // /api/trakt-popular-lists?traktKey=...
    // -> returns popular public community lists directly from Trakt's API
    if (path === "/api/trakt-popular-lists") {
      const traktKeyParam = url.searchParams.get("traktKey") || "";
      const traktKey = traktKeyParam || TRAKT_CLIENT_ID;
      if (!traktKey) {
        return json({ ok: false, lists: [] });
      }
      try {
        const cacheKey = "user_cache:trakt:popular-lists";
        const kvKey = "trakt:popular-lists";
        const lists = await fetchWithPerUserCacheAndCircuitBreaker({
          cacheKey,
          kvKey,
          env,
          ctx,
          freshTtlSec: 3600,
          staleTtlSec: 86400,
          kvTtlSec: 86400,
          providerLabel: "Trakt Popular Lists",
          fetchFn: async () => {
            const src = "https://api.trakt.tv/lists/popular?limit=30";
            const res = await fetchTraktWithRetry(src, {
              headers: {
                "Content-Type": "application/json",
                "trakt-api-version": "2",
                "trakt-api-key": traktKey,
                "User-Agent": `my-list-addon/${ADDON_VERSION}`,
              },
              cf: { cacheTtl: 3600, cacheEverything: true },
            });
            if (!res.ok) {
              throw new Error(`Trakt popular lists failed (HTTP ${res.status}).`);
            }
            const data = await res.json();
            return (Array.isArray(data) ? data : [])
              .map((r) => r.list || r)
              .filter((l) => l && l.ids && l.ids.slug && l.user && (l.user.username || (l.user.ids && l.user.ids.slug)))
              .map((l) => {
                const username = l.user.username || l.user.ids.slug;
                const slug = l.ids.slug;
                return {
                  name: l.name,
                  user: username,
                  slug: slug,
                  items: l.item_count || 0,
                  likes: l.likes || 0,
                  url: `https://trakt.tv/users/${encodeURIComponent(username)}/lists/${encodeURIComponent(slug)}`,
                  type: "movie",
                };
              });
          },
        });
        return json({ ok: true, lists });
      } catch (err) {
        return json({ ok: false, lists: [] });
      }
    }

    // /api/trakt-my-lists?username=...&traktKey=...
    // -> powers the "Your Trakt Lists" section in the builder: once someone
    // fills in a Trakt username, this lists everything they've made public
    // at trakt.tv/users/:username/lists (public data -- no OAuth/user-level
    // token needed, just the usual app-level Trakt-Api-Key, same as every
    // other Trakt call here). traktKey overrides the shared TRAKT_CLIENT_ID
    // the same way it does everywhere else.
    if (path === "/api/trakt-my-lists") {
      const username = (url.searchParams.get("username") || "").trim();
      const traktKeyParam = url.searchParams.get("traktKey") || "";
      if (!username) return json({ ok: false, error: "Missing username." }, 400);
      const traktKey = traktKeyParam || TRAKT_CLIENT_ID;
      if (!traktKey) {
        return json({ ok: false, error: "Trakt lists aren't configured on this add-on yet — enter a Trakt Client ID above, or ask the Worker owner to set TRAKT_CLIENT_ID." });
      }
      try {
        const src = `https://api.trakt.tv/users/${encodeURIComponent(username)}/lists`;
        const res = await fetchTraktWithRetry(src, {
          headers: {
            "Content-Type": "application/json",
            "trakt-api-version": "2",
            "trakt-api-key": traktKey,
            "User-Agent": `my-list-addon/${ADDON_VERSION}`,
          },
          cf: { cacheTtl: 300, cacheEverything: true },
        });
        if (!res.ok) {
          if (res.status === 404) {
            return json({ ok: false, error: `No Trakt user found with the username "${username}".` });
          }
          if (res.status === 403) {
            return json({
              ok: false,
              error: traktKeyParam
                ? "Trakt rejected the Client ID you entered (HTTP 403 = invalid or unapproved app). Double check it against https://trakt.tv/oauth/applications."
                : "Trakt rejected this add-on's API key (HTTP 403 = invalid or unapproved app). Enter your own Trakt Client ID above to bypass this, or ask the Worker owner to fix TRAKT_CLIENT_ID.",
            });
          }
          if (res.status === 429) {
            return json({ ok: false, error: "Trakt is temporarily busy (rate limit). Please wait a few seconds and try again." });
          }
          return json({ ok: false, error: `Trakt request failed (HTTP ${res.status}).` });
        }
        const data = await res.json();
        const customLists = (Array.isArray(data) ? data : [])
          .filter((l) => l && l.ids && l.ids.slug)
          .map((l) => {
            const name = l.name || "";
            const isMovie = /\bmovie(s)?\b/i.test(name);
            const isSeries = /\b(show|shows|series|anime|tv|season(s)?)\b/i.test(name);
            const contentType = isMovie && !isSeries ? "movie" : (isSeries && !isMovie ? "series" : "unknown");
            return {
              name: l.name,
              slug: l.ids.slug,
              items: l.item_count || 0,
              likes: l.likes || 0,
              contentType,
              url: `https://trakt.tv/users/${encodeURIComponent(username)}/lists/${encodeURIComponent(l.ids.slug)}`,
            };
          });

        let watchlistCount = 0;
        let airingCandidates = [];
        try {
          const [wlRes, wShowsRes, wlShowsRes] = await Promise.all([
            fetchTraktWithRetry(`https://api.trakt.tv/users/${encodeURIComponent(username)}/watchlist?limit=1&page=1`, {
              headers: { "Content-Type": "application/json", "trakt-api-version": "2", "trakt-api-key": traktKey, "User-Agent": `my-list-addon/${ADDON_VERSION}` },
              cf: { cacheTtl: 120, cacheEverything: false },
            }).catch(() => null),
            fetchTraktWithRetry(`https://api.trakt.tv/users/${encodeURIComponent(username)}/watched/shows?extended=noseasons`, {
              headers: { "Content-Type": "application/json", "trakt-api-version": "2", "trakt-api-key": traktKey, "User-Agent": `my-list-addon/${ADDON_VERSION}` },
              cf: { cacheTtl: 120, cacheEverything: false },
            }).catch(() => null),
            fetchTraktWithRetry(`https://api.trakt.tv/users/${encodeURIComponent(username)}/watchlist/shows?limit=50`, {
              headers: { "Content-Type": "application/json", "trakt-api-version": "2", "trakt-api-key": traktKey, "User-Agent": `my-list-addon/${ADDON_VERSION}` },
              cf: { cacheTtl: 120, cacheEverything: false },
            }).catch(() => null),
          ]);

          if (wlRes && wlRes.ok) {
            watchlistCount = parseInt(wlRes.headers.get("X-Pagination-Item-Count") || "0", 10) || 0;
          }

          const rawAiring = [];
          if (wShowsRes && wShowsRes.ok) {
            const wData = await wShowsRes.json().catch(() => []);
            if (Array.isArray(wData)) rawAiring.push(...wData);
          }
          if (wlShowsRes && wlShowsRes.ok) {
            const wlData = await wlShowsRes.json().catch(() => []);
            if (Array.isArray(wlData)) rawAiring.push(...wlData);
          }

          const seenIds = new Set();
          for (const it of rawAiring) {
            const show = it.show || it;
            if (show && show.ids) {
              const imdbId = show.ids.imdb || "";
              const tmdbId = show.ids.tmdb || "";
              const bestId = imdbId || (tmdbId ? `tmdb:${tmdbId}` : "");
              if (bestId && !seenIds.has(bestId)) {
                seenIds.add(bestId);
                airingCandidates.push({
                  id: bestId,
                  imdbId: imdbId || null,
                  tmdbId: tmdbId || null,
                  name: show.title || "",
                  year: show.year || "",
                  poster: imdbId ? `https://images.metahub.space/poster/medium/${imdbId}/img` : "",
                  type: "series",
                  lastWatched: it.last_watched_at || null,
                });
              }
            }
          }
        } catch {}

        const airingNextCard = {
          name: "Trakt Airing Next",
          slug: "airing-next",
          statusKey: "airing-next",
          type: "series",
          contentType: "series",
          itemCount: airingCandidates.length,
          items: airingCandidates,
          private: true,
          url: "trakt:user:shows:airing-next",
        };

        const watchlistCard = {
          name: "Watchlist",
          slug: "watchlist",
          items: watchlistCount,
          likes: 0,
          private: true,
          url: `https://trakt.tv/users/${encodeURIComponent(username)}/watchlist`,
          contentType: "unknown",
        };

        const historyCard = {
          name: "Watch History",
          slug: "history",
          items: 0,
          likes: 0,
          private: true,
          url: `https://trakt.tv/users/${encodeURIComponent(username)}/history`,
          contentType: "unknown",
        };

        if (!traktKeyParam) ctx.waitUntil(bumpStat(env, "apiuse:trakt"));
        return json({ ok: true, lists: [airingNextCard, watchlistCard, historyCard, ...customLists], username });
      } catch (err) {
        return json({ ok: false, error: safeErrorMessage(err) });
      }
    }

    // --- Trakt OAuth (private lists) ----------------------------------------
    //
    // Everything above this point only ever needed TRAKT_CLIENT_ID (an
    // app-level key, same for every visitor) since it's all public data.
    // A private list is only visible to its own owner, which Trakt only
    // recognizes via a real user-level OAuth token -- this is that flow.
    // TRAKT_CLIENT_SECRET is a genuine secret (unlike TRAKT_CLIENT_ID,
    // which is already public-facing in every request this Worker makes)
    // and must be set via `wrangler secret put TRAKT_CLIENT_SECRET`, never
    // hardcoded here.
    //
    // No server-side token storage: the resulting access token is handed
    // straight back to the browser and saved into the person's own config,
    // the same way their MDBList key or Trakt Client ID already are (see
    // traktAccessToken throughout). That keeps this consistent with how
    // every other credential in this add-on works -- nothing here is tied
    // to an account on this Worker -- at the cost of no silent background
    // refresh: Trakt access tokens last about 3 months, and reconnecting
    // after that is a deliberate manual step, not automatic.

    // /api/trakt/oauth/start -> redirects to Trakt's own login/approve page.
    // A short-lived, HttpOnly state cookie (scoped to just this OAuth path)
    // guards against CSRF -- the callback below refuses to proceed unless
    // the state Trakt hands back matches what was stored here.
    if (path === "/api/trakt/oauth/start") {
      if (!TRAKT_CLIENT_ID) {
        return new Response("Trakt isn't configured on this Worker (missing TRAKT_CLIENT_ID).", { status: 500 });
      }
      const state = generateShortId();
      const redirectUri = `${url.origin}/api/trakt/oauth/callback`;
      const authorizeUrl =
        `https://trakt.tv/oauth/authorize?response_type=code&client_id=${encodeURIComponent(TRAKT_CLIENT_ID)}` +
        `&redirect_uri=${encodeURIComponent(redirectUri)}&state=${encodeURIComponent(state)}`;
      // ?debug=1 -> shows the exact values as plain text instead of
      // redirecting, so a redirect_uri mismatch against what's registered
      // at trakt.tv/oauth/applications can be spotted directly (copy/paste
      // comparison) instead of needing to catch a fleeting 302 in devtools.
      // Not a security concern to expose -- everything shown here (origin,
      // Client ID, computed callback URL) is either already public or
      // derived from the request itself; no secret ever appears.
      if (url.searchParams.get("debug") === "1") {
        return new Response(
          `Worker sees this request's origin as:\n  ${url.origin}\n\n` +
            `It will send Trakt exactly this redirect_uri:\n  ${redirectUri}\n\n` +
            `That needs to appear byte-for-byte in your Trakt app's Redirect URI list at\n  https://trakt.tv/oauth/applications\n\n` +
            `Full authorize URL it would redirect to:\n  ${authorizeUrl}\n`,
          { headers: { "Content-Type": "text/plain; charset=utf-8" } }
        );
      }
      return new Response(null, {
        status: 302,
        headers: {
          Location: authorizeUrl,
          // SameSite=Lax (not Strict) -- this cookie has to survive the
          // top-level cross-site redirect Trakt sends the browser back
          // through to reach the callback below; Strict cookies aren't
          // sent on that kind of navigation.
          "Set-Cookie": `mla_trakt_state=${state}; Path=/api/trakt/oauth; HttpOnly; Secure; SameSite=Lax; Max-Age=600`,
        },
      });
    }

    // /api/trakt/oauth/callback -> exchanges the code Trakt sends back for
    // an access token, then redirects to the builder page with that token
    // in a URL *fragment* (#trakt_token=...) rather than a query string --
    // fragments are never sent to any server on subsequent requests or
    // typically written to server access logs, unlike a query param would
    // be. The builder page's own init script reads it from
    // location.hash, saves it, and strips it from the address bar
    // immediately (see the client-side pickUpTraktTokenFromUrl below).
    if (path === "/api/trakt/oauth/callback") {
      const cookies = parseCookies(request);
      const expectedState = cookies.mla_trakt_state || "";
      const clearStateCookie = "mla_trakt_state=; Path=/api/trakt/oauth; HttpOnly; Secure; SameSite=Lax; Max-Age=0";
      const failWith = (reason, detail) => {
        const params = new URLSearchParams({ trakt_error: reason });
        if (detail) params.set("trakt_error_detail", detail);
        return new Response(null, {
          status: 302,
          headers: { Location: `${url.origin}/?${params.toString()}`, "Set-Cookie": clearStateCookie },
        });
      };

      if (url.searchParams.get("error")) return failWith(url.searchParams.get("error"));
      const code = url.searchParams.get("code") || "";
      const state = url.searchParams.get("state") || "";
      if (!code || !state || !expectedState || !timingSafeEqualHex(state, expectedState)) {
        return failWith("state_mismatch");
      }
      if (!env || !env.TRAKT_CLIENT_SECRET) return failWith("not_configured");

      try {
        const redirectUri = `${url.origin}/api/trakt/oauth/callback`;
        const traktHeaders = {
          "Content-Type": "application/json",
          "Accept": "application/json",
          "trakt-api-version": "2",
          "trakt-api-key": TRAKT_CLIENT_ID,
          "User-Agent": "my-list-addon/1.4",
        };
        const tokenBody = JSON.stringify({
          code,
          client_id: TRAKT_CLIENT_ID,
          client_secret: env.TRAKT_CLIENT_SECRET,
          redirect_uri: redirectUri,
          grant_type: "authorization_code",
        });

        let tokenRes = null;
        const delays = [0, 1000, 2000, 3000];
        for (const delay of delays) {
          if (delay > 0) await new Promise((r) => setTimeout(r, delay));
          try {
            tokenRes = await fetch("https://api.trakt.tv/oauth/token", {
              method: "POST",
              headers: traktHeaders,
              body: tokenBody,
            });
            if (tokenRes.ok) break;
            if (tokenRes.status !== 429 && tokenRes.status !== 403 && tokenRes.status !== 503) {
              break;
            }
          } catch {}
        }
        if (!tokenRes || !tokenRes.ok) {
          let detail = tokenRes ? `HTTP ${tokenRes.status}` : "Network failed";
          try {
            if (tokenRes) {
              const text = await tokenRes.text();
              try {
                const errBody = JSON.parse(text);
                if (errBody && (errBody.error || errBody.error_description)) {
                  detail = [errBody.error, errBody.error_description].filter(Boolean).join(": ");
                } else if (text) {
                  detail = text.slice(0, 200);
                }
              } catch {
                if (text) detail = text.slice(0, 200);
              }
            }
          } catch {}
          return failWith("exchange_failed", detail);
        }
        const tokenData = await tokenRes.json();
        if (!tokenData.access_token) return failWith("no_token");
        let traktUsername = "";
        try {
          const meRes = await fetch("https://api.trakt.tv/users/me", {
            headers: {
              "Content-Type": "application/json",
              "Authorization": `Bearer ${tokenData.access_token}`,
              "trakt-api-version": "2",
              "trakt-api-key": clientId || TRAKT_CLIENT_ID,
              "User-Agent": "my-list-addon/1.4",
            },
          });
          if (meRes.ok) {
            const meData = await meRes.json();
            if (meData && meData.username) traktUsername = meData.username;
          }
        } catch {}
        return new Response(null, {
          status: 302,
          headers: {
            Location: `${url.origin}/#trakt_token=${encodeURIComponent(tokenData.access_token)}${traktUsername ? `&trakt_username=${encodeURIComponent(traktUsername)}` : ""}`,
            "Set-Cookie": clearStateCookie,
          },
        });
      } catch {
        return failWith("network");
      }
    }

    // /api/trakt/device/code -> starts Trakt device activation flow (bypasses browser redirects & 1015)
    if (path === "/api/trakt/device/code" && request.method === "POST") {
      let body = {};
      try { body = await request.json(); } catch {}
      const userKey = String(body.traktKey || body.clientId || "").trim();
      const clientId = userKey || TRAKT_CLIENT_ID || (env && env.TRAKT_CLIENT_ID) || "";
      if (!clientId) return json({ ok: false, error: "Trakt Client ID is not configured. Add your Trakt Client ID in Settings." }, 400);
      try {
        let res = await fetch("https://api.trakt.tv/oauth/device/code", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "trakt-api-version": "2",
            "trakt-api-key": clientId,
            "User-Agent": `my-list-addon/${ADDON_VERSION}`,
          },
          body: JSON.stringify({ client_id: clientId }),
        });

        // If rate limited by Trakt (429), automatically wait and retry once
        if (res.status === 429) {
          const retrySec = parseInt(res.headers.get("Retry-After") || "2", 10);
          await new Promise((resolve) => setTimeout(resolve, Math.min(3000, Math.max(1000, retrySec * 1000))));
          res = await fetch("https://api.trakt.tv/oauth/device/code", {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
              "trakt-api-version": "2",
              "trakt-api-key": clientId,
              "User-Agent": `my-list-addon/${ADDON_VERSION}`,
            },
            body: JSON.stringify({ client_id: clientId }),
          });
        }

        const data = await res.json().catch(() => ({}));
        if (!res.ok) {
          const errMsg = data.error_description || data.error || (res.status === 429 ? "Trakt is busy (rate limit). Please wait a few seconds and try again." : `Trakt error (HTTP ${res.status})`);
          return json({ ok: false, error: errMsg }, res.status);
        }
        return json({ ok: true, ...data });
      } catch (err) {
        return json({ ok: false, error: safeErrorMessage(err) }, 500);
      }
    }

    // /api/trakt/device/token -> polls for authorization of device code
    if (path === "/api/trakt/device/token" && request.method === "POST") {
      let body = {};
      try { body = await request.json(); } catch {}
      const code = String(body.code || "").trim();
      const userKey = String(body.traktKey || body.clientId || "").trim();
      const clientId = userKey || TRAKT_CLIENT_ID || (env && env.TRAKT_CLIENT_ID) || "";
      const clientSecret = (env && env.TRAKT_CLIENT_SECRET) || "";
      if (!code) return json({ ok: false, error: "Device code is required." }, 400);
      if (!clientId || !clientSecret) return json({ ok: false, error: "TRAKT_CLIENT_SECRET not configured on worker." }, 500);

      try {
        const res = await fetch("https://api.trakt.tv/oauth/device/token", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "trakt-api-version": "2",
            "trakt-api-key": clientId,
            "User-Agent": `my-list-addon/${ADDON_VERSION}`,
          },
          body: JSON.stringify({
            code,
            client_id: clientId,
            client_secret: clientSecret,
          }),
        });

        if (res.status === 400) {
          return json({ ok: false, pending: true, error: "Pending authorization." }, 200);
        }
        if (res.status === 404) {
          return json({ ok: false, error: "Invalid device code." }, 404);
        }
        if (res.status === 409) {
          return json({ ok: false, error: "Code already approved or expired." }, 409);
        }
        if (res.status === 410) {
          return json({ ok: false, error: "Code expired. Please request a new code." }, 410);
        }
        if (res.status === 418) {
          return json({ ok: false, error: "Authorization was denied by user." }, 418);
        }
        if (res.status === 429) {
          return json({ ok: false, slowDown: true, error: "Slow down polling." }, 200);
        }

        const data = await res.json().catch(() => ({}));
        if (!res.ok || !data.access_token) {
          return json({ ok: false, error: data.error || `HTTP ${res.status}` }, res.status);
        }

        let traktUsername = "";
        try {
          const meRes = await fetch("https://api.trakt.tv/users/me", {
            headers: {
              "Content-Type": "application/json",
              "Authorization": `Bearer ${data.access_token}`,
              "trakt-api-version": "2",
              "trakt-api-key": clientId,
              "User-Agent": "my-list-addon/1.4",
            },
          });
          if (meRes.ok) {
            const meData = await meRes.json();
            if (meData && meData.username) traktUsername = meData.username;
          }
        } catch {}

        return json({ ok: true, access_token: data.access_token, username: traktUsername });
      } catch (err) {
        return json({ ok: false, error: safeErrorMessage(err) }, 500);
      }
    }

    // /api/mdblist/oauth/start -> redirects to MDBList login/authorization
    if (path === "/api/mdblist/oauth/start") {
      const clientId = MDBLIST_CLIENT_ID || (env && env.MDBLIST_CLIENT_ID) || "";
      if (!clientId) {
        return new Response("MDBList OAuth isn't configured on this Worker (missing MDBLIST_CLIENT_ID in Cloudflare Secrets).", { status: 500 });
      }
      const state = generateShortId();
      const { verifier, challenge } = await generatePkcePair();
      const redirectUri = url.hostname.includes("mylistsaddon.com")
        ? "https://mylistsaddon.com/api/mdblist/oauth/callback"
        : `${url.origin}/api/mdblist/oauth/callback`;
      const authorizeUrl =
        `https://mdblist.com/oauth/authorize/?response_type=code&client_id=${encodeURIComponent(clientId)}` +
        `&redirect_uri=${encodeURIComponent(redirectUri)}&state=${encodeURIComponent(state)}` +
        `&code_challenge=${encodeURIComponent(challenge)}&code_challenge_method=S256`;
      if (url.searchParams.get("debug") === "1") {
        return new Response(
          `Worker sees this request's origin as:\n  ${url.origin}\n\n` +
            `It will send MDBList exactly this redirect_uri:\n  ${redirectUri}\n\n` +
            `That needs to appear byte-for-byte in your MDBList app's Redirect URI list at\n  https://mdblist.com/developer/\n\n` +
            `Full authorize URL it would redirect to:\n  ${authorizeUrl}\n`,
          { headers: { "Content-Type": "text/plain; charset=utf-8" } }
        );
      }
      return new Response(null, {
        status: 302,
        headers: {
          Location: authorizeUrl,
          "Set-Cookie": `mla_mdblist_state=${state}:${verifier}; Path=/api/mdblist/oauth; HttpOnly; Secure; SameSite=Lax; Max-Age=600`,
        },
      });
    }

    // /api/mdblist/oauth/callback -> exchanges the code for an MDBList token
    if (path === "/api/mdblist/oauth/callback") {
      const cookies = parseCookies(request);
      const rawState = cookies.mla_mdblist_state || "";
      const [expectedState, verifier] = rawState.split(":");
      const clearStateCookie = "mla_mdblist_state=; Path=/api/mdblist/oauth; HttpOnly; Secure; SameSite=Lax; Max-Age=0";
      const failWith = (reason, detail) => {
        const params = new URLSearchParams({ mdblist_error: reason });
        if (detail) params.set("mdblist_error_detail", detail);
        return new Response(null, {
          status: 302,
          headers: { Location: `${url.origin}/?${params.toString()}`, "Set-Cookie": clearStateCookie },
        });
      };

      if (url.searchParams.get("error")) return failWith(url.searchParams.get("error"));
      const code = url.searchParams.get("code") || "";
      const state = url.searchParams.get("state") || "";
      if (!code || !state || !expectedState || !timingSafeEqualHex(state, expectedState)) {
        return failWith("state_mismatch");
      }
      const clientId = MDBLIST_CLIENT_ID || (env && env.MDBLIST_CLIENT_ID) || "";
      const clientSecret = (env && env.MDBLIST_CLIENT_SECRET) || "";
      if (!clientId || !clientSecret) return failWith("not_configured");

      try {
        const redirectUri = url.hostname.includes("mylistsaddon.com")
          ? "https://mylistsaddon.com/api/mdblist/oauth/callback"
          : `${url.origin}/api/mdblist/oauth/callback`;

        const formParams = new URLSearchParams();
        formParams.set("grant_type", "authorization_code");
        formParams.set("code", code);
        formParams.set("client_id", clientId);
        formParams.set("client_secret", clientSecret);
        formParams.set("redirect_uri", redirectUri);
        if (verifier) formParams.set("code_verifier", verifier);

        const basicAuth = btoa(`${clientId}:${clientSecret}`);

        let tokenRes = await fetch("https://api.mdblist.com/oauth/token/", {
          method: "POST",
          headers: {
            "Content-Type": "application/x-www-form-urlencoded;charset=UTF-8",
            "Authorization": `Basic ${basicAuth}`,
            "User-Agent": `my-list-addon/${ADDON_VERSION}`,
            "Accept": "application/json",
          },
          body: formParams.toString(),
        });

        if (!tokenRes.ok) {
          // Fallback: try without Authorization header (credentials in form body only)
          const fallbackRes = await fetch("https://api.mdblist.com/oauth/token/", {
            method: "POST",
            headers: {
              "Content-Type": "application/x-www-form-urlencoded;charset=UTF-8",
              "User-Agent": `my-list-addon/${ADDON_VERSION}`,
              "Accept": "application/json",
            },
            body: formParams.toString(),
          });
          if (fallbackRes.ok) {
            tokenRes = fallbackRes;
          }
        }

        if (!tokenRes.ok) {
          let detail = `HTTP ${tokenRes.status}`;
          try {
            const text = await tokenRes.text();
            try {
              const errBody = JSON.parse(text);
              if (errBody && (errBody.error || errBody.error_description || errBody.message)) {
                detail = [errBody.error, errBody.error_description, errBody.message].filter(Boolean).join(": ");
              } else if (text) {
                detail = text.slice(0, 200);
              }
            } catch {
              if (text) detail = text.slice(0, 200);
            }
          } catch {}
          return failWith("exchange_failed", detail);
        }
        const tokenData = await tokenRes.json();
        const token = tokenData.access_token || tokenData.apikey || tokenData.token;
        if (!token) return failWith("no_token");
        let mdblistUsername = tokenData.username || tokenData.user || "";
        if (!mdblistUsername) {
          try {
            const uRes = await fetch(`https://api.mdblist.com/user?apikey=${encodeURIComponent(token)}`, {
              headers: { "User-Agent": `my-list-addon/${ADDON_VERSION}` }
            });
            if (uRes.ok) {
              const uData = await uRes.json();
              if (uData && (uData.username || uData.user_name || uData.name)) {
                mdblistUsername = uData.username || uData.user_name || uData.name;
              }
            }
          } catch {}
        }
        return new Response(null, {
          status: 302,
          headers: {
            Location: `${url.origin}/#mdblist_token=${encodeURIComponent(token)}${mdblistUsername ? `&mdblist_username=${encodeURIComponent(mdblistUsername)}` : ""}`,
            "Set-Cookie": clearStateCookie,
          },
        });
      } catch (err) {
        return failWith("network", safeErrorMessage(err));
      }
    }

    // /api/simkl/oauth/start -> redirects to Simkl login/authorization
    if (path === "/api/simkl/oauth/start") {
      const clientId = SIMKL_CLIENT_ID || (env && env.SIMKL_CLIENT_ID) || "";
      if (!clientId) {
        return new Response("Simkl OAuth isn't configured on this Worker (missing SIMKL_CLIENT_ID).", { status: 500 });
      }
      const state = generateShortId();
      const redirectUri = url.hostname.includes("mylistsaddon.com")
        ? "https://mylistsaddon.com/api/simkl/oauth/callback"
        : `${url.origin}/api/simkl/oauth/callback`;
      const authorizeUrl = `https://simkl.com/oauth/authorize?response_type=code&client_id=${encodeURIComponent(clientId)}&redirect_uri=${encodeURIComponent(redirectUri)}&state=${encodeURIComponent(state)}&app-name=MyListsAddon&app-version=${encodeURIComponent(ADDON_VERSION)}`;
      return new Response(null, {
        status: 302,
        headers: {
          Location: authorizeUrl,
          "Set-Cookie": `mla_simkl_state=${state}; Path=/api/simkl/oauth; HttpOnly; Secure; SameSite=Lax; Max-Age=600`,
        },
      });
    }

    // /api/simkl/oauth/callback -> exchanges authorization code for Simkl access token
    if (path === "/api/simkl/oauth/callback") {
      const cookies = parseCookies(request);
      const stateCookie = cookies.mla_simkl_state || "";
      const clearStateCookie = "mla_simkl_state=; Path=/api/simkl/oauth; HttpOnly; Secure; SameSite=Lax; Max-Age=0";
      const failWith = (code, detail) => {
        const dest = `${url.origin}/#settings&simkl_error=${encodeURIComponent(code)}` +
          (detail ? `&simkl_error_detail=${encodeURIComponent(detail)}` : "");
        return new Response(null, { status: 302, headers: { Location: dest, "Set-Cookie": clearStateCookie } });
      };

      const clientId = SIMKL_CLIENT_ID || (env && env.SIMKL_CLIENT_ID) || "";
      const clientSecret = SIMKL_CLIENT_SECRET || (env && env.SIMKL_CLIENT_SECRET) || "";
      if (!clientId) return failWith("not_configured");

      const q = new URLSearchParams(url.search);
      const code = q.get("code");
      const state = q.get("state");
      const err = q.get("error");
      if (err) return failWith("access_denied", q.get("error_description") || err);
      if (!code) return failWith("no_code");
      if (!stateCookie) return failWith("state_mismatch", "missing cookie");
      if (state !== stateCookie) return failWith("state_mismatch", "state mismatch");

      const redirectUri = url.hostname.includes("mylistsaddon.com")
        ? "https://mylistsaddon.com/api/simkl/oauth/callback"
        : `${url.origin}/api/simkl/oauth/callback`;

      try {
        const tokenRes = await fetch("https://api.simkl.com/oauth/token", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "User-Agent": `my-list-addon/${ADDON_VERSION}`,
            "Accept": "application/json",
          },
          body: JSON.stringify({
            code,
            client_id: clientId,
            client_secret: clientSecret,
            redirect_uri: redirectUri,
            grant_type: "authorization_code",
          }),
        });

        if (!tokenRes.ok) {
          let detail = `HTTP ${tokenRes.status}`;
          try {
            const text = await tokenRes.text();
            try {
              const errBody = JSON.parse(text);
              if (errBody && (errBody.error || errBody.error_description || errBody.message)) {
                detail = [errBody.error, errBody.error_description, errBody.message].filter(Boolean).join(": ");
              } else if (text) {
                detail = text.slice(0, 200);
              }
            } catch {
              if (text) detail = text.slice(0, 200);
            }
          } catch {}
          return failWith("exchange_failed", detail);
        }
        const tokenData = await tokenRes.json();
        const token = tokenData.access_token || tokenData.token;
        if (!token) return failWith("no_token");
        let simklUsername = "";
        try {
          const uRes = await fetch("https://api.simkl.com/users/settings", {
            headers: {
              "Authorization": `Bearer ${token}`,
              "simkl-api-key": clientId,
              "User-Agent": `my-list-addon/${ADDON_VERSION}`,
              "Accept": "application/json",
            },
          });
          if (uRes.ok) {
            const uData = await uRes.json();
            if (uData && uData.user && (uData.user.username || uData.user.name)) {
              simklUsername = uData.user.username || uData.user.name;
            }
          }
        } catch {}

        return new Response(null, {
          status: 302,
          headers: {
            Location: `${url.origin}/#simkl_token=${encodeURIComponent(token)}${simklUsername ? `&simkl_username=${encodeURIComponent(simklUsername)}` : ""}`,
            "Set-Cookie": clearStateCookie,
          },
        });
      } catch (err) {
        return failWith("network", safeErrorMessage(err));
      }
    }

    // /api/simkl/my-lists -> returns authenticated user's personal Simkl watchlists
    if (path === "/api/simkl/my-lists") {
      let token = request.headers.get("Authorization")?.replace(/^Bearer\s+/i, "") || url.searchParams.get("token") || "";
      let manualKey = url.searchParams.get("simklKey") || "";
      if (request.method === "POST") {
        try {
          const body = await request.json();
          if (body.token) token = body.token;
          if (body.simklKey) manualKey = body.simklKey;
        } catch {}
      }
      const clientId = manualKey || SIMKL_CLIENT_ID || (env && env.SIMKL_CLIENT_ID) || "";
      if (!token) {
        return json({ ok: false, error: "Please connect your Simkl account first." }, 400);
      }
      try {
        // extended=full is required to get watched_episodes_count/
        // total_episodes_count/not_aired_episodes_count back on each item --
        // without it Simkl's default (summary) shape omits or zeroes these,
        // which breaks isCaughtUp's fallback check in
        // enrichSimklAiringNextDates (17_client-my-lists-and-trakt-oauth.js)
        // for any show whose completion isn't otherwise obvious from
        // status alone. No date_from on purpose -- this always wants the
        // full current watchlist, not a delta since a stored checkpoint.
        const res = await fetch("https://api.simkl.com/sync/all-items/?extended=full", {
          headers: {
            "Authorization": `Bearer ${token}`,
            "simkl-api-key": clientId,
            "User-Agent": `my-list-addon/${ADDON_VERSION}`,
            "Accept": "application/json",
          },
        });
        if (!res.ok) {
          return json({ ok: false, error: `Simkl sync request failed (HTTP ${res.status}).` }, res.status);
        }
        const data = await res.json();
        const statusLabels = {
          plantowatch: "Plan to Watch",
          watching: "Watching",
          completed: "Completed",
          hold: "On Hold",
          dropped: "Dropped",
        };

        const lists = [];
        const categories = [
          { key: "movies", type: "movie", label: "Movies" },
          { key: "shows", type: "series", label: "Shows" },
          { key: "anime", type: "series", label: "Anime" },
        ];

        for (const cat of categories) {
          const itemsArr = Array.isArray(data[cat.key]) ? data[cat.key] : [];
          if (!itemsArr.length) continue;
          const byStatus = {};
          for (const item of itemsArr) {
            const st = item.status || "plantowatch";
            if (!byStatus[st]) byStatus[st] = [];
            const mediaObj = item.movie || item.show || item.anime;
            if (mediaObj) {
              const ids = mediaObj.ids || {};
              const imdbId = ids.imdb || "";
              const tmdbId = ids.tmdb || "";
              const simklId = ids.simkl || "";
              const bestId = imdbId || (tmdbId ? `tmdb:${tmdbId}` : (simklId ? `simkl:${simklId}` : ""));
              if (bestId) {
                byStatus[st].push({
                  id: bestId,
                  imdbId: imdbId || null,
                  tmdbId: tmdbId || null,
                  name: mediaObj.title || "",
                  year: mediaObj.year || "",
                  poster: ids.poster ? `https://simkl.in/posters/${ids.poster}_m.jpg` : (imdbId ? `https://images.metahub.space/poster/medium/${imdbId}/img` : ""),
                  type: cat.type,
                });
              }
            }
          }

          for (const [stKey, stItems] of Object.entries(byStatus)) {
            if (!stItems.length) continue;
            const stLabel = statusLabels[stKey] || stKey;
            lists.push({
              name: `Simkl ${stLabel} (${cat.label})`,
              type: cat.type,
              itemCount: stItems.length,
              statusKey: stKey,
              categoryKey: cat.key,
              items: stItems,
              url: `simkl:user:${cat.key}:${stKey}`,
            });
          }
        }

        const airingCandidateItems = [
          ...(Array.isArray(data.shows) ? data.shows : []),
          ...(Array.isArray(data.anime) ? data.anime : []),
        ].filter((it) => (it.status === "watching" || it.status === "completed"));

        airingCandidateItems.sort((a, b) => {
          const aTime = a.last_watched_at ? new Date(a.last_watched_at).getTime() : 0;
          const bTime = b.last_watched_at ? new Date(b.last_watched_at).getTime() : 0;
          if (a.status === "watching" && b.status !== "watching") return -1;
          if (b.status === "watching" && a.status !== "watching") return 1;
          return bTime - aTime;
        });

        const seenAiringIds = new Set();
        const dedupedAiring = [];
        for (const item of airingCandidateItems) {
          const mediaObj = item.show || item.anime;
          if (mediaObj && mediaObj.ids) {
            const imdbId = mediaObj.ids.imdb || "";
            const tmdbId = mediaObj.ids.tmdb || "";
            const simklId = mediaObj.ids.simkl || "";
            const bestId = imdbId || (tmdbId ? `tmdb:${tmdbId}` : (simklId ? `simkl:${simklId}` : ""));
            if (bestId && !seenAiringIds.has(bestId)) {
              seenAiringIds.add(bestId);
              dedupedAiring.push({
                id: bestId,
                imdbId: imdbId || null,
                tmdbId: tmdbId || null,
                name: mediaObj.title || "",
                year: mediaObj.year || "",
                poster: mediaObj.ids.poster ? `https://simkl.in/posters/${mediaObj.ids.poster}_m.jpg` : (imdbId ? `https://images.metahub.space/poster/medium/${imdbId}/img` : ""),
                type: "series",
                status: item.status || "watching",
                watchedCount: item.watched_episodes_count,
                totalCount: item.total_episodes_count,
                lastWatched: item.last_watched || null,
              });
            }
          }
        }

        if (dedupedAiring.length > 0) {
          lists.unshift({
            name: "Simkl Airing Next",
            type: "series",
            itemCount: dedupedAiring.length,
            statusKey: "airing-next",
            categoryKey: "shows",
            items: dedupedAiring,
            url: "simkl:user:shows:airing-next",
          });
        }
        let simklUsername = "";
        try {
          const uRes = await fetch("https://api.simkl.com/users/settings", {
            headers: {
              "Authorization": `Bearer ${token}`,
              "simkl-api-key": clientId,
              "User-Agent": `my-list-addon/${ADDON_VERSION}`,
              "Accept": "application/json",
            },
          });
          if (uRes.ok) {
            const uData = await uRes.json();
            if (uData && uData.user && (uData.user.username || uData.user.name)) {
              simklUsername = uData.user.username || uData.user.name;
            }
          }
        } catch {}

        return json({ ok: true, lists, username: simklUsername });
      } catch (err) {
        return json({ ok: false, error: safeErrorMessage(err) }, 500);
      }
    }

    // /api/external-list/item-mutate -> adds or removes items on external provider accounts (Trakt, Simkl, TMDB, MDBList)
    if ((path === "/api/external-list/item-mutate" || path === "/api/external-list/item-add" || path === "/api/external-list/item-remove") && request.method === "POST") {
      let body = {};
      try {
        body = await request.json();
      } catch {
        return json({ ok: false, error: "Invalid JSON body." }, 400);
      }

      const action = (path.endsWith("/item-remove") || body.action === "remove") ? "remove" : "add";
      const provider = (body.provider || "").toLowerCase().trim();
      const target = (body.target || "watchlist").toLowerCase().trim(); // watchlist | favorite | history | custom | status
      const listId = body.listId || body.status || "";
      const mediaType = (body.mediaType === "series" || body.type === "series" || body.type === "tv" || body.type === "episode") ? "series" : "movie";
      const title = body.title || body.name || "";
      const year = body.year || "";
      let id = String(body.id || "").trim();
      let imdbId = String(body.imdbId || "").trim();
      let tmdbId = String(body.tmdbId || "").trim();

      let seasonNum = body.season != null ? parseInt(body.season, 10) : (body.seasonNum != null ? parseInt(body.seasonNum, 10) : null);
      let episodeNum = body.episode != null ? parseInt(body.episode, 10) : (body.episodeNum != null ? parseInt(body.episodeNum, 10) : null);

      if (id.includes(":")) {
        const parts = id.split(":");
        if (parts[0].startsWith("tt") || parts[0].startsWith("tmdb")) {
          if (!imdbId && parts[0].startsWith("tt")) imdbId = parts[0];
          if (!tmdbId && parts[0].startsWith("tmdb:")) tmdbId = parts[0].slice(5);
          if (seasonNum == null && !isNaN(parseInt(parts[1], 10))) seasonNum = parseInt(parts[1], 10);
          if (episodeNum == null && !isNaN(parseInt(parts[2], 10))) episodeNum = parseInt(parts[2], 10);
        }
      }

      if (!imdbId && id.startsWith("tt")) imdbId = id;
      if (!tmdbId && id.startsWith("tmdb:")) tmdbId = id.slice(5);

      if (imdbId.includes(":")) imdbId = imdbId.split(":")[0];
      if (tmdbId.includes(":")) tmdbId = tmdbId.split(":")[0];

      const apiKeyTmdb = TMDB_API_KEY || (env && env.TMDB_API_KEY) || body.tmdbKey || "";

      // Resolve TMDB ID or IMDb ID if missing
      if (!tmdbId && imdbId && apiKeyTmdb) {
        try {
          const findRes = await fetch(`https://api.themoviedb.org/3/find/${encodeURIComponent(imdbId)}?api_key=${encodeURIComponent(apiKeyTmdb)}&external_source=imdb_id`);
          if (findRes.ok) {
            const findData = await findRes.json();
            const hit = (mediaType === "series" ? (findData.tv_results && findData.tv_results[0]) : (findData.movie_results && findData.movie_results[0])) || (findData.movie_results && findData.movie_results[0]) || (findData.tv_results && findData.tv_results[0]);
            if (hit && hit.id) tmdbId = String(hit.id);
          }
        } catch {}
      }

      if (!imdbId && tmdbId && apiKeyTmdb) {
        try {
          const detRes = await fetch(`https://api.themoviedb.org/3/${mediaType === "series" ? "tv" : "movie"}/${encodeURIComponent(tmdbId)}/external_ids?api_key=${encodeURIComponent(apiKeyTmdb)}`);
          if (detRes.ok) {
            const detData = await detRes.json();
            if (detData && detData.imdb_id) imdbId = detData.imdb_id;
          }
        } catch {}
      }

      // 1. TRAKT
      if (provider === "trakt") {
        const token = body.traktAccessToken || body.token || "";
        const clientId = body.traktKey || TRAKT_CLIENT_ID || (env && env.TRAKT_CLIENT_ID) || "";
        const username = body.traktUsername || "me";
        if (!token) return json({ ok: false, error: "Please connect your Trakt account first." }, 400);

        const idsObj = {};
        if (imdbId && imdbId.startsWith("tt")) idsObj.imdb = imdbId;
        if (tmdbId && !isNaN(parseInt(tmdbId, 10))) idsObj.tmdb = parseInt(tmdbId, 10);
        if (!idsObj.imdb && !idsObj.tmdb && id) idsObj.imdb = id.split(":")[0];

        let traktPayload = {};
        if (target === "history" && mediaType === "series" && seasonNum != null && episodeNum != null) {
          traktPayload = {
            shows: [{
              ids: idsObj,
              title: title || undefined,
              seasons: [{ number: seasonNum, episodes: [{ number: episodeNum }] }],
            }],
          };
        } else {
          const mediaKey = mediaType === "series" ? "shows" : "movies";
          traktPayload = {
            [mediaKey]: [{
              ids: idsObj,
              title: title || undefined,
              year: year ? parseInt(year, 10) : undefined,
            }],
          };
        }

        let traktUrl = `https://api.trakt.tv/sync/watchlist${action === "remove" ? "/remove" : ""}`;
        if (target === "history") {
          traktUrl = `https://api.trakt.tv/sync/history${action === "remove" ? "/remove" : ""}`;
        } else if (target === "collection") {
          traktUrl = `https://api.trakt.tv/sync/collection${action === "remove" ? "/remove" : ""}`;
        } else if (target === "custom" && listId) {
          traktUrl = `https://api.trakt.tv/users/${encodeURIComponent(username)}/lists/${encodeURIComponent(listId)}/items${action === "remove" ? "/remove" : ""}`;
        }

        try {
          const tRes = await fetch(traktUrl, {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
              "Authorization": `Bearer ${token}`,
              "trakt-api-version": "2",
              "trakt-api-key": clientId,
              "User-Agent": `my-list-addon/${ADDON_VERSION}`,
            },
            body: JSON.stringify(traktPayload),
          });
          const tData = await tRes.json().catch(() => ({}));
          if (!tRes.ok) {
            return json({ ok: false, error: tData.error || `Trakt API error (HTTP ${tRes.status})` }, tRes.status);
          }
          invalidatePerUserCache("trakt", safeUserHash(token));
          return json({ ok: true, provider: "trakt", action, target, data: tData });
        } catch (err) {
          return json({ ok: false, error: safeErrorMessage(err) }, 500);
        }
      }

      // 2. SIMKL
      if (provider === "simkl") {
        const token = body.simklAccessToken || body.token || "";
        const clientId = body.simklKey || SIMKL_CLIENT_ID || (env && env.SIMKL_CLIENT_ID) || "";
        if (!token) return json({ ok: false, error: "Please connect your Simkl account first." }, 400);

        const idsObj = {};
        if (imdbId && imdbId.startsWith("tt")) idsObj.imdb = imdbId;
        if (tmdbId && !isNaN(parseInt(tmdbId, 10))) idsObj.tmdb = parseInt(tmdbId, 10);
        if (!idsObj.imdb && !idsObj.tmdb && id) idsObj.imdb = id.split(":")[0];

        const mediaKey = mediaType === "series" ? "shows" : "movies";
        const targetStatus = target || "plantowatch";

        let simklUrl = "https://api.simkl.com/sync/add-to-list";
        let simklBody = {};

        if (target === "history") {
          simklUrl = action === "remove" ? "https://api.simkl.com/sync/history/remove" : "https://api.simkl.com/sync/history";
          if (mediaType === "series" && seasonNum != null && episodeNum != null) {
            simklBody = {
              shows: [{
                ids: idsObj,
                title: title || undefined,
                seasons: [{ number: seasonNum, episodes: [{ number: episodeNum }] }],
              }],
            };
          } else if (mediaType === "series") {
            simklBody = {
              shows: [{
                ids: idsObj,
                title: title || undefined,
              }],
            };
          } else {
            simklBody = {
              movies: [{
                ids: idsObj,
                title: title || undefined,
              }],
            };
          }
        } else if (action === "remove") {
          simklUrl = "https://api.simkl.com/sync/history/remove";
          simklBody = {
            [mediaKey]: [{
              ids: idsObj,
              title: title || undefined,
            }],
          };
        } else {
          simklBody = {
            [mediaKey]: [{
              ids: idsObj,
              to: targetStatus,
            }],
          };
        }

        try {
          const sRes = await fetch(simklUrl, {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
              "Authorization": `Bearer ${token}`,
              "simkl-api-key": clientId,
              "User-Agent": `my-list-addon/${ADDON_VERSION}`,
            },
            body: JSON.stringify(simklBody),
          });
          const sData = await sRes.json().catch(() => ({}));
          if (!sRes.ok) {
            return json({ ok: false, error: sData.error || `Simkl API error (HTTP ${sRes.status})` }, sRes.status);
          }
          invalidatePerUserCache("simkl", safeUserHash(token));
          return json({ ok: true, provider: "simkl", action, target: targetStatus, data: sData });
        } catch (err) {
          return json({ ok: false, error: safeErrorMessage(err) }, 500);
        }
      }

      // 3. TMDB
      if (provider === "tmdb") {
        const apiKey = apiKeyTmdb;
        const sessionId = body.tmdbSessionId || body.sessionId || "";
        const accountId = body.tmdbAccountId || "null";
        const v4Token = body.tmdbAccessToken || "";
        if (!apiKey) return json({ ok: false, error: "TMDB API Key missing." }, 400);
        if (!sessionId && !v4Token) return json({ ok: false, error: "Please connect your TMDB account first." }, 400);
        if (!tmdbId) return json({ ok: false, error: "Could not find a valid TMDB media ID for this title." }, 400);

        const tmdbType = mediaType === "series" ? "tv" : "movie";
        const numId = parseInt(tmdbId, 10);

        if (target === "watchlist") {
          const wUrl = `https://api.themoviedb.org/3/account/${encodeURIComponent(accountId)}/watchlist?api_key=${encodeURIComponent(apiKey)}${sessionId ? `&session_id=${encodeURIComponent(sessionId)}` : ""}`;
          try {
            const tmdbRes = await fetch(wUrl, {
              method: "POST",
              headers: {
                "Content-Type": "application/json",
                ...(v4Token ? { "Authorization": `Bearer ${v4Token}` } : {}),
                "User-Agent": `my-list-addon/${ADDON_VERSION}`,
              },
              body: JSON.stringify({ media_type: tmdbType, media_id: numId, watchlist: (action === "add") }),
            });
            const tmdbData = await tmdbRes.json().catch(() => ({}));
            if (!tmdbRes.ok || (tmdbData.success === false)) {
              return json({ ok: false, error: tmdbData.status_message || `TMDB error (HTTP ${tmdbRes.status})` }, tmdbRes.status);
            }
            invalidatePerUserCache("tmdb", safeUserHash(sessionId || v4Token));
            return json({ ok: true, provider: "tmdb", action, target: "watchlist", data: tmdbData });
          } catch (err) {
            return json({ ok: false, error: safeErrorMessage(err) }, 500);
          }
        }

        if (target === "favorite") {
          const fUrl = `https://api.themoviedb.org/3/account/${encodeURIComponent(accountId)}/favorite?api_key=${encodeURIComponent(apiKey)}${sessionId ? `&session_id=${encodeURIComponent(sessionId)}` : ""}`;
          try {
            const tmdbRes = await fetch(fUrl, {
              method: "POST",
              headers: {
                "Content-Type": "application/json",
                ...(v4Token ? { "Authorization": `Bearer ${v4Token}` } : {}),
                "User-Agent": `my-list-addon/${ADDON_VERSION}`,
              },
              body: JSON.stringify({ media_type: tmdbType, media_id: numId, favorite: (action === "add") }),
            });
            const tmdbData = await tmdbRes.json().catch(() => ({}));
            if (!tmdbRes.ok || (tmdbData.success === false)) {
              return json({ ok: false, error: tmdbData.status_message || `TMDB error (HTTP ${tmdbRes.status})` }, tmdbRes.status);
            }
            invalidatePerUserCache("tmdb", safeUserHash(sessionId || v4Token));
            return json({ ok: true, provider: "tmdb", action, target: "favorite", data: tmdbData });
          } catch (err) {
            return json({ ok: false, error: safeErrorMessage(err) }, 500);
          }
        }

        if (target === "custom" && listId) {
          const lUrl = `https://api.themoviedb.org/3/list/${encodeURIComponent(listId)}/${action === "add" ? "add_item" : "remove_item"}?api_key=${encodeURIComponent(apiKey)}${sessionId ? `&session_id=${encodeURIComponent(sessionId)}` : ""}`;
          try {
            const tmdbRes = await fetch(lUrl, {
              method: "POST",
              headers: {
                "Content-Type": "application/json",
                ...(v4Token ? { "Authorization": `Bearer ${v4Token}` } : {}),
                "User-Agent": `my-list-addon/${ADDON_VERSION}`,
              },
              body: JSON.stringify({ media_id: numId }),
            });
            const tmdbData = await tmdbRes.json().catch(() => ({}));
            if (!tmdbRes.ok || (tmdbData.success === false)) {
              return json({ ok: false, error: tmdbData.status_message || `TMDB error (HTTP ${tmdbRes.status})` }, tmdbRes.status);
            }
            invalidatePerUserCache("tmdb", safeUserHash(sessionId || v4Token));
            return json({ ok: true, provider: "tmdb", action, target: "custom", listId, data: tmdbData });
          } catch (err) {
            return json({ ok: false, error: safeErrorMessage(err) }, 500);
          }
        }
      }

      // 4. MDBLIST
      if (provider === "mdblist") {
        const accessToken = (body.mdblistAccessToken || "").trim();
        const apiKey = (body.mdblistKey || body.apikey || body.token || "").trim();
        const token = accessToken || apiKey;
        if (!token) return json({ ok: false, error: "Please connect your MDBList account or API key first." }, 400);

        const headers = {
          "Content-Type": "application/json",
          "Accept": "application/json",
          "User-Agent": `my-list-addon/${ADDON_VERSION}`,
        };
        const authParam = accessToken ? "" : `?apikey=${encodeURIComponent(apiKey || token)}`;
        if (accessToken) {
          headers["Authorization"] = `Bearer ${accessToken}`;
        } else if (apiKey) {
          headers["x-api-key"] = apiKey;
        }

        let cleanId = String(imdbId || id || "").trim();
        while (cleanId.startsWith("tmdb:")) cleanId = cleanId.slice(5).trim();
        const cleanImdb = cleanId.startsWith("tt") ? cleanId : (imdbId && imdbId.startsWith("tt") ? imdbId : null);
        const numTmdb = tmdbId ? parseInt(tmdbId, 10) : (!cleanId.startsWith("tt") && /^\d+$/.test(cleanId) ? parseInt(cleanId, 10) : null);
        const bestId = cleanImdb || numTmdb || cleanId;
        const isMovie = mediaType === "movie" || body.type === "movie";
        const mdbType = isMovie ? "movie" : "show";

        const idsObj = {};
        if (cleanImdb) idsObj.imdb = cleanImdb;
        if (numTmdb) idsObj.tmdb = numTmdb;
        if (bestId) idsObj.id = bestId;

        if (target === "watchlist") {
          const endpoints = [
            `https://api.mdblist.com/watchlist/items/${action === "add" ? "add" : "remove"}${authParam}`,
            `https://api.mdblist.com/watchlist/${action === "add" ? "add" : "remove"}${authParam}`,
          ];
          const payload = {
            id: bestId,
            imdb: cleanImdb,
            tmdb: numTmdb,
            mediatype: mdbType,
            movies: isMovie ? [idsObj] : [],
            shows: !isMovie ? [idsObj] : [],
          };
          let success = false;
          let lastErr = null;
          let mData = {};
          for (const mUrl of endpoints) {
            try {
              const mRes = await fetch(mUrl, {
                method: "POST",
                headers,
                body: JSON.stringify(payload),
              });
              mData = await mRes.json().catch(() => ({}));
              if (mRes.ok) {
                success = true;
                break;
              } else {
                lastErr = mData.error || `MDBList error (HTTP ${mRes.status})`;
              }
            } catch (err) {
              lastErr = safeErrorMessage(err);
            }
          }
          if (!success) {
            return json({ ok: false, error: lastErr || "Failed to update MDBList watchlist." }, 400);
          }
          invalidatePerUserCache("mdblist", safeUserHash(token));
          return json({ ok: true, provider: "mdblist", action, target: "watchlist", data: mData });
        }

        if (target === "history") {
          let mUrl = `https://api.mdblist.com/sync/watched${authParam}`;
          const payload = isMovie ? { movies: [idsObj] } : { shows: [idsObj] };

          try {
            const mRes = await fetch(mUrl, {
              method: "POST",
              headers,
              body: JSON.stringify(payload),
            });
            const mData = await mRes.json().catch(() => ({}));
            if (!mRes.ok) {
              let fallbackUrl = `https://api.mdblist.com/history/${action === "add" ? "add" : "remove"}${authParam}`;
              const fbRes = await fetch(fallbackUrl, {
                method: "POST",
                headers,
                body: JSON.stringify({ id: bestId, mediatype: mdbType }),
              });
              const fbData = await fbRes.json().catch(() => ({}));
              if (!fbRes.ok) {
                return json({ ok: false, error: mData.error || fbData.error || `MDBList error (HTTP ${mRes.status})` }, mRes.status);
              }
            }
            invalidatePerUserCache("mdblist", safeUserHash(token));
            return json({ ok: true, provider: "mdblist", action, target: "history", data: mData });
          } catch (err) {
            return json({ ok: false, error: safeErrorMessage(err) }, 500);
          }
        }

        if (target === "custom" && listId) {
          const endpoints = [
            `https://api.mdblist.com/lists/${encodeURIComponent(listId)}/items/${action === "add" ? "add" : "remove"}${authParam}`,
            `https://api.mdblist.com/lists/${encodeURIComponent(listId)}/${action === "add" ? "add" : "remove"}${authParam}`,
          ];
          const payload = {
            id: bestId,
            imdb: cleanImdb,
            tmdb: numTmdb,
            mediatype: mdbType,
            movies: isMovie ? [idsObj] : [],
            shows: !isMovie ? [idsObj] : [],
          };
          let success = false;
          let lastErr = null;
          let mData = {};
          for (const mUrl of endpoints) {
            try {
              const mRes = await fetch(mUrl, {
                method: "POST",
                headers,
                body: JSON.stringify(payload),
              });
              mData = await mRes.json().catch(() => ({}));
              if (mRes.ok) {
                success = true;
                break;
              } else {
                lastErr = mData.error || `MDBList error (HTTP ${mRes.status})`;
              }
            } catch (err) {
              lastErr = safeErrorMessage(err);
            }
          }
          if (!success) {
            return json({ ok: false, error: lastErr || `MDBList error` }, 400);
          }
          invalidatePerUserCache("mdblist", safeUserHash(token));
          return json({ ok: true, provider: "mdblist", action, target: "custom", listId, data: mData });
        }
      }

      return json({ ok: false, error: "Unsupported provider or target." }, 400);
    }

    // /api/external-sync/history -> bulk syncs Watch History items to Trakt, MDBList, or Simkl
    if (path === "/api/external-sync/history" && request.method === "POST") {
      let body = {};
      try {
        body = await request.json();
      } catch {
        return json({ ok: false, error: "Invalid JSON body." }, 400);
      }

      const provider = (body.provider || "").toLowerCase().trim();
      const items = Array.isArray(body.items) ? body.items : [];
      if (!items.length) {
        return json({ ok: true, syncedCount: 0, message: "No items to sync." });
      }

      function parseWatchItem(it) {
        const isMovie = it.type === "movie" || it.kind === "movie" || it.mediaType === "movie";
        let rawId = String(it.id || "").trim();
        let showId = String(it.showId || "").trim();
        let imdbId = String(it.imdbId || "").trim();
        let tmdbId = String(it.tmdbId || "").trim();

        let parsedSeason = it.seasonNum != null ? parseInt(it.seasonNum, 10) : (it.season != null ? parseInt(it.season, 10) : null);
        let parsedEpisode = it.episodeNum != null ? parseInt(it.episodeNum, 10) : (it.episode != null ? parseInt(it.episode, 10) : (it.number != null ? parseInt(it.number, 10) : null));

        if (rawId.includes(":")) {
          const parts = rawId.split(":");
          if (parts[0].startsWith("tt") || parts[0].startsWith("tmdb")) {
            if (!showId) showId = parts[0];
            if (parsedSeason == null && !isNaN(parseInt(parts[1], 10))) parsedSeason = parseInt(parts[1], 10);
            if (parsedEpisode == null && !isNaN(parseInt(parts[2], 10))) parsedEpisode = parseInt(parts[2], 10);
          }
        }

        let cleanImdb = "";
        if (imdbId && imdbId.startsWith("tt")) cleanImdb = imdbId.split(":")[0];
        else if (showId && showId.startsWith("tt")) cleanImdb = showId.split(":")[0];
        else if (rawId.startsWith("tt")) cleanImdb = rawId.split(":")[0];

        let cleanTmdb = null;
        if (tmdbId && !isNaN(parseInt(tmdbId, 10))) cleanTmdb = parseInt(tmdbId, 10);
        else if (showId && showId.startsWith("tmdb:")) cleanTmdb = parseInt(showId.slice(5), 10);
        else if (rawId.startsWith("tmdb:")) cleanTmdb = parseInt(rawId.slice(5).split(":")[0], 10);
        else if (!isNaN(parseInt(rawId, 10))) cleanTmdb = parseInt(rawId, 10);

        const title = it.title || it.name || it.showTitle || "";
        const showTitle = it.showTitle || it.title || it.name || "";

        let watchedAtIso = "";
        if (it.watchedAt || it.watched_at || it.date) {
          try {
            const d = new Date(it.watchedAt || it.watched_at || it.date);
            if (!isNaN(d.getTime())) watchedAtIso = d.toISOString();
          } catch {}
        }

        return {
          isMovie,
          cleanImdb,
          cleanTmdb,
          title,
          showTitle,
          season: parsedSeason,
          episode: parsedEpisode,
          watchedAtIso
        };
      }

      // 1. TRAKT BATCH HISTORY SYNC
      if (provider === "trakt") {
        const token = body.traktAccessToken || body.token || "";
        const clientId = body.traktKey || TRAKT_CLIENT_ID || (env && env.TRAKT_CLIENT_ID) || "";
        if (!token) return json({ ok: false, error: "Please connect your Trakt account first." }, 400);

        const traktMovies = [];
        const traktShowMap = new Map();

        items.forEach((it) => {
          const p = parseWatchItem(it);
          const ids = {};
          if (p.cleanImdb) ids.imdb = p.cleanImdb;
          if (p.cleanTmdb) ids.tmdb = p.cleanTmdb;

          if (p.isMovie) {
            const movieObj = { ids, title: p.title };
            if (p.watchedAtIso) movieObj.watched_at = p.watchedAtIso;
            traktMovies.push(movieObj);
          } else {
            const showKey = p.cleanImdb || (p.cleanTmdb ? "tmdb:" + p.cleanTmdb : p.showTitle);
            if (!traktShowMap.has(showKey)) {
              traktShowMap.set(showKey, {
                ids,
                title: p.showTitle,
                seasonMap: new Map(),
              });
            }
            const showEntry = traktShowMap.get(showKey);
            const sNum = p.season || 1;
            const eNum = p.episode || 1;
            if (!showEntry.seasonMap.has(sNum)) {
              showEntry.seasonMap.set(sNum, []);
            }
            const epObj = { number: eNum };
            if (p.watchedAtIso) epObj.watched_at = p.watchedAtIso;
            showEntry.seasonMap.get(sNum).push(epObj);
          }
        });

        const traktShows = [];
        traktShowMap.forEach((showEntry) => {
          const seasons = [];
          showEntry.seasonMap.forEach((eps, sNum) => {
            seasons.push({ number: sNum, episodes: eps });
          });
          traktShows.push({
            ids: showEntry.ids,
            title: showEntry.title,
            seasons: seasons,
          });
        });

        const traktPayload = {};
        if (traktMovies.length) traktPayload.movies = traktMovies;
        if (traktShows.length) traktPayload.shows = traktShows;

        try {
          const tRes = await fetch("https://api.trakt.tv/sync/history", {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
              "Authorization": `Bearer ${token}`,
              "trakt-api-version": "2",
              "trakt-api-key": clientId,
              "User-Agent": `my-list-addon/${ADDON_VERSION}`,
            },
            body: JSON.stringify(traktPayload),
          });
          const tData = await tRes.json().catch(() => ({}));
          if (!tRes.ok) {
            return json({ ok: false, error: tData.error || `Trakt sync error (HTTP ${tRes.status})` }, tRes.status);
          }
          invalidatePerUserCache("trakt", safeUserHash(token));
          return json({ ok: true, provider: "trakt", syncedCount: items.length, data: tData });
        } catch (err) {
          return json({ ok: false, error: safeErrorMessage(err) }, 500);
        }
      }

      // 2. SIMKL BATCH HISTORY SYNC
      if (provider === "simkl") {
        const token = body.simklAccessToken || body.token || "";
        const clientId = body.simklKey || SIMKL_CLIENT_ID || (env && env.SIMKL_CLIENT_ID) || "";
        if (!token) return json({ ok: false, error: "Please connect your Simkl account first." }, 400);

        const simklMovies = [];
        const simklShowMap = new Map();

        items.forEach((it) => {
          const p = parseWatchItem(it);
          const ids = {};
          if (p.cleanImdb) ids.imdb = p.cleanImdb;
          if (p.cleanTmdb) ids.tmdb = p.cleanTmdb;

          if (p.isMovie) {
            const movieObj = { ids, title: p.title };
            if (p.watchedAtIso) movieObj.watched_at = p.watchedAtIso;
            simklMovies.push(movieObj);
          } else {
            const showKey = p.cleanImdb || (p.cleanTmdb ? "tmdb:" + p.cleanTmdb : p.showTitle);
            if (!simklShowMap.has(showKey)) {
              simklShowMap.set(showKey, {
                ids,
                title: p.showTitle,
                seasonMap: new Map(),
              });
            }
            const showEntry = simklShowMap.get(showKey);
            const sNum = p.season || 1;
            const eNum = p.episode || 1;
            if (!showEntry.seasonMap.has(sNum)) {
              showEntry.seasonMap.set(sNum, []);
            }
            const epObj = { number: eNum };
            if (p.watchedAtIso) epObj.watched_at = p.watchedAtIso;
            showEntry.seasonMap.get(sNum).push(epObj);
          }
        });

        const simklShows = [];
        simklShowMap.forEach((showEntry) => {
          const seasons = [];
          showEntry.seasonMap.forEach((eps, sNum) => {
            seasons.push({ number: sNum, episodes: eps });
          });
          simklShows.push({
            ids: showEntry.ids,
            title: showEntry.title,
            seasons: seasons,
          });
        });

        const simklPayload = {};
        if (simklMovies.length) simklPayload.movies = simklMovies;
        if (simklShows.length) simklPayload.shows = simklShows;

        try {
          const sRes = await fetch("https://api.simkl.com/sync/history", {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
              "Authorization": `Bearer ${token}`,
              "simkl-api-key": clientId,
              "User-Agent": `my-list-addon/${ADDON_VERSION}`,
            },
            body: JSON.stringify(simklPayload),
          });
          const sData = await sRes.json().catch(() => ({}));
          if (!sRes.ok) {
            return json({ ok: false, error: sData.error || `Simkl sync error (HTTP ${sRes.status})` }, sRes.status);
          }
          invalidatePerUserCache("simkl", safeUserHash(token));
          return json({ ok: true, provider: "simkl", syncedCount: items.length, data: sData });
        } catch (err) {
          return json({ ok: false, error: safeErrorMessage(err) }, 500);
        }
      }

      // 3. MDBLIST BATCH HISTORY SYNC
      if (provider === "mdblist") {
        const accessToken = (body.mdblistAccessToken || "").trim();
        const apiKey = (body.mdblistKey || body.apikey || "").trim();
        const token = accessToken || apiKey || body.token || "";
        if (!token) return json({ ok: false, error: "Please connect your MDBList account or API key first." }, 400);

        const movies = [];
        const episodes = [];

        items.forEach((it) => {
          const p = parseWatchItem(it);
          const obj = {};
          if (p.cleanImdb) obj.imdb = p.cleanImdb;
          if (p.cleanTmdb) obj.tmdb = p.cleanTmdb;

          if (p.isMovie) {
            movies.push(obj);
          } else {
            episodes.push({
              ...obj,
              season: p.season || 1,
              episode: p.episode || 1,
            });
          }
        });

        const mdblistPayload = {};
        if (movies.length) mdblistPayload.movies = movies;
        if (episodes.length) mdblistPayload.episodes = episodes;

        const headers = {
          "Content-Type": "application/json",
          "Accept": "application/json",
          "User-Agent": `my-list-addon/${ADDON_VERSION}`,
        };
        let mUrl = "https://api.mdblist.com/sync/watched";
        if (accessToken) {
          headers["Authorization"] = `Bearer ${accessToken}`;
        } else {
          headers["x-api-key"] = apiKey;
          mUrl += `?apikey=${encodeURIComponent(apiKey)}`;
        }

        try {
          const mRes = await fetch(mUrl, {
            method: "POST",
            headers,
            body: JSON.stringify(mdblistPayload),
          });
          const mData = await mRes.json().catch(() => ({}));
          if (!mRes.ok) {
            let successCount = 0;
            await mapWithConcurrency(items.slice(0, 50), 6, async (it) => {
              const isMovie = it.type === "movie" || it.kind === "movie" || it.mediaType === "movie";
              const mdbId = (it.imdbId && it.imdbId.startsWith("tt")) ? it.imdbId : (it.id || it.tmdbId);
              if (!mdbId) return;
              try {
                let singleUrl = `https://api.mdblist.com/history/add`;
                if (!accessToken && apiKey) singleUrl += `?apikey=${encodeURIComponent(apiKey)}`;
                const sRes = await fetch(singleUrl, {
                  method: "POST",
                  headers,
                  body: JSON.stringify({
                    id: mdbId,
                    mediatype: isMovie ? "movie" : "show",
                  }),
                });
                if (sRes.ok) successCount++;
              } catch {}
            });
            if (successCount > 0) {
              invalidatePerUserCache("mdblist", safeUserHash(token));
              return json({ ok: true, provider: "mdblist", syncedCount: successCount });
            }
            return json({ ok: false, error: mData.error || `MDBList sync error (HTTP ${mRes.status})` }, mRes.status);
          }
          invalidatePerUserCache("mdblist", safeUserHash(token));
          return json({ ok: true, provider: "mdblist", syncedCount: items.length, data: mData });
        } catch (err) {
          return json({ ok: false, error: safeErrorMessage(err) }, 500);
        }
      }

      return json({ ok: false, error: "Unsupported provider." }, 400);
    }

    // /api/external-list/create -> creates a new custom list on Trakt, TMDB, or MDBList
    if (path === "/api/external-list/create" && request.method === "POST") {
      let body = {};
      try {
        body = await request.json();
      } catch {
        return json({ ok: false, error: "Invalid JSON body." }, 400);
      }

      const provider = (body.provider || "").toLowerCase().trim();
      const name = (body.name || "").trim();
      const description = (body.description || "").trim();
      const privacy = (body.privacy || "private").toLowerCase().trim();
      const listType = (body.type || "mixed").toLowerCase().trim();

      if (!name) {
        return json({ ok: false, error: "List name is required." }, 400);
      }

      // 1. TRAKT
      if (provider === "trakt") {
        const token = body.traktAccessToken || body.token || "";
        const traktKey = body.traktKey || TRAKT_CLIENT_ID || (env && env.TRAKT_CLIENT_ID) || "";
        const username = body.traktUsername || "me";
        if (!token) return json({ ok: false, error: "Please connect your Trakt account first." }, 400);

        try {
          const res = await fetch("https://api.trakt.tv/users/me/lists", {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
              "Authorization": `Bearer ${token}`,
              "trakt-api-key": traktKey,
              "trakt-api-version": "2",
              "User-Agent": `my-list-addon/${ADDON_VERSION}`,
            },
            body: JSON.stringify({
              name: name,
              description: description,
              privacy: privacy === "public" ? "public" : "private",
              display_numbers: false,
              allow_comments: true,
              sort_by: "rank",
              sort_how: "asc"
            }),
          });
          const data = await res.json().catch(() => ({}));
          if (!res.ok) {
            return json({ ok: false, error: data.error || data.message || `Trakt error (HTTP ${res.status})` }, res.status);
          }
          const slug = data.ids?.slug || data.slug || name.toLowerCase().replace(/[^a-z0-9]+/g, "-");
          const traktUser = data.user?.ids?.slug || username || "me";
          invalidatePerUserCache("trakt", safeUserHash(token));
          return json({
            ok: true,
            provider: "trakt",
            list: {
              id: data.ids?.trakt || data.id || slug,
              slug: slug,
              name: data.name || name,
              description: data.description || description,
              privacy: data.privacy || privacy,
              url: `https://trakt.tv/users/${traktUser}/lists/${slug}`,
              type: listType
            }
          });
        } catch (err) {
          return json({ ok: false, error: safeErrorMessage(err) }, 500);
        }
      }

      // 2. TMDB
      if (provider === "tmdb") {
        const sessionId = body.tmdbSessionId || "";
        const apiKey = body.tmdbKey || TMDB_API_KEY || (env && env.TMDB_API_KEY) || "";
        if (!apiKey) return json({ ok: false, error: "TMDB API key is missing." }, 400);
        if (!sessionId) return json({ ok: false, error: "Please connect your TMDB account in Settings first." }, 400);

        try {
          const res = await fetch(`https://api.themoviedb.org/3/list?api_key=${encodeURIComponent(apiKey)}&session_id=${encodeURIComponent(sessionId)}`, {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
              "User-Agent": `my-list-addon/${ADDON_VERSION}`,
            },
            body: JSON.stringify({
              name: name,
              description: description,
              language: "en"
            }),
          });
          const data = await res.json().catch(() => ({}));
          if (!res.ok || data.success === false) {
            return json({ ok: false, error: data.status_message || `TMDB error (HTTP ${res.status})` }, res.status || 400);
          }
          const listId = String(data.list_id || data.id);
          invalidatePerUserCache("tmdb", safeUserHash(sessionId));
          return json({
            ok: true,
            provider: "tmdb",
            list: {
              id: listId,
              name: name,
              description: description,
              url: `https://www.themoviedb.org/list/${listId}`,
              type: listType
            }
          });
        } catch (err) {
          return json({ ok: false, error: safeErrorMessage(err) }, 500);
        }
      }

      // 3. MDBLIST
      if (provider === "mdblist") {
        const token = body.mdblistAccessToken || body.mdblistKey || body.apikey || "";
        const username = body.mdblistUsername || "";
        if (!token) return json({ ok: false, error: "Please connect your MDBList account first." }, 400);

        try {
          const res = await fetch("https://api.mdblist.com/lists/create", {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
              "User-Agent": `my-list-addon/${ADDON_VERSION}`,
            },
            body: JSON.stringify({
              apikey: token,
              access_token: token,
              name: name,
              description: description,
              private: privacy !== "public",
              dynamic: false
            }),
          });
          const data = await res.json().catch(() => ({}));
          if (!res.ok || data.ok === false || data.error) {
            return json({ ok: false, error: data.error || `MDBList error (HTTP ${res.status})` }, res.status || 400);
          }
          const listId = String(data.id || data.slug || "");
          const slug = data.slug || listId;
          invalidatePerUserCache("mdblist", safeUserHash(token));
          return json({
            ok: true,
            provider: "mdblist",
            list: {
              id: listId,
              slug: slug,
              name: data.name || name,
              description: description,
              url: username ? `https://mdblist.com/lists/${username}/${slug}` : `mdblist:list:${listId}`,
              type: listType
            }
          });
        } catch (err) {
          return json({ ok: false, error: safeErrorMessage(err) }, 500);
        }
      }

      // 4. SIMKL
      if (provider === "simkl") {
        const token = body.simklAccessToken || body.token || "";
        if (!token) return json({ ok: false, error: "Please connect your Simkl account first." }, 400);

        const slug = name.toLowerCase().replace(/[^a-z0-9]+/g, "-");
        const simklUrl = `simkl:user:${listType === "series" ? "shows" : "movies"}:${slug || "plantowatch"}`;
        invalidatePerUserCache("simkl", safeUserHash(token));
        return json({
          ok: true,
          provider: "simkl",
          list: {
            id: slug,
            slug: slug,
            name: name,
            description: description,
            url: simklUrl,
            type: listType
          }
        });
      }

      return json({ ok: false, error: "Unsupported provider for creating lists." }, 400);
    }

    // /api/external-list/delete -> deletes a custom list from Trakt, TMDB, or MDBList
    if (path === "/api/external-list/delete" && request.method === "POST") {
      let body = {};
      try {
        body = await request.json();
      } catch {
        return json({ ok: false, error: "Invalid JSON body." }, 400);
      }

      const provider = (body.provider || "").toLowerCase().trim();
      const listId = String(body.listId || "").trim();

      if (!listId) {
        return json({ ok: false, error: "List ID is required for deletion." }, 400);
      }

      // 1. TRAKT
      if (provider === "trakt") {
        const token = body.traktAccessToken || body.token || "";
        const traktKey = body.traktKey || TRAKT_CLIENT_ID || (env && env.TRAKT_CLIENT_ID) || "";
        if (!token) return json({ ok: false, error: "Please connect your Trakt account first." }, 400);

        try {
          const res = await fetch(`https://api.trakt.tv/users/me/lists/${encodeURIComponent(listId)}`, {
            method: "DELETE",
            headers: {
              "Authorization": `Bearer ${token}`,
              "trakt-api-key": traktKey,
              "trakt-api-version": "2",
              "User-Agent": `my-list-addon/${ADDON_VERSION}`,
            },
          });
          if (!res.ok && res.status !== 204 && res.status !== 200) {
            const data = await res.json().catch(() => ({}));
            return json({ ok: false, error: data.error || `Trakt error (HTTP ${res.status})` }, res.status);
          }
          invalidatePerUserCache("trakt", safeUserHash(token));
          return json({ ok: true, provider: "trakt", listId });
        } catch (err) {
          return json({ ok: false, error: safeErrorMessage(err) }, 500);
        }
      }

      // 2. TMDB
      if (provider === "tmdb") {
        const sessionId = body.tmdbSessionId || "";
        const apiKey = body.tmdbKey || TMDB_API_KEY || (env && env.TMDB_API_KEY) || "";
        if (!apiKey) return json({ ok: false, error: "TMDB API key is missing." }, 400);
        if (!sessionId) return json({ ok: false, error: "Please connect your TMDB account in Settings first." }, 400);

        try {
          const res = await fetch(`https://api.themoviedb.org/3/list/${encodeURIComponent(listId)}?api_key=${encodeURIComponent(apiKey)}&session_id=${encodeURIComponent(sessionId)}`, {
            method: "DELETE",
            headers: {
              "User-Agent": `my-list-addon/${ADDON_VERSION}`,
            },
          });
          const data = await res.json().catch(() => ({}));
          if (!res.ok && data.success === false) {
            return json({ ok: false, error: data.status_message || `TMDB error (HTTP ${res.status})` }, res.status || 400);
          }
          invalidatePerUserCache("tmdb", safeUserHash(sessionId));
          return json({ ok: true, provider: "tmdb", listId });
        } catch (err) {
          return json({ ok: false, error: safeErrorMessage(err) }, 500);
        }
      }

      // 3. MDBLIST
      if (provider === "mdblist") {
        const accessToken = (body.mdblistAccessToken || "").trim();
        const apiKey = (body.mdblistKey || body.apikey || "").trim();
        const token = accessToken || apiKey;
        if (!token) return json({ ok: false, error: "Please connect your MDBList account first." }, 400);

        try {
          const headers = {
            "Accept": "application/json",
            "User-Agent": `my-list-addon/${ADDON_VERSION}`,
          };
          let deleteUrl = `https://api.mdblist.com/lists/${encodeURIComponent(listId)}`;
          if (accessToken) {
            headers["Authorization"] = `Bearer ${accessToken}`;
          } else {
            headers["x-api-key"] = apiKey;
            deleteUrl += `?apikey=${encodeURIComponent(apiKey)}`;
          }

          let res = await fetch(deleteUrl, {
            method: "DELETE",
            headers,
          });

          // Fallback: If slug was passed or initial attempt returned 404, resolve numeric id via /lists/user
          if (!res.ok && (res.status === 404 || res.status === 400 || res.status === 405)) {
            try {
              let userListsUrl = "https://api.mdblist.com/lists/user";
              const userHeaders = {
                "Accept": "application/json",
                "User-Agent": `my-list-addon/${ADDON_VERSION}`,
              };
              if (accessToken) {
                userHeaders["Authorization"] = `Bearer ${accessToken}`;
              } else {
                userHeaders["x-api-key"] = apiKey;
                userListsUrl += `?apikey=${encodeURIComponent(apiKey)}`;
              }
              const userRes = await fetch(userListsUrl, { headers: userHeaders });
              if (userRes.ok) {
                const udata = await userRes.json();
                const raw = Array.isArray(udata) ? udata : (Array.isArray(udata.lists) ? udata.lists : []);
                const match = raw.find((l) => l && (String(l.id) === listId || l.slug === listId || l.name === listId));
                if (match && match.id && String(match.id) !== listId) {
                  let retryUrl = `https://api.mdblist.com/lists/${encodeURIComponent(match.id)}`;
                  if (!accessToken) retryUrl += `?apikey=${encodeURIComponent(apiKey)}`;
                  res = await fetch(retryUrl, { method: "DELETE", headers });
                }
              }
            } catch {}
          }

          if (!res.ok && res.status !== 204 && res.status !== 200) {
            const errData = await res.json().catch(() => ({}));
            const errMsg = errData.error || errData.message || `MDBList error (HTTP ${res.status})`;
            return json({ ok: false, error: errMsg }, res.status || 400);
          }

          invalidatePerUserCache("mdblist", safeUserHash(token));
          return json({ ok: true, provider: "mdblist", listId });
        } catch (err) {
          return json({ ok: false, error: safeErrorMessage(err) }, 500);
        }
      }

      return json({ ok: false, error: "Unsupported provider for deleting lists." }, 400);
    }

    // /api/tmdb/oauth/start -> requests temporary request token from TMDB & redirects to authenticate page
    if (path === "/api/tmdb/oauth/start") {
      const apiKey = TMDB_API_KEY || (env && env.TMDB_API_KEY) || "";
      if (!apiKey) {
        return new Response("TMDB isn't configured on this Worker (missing TMDB_API_KEY).", { status: 500 });
      }
      try {
        const tokenRes = await fetch(`https://api.themoviedb.org/3/authentication/token/new?api_key=${encodeURIComponent(apiKey)}`, {
          headers: { "User-Agent": `my-list-addon/${ADDON_VERSION}` },
        });
        const tokenData = await tokenRes.json();
        if (!tokenData.success || !tokenData.request_token) {
          return new Response("Could not create TMDB request token: " + (tokenData.status_message || "unknown error"), { status: 500 });
        }
        const requestToken = tokenData.request_token;
        const redirectUri = `${url.origin}/api/tmdb/oauth/callback`;
        const authorizeUrl = `https://www.themoviedb.org/authenticate/${encodeURIComponent(requestToken)}?redirect_to=${encodeURIComponent(redirectUri)}`;
        return new Response(null, {
          status: 302,
          headers: {
            Location: authorizeUrl,
            "Set-Cookie": `mla_tmdb_token=${encodeURIComponent(requestToken)}; Path=/api/tmdb/oauth; HttpOnly; Secure; SameSite=Lax; Max-Age=600`,
          },
        });
      } catch (err) {
        return new Response("Network error contacting TMDB: " + err.message, { status: 500 });
      }
    }

    // /api/tmdb/oauth/callback -> exchanges request token for session ID & account details
    if (path === "/api/tmdb/oauth/callback") {
      const cookies = parseCookies(request);
      const cookieToken = cookies.mla_tmdb_token || "";
      const clearCookie = "mla_tmdb_token=; Path=/api/tmdb/oauth; HttpOnly; Secure; SameSite=Lax; Max-Age=0";
      const failWith = (reason, detail) => {
        const params = new URLSearchParams({ tmdb_error: reason });
        if (detail) params.set("tmdb_error_detail", detail);
        return new Response(null, {
          status: 302,
          headers: { Location: `${url.origin}/?${params.toString()}`, "Set-Cookie": clearCookie },
        });
      };

      const approved = url.searchParams.get("approved") === "true";
      const denied = url.searchParams.get("denied") === "true";
      if (denied) return failWith("access_denied");
      const requestToken = url.searchParams.get("request_token") || cookieToken;
      if (!requestToken) return failWith("no_token");

      const apiKey = TMDB_API_KEY || (env && env.TMDB_API_KEY) || "";
      if (!apiKey) return failWith("not_configured");

      try {
        // Exchange request token for session_id
        const sessionRes = await fetch(`https://api.themoviedb.org/3/authentication/session/new?api_key=${encodeURIComponent(apiKey)}`, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "User-Agent": `my-list-addon/${ADDON_VERSION}`,
          },
          body: JSON.stringify({ request_token: requestToken }),
        });
        const sessionData = await sessionRes.json();
        if (!sessionData.success || !sessionData.session_id) {
          return failWith("session_failed", sessionData.status_message || "");
        }
        const sessionId = sessionData.session_id;

        // Fetch account profile
        const accountRes = await fetch(`https://api.themoviedb.org/3/account?api_key=${encodeURIComponent(apiKey)}&session_id=${encodeURIComponent(sessionId)}`, {
          headers: { "User-Agent": `my-list-addon/${ADDON_VERSION}` },
        });
        const accountData = await accountRes.json();
        const accountId = accountData.id ? String(accountData.id) : "";
        const username = accountData.username || "";

        return new Response(null, {
          status: 302,
          headers: {
            Location: `${url.origin}/#tmdb_session=${encodeURIComponent(sessionId)}&tmdb_account=${encodeURIComponent(accountId)}&tmdb_user=${encodeURIComponent(username)}`,
            "Set-Cookie": clearCookie,
          },
        });
      } catch (err) {
        return failWith("network", err.message || String(err));
      }
    }

    // /api/tmdb-my-lists (GET or POST) -> returns user created lists, watchlist, and favorites
    if (path === "/api/tmdb-my-lists") {
      let sessionId = url.searchParams.get("sessionId") || "";
      let accountId = url.searchParams.get("accountId") || "";
      let manualKey = url.searchParams.get("tmdbKey") || "";

      if (request.method === "POST") {
        try {
          const body = await request.json();
          if (body.sessionId) sessionId = body.sessionId;
          if (body.accountId) accountId = body.accountId;
          if (body.tmdbKey) manualKey = body.tmdbKey;
        } catch {}
      }

      const apiKey = manualKey || TMDB_API_KEY || (env && env.TMDB_API_KEY) || "";
      if (!apiKey) {
        return json({ ok: false, error: "TMDB API key is missing." }, 400);
      }

      const isV4 = apiKey.startsWith("ey");
      const makeHeaders = () => {
        const h = { "User-Agent": `my-list-addon/${ADDON_VERSION}`, "Accept": "application/json" };
        if (isV4) h["Authorization"] = `Bearer ${apiKey}`;
        return h;
      };
      const makeUrl = (endpoint, params = {}) => {
        const u = new URL(`https://api.themoviedb.org/3${endpoint}`);
        if (!isV4) u.searchParams.set("api_key", apiKey);
        if (sessionId) u.searchParams.set("session_id", sessionId);
        for (const [k, v] of Object.entries(params)) {
          if (v !== undefined && v !== null && v !== "") u.searchParams.set(k, v);
        }
        return u.toString();
      };
      let tmdbUsername = "";

      // If we don't have accountId but have sessionId, query account details
      if (sessionId) {
        try {
          const accRes = await fetch(makeUrl("/account"), { headers: makeHeaders() });
          const acc = await accRes.json();
          if (acc && acc.id) {
            accountId = String(acc.id);
            if (acc.username) tmdbUsername = acc.username;
          }
        } catch {}
      }

      if (!accountId && !sessionId) {
        return json({ ok: false, error: "Please connect your TMDB account first." }, 400);
      }

      const lists = [];

      try {
        // 1. Fetch user's custom lists
        if (accountId) {
          const listsRes = await fetch(makeUrl(`/account/${encodeURIComponent(accountId)}/lists`, { page: "1" }), {
            headers: makeHeaders()
          });
          if (listsRes.ok) {
            const listsData = await listsRes.json();
            const rawLists = Array.isArray(listsData.results) ? listsData.results : [];
            const fetched = await mapWithConcurrency(rawLists, 4, async (it) => {
              const listId = it.id;
              let itemCount = it.item_count || 0;
              let previewItems = [];
              try {
                const detailRes = await fetch(makeUrl(`/list/${encodeURIComponent(listId)}`), { headers: makeHeaders() });
                if (detailRes.ok) {
                  const listDetail = await detailRes.json();
                  const rawItems = Array.isArray(listDetail.items) ? listDetail.items : (Array.isArray(listDetail.results) ? listDetail.results : []);
                  itemCount = listDetail.item_count || rawItems.length || itemCount;
                  previewItems = rawItems.slice(0, 9).map((item) => ({
                    id: item.id,
                    title: item.title || item.name || "Untitled",
                    year: (item.release_date || item.first_air_date || "").slice(0, 4),
                    poster: item.poster_path ? `https://image.tmdb.org/t/p/w300${item.poster_path}` : "",
                    type: item.media_type === "tv" ? "series" : "movie",
                  }));
                }
              } catch {}
              return {
                id: String(listId),
                name: it.name || "Untitled List",
                url: `https://www.themoviedb.org/list/${encodeURIComponent(listId)}`,
                contentType: "mixed",
                items: itemCount,
                likes: it.favorite_count || 0,
                description: it.description || "",
                private: it.public === false,
                previewItems: previewItems,
              };
            });
            lists.push(...fetched);
          }
        }

        // 2. Fetch user's Watchlist (Movies & TV Shows) and Favorites if accountId is available
        if (accountId) {
          const [wlMovRes, wlTvRes, favMovRes, favTvRes] = await Promise.all([
            fetch(makeUrl(`/account/${encodeURIComponent(accountId)}/watchlist/movies`, { page: "1" }), { headers: makeHeaders() }),
            fetch(makeUrl(`/account/${encodeURIComponent(accountId)}/watchlist/tv`, { page: "1" }), { headers: makeHeaders() }),
            fetch(makeUrl(`/account/${encodeURIComponent(accountId)}/favorite/movies`, { page: "1" }), { headers: makeHeaders() }),
            fetch(makeUrl(`/account/${encodeURIComponent(accountId)}/favorite/tv`, { page: "1" }), { headers: makeHeaders() }),
          ]);

          if (wlMovRes && wlMovRes.ok) {
            const wlMovData = await wlMovRes.json();
            const rawItems = Array.isArray(wlMovData.results) ? wlMovData.results : [];
            const total = wlMovData.total_results || rawItems.length;
            if (total > 0) {
              const previewItems = rawItems.slice(0, 9).map((it) => ({
                id: it.id,
                title: it.title || it.name || "Untitled",
                year: (it.release_date || it.first_air_date || "").slice(0, 4),
                poster: it.poster_path ? `https://image.tmdb.org/t/p/w300${it.poster_path}` : "",
                type: "movie",
              }));
              lists.push({
                id: "watchlist_movies",
                name: "TMDB Watchlist (Movies)",
                url: `tmdb:account:watchlist:movies`,
                contentType: "movie",
                items: total,
                likes: 0,
                description: "Your TMDB Watchlist Movies",
                private: true,
                previewItems: previewItems,
              });
            }
          }

          if (wlTvRes && wlTvRes.ok) {
            const wlTvData = await wlTvRes.json();
            const rawItems = Array.isArray(wlTvData.results) ? wlTvData.results : [];
            const total = wlTvData.total_results || rawItems.length;
            if (total > 0) {
              const previewItems = rawItems.slice(0, 9).map((it) => ({
                id: it.id,
                title: it.name || it.title || "Untitled",
                year: (it.first_air_date || it.release_date || "").slice(0, 4),
                poster: it.poster_path ? `https://image.tmdb.org/t/p/w300${it.poster_path}` : "",
                type: "series",
              }));
              lists.push({
                id: "watchlist_tv",
                name: "TMDB Watchlist (Shows)",
                url: `tmdb:account:watchlist:tv`,
                contentType: "series",
                items: total,
                likes: 0,
                description: "Your TMDB Watchlist TV Shows",
                private: true,
                previewItems: previewItems,
              });
            }
          }

          if (favMovRes && favMovRes.ok) {
            const favMovData = await favMovRes.json();
            const rawItems = Array.isArray(favMovData.results) ? favMovData.results : [];
            const total = favMovData.total_results || rawItems.length;
            if (total > 0) {
              const previewItems = rawItems.slice(0, 9).map((it) => ({
                id: it.id,
                title: it.title || it.name || "Untitled",
                year: (it.release_date || it.first_air_date || "").slice(0, 4),
                poster: it.poster_path ? `https://image.tmdb.org/t/p/w300${it.poster_path}` : "",
                type: "movie",
              }));
              lists.push({
                id: "favorites_movies",
                name: "TMDB Favorites (Movies)",
                url: `tmdb:account:favorites:movies`,
                contentType: "movie",
                items: total,
                likes: 0,
                description: "Your TMDB Favorite Movies",
                private: true,
                previewItems: previewItems,
              });
            }
          }

          if (favTvRes && favTvRes.ok) {
            const favTvData = await favTvRes.json();
            const rawItems = Array.isArray(favTvData.results) ? favTvData.results : [];
            const total = favTvData.total_results || rawItems.length;
            if (total > 0) {
              const previewItems = rawItems.slice(0, 9).map((it) => ({
                id: it.id,
                title: it.name || it.title || "Untitled",
                year: (it.first_air_date || it.release_date || "").slice(0, 4),
                poster: it.poster_path ? `https://image.tmdb.org/t/p/w300${it.poster_path}` : "",
                type: "series",
              }));
              lists.push({
                id: "favorites_tv",
                name: "TMDB Favorites (Shows)",
                url: `tmdb:account:favorites:tv`,
                contentType: "series",
                items: total,
                likes: 0,
                description: "Your TMDB Favorite TV Shows",
                private: true,
                previewItems: previewItems,
              });
            }
          }
        }

        return json({ ok: true, lists, username: tmdbUsername, accountId });
      } catch (err) {
        return json({ ok: false, error: "Failed to load TMDB lists: " + (err.message || String(err)) }, 500);
      }
    }


    // /api/trakt-my-private-lists  (POST)  { accessToken } -> { ok, lists }
    // Same shape as /api/trakt-my-lists above, but hits /users/me/lists
    // with the OAuth token as a Bearer header instead of a plain username
    // lookup -- "me" resolves to whichever account approved the
    // connection, and includes their private lists (which the public,
    // username-based endpoint above can never see). POST, not GET, so the
    // token travels in the body rather than sitting in a URL/query string
    // that could end up in logs.
    if (path === "/api/trakt-my-private-lists" && request.method === "POST") {
      let body;
      try {
        body = await request.json();
      } catch {
        return json({ ok: false, error: "Invalid JSON body." }, 400);
      }
      const accessToken = String(body.accessToken || "").trim();
      if (!accessToken) return json({ ok: false, error: "Not connected to Trakt." }, 400);
      try {
        const userHash = safeUserHash(accessToken);
        const cacheKey = `user_cache:trakt:private_lists:${userHash}`;

        const result = await fetchWithPerUserCacheAndCircuitBreaker({
          cacheKey,
          kvKey: cacheKey,
          env,
          ctx,
          freshTtlSec: 60,
          staleTtlSec: 1800,
          kvTtlSec: 1800,
          providerLabel: "Trakt Private Lists",
          fetchFn: async () => {
            const res = await fetchTraktWithRetry("https://api.trakt.tv/users/me/lists", {
              headers: {
                "Content-Type": "application/json",
                "trakt-api-version": "2",
                "trakt-api-key": TRAKT_CLIENT_ID,
                Authorization: `Bearer ${accessToken}`,
                "User-Agent": `my-list-addon/${ADDON_VERSION}`,
              },
              cf: { cacheTtl: 0, cacheEverything: false },
            });
            if (res.status === 401) {
              throw new Error("Your Trakt connection has expired or was revoked -- reconnect in Settings.");
            }
            if (!res.ok) throw new Error(`Trakt request failed (HTTP ${res.status}).`);
            const data = await res.json();
            const meRes = await fetchTraktWithRetry("https://api.trakt.tv/users/me", {
              headers: {
                "Content-Type": "application/json",
                "trakt-api-version": "2",
                "trakt-api-key": TRAKT_CLIENT_ID,
                Authorization: `Bearer ${accessToken}`,
                "User-Agent": `my-list-addon/${ADDON_VERSION}`,
              },
              cf: { cacheTtl: 0, cacheEverything: false },
            });
            const me = meRes.ok ? await meRes.json() : null;
            const meSlug = me && me.ids && me.ids.slug ? me.ids.slug : "me";
            const rawLists = (Array.isArray(data) ? data : [])
              .filter((l) => l && l.ids && l.ids.slug)
              .map((l) => {
                const name = l.name || "";
                const isMovie = /\bmovie(s)?\b/i.test(name);
                const isSeries = /\b(show|shows|series|anime|tv|season(s)?)\b/i.test(name);
                const contentType = isMovie && !isSeries ? "movie" : (isSeries && !isMovie ? "series" : "unknown");
                return {
                  name: l.name,
                  slug: l.ids.slug,
                  items: l.item_count || 0,
                  likes: l.likes || 0,
                  private: l.privacy !== "public",
                  contentType,
                  url: `https://trakt.tv/users/${encodeURIComponent(meSlug)}/lists/${encodeURIComponent(l.ids.slug)}`,
                };
              });

            let watchlistCount = 0;
            try {
              const watchlistRes = await fetchTraktWithRetry("https://api.trakt.tv/users/me/watchlist?limit=1&page=1", {
                headers: {
                  "Content-Type": "application/json",
                  "trakt-api-version": "2",
                  "trakt-api-key": TRAKT_CLIENT_ID,
                  Authorization: `Bearer ${accessToken}`,
                  "User-Agent": `my-list-addon/${ADDON_VERSION}`,
                },
                cf: { cacheTtl: 0, cacheEverything: false },
              });
              if (watchlistRes.ok) {
                watchlistCount = parseInt(watchlistRes.headers.get("X-Pagination-Item-Count") || "0", 10) || 0;
              }
            } catch {}
            const watchlistEntry = {
              name: "Watchlist",
              slug: "watchlist",
              items: watchlistCount,
              likes: 0,
              private: true,
              url: "trakt:watchlist",
              contentType: "unknown",
            };

            let historyCount = 0;
            try {
              const historyRes = await fetchTraktWithRetry("https://api.trakt.tv/users/me/history?limit=1&page=1", {
                headers: {
                  "Content-Type": "application/json",
                  "trakt-api-version": "2",
                  "trakt-api-key": TRAKT_CLIENT_ID,
                  Authorization: `Bearer ${accessToken}`,
                  "User-Agent": `my-list-addon/${ADDON_VERSION}`,
                },
                cf: { cacheTtl: 0, cacheEverything: false },
              });
              if (historyRes.ok) {
                historyCount = parseInt(historyRes.headers.get("X-Pagination-Item-Count") || "0", 10) || 0;
              }
            } catch {}
            const historyEntry = {
              name: "Watch History",
              slug: "history",
              items: historyCount,
              likes: 0,
              private: true,
              url: "trakt:history",
              contentType: "unknown",
            };

            let airingCandidates = [];
            try {
              const [wShowsRes, wlShowsRes] = await Promise.all([
                fetchTraktWithRetry("https://api.trakt.tv/users/me/watched/shows?extended=noseasons", {
                  headers: {
                    "Content-Type": "application/json",
                    "trakt-api-version": "2",
                    "trakt-api-key": TRAKT_CLIENT_ID,
                    Authorization: `Bearer ${accessToken}`,
                    "User-Agent": `my-list-addon/${ADDON_VERSION}`,
                  },
                  cf: { cacheTtl: 60, cacheEverything: false },
                }).catch(() => null),
                fetchTraktWithRetry("https://api.trakt.tv/users/me/watchlist/shows?limit=50", {
                  headers: {
                    "Content-Type": "application/json",
                    "trakt-api-version": "2",
                    "trakt-api-key": TRAKT_CLIENT_ID,
                    Authorization: `Bearer ${accessToken}`,
                    "User-Agent": `my-list-addon/${ADDON_VERSION}`,
                  },
                  cf: { cacheTtl: 60, cacheEverything: false },
                }).catch(() => null),
              ]);

              const rawAiring = [];
              if (wShowsRes && wShowsRes.ok) {
                const wData = await wShowsRes.json();
                if (Array.isArray(wData)) rawAiring.push(...wData);
              }
              if (wlShowsRes && wlShowsRes.ok) {
                const wlData = await wlShowsRes.json();
                if (Array.isArray(wlData)) rawAiring.push(...wlData);
              }

              const seenIds = new Set();
              for (const it of rawAiring) {
                const show = it.show || it;
                if (show && show.ids) {
                  const imdbId = show.ids.imdb || "";
                  const tmdbId = show.ids.tmdb || "";
                  const bestId = imdbId || (tmdbId ? `tmdb:${tmdbId}` : "");
                  if (bestId && !seenIds.has(bestId)) {
                    seenIds.add(bestId);
                    airingCandidates.push({
                      id: bestId,
                      imdbId: imdbId || null,
                      tmdbId: tmdbId || null,
                      name: show.title || "",
                      year: show.year || "",
                      poster: imdbId ? `https://images.metahub.space/poster/medium/${imdbId}/img` : "",
                      type: "series",
                      lastWatched: it.last_watched_at || null,
                    });
                  }
                }
              }
            } catch {}

            const airingNextEntry = {
              name: "Trakt Airing Next",
              slug: "airing-next",
              statusKey: "airing-next",
              type: "series",
              contentType: "series",
              itemCount: airingCandidates.length,
              items: airingCandidates,
              private: true,
              url: "trakt:user:shows:airing-next",
            };

            const meUsername = (me && me.username) || (meSlug !== "me" ? meSlug : "");

            ctx.waitUntil(bumpStatBy(env, "apiuse:trakt", 4));
            return { lists: [airingNextEntry, watchlistEntry, historyEntry, ...rawLists], username: meUsername };
          }
        });

        const lists = Array.isArray(result) ? result : (result && result.lists) || [];
        const username = (result && result.username) || "";
        return json({ ok: true, lists, username });
      } catch (err) {
        return json({ ok: false, error: safeErrorMessage(err) });
      }
    }

    // /api/trakt-history-raw  (POST)  { accessToken, type: 'movies'|'episodes', page, limit }
    // -> { ok, items: [...raw Trakt history rows...], hasMore }
    if (path === "/api/trakt-history-raw" && request.method === "POST") {
      let body;
      try {
        body = await request.json();
      } catch {
        return json({ ok: false, error: "Invalid JSON body." }, 400);
      }
      const accessToken = String(body.accessToken || "").trim();
      if (!accessToken) return json({ ok: false, error: "Not connected to Trakt." }, 400);
      const itemKind = body.type === "episodes" ? "episodes" : "movies";
      const page = Math.max(1, parseInt(body.page, 10) || 1);
      const limit = Math.min(100, Math.max(1, parseInt(body.limit, 10) || 100));
      try {
        const userHash = safeUserHash(accessToken);
        const cacheKey = `user_cache:trakt:history_raw:${itemKind}:${page}:${limit}:${userHash}`;

        const historyResult = await fetchWithPerUserCacheAndCircuitBreaker({
          cacheKey,
          kvKey: cacheKey,
          env,
          ctx,
          freshTtlSec: 60,
          staleTtlSec: 1800,
          kvTtlSec: 1800,
          providerLabel: "Trakt History Raw",
          fetchFn: async () => {
            ctx.waitUntil(bumpStat(env, "apiuse:trakt"));
            const res = await fetchTraktWithRetry(`https://api.trakt.tv/users/me/history/${itemKind}?limit=${limit}&page=${page}`, {
              headers: {
                "Content-Type": "application/json",
                "trakt-api-version": "2",
                "trakt-api-key": TRAKT_CLIENT_ID,
                Authorization: `Bearer ${accessToken}`,
                "User-Agent": `my-list-addon/${ADDON_VERSION}`,
              },
              cf: { cacheTtl: 0, cacheEverything: false },
            });
            if (res.status === 401) {
              throw new Error("Your Trakt connection has expired or was revoked -- reconnect in Settings.");
            }
            if (!res.ok) throw new Error(`Trakt history request failed (HTTP ${res.status}).`);
            const items = await res.json();
            const totalPages = parseInt(res.headers.get("x-pagination-page-count") || "1", 10) || 1;
            return { items: Array.isArray(items) ? items : [], hasMore: page < totalPages };
          }
        });

        return json({ ok: true, items: historyResult.items || [], hasMore: !!historyResult.hasMore });
      } catch (err) {
        return json({ ok: false, error: safeErrorMessage(err) });
      }
    }

    // /api/feedback  (POST)  { category, message, contact?, creatorName?, threadId? } -> { ok, entry }
    // Settings > Feedback & Support 2-way chat.
    if (path === "/api/feedback" && request.method === "POST") {
      if (!env || !env.CONFIGS) return json({ ok: false, error: "Feedback storage isn't configured on this deployment." });
      let body;
      try {
        body = await request.json();
      } catch {
        return json({ ok: false, error: "Invalid JSON body." }, 400);
      }
      const message = String(body.message || "").trim();
      if (!message) return json({ ok: false, error: "Message can't be empty." }, 400);
      if (message.length > 4000) return json({ ok: false, error: "That's a bit long -- please keep it under 4000 characters." }, 400);
      const allowedCategories = new Set(["bug", "improvement", "idea", "other"]);
      const category = allowedCategories.has(body.category) ? body.category : "other";
      const contact = String(body.contact || "").trim().slice(0, 200);
      const claimedCreator = body.creatorName ? String(body.creatorName).trim().slice(0, 100) : null;
      const threadId = body.threadId ? String(body.threadId).trim() : null;

      const isAdmin = (await isAdminRequest(request, env)) && body.fromAdminPanel === true;

      // A claimed creatorName used to be recorded, and rendered in the admin
      // panel as the sender, on nothing but the caller's say-so -- so anyone
      // could file or answer feedback wearing someone else's name. It is now
      // proven before it is stored anywhere.
      //
      // An unprovable claim is DROPPED, not rejected. This is the support
      // channel: the person whose key stopped working is exactly the person
      // who needs to reach support, and 401ing them here would close the one
      // door they have left. Their message still goes through, just as an
      // anonymous one -- which is all "we could not verify who you are"
      // honestly supports. (Replying to a thread that already belongs to an
      // account is the separate, stricter case, handled below.)
      //
      // The admin panel is the one exemption: its "Log something yourself"
      // button posts creatorName:"admin" with fromAdminPanel:true and no key
      // (see submitAdminFeedback, 03_admin.js), and "admin" is a marker that
      // feedbackCardHtml keys off, not a Creator Profile to authenticate.
      let authedCreator = null;
      if (!isAdmin && claimedCreator) {
        const auth = await authenticateCreator(claimedCreator, body.creatorKey ? String(body.creatorKey) : "");
        if (auth.ok) authedCreator = auth.username;
      }
      // What actually gets stored: the admin marker, a proven username, or
      // nothing. Never the raw claim.
      const creatorName = isAdmin ? claimedCreator : authedCreator;
      let rateLimitKey = null;
      let rateCount = 0;
      if (!isAdmin) {
        const ip = clientIpKey(request);
        if (!ip) return json({ ok: false, error: "Could not process this request." }, 400);
        rateLimitKey = `feedbackrate:${ip}:${statsToday()}`;
        const rateCountRaw = await env.CONFIGS.get(rateLimitKey);
        rateCount = parseInt(rateCountRaw, 10) || 0;
        if (rateCount >= 20) {
          return json({ ok: false, error: "You've sent a few messages today -- please try again tomorrow." });
        }
      }

      // If replying to an existing thread
      if (threadId) {
        let entry = null;
        try {
          const raw = await env.CONFIGS.get(`feedback:${threadId}`);
          if (raw) entry = JSON.parse(raw);
        } catch (e) {
          entry = null;
        }

        // A thread id is a capability, and for a thread nobody owns that is
        // the whole design: an anonymous reporter has no account and follows
        // up with nothing else. But a thread that DOES belong to an account
        // is not a bare capability -- the id alone used to be enough for any
        // stranger to append to it, reopen it, and pick their own display
        // name, which the admin panel then rendered as the sender.
        //
        // A stored name that no longer normalises to a valid username (legacy
        // free-text) cannot be authenticated as by anyone, so treating it as
        // owned would strand the thread. Those stay id-capability threads.
        if (entry && !isAdmin) {
          const ownerRaw = entry.creatorName ? String(entry.creatorName).trim() : "";
          let ownerNorm = "";
          if (ownerRaw) {
            const ownerV = validateCreatorUsername(ownerRaw);
            if (ownerV && ownerV.ok) ownerNorm = ownerV.normalized;
          }
          if (ownerNorm && ownerNorm !== authedCreator) {
            return json(
              { ok: false, error: "That conversation belongs to an account. Sign in to reply to it." },
              403,
              { "Cache-Control": "no-store" }
            );
          }
        }

        try {
          if (entry) {
            if (!Array.isArray(entry.messages) || !entry.messages.length) {
              entry.messages = [{
                id: `msg_init`,
                sender: "user",
                senderName: entry.creatorName || "User",
                text: entry.message || "(Initial message)",
                timestamp: entry.createdAt || Date.now()
              }];
            }
            const newMsg = {
              id: `msg_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`,
              sender: isAdmin ? "admin" : "user",
              // Derived, never taken from the request body. This is what
              // the admin panel renders as the sender, so letting the
              // caller choose it meant a stranger could plant a message
              // signed "Developer" inside someone else's thread.
              senderName: isAdmin ? "Developer" : (entry.creatorName || authedCreator || "User"),
              text: message,
              timestamp: Date.now()
            };
            entry.messages.push(newMsg);
            entry.updatedAt = Date.now();
            entry.status = isAdmin ? "replied" : "open";
            entry.completed = false;
            if (contact && !entry.contact) entry.contact = contact;
            // Claiming an unowned thread now takes proof, not just the id --
            // otherwise anyone holding it could attach their own account to
            // someone else's report.
            if (creatorName && !entry.creatorName) entry.creatorName = creatorName;
            await putFeedbackThread(env, `feedback:${threadId}`, entry);
            if (!isAdmin) await env.CONFIGS.put(rateLimitKey, String(rateCount + 1), { expirationTtl: 86400 });
            return json({ ok: true, entry });
          }
        } catch (e) {}
      }

      // New Thread
      //
      // The id is a capability: /api/feedback/threads hands the whole thread
      // -- every message plus the contact address the form asks for -- to
      // anyone who presents it, deliberately, so anonymous reporters can
      // follow up. It was minted with Math.random(), which is not a CSPRNG:
      // V8's xorshift128+ state is recoverable from a handful of outputs, so
      // filing a few reports of your own leaked the ids being handed to
      // other people from the same isolate. generateShortId is the same
      // crypto.getRandomValues helper the OAuth state cookies use.
      // Date.now() stays as the prefix -- /admin/api/feedback relies on
      // these keys sorting chronologically.
      const id = `${Date.now()}:${generateShortId()}`;
      const entry = {
        id, category, message, contact: contact || null, creatorName,
        createdAt: Date.now(),
        updatedAt: Date.now(),
        completed: false,
        status: "open",
        messages: [
          {
            id: `msg_${Date.now()}_1`,
            sender: isAdmin ? "admin" : "user",
            // creatorName here is the proven name (or the admin marker),
            // never the raw claim -- see its assignment above.
            senderName: isAdmin ? "Developer" : (creatorName || "User"),
            text: message,
            timestamp: Date.now()
          }
        ],
        userAgent: (request.headers.get("User-Agent") || "").slice(0, 300),
      };
      try {
        await putFeedbackThread(env, `feedback:${id}`, entry);
        if (!isAdmin) await env.CONFIGS.put(rateLimitKey, String(rateCount + 1), { expirationTtl: 86400 });
      } catch (e) {
        return json({ ok: false, error: "Could not save your feedback right now. Please try again in a moment." }, 500);
      }
      return json({ ok: true, entry });
    }

    // /api/feedback/threads (POST) { creatorName?, threadIds? } -> { ok, threads }
    // Loads active support chat threads for a user/device
    if (path === "/api/feedback/threads" && (request.method === "POST" || request.method === "GET")) {
      if (!env || !env.CONFIGS) return json({ ok: true, threads: [] }, 200, { "Cache-Control": "no-store" });
      let threadIds = [];
      let creatorName = null;
      let creatorKey = null;
      if (request.method === "POST") {
        try {
          const body = await request.json();
          if (Array.isArray(body.threadIds)) threadIds = body.threadIds.map((t) => String(t).trim()).filter(Boolean);
          if (body.creatorName) creatorName = String(body.creatorName).trim().toLowerCase();
          if (body.creatorKey) creatorKey = String(body.creatorKey);
        } catch {}
      } else {
        const pIds = url.searchParams.get("threadIds");
        if (pIds) threadIds = pIds.split(",").map((s) => s.trim()).filter(Boolean);
        const pCreator = url.searchParams.get("creatorName");
        if (pCreator) creatorName = pCreator.trim().toLowerCase();
        const pKey = url.searchParams.get("creatorKey");
        if (pKey) creatorKey = pKey;
      }

      // Looking a creator up BY NAME returns their whole support history --
      // free-text messages plus the optional `contact` field the feedback
      // form explicitly asks for. That used to require nothing but the
      // username, which /lists/public.json publishes for everyone who has
      // ever shared a list, so anyone could harvest every user's
      // correspondence and contact details by iterating the directory.
      //
      // The name-based scan below now requires the account's own key. The
      // threadIds path is deliberately left unauthenticated: a thread id
      // is a capability (it is only ever shown to the person who filed the
      // report), and anonymous users with no account at all rely on it to
      // follow up on what they submitted.
      // authenticateCreator is declared further down in
      // 26_api-creator-and-admin-routes.js, which is the same function
      // body as this file after the build concatenates them -- a hoisted
      // function declaration, so it is in scope here.
      if (creatorName) {
        const auth = await authenticateCreator(creatorName, creatorKey);
        if (!auth.ok) {
          return json({ ok: false, error: "Username or Key is incorrect." }, 401, { "Cache-Control": "no-store" });
        }
        creatorName = auth.username;
      }

      const threadsMap = new Map();

      // 1. Fetch explicitly listed thread IDs
      if (threadIds.length) {
        const lookups = threadIds.slice(0, 20).map(async (tid) => {
          try {
            const raw = await env.CONFIGS.get(`feedback:${tid}`);
            if (raw) {
              const entry = JSON.parse(raw);
              if (!Array.isArray(entry.messages) || !entry.messages.length) {
                entry.messages = [{
                  id: `msg_init`,
                  sender: "user",
                  senderName: entry.creatorName || "User",
                  text: entry.message || "(Initial message)",
                  timestamp: entry.createdAt || Date.now()
                }];
              }
              threadsMap.set(entry.id, entry);
            }
          } catch {}
        });
        await Promise.all(lookups);
      }

      // 2. If creatorName is given, also scan recent feedback keys for this creator
      //
      // KV list() on `feedback:` returns oldest-first (keys sort
      // chronologically -- see /admin/api/feedback). A single unpaginated
      // list({limit:200}) therefore only ever sees the 200 OLDEST entries
      // system-wide, not the newest -- once total feedback volume passes
      // that, a real creator's own recent thread falls outside the window
      // and this scan silently stops finding it, forever, for every
      // creator whose thread isn't in that fixed oldest-200 slice. Same
      // fix as /admin/api/feedback: walk every page but only keep a
      // rolling tail of the newest FEEDBACK_USER_SCAN_CAP keys, bounded so
      // this stays cheap even with a very large feedback table.
      if (creatorName) {
        try {
          const FEEDBACK_USER_SCAN_CAP = 300; // matches /admin/api/feedback's cap
          let scanKeys = [];
          let cursor;
          let pages = 0;
          while (pages < 30) {
            const listRes = await env.CONFIGS.list({ prefix: "feedback:", limit: 1000, cursor });
            scanKeys.push(...(listRes.keys || []).map((k) => k.name));
            if (scanKeys.length > FEEDBACK_USER_SCAN_CAP) scanKeys = scanKeys.slice(-FEEDBACK_USER_SCAN_CAP);
            pages++;
            if (listRes.list_complete || !listRes.cursor) break;
            cursor = listRes.cursor;
          }
          scanKeys.reverse();
          const scanLookups = scanKeys.map(async (kName) => {
            const tid = kName.replace(/^feedback:/, "");
            if (threadsMap.has(tid)) return;
            try {
              const raw = await env.CONFIGS.get(kName);
              if (raw) {
                const entry = JSON.parse(raw);
                if (entry.creatorName && entry.creatorName.trim().toLowerCase() === creatorName) {
                  if (!Array.isArray(entry.messages) || !entry.messages.length) {
                    entry.messages = [{
                      id: `msg_init`,
                      sender: "user",
                      senderName: entry.creatorName || "User",
                      text: entry.message || "(Initial message)",
                      timestamp: entry.createdAt || Date.now()
                    }];
                  }
                  threadsMap.set(entry.id, entry);
                }
              }
            } catch {}
          });
          await Promise.all(scanLookups);
        } catch {}
      }

      const threads = Array.from(threadsMap.values()).sort((a, b) => {
        const timeA = a.updatedAt || a.createdAt || 0;
        const timeB = b.updatedAt || b.createdAt || 0;
        return timeB - timeA;
      });

      return json({ ok: true, threads }, 200, { "Cache-Control": "no-store" });
    }

    // /api/track-search  (POST)  { query } -> { ok }
    // Fire-and-forget anonymous search query telemetry
    if (path === "/api/track-search" && request.method === "POST") {
      if (!env || !env.CONFIGS) return json({ ok: true });
      let body;
      try { body = await request.json(); } catch { return json({ ok: true }); }
      // recordSearchQuery keys `searchquery:{q}:days` on the query text
      // itself, so like /api/track-event this is an unauthenticated write
      // whose key name comes from the caller. Same per-IP bucket, same
      // ok:true-on-limit behaviour (it's a beacon, not a feature).
      const searchIp = clientIpKey(request);
      if (!searchIp) return json({ ok: true });
      const searchRateKey = `ratelimit:tracksearch:${searchIp}`;
      const searchAttempts = parseInt((await env.CONFIGS.get(searchRateKey)) || "0", 10);
      if (searchAttempts >= 30) return json({ ok: true });
      ctx.waitUntil(env.CONFIGS.put(searchRateKey, String(searchAttempts + 1), { expirationTtl: 60 }));

      if (body && typeof body.query === "string" && body.query.trim()) {
        ctx.waitUntil(recordSearchQuery(env, body.query.trim()));
      }
      return json({ ok: true });
    }

    // /api/track-event  (POST)  { events: [{ eventType, id, title, mediaType }, ...] } -> { ok }
    // Fire-and-forget analytics beacon feeding recordTrackedEvent above --
    // "watched" for anything marked watched, "list-add" for anything added
    // to a Custom List, "list-copy" for imported lists, "catalog-add" for installed catalogs.
    if (path === "/api/track-event" && request.method === "POST") {
      if (!env || !env.CONFIGS) return json({ ok: true });
      let body;
      try {
        body = await request.json();
      } catch {
        return json({ ok: true });
      }
      // Unauthenticated, and every branch below writes a KV key derived
      // from caller input -- so it gets the same per-IP bucket the other
      // anonymous write endpoints here use. Returns ok:true rather than
      // 429 on purpose: this is a fire-and-forget beacon, and a real
      // client has nothing useful to do with a rejection.
      // CONFIGS is guaranteed bound at this point (checked above).
      const trackIp = clientIpKey(request);
      if (!trackIp) return json({ ok: true });
      const trackRateKey = `ratelimit:trackevent:${trackIp}`;
      const trackAttempts = parseInt((await env.CONFIGS.get(trackRateKey)) || "0", 10);
      if (trackAttempts >= 30) return json({ ok: true });
      ctx.waitUntil(env.CONFIGS.put(trackRateKey, String(trackAttempts + 1), { expirationTtl: 60 }));

      const events = Array.isArray(body.events) ? body.events.slice(0, 50) : [];
      // "catalog-add" is deliberately absent: no client has ever sent it
      // (installed catalogs are counted by /api/track-install, which feeds
      // stats:sourcegroup: instead), so the only thing that branch could
      // still do was let an anonymous caller mint stats:catalog_add: keys
      // that nothing legitimate ever writes.
      const allowedTypes = new Set(["watched", "list-add", "list-copy"]);
      await Promise.all(
        events.map((e) => {
          if (!e || !allowedTypes.has(e.eventType)) return Promise.resolve();
          if (e.eventType === "list-copy") {
            // Only this add-on's own lists, keyed by the slug the admin
            // panel actually reads -- see recordListCopySlug (03_admin.js).
            const slug = recordListCopySlug(e.id, url.origin);
            if (slug) return bumpStat(env, `list_copy:${slug}`);
            return Promise.resolve();
          }
          if (!e.id) return Promise.resolve();
          // The id becomes part of three permanent KV key names
          // (evtcount:/evtmeta:), so it is constrained to the shape a real
          // title id actually has -- "tt123", "tt123:1:2", "tmdb:456",
          // "channel_x", a bare TMDB number. Truncating to 100 characters
          // bounded the length but not the contents, which let arbitrary
          // text (including markup) end up in key names.
          const evtId = String(e.id).trim();
          if (!/^[A-Za-z0-9][A-Za-z0-9:_.-]{0,99}$/.test(evtId)) return Promise.resolve();
          return recordTrackedEvent(
            env,
            e.eventType,
            evtId,
            String(e.title || "").slice(0, 200),
            e.mediaType === "series" ? "series" : "movie"
          );
        })
      );
      return json({ ok: true });
    }

    // /api/mdblist-my-lists?apikey=... OR ?accessToken=...
    // -> powers the "Your MDBList Lists" section in the builder: includes
    // your Watchlist, Watch History, and all created public & private lists.
    if (path === "/api/mdblist-my-lists") {
      const apikey = (url.searchParams.get("apikey") || "").trim();
      const accessToken = (url.searchParams.get("accessToken") || "").trim();
      if (!apikey && !accessToken) return json({ ok: false, error: "Missing apikey or accessToken." }, 400);
      try {
        const token = accessToken || apikey;
        const headers = { "User-Agent": `my-list-addon/${ADDON_VERSION}` };
        if (accessToken) {
          headers["Authorization"] = `Bearer ${accessToken}`;
        }
        const targetUrl = `https://api.mdblist.com/lists/user?apikey=${encodeURIComponent(token)}`;
        const res = await fetch(targetUrl, {
          headers,
          cf: { cacheTtl: 60, cacheEverything: false },
        });
        if (!res.ok) {
          // 429 means MDBList's own rate limit was hit -- a bad/expired
          // key would come back as 401/403, not 429, so don't tell the
          // person to "double check the API key" for a rate limit; that
          // sends them looking in the wrong place. See the matching hint
          // logic in fetchMdblistList (06_source-fetchers-mdblist-trakt.js)
          // for the same distinction on the other MDBList call site.
          const hint = res.status === 429
            ? " MDBList's rate limit was hit -- wait a bit and try again."
            : (res.status === 401 || res.status === 403 ? " Double check the API key or connection." : "");
          return json({ ok: false, error: `MDBList request failed (HTTP ${res.status}).${hint}` });
        }
        const data = await res.json();
        const rawLists = Array.isArray(data) ? data : Array.isArray(data.lists) ? data.lists : [];

        let username = "";
        for (const l of rawLists) {
          if (l && (l.user_name || l.username || l.user)) {
            username = l.user_name || l.username || l.user;
            break;
          }
        }

        if (!username) {
          try {
            const uRes = await fetch(`https://api.mdblist.com/user?apikey=${encodeURIComponent(token)}`, {
              headers,
              cf: { cacheTtl: 300, cacheEverything: false },
            });
            if (uRes.ok) {
              const uData = await uRes.json();
              if (uData) {
                username = uData.user || uData.username || uData.user_name || uData.name || "";
              }
            }
          } catch {}
        }

        const lists = rawLists
          .filter((l) => l && (l.slug || l.id))
          .map((l) => {
            const itemUser = l.user_name || l.username || l.user || username || "";
            return {
              id: l.id != null ? String(l.id) : (l.slug || ""),
              name: l.name || l.slug,
              slug: l.slug,
              dynamic: !!l.dynamic,
              mediatype: l.mediatype || "",
              contentType: l.mediatype === "show" ? "series" : (l.mediatype === "movie" ? "movie" : "unknown"),
              items: l.items || 0,
              likes: l.likes || 0,
              private: l.public === false || l.private === true,
              url: itemUser ? `https://mdblist.com/lists/${encodeURIComponent(itemUser)}/${encodeURIComponent(l.slug)}` : `https://mdblist.com/lists/${encodeURIComponent(l.slug)}`,
            };
          });

        let mdblistAiringCandidates = [];
        let wlItemCount = 0;
        let wlSampleItems = [];
        try {
          const authQuery = `?apikey=${encodeURIComponent(token)}`;
          const [showsRes, epsRes, wlRes, wlItemsRes, wlSyncRes] = await Promise.all([
            fetch(`https://api.mdblist.com/sync/watched${authQuery}&mediatype=show&limit=50&append_to_response=poster`, {
              headers,
              cf: { cacheTtl: 60, cacheEverything: false },
            }).catch(() => null),
            fetch(`https://api.mdblist.com/sync/watched${authQuery}&mediatype=episode&limit=50&append_to_response=poster`, {
              headers,
              cf: { cacheTtl: 60, cacheEverything: false },
            }).catch(() => null),
            fetch(`https://api.mdblist.com/watchlist${authQuery}`, {
              headers,
              cf: { cacheTtl: 120, cacheEverything: false },
            }).catch(() => null),
            fetch(`https://api.mdblist.com/watchlist/items${authQuery}`, {
              headers,
              cf: { cacheTtl: 120, cacheEverything: false },
            }).catch(() => null),
            fetch(`https://api.mdblist.com/sync/watchlist${authQuery}`, {
              headers,
              cf: { cacheTtl: 120, cacheEverything: false },
            }).catch(() => null),
          ]);

          const rawAiringItems = [];
          if (showsRes && showsRes.ok) {
            const d = await showsRes.json().catch(() => []);
            if (Array.isArray(d)) rawAiringItems.push(...d);
            else if (d && Array.isArray(d.shows)) rawAiringItems.push(...d.shows);
            else if (d && Array.isArray(d.results)) rawAiringItems.push(...d.results);
          }
          if (epsRes && epsRes.ok) {
            const d = await epsRes.json().catch(() => []);
            if (Array.isArray(d)) rawAiringItems.push(...d);
            else if (d && Array.isArray(d.episodes)) rawAiringItems.push(...d.episodes);
            else if (d && Array.isArray(d.results)) rawAiringItems.push(...d.results);
          }

          let wlAll = [];
          const wlResponses = [wlRes, wlItemsRes, wlSyncRes];
          for (const r of wlResponses) {
            if (r && r.ok) {
              const d = await r.json().catch(() => null);
              if (d) {
                const target = d.watchlist || d.data || d;
                if (Array.isArray(target) && target.length) {
                  wlAll = target;
                  break;
                } else if (target && typeof target === "object") {
                  const movies = Array.isArray(target.movies) ? target.movies : [];
                  const shows = Array.isArray(target.shows) ? target.shows : [];
                  const series = Array.isArray(target.series) ? target.series : [];
                  const episodes = Array.isArray(target.episodes) ? target.episodes : [];
                  const seasons = Array.isArray(target.seasons) ? target.seasons : [];
                  const results = Array.isArray(target.results) ? target.results : [];
                  const items = Array.isArray(target.items) ? target.items : [];
                  const combined = [...movies, ...shows, ...series, ...episodes, ...seasons, ...results, ...items];
                  if (combined.length) {
                    wlAll = combined;
                    break;
                  }
                }
              }
            }
          }

          if (!wlAll.length) {
            const wlListObj = rawLists.find(l => l && (l.slug === 'watchlist' || (l.name && l.name.toLowerCase() === 'watchlist') || l.is_watchlist || l.watchlist));
            if (wlListObj && wlListObj.id) {
              const customWlRes = await fetch(`https://api.mdblist.com/lists/${encodeURIComponent(wlListObj.id)}/items${authQuery}`, { headers }).catch(() => null);
              if (customWlRes && customWlRes.ok) {
                const customWlData = await customWlRes.json().catch(() => null);
                if (Array.isArray(customWlData)) wlAll = customWlData;
                else if (customWlData && typeof customWlData === "object") {
                  wlAll = [
                    ...(Array.isArray(customWlData.movies) ? customWlData.movies : []),
                    ...(Array.isArray(customWlData.shows) ? customWlData.shows : []),
                    ...(Array.isArray(customWlData.results) ? customWlData.results : []),
                    ...(Array.isArray(customWlData.items) ? customWlData.items : []),
                  ];
                }
              }
            }
          }

          if (wlAll.length) {
            rawAiringItems.push(...wlAll);
            const parsedMetas = (typeof mapMdblistItems === "function") ? mapMdblistItems(wlAll, "mixed") : [];
            wlItemCount = parsedMetas.length || wlAll.length;
            wlSampleItems = parsedMetas.slice(0, 10);
          }

          const seenIds = new Set();
          for (const it of rawAiringItems) {
            const extracted = typeof extractMdblistItem === "function" ? extractMdblistItem(it) : null;
            if (extracted && (extracted.mediatype === "series" || extracted.mediatype === "show" || extracted.mediatype === "tv" || extracted.season != null || extracted.episode != null)) {
              const bestId = extracted.id;
              if (bestId && !seenIds.has(bestId)) {
                seenIds.add(bestId);
                mdblistAiringCandidates.push({
                  id: bestId,
                  imdbId: extracted.imdbId || null,
                  tmdbId: extracted.tmdbId || null,
                  name: extracted.showTitle || extracted.name || "",
                  year: extracted.releaseInfo || "",
                  poster: extracted.poster || (extracted.imdbId ? `https://images.metahub.space/poster/medium/${extracted.imdbId}/img` : ""),
                  type: "series",
                });
              }
            }
          }
        } catch {}

        const watchlistCard = {
          name: "My Watchlist",
          slug: "watchlist",
          items: wlItemCount,
          likes: 0,
          private: true,
          url: "mdblist:watchlist",
          contentType: "unknown",
          previewItems: wlSampleItems,
        };

        const historyCard = {
          name: "Watch History",
          slug: "history",
          items: 0,
          likes: 0,
          private: true,
          url: username ? `https://mdblist.com/history/${encodeURIComponent(username)}` : "mdblist:history",
          contentType: "unknown",
        };

        const airingNextCard = {
          name: "MDBList Airing Next",
          slug: "airing-next",
          statusKey: "airing-next",
          type: "series",
          contentType: "series",
          itemCount: mdblistAiringCandidates.length,
          items: mdblistAiringCandidates,
          private: true,
          url: "mdblist:user:shows:airing-next",
        };

        return json({ ok: true, lists: [airingNextCard, watchlistCard, historyCard, ...lists], username });
      } catch (err) {
        return json({ ok: false, error: safeErrorMessage(err) });
      }
    }

    // /api/mdblist-history-raw (POST) { apikey, accessToken, username? } -> { ok, items }
    if (path === "/api/mdblist-history-raw" && request.method === "POST") {
      let body;
      try { body = await request.json(); } catch { return json({ ok: false, error: "Invalid JSON body." }, 400); }
      const apikey = String(body.apikey || "").trim();
      const accessToken = String(body.accessToken || "").trim();
      let username = String(body.username || "").trim();
      const pageArg = parseInt(body.page || 1, 10);
      const token = accessToken || apikey;
      if (!token && !username) return json({ ok: false, error: "Not connected to MDBList." }, 400);
      try {
        const headers = { "User-Agent": `my-list-addon/${ADDON_VERSION}`, "Accept": "application/json" };
        const authQuery = accessToken ? "" : `?apikey=${encodeURIComponent(apikey)}`;
        if (accessToken) {
          headers["Authorization"] = `Bearer ${accessToken}`;
        }

        if (!username) {
          try {
            const userListsRes = await fetch(`https://api.mdblist.com/lists/user${authQuery}`, { headers });
            if (userListsRes.ok) {
              const udata = await userListsRes.json();
              const raw = Array.isArray(udata) ? udata : (Array.isArray(udata.lists) ? udata.lists : []);
              const found = raw.find((l) => l && l.user_name);
              if (found) username = found.user_name;
            }
          } catch {}
        }

        // Fetch all history from MDBList /sync/watched across mediatypes (movie, show, episode)
        let allItems = [];
        const logs = [];
        const LIMIT = 1000;
        const MAX_PAGES = 10;

        const mediatypes = ["movie", "show", "episode"];
        for (const mt of mediatypes) {
          let cursor = null;
          let offset = 0;
          let hasMore = true;
          let pageCount = 0;

          while (hasMore && pageCount < MAX_PAGES) {
            pageCount++;
            const sep = authQuery ? "&" : "?";
            const cursorParam = cursor ? `&cursor=${encodeURIComponent(cursor)}` : `&offset=${offset}`;
            const pageUrl = `https://api.mdblist.com/sync/watched${authQuery}${sep}mediatype=${mt}&limit=${LIMIT}${cursorParam}&append_to_response=poster`;
            try {
              const res = await fetch(pageUrl, {
                headers,
                cf: { cacheTtl: 0, cacheEverything: false },
              });
              const text = await res.text();
              let parsed = null;
              try { parsed = JSON.parse(text); } catch {}
              logs.push({ url: pageUrl.replace(apikey, "***").replace(accessToken, "***"), status: res.status, preview: text.slice(0, 120) });
              if (!res.ok || !parsed) break;

              const movies = Array.isArray(parsed.movies) ? parsed.movies : [];
              const shows = Array.isArray(parsed.shows) ? parsed.shows : [];
              const episodes = Array.isArray(parsed.episodes) ? parsed.episodes : [];
              const seasons = Array.isArray(parsed.seasons) ? parsed.seasons : [];
              const results = Array.isArray(parsed.results) ? parsed.results : [];
              const items = Array.isArray(parsed.items) ? parsed.items : [];
              const rawArray = Array.isArray(parsed) ? parsed : [];
              const batch = [...movies, ...shows, ...episodes, ...seasons, ...results, ...items, ...rawArray];
              allItems.push(...batch);

              if (parsed.next_cursor) {
                cursor = parsed.next_cursor;
                hasMore = true;
              } else if (batch.length >= LIMIT) {
                offset += batch.length;
                hasMore = true;
              } else {
                hasMore = false;
              }
            } catch (e) {
              logs.push({ url: pageUrl.replace(apikey, "***").replace(accessToken, "***"), error: safeErrorMessage(e) });
              break;
            }
          }
        }

        // If mediatype queries returned nothing, fallback to unfiltered /sync/watched
        if (!allItems.length) {
          let cursor = null;
          let offset = 0;
          let hasMore = true;
          let pageCount = 0;
          while (hasMore && pageCount < MAX_PAGES) {
            pageCount++;
            const sep = authQuery ? "&" : "?";
            const cursorParam = cursor ? `&cursor=${encodeURIComponent(cursor)}` : `&offset=${offset}`;
            const pageUrl = `https://api.mdblist.com/sync/watched${authQuery}${sep}limit=${LIMIT}${cursorParam}&append_to_response=poster`;
            try {
              const res = await fetch(pageUrl, {
                headers,
                cf: { cacheTtl: 0, cacheEverything: false },
              });
              const text = await res.text();
              let parsed = null;
              try { parsed = JSON.parse(text); } catch {}
              logs.push({ url: pageUrl.replace(apikey, "***").replace(accessToken, "***"), status: res.status, preview: text.slice(0, 120) });
              if (!res.ok || !parsed) break;

              const movies = Array.isArray(parsed.movies) ? parsed.movies : [];
              const shows = Array.isArray(parsed.shows) ? parsed.shows : [];
              const episodes = Array.isArray(parsed.episodes) ? parsed.episodes : [];
              const seasons = Array.isArray(parsed.seasons) ? parsed.seasons : [];
              const results = Array.isArray(parsed.results) ? parsed.results : [];
              const items = Array.isArray(parsed.items) ? parsed.items : [];
              const rawArray = Array.isArray(parsed) ? parsed : [];
              const batch = [...movies, ...shows, ...episodes, ...seasons, ...results, ...items, ...rawArray];
              allItems.push(...batch);

              if (parsed.next_cursor) {
                cursor = parsed.next_cursor;
                hasMore = true;
              } else if (batch.length >= LIMIT) {
                offset += batch.length;
                hasMore = true;
              } else {
                hasMore = false;
              }
            } catch (e) {
              logs.push({ url: pageUrl.replace(apikey, "***").replace(accessToken, "***"), error: safeErrorMessage(e) });
              break;
            }
          }
        }

        return json({ ok: true, items: allItems, debug: logs });
      } catch (err) {
        return json({ ok: false, error: safeErrorMessage(err) });
      }
    }

    // /api/resolve?config=...
    // -> powers "Import from a link" in the builder page. Reuses the same
    // resolveConfig() the manifest/configure routes already use (handles
    // both a short KV id and a legacy self-contained base64 blob), just
    // returned as plain JSON instead of a manifest or an HTML page -- so
    // pasting an existing install/configure link can rebuild the same rows
    // client-side via addRow(), the same way importing a config JSON blob
    // does.
    if (path === "/api/resolve") {
      const config = url.searchParams.get("config") || "";
      const rawUrl = url.searchParams.get("url") || "";
      if (!config) return json({ ok: false, error: "Missing config." }, 400);
      try {
        let resData = await resolveConfig(config, env);
        let { entries, mdblistKey, mdblistAccessToken, traktKey, traktUsername, traktAccessToken, watchHistory, continueWatching, watchlist, airingNext } = resData;
        if (!entries || !entries.length) {
          if (rawUrl && /^https?:\/\//i.test(rawUrl)) {
            try {
              const u = new URL(rawUrl);
              const remoteResolveUrl = `${u.origin}/api/resolve?config=${encodeURIComponent(config)}`;
              const remoteRes = await fetch(remoteResolveUrl);
              if (remoteRes.ok) {
                const remoteData = await remoteRes.json();
                if (remoteData && remoteData.ok && Array.isArray(remoteData.entries) && remoteData.entries.length) {
                  return json(remoteData);
                }
              }
            } catch {}
          }
        }
        if (!entries || !entries.length) return json({ ok: false, error: "That link has no lists in it." });
        return json({
          ok: true,
          entries,
          watchHistory: watchHistory || [],
          continueWatching: continueWatching || [],
          watchlist: watchlist || [],
          airingNext: airingNext || [],
          mdblistKey,
          mdblistAccessToken,
          traktKey,
          traktUsername,
          traktAccessToken
        });
      } catch (err) {
        return json({ ok: false, error: safeErrorMessage(err) });
      }
    }

    // POST /api/save  { entries, mdblistKey, traktKey, traktUsername } -> { ok, id }
    // Stores the config server-side (when a CONFIGS KV namespace is bound)
    // and returns a short id to use in the install URL instead of a long
    // base64 blob. Returns { ok: false, error: "no-kv" } when no KV
    // namespace is bound, so the builder page can fall back to the old
    // client-side base64 link instead.
    if (path === "/api/save" && request.method === "POST") {
      if (!env || !env.CONFIGS) {
        return json({ ok: false, error: "no-kv" });
      }
      // Unauthenticated, and each call writes a permanent KV key (the
      // install config) that nothing ever expires or deletes. Generous
      // bucket -- regenerating an install link a few times while adjusting
      // rows is normal -- but not unlimited.
      const saveIp = clientIpKey(request);
      if (!saveIp) return json({ ok: false, error: "Could not process this request." }, 400);
      const saveRateKey = `ratelimit:save:${saveIp}`;
      const saveAttempts = parseInt((await env.CONFIGS.get(saveRateKey)) || "0", 10);
      if (saveAttempts >= 20) {
        return json({ ok: false, error: "Too many saves just now. Please wait a minute and try again." }, 429);
      }
      await env.CONFIGS.put(saveRateKey, String(saveAttempts + 1), { expirationTtl: 60 });

      let body;
      try {
        body = await request.json();
      } catch {
        return json({ ok: false, error: "Invalid JSON body." }, 400);
      }
      const entries = Array.isArray(body.entries) ? body.entries : [];
      if (!entries.length) {
        return json({ ok: false, error: "No lists provided." }, 400);
      }
      // A config is a list of catalog rows; the builder's own URL-length
      // problem (see generateShortId's comment) starts around 20 rows, so
      // this ceiling is orders of magnitude above real use and only
      // rejects a payload built to waste storage. Rejected, not truncated
      // -- a silently shortened install config would be worse than an
      // error.
      if (entries.length > SAVED_CONFIG_ENTRIES_MAX) {
        return json({ ok: false, error: "Too many lists in that configuration." }, 413);
      }
      const payload = { entries };
      if (body.tmdbKey) payload.tmdbKey = body.tmdbKey;
      if (body.mdblistKey) payload.mdblistKey = body.mdblistKey;
      if (body.mdblistAccessToken) payload.mdblistAccessToken = body.mdblistAccessToken;
      if (body.traktKey) payload.traktKey = body.traktKey;
      if (body.traktUsername) payload.traktUsername = body.traktUsername;
      if (body.traktAccessToken) payload.traktAccessToken = body.traktAccessToken;
      if (body.simklKey) payload.simklKey = body.simklKey;
      if (body.simklAccessToken) payload.simklAccessToken = body.simklAccessToken;
      if (body.simklUsername) payload.simklUsername = body.simklUsername;
      if (body.track) {
        payload.track = true;
        payload.trackCreatorName = body.trackCreatorName || "";
        payload.trackCreatorKey = body.trackCreatorKey || "";
      }
      if (body.shuffleShelves) payload.shuffleShelves = true;
      if (body.shuffleItems) payload.shuffleItems = true;
      if (body.region && body.region !== "US") payload.region = body.region;
      if (body.hideNonDigitalReleases) payload.hideNonDigitalReleases = true;

      const savePayload = JSON.stringify(payload);
      // Row count alone is not a size bound -- a row carries a URL, a
      // name and a group. Checked on the exact bytes about to be stored.
      if (savePayload.length > SAVED_CONFIG_BYTES_MAX) {
        return json({ ok: false, error: "That configuration is too large to save." }, 413);
      }

      let id;
      for (let attempt = 0; attempt < 5; attempt++) {
        id = generateShortId();
        const existing = await env.CONFIGS.get(id);
        if (!existing) break;
      }
      await env.CONFIGS.put(id, savePayload);
      return json({ ok: true, id });
    }

    if (path === "/api/publish-list" && request.method === "POST") {
      if (!env || !env.CONFIGS) return json({ ok: false, error: "no-kv" });
      // Unauthenticated, and every call mints a permanent KV key that no
      // route in this Worker can ever delete again. Same per-IP bucket as
      // /api/creator/create, just a little more permissive because
      // publishing several lists in one sitting is normal.
      const plIp = clientIpKey(request);
      if (!plIp) return json({ ok: false, error: "Could not process this request." }, 400);
      const plRateKey = `ratelimit:publishlist:${plIp}`;
      const plAttempts = parseInt((await env.CONFIGS.get(plRateKey)) || "0", 10);
      if (plAttempts >= 10) {
        return json({ ok: false, error: "Too many lists published just now. Please wait a minute and try again." }, 429);
      }
      await env.CONFIGS.put(plRateKey, String(plAttempts + 1), { expirationTtl: 60 });

      let plBody;
      try { plBody = await request.json(); } catch { return json({ ok: false, error: "Invalid JSON body." }, 400); }
      const baseSlug = slugifyServer(plBody.name || "");
      const plType = (plBody.type === "series" || plBody.type === "mixed") ? plBody.type : (plBody.type === "movie" ? "movie" : null);
      const plItems = Array.isArray(plBody.items) ? plBody.items : [];
      if (!baseSlug) return json({ ok: false, error: "Missing a list name." }, 400);
      if (!plType) return json({ ok: false, error: "Missing or invalid list type." }, 400);
      // Bounds, deliberately REJECTING rather than truncating: silently
      // storing a shortened list is exactly the kind of quiet data loss
      // this endpoint should not be capable of, and a real list that is
      // over the limit deserves to be told so. The ceilings are far above
      // anything genuine -- a real account's largest observed list was
      // ~1,200 items (see compactCustomListItem, 22_client-creator-
      // profile.js) -- and exist only to stop an anonymous caller storing
      // multi-megabyte payloads permanently.
      if (String(plBody.name || "").length > PUBLISHED_LIST_NAME_MAX) {
        return json({ ok: false, error: "That list name is too long." }, 400);
      }
      if (plItems.length > PUBLISHED_LIST_ITEMS_MAX) {
        return json({ ok: false, error: `That list is too large to publish (limit ${PUBLISHED_LIST_ITEMS_MAX} items).` }, 413);
      }
      let listSlug = baseSlug;
      let plKey = "publishedlist:user:" + listSlug;
      for (let attempt = 2; attempt <= 500; attempt++) {
        const existing = await env.CONFIGS.get(plKey);
        if (!existing) break;
        listSlug = baseSlug + "-" + attempt;
        plKey = "publishedlist:user:" + listSlug;
      }
      const plVisibility = normalizeListVisibility(plBody.visibility);
      const plNow = Date.now();
      const plPayload = JSON.stringify({ name: plBody.name || baseSlug, type: plType, items: plItems, visibility: plVisibility, likes: 0, publishedAt: plNow });
      // Item COUNT alone is not a size bound -- individual items carry
      // titles, overviews and poster URLs, so a few thousand of them can
      // still be many megabytes. This is the bound that actually protects
      // storage, checked on the exact bytes about to be written.
      if (plPayload.length > PUBLISHED_LIST_BYTES_MAX) {
        return json({ ok: false, error: "That list is too large to publish." }, 413);
      }
      await env.CONFIGS.put(plKey, plPayload);
      // Anonymous publishes belong in the directory index too.
      if (isPublicListVisibility(plVisibility)) {
        ctx.waitUntil(updatePublicListIndex(env, `a:${listSlug}`, {
          isCreator: false,
          username: "user",
          slug: listSlug,
          name: plBody.name || baseSlug,
          type: plType,
          itemCount: plItems.length,
          likes: 0,
          updatedAt: plNow,
        }));
      }
      return json({ ok: true, listName: listSlug, url: url.origin + "/lists/user/" + listSlug });
    }

    if (path === "/api/lists/like" && request.method === "POST") {
      if (!env || !env.CONFIGS) return json({ ok: false, error: "no-kv" });
      let likeBody;
      try { likeBody = await request.json(); } catch { return json({ ok: false, error: "Invalid JSON body." }, 400); }
      const likeUser = String(likeBody.username || "").toLowerCase().trim();
      const likeSlug = String(likeBody.slug || "").toLowerCase().trim();
      const likeUnlike = likeBody.action === "unlike";
      if (!likeUser || !likeSlug) return json({ ok: false, error: "Missing list reference." }, 400);

      // The list must actually exist before any vote is recorded --
      // otherwise a ledger (and a permanent KV key) could be created for
      // any username/slug pair someone cared to invent.
      const likeCreatorKey = "creatorlist:" + likeUser + ":" + likeSlug;
      const likeAnonKey = "publishedlist:" + likeUser + ":" + likeSlug;
      let likeKey = null;
      let likeRaw = await env.CONFIGS.get(likeCreatorKey);
      if (likeRaw) { likeKey = likeCreatorKey; } else { likeRaw = await env.CONFIGS.get(likeAnonKey); if (likeRaw) likeKey = likeAnonKey; }
      if (!likeKey) return json({ ok: false, error: "List not found." }, 404);
      let likeData;
      try { likeData = JSON.parse(likeRaw); } catch { return json({ ok: false, error: "Corrupted." }, 500); }
      await stampListVisibilityIfNeeded(env, likeKey, likeData);

      // Signed-in visitors vote as themselves; everyone else votes as a
      // per-list hash of their IP. Either way one identity is worth exactly
      // one like, no matter how many times it POSTs. A creatorKey is
      // verified when supplied, but is NOT required -- signed-out liking
      // is existing behaviour and stays working.
      let likeVoterName = "";
      if (likeBody.creatorName && likeBody.creatorKey) {
        const likeAuth = await authenticateCreator(likeBody.creatorName, likeBody.creatorKey);
        if (likeAuth.ok) likeVoterName = likeAuth.username;
      }
      const listScopeId = `${likeUser}:${likeSlug}`;
      const voterId = await likeVoterId(request, env, likeVoterName, listScopeId);
      if (!voterId) return json({ ok: false, error: "Could not process this request." }, 400);
      const ledgerKey = `listlikevoters:${listScopeId}`;
      const { count, capped } = await applyLikeVote(env, ledgerKey, voterId, !likeUnlike);

      // The count lives on the list record too, because the directory,
      // search, and the admin dashboard all read it from there and none of
      // them should have to open a ledger per list. Derived from the
      // ledger, never incremented, so it cannot drift upward on its own.
      //
      // Re-read before writing. `likeData` was parsed before applyLikeVote,
      // which spends several KV round-trips on the ledger (up to four
      // read/write/verify attempts under contention). Writing that stale
      // snapshot back put the WHOLE record -- items included -- on top of
      // whatever landed in the meantime, so a like arriving while the
      // list's owner was saving silently reverted their edit, with both
      // requests returning 200. Only the one field this route owns gets
      // written, onto the current record.
      if ((likeData.likes || 0) !== count) {
        // Re-read, then copy only `likes` onto the CURRENT record. If it
        // vanished or turned unparseable while the vote was being
        // recorded, write nothing at all: the ledger already holds the
        // vote, and re-creating the record from a stale copy would be
        // worse than leaving the denormalised count to catch up on the
        // next like.
        const freshRaw = await env.CONFIGS.get(likeKey);
        let updated = null;
        if (freshRaw) {
          try {
            updated = JSON.parse(freshRaw);
            updated.likes = count;
          } catch {
            updated = null;
          }
        }
        if (updated) {
          await env.CONFIGS.put(likeKey, JSON.stringify(updated));
          // The directory ranks by likes, so the index has to see this or the
          // ordering freezes at whatever it was when the index was built.
          // Only on an actual change -- a repeated like writes nothing.
          // Anonymous lists are indexed as `a:<slug>`, creator-owned as
          // `c:<user>:<slug>` -- using the wrong prefix here would append a
          // duplicate entry instead of updating the existing one.
          // Fed from `updated`, not the pre-vote snapshot, so the indexed
          // name/type/itemCount match what is actually stored.
          const likeIsCreator = likeKey === likeCreatorKey;
          if (isPublicListVisibility(updated.visibility)) {
            ctx.waitUntil(updatePublicListIndex(env, likeIsCreator ? `c:${likeUser}:${likeSlug}` : `a:${likeSlug}`, {
              isCreator: likeIsCreator,
              username: likeIsCreator ? likeUser : "user",
              slug: likeSlug,
              name: updated.name || "List",
              type: updated.type || "mixed",
              itemCount: Array.isArray(updated.items) ? updated.items.length : 0,
              likes: count,
              updatedAt: updated.updatedAt || updated.createdAt || null,
            }));
          }
        }
      }

      if (env.DB) {
        try {
          await env.DB.prepare("UPDATE creator_lists SET likes = ? WHERE id = ?").bind(count, listScopeId).run();
        } catch (dbErr) {
          // Non-fatal: KV above holds the authoritative count, so a like is
          // never lost by D1 being unavailable. Requires the `likes` column
          // from migrations/0001; without it this throws on every like.
          console.error("D1 write error (list likes):", dbErr);
        }
      }

      return json({ ok: true, likes: count, liked: !likeUnlike, capped: capped || undefined });
    }

    if (path === "/api/lists/like-external" && request.method === "POST") {
      if (!env || !env.CONFIGS) return json({ ok: false, error: "no-kv" });
      let body;
      try {
        body = await request.json();
      } catch {
        return json({ ok: false, error: "Invalid JSON body." }, 400);
      }
      const rawUrl = String(body.url || "").trim();
      if (!rawUrl) return json({ ok: false, error: "Missing list URL." }, 400);
      // Validated and normalized before it is allowed anywhere near a KV
      // key -- see normalizeExternalListUrl. Rejects non-http(s) schemes,
      // over-long strings, and any host that isn't a provider this add-on
      // integrates with, which is what stops this endpoint being an
      // unbounded attacker-controlled keyspace.
      const normalizedUrl = normalizeExternalListUrl(rawUrl);
      if (!normalizedUrl) {
        return json({ ok: false, error: "That URL can't be liked -- only MDBList, Trakt, TMDB, Simkl, and Letterboxd list links are supported." }, 400);
      }
      const unlike = body.action === "unlike";

      let extVoterName = "";
      if (body.creatorName && body.creatorKey) {
        const extAuth = await authenticateCreator(body.creatorName, body.creatorKey);
        if (extAuth.ok) extVoterName = extAuth.username;
      }

      const hash = await hashStringForKey(normalizedUrl);
      const key = `externallike:${hash}`;
      const voterId = await likeVoterId(request, env, extVoterName, hash);
      if (!voterId) return json({ ok: false, error: "Could not process this request." }, 400);
      const { count, capped } = await applyLikeVote(env, `extlikevoters:${hash}`, voterId, !unlike);

      const raw = await env.CONFIGS.get(key);
      let data = { url: normalizedUrl, likes: 0 };
      if (raw) {
        try {
          data = JSON.parse(raw);
        } catch {
          data = { url: normalizedUrl, likes: 0 };
        }
      }
      if (data.likes !== count || data.url !== normalizedUrl) {
        data.likes = count;
        data.url = normalizedUrl;
        data.updatedAt = Date.now();
        await env.CONFIGS.put(key, JSON.stringify(data));
      }
      return json({ ok: true, likes: count, liked: !unlike, capped: capped || undefined });
    }


    // /api/details/batch  (POST)  { ids: [...], type?, tmdbKey?, region?, fresh? }
    //   -> { ok, results: { <id>: details | null } }
    // The plural sibling of /api/details below, for callers that already
    // know they need many shows at once. Airing Next is the one that
    // matters (refreshAiringNext, 21_client-custom-list-builder.js): it
    // walks up to 60 shows per refresh, and was doing so as 60 separate
    // round trips at a concurrency of 4 -- so fifteen sequential waves of
    // request latency before the shelf could be rebuilt, per browser, per
    // refresh.
    //
    // This is not a way to make MORE upstream calls in one go. Each id
    // still goes through fetchTmdbItemDetails, which means the shared
    // memory/KV/edge cache and, as of the same change, in-flight
    // coalescing -- so ids already known cost nothing, ids being fetched
    // concurrently by another request are joined rather than duplicated,
    // and only genuine misses reach TMDB. The batch simply removes the
    // round trips.
    //
    // Capped at 60 ids to bound the worst case for a single request, and
    // resolved with a small worker pool rather than one Promise.all over
    // every id, so a large batch of genuine misses cannot open sixty
    // simultaneous TMDB connections. A failed id resolves to null rather
    // than failing the batch -- the caller simply retries it next refresh,
    // exactly as it did when each id was its own request.
    if (path === "/api/details/batch" && request.method === "POST") {
      let reqBody;
      try {
        reqBody = await request.json();
      } catch {
        return json({ ok: false, error: "Invalid JSON body." }, 400);
      }
      const rawIds = Array.isArray(reqBody.ids) ? reqBody.ids : [];
      // De-duplicated up front: the same show can legitimately appear under
      // both an imdb and a tmdb-prefixed id in a Watch History, and there is
      // no reason to resolve it twice.
      const ids = [...new Set(rawIds.map((v) => String(v || "").trim()).filter(Boolean))].slice(0, 60);
      if (!ids.length) return json({ ok: false, error: "Missing ids" }, 400);

      const tmdbKey = reqBody.tmdbKey || TMDB_API_KEY;
      // Rate-limited only when this falls back to the Worker owner's shared
      // TMDB key. A visitor who supplied their own is spending their own
      // quota, so there is nothing here to protect them from -- and
      // throttling them would break exactly the power users who set a key
      // up. 60/minute leaves plenty of room for the real bulk caller
      // (refreshAiringNext pages a large Watch History 60 ids at a time).
      if (!reqBody.tmdbKey) {
        const batchIp = clientIpKey(request);
        if (!batchIp) return json({ ok: false, error: "Could not load those details." }, 400);
        if (await consumeRateLimit(env, ctx, "detailsbatch", batchIp, 60)) {
          return json({ ok: false, error: "Too many lookups just now. Please wait a minute and try again." }, 429);
        }
      }
      if (!reqBody.tmdbKey) ctx.waitUntil(bumpStat(env, "apiuse:tmdb"));
      const wantType = reqBody.type || "";
      const region = reqBody.region || "";
      const isFreshReq = reqBody.fresh === "1" || reqBody.fresh === true;

      const results = {};
      let cursor = 0;
      async function worker() {
        while (cursor < ids.length) {
          const id = ids[cursor++];
          try {
            results[id] = await fetchTmdbItemDetails(id, tmdbKey, wantType, region, isFreshReq, env, ctx);
          } catch {
            results[id] = null;
          }
        }
      }
      await Promise.all(
        Array.from({ length: Math.min(6, ids.length) }, () => worker())
      );

      // Same short max-age as /api/details for the same reason -- this
      // response's shape changes occasionally and an hour-old copy would
      // strand anyone who had just opened it.
      return json({ ok: true, results }, 200, { "Cache-Control": "max-age=60" });
    }

    // /api/details (GET or POST) -> { ok: true, details: { title, overview, rating, releaseYear, poster, background } }
    if (path === "/api/details") {
      let reqBody;
      if (request.method === "POST") {
        try {
          reqBody = await request.json();
        } catch {
          reqBody = {};
        }
      } else {
        const q = url.searchParams;
        reqBody = { imdbId: q.get("imdbId") || q.get("id") || "", tmdbKey: q.get("tmdbKey") || "", type: q.get("type") || "", region: q.get("region") || "" };
      }
      
      const imdbId = reqBody.imdbId || reqBody.id;
      const tmdbKey = reqBody.tmdbKey || TMDB_API_KEY;
      if (!imdbId) return json({ ok: false, error: "Missing imdbId" }, 400);
      if (!reqBody.tmdbKey) ctx.waitUntil(bumpStat(env, "apiuse:tmdb"));
      
      const isFreshReq = reqBody.fresh === "1" || reqBody.fresh === true || (url && url.searchParams.get("fresh") === "1");
      const details = await fetchTmdbItemDetails(imdbId, tmdbKey, reqBody.type, reqBody.region, isFreshReq, env, ctx);
      if (!details) return json({ ok: false, error: "Not found or TMDB error" }, 404);
      
      // Short max-age -- same reasoning as /api/season's own comment: this
      // response's shape changes occasionally (tmdbId is a recent
      // addition), and json()'s 3600s default would leave anyone who'd
      // opened this exact show recently stuck looking at an hour-old,
      // pre-fix cached copy.
      return json({ ok: true, details }, 200, { "Cache-Control": "max-age=60" });
    }

    // --- Creator Profile system --------------------------------------------
    //
    // No accounts, no email, no passwords -- a Creator Profile is just a
    // chosen name plus a randomly generated Creator Key (see
    // generateCreatorKey), with only a salted hash of that key ever stored
    // (see hashCreatorKey/verifyCreatorKey above). There's no session or
    // token issued on "login" either: every authenticated request below
    // re-sends the creatorName + creatorKey and gets re-verified against
    // the stored hash each time, which is what "no authentication system"
    // means here in practice -- simple, stateless, and nothing to expire
    // or revoke separately from the key itself.
    async function authenticateCreator(creatorNameRaw, creatorKey) {
      if (!env || !env.CONFIGS) return { ok: false, error: "no-kv" };
      const v = validateCreatorUsername(creatorNameRaw);
      if (!v.ok) return { ok: false, error: "Username or Key is incorrect." };
      const raw = await getCreator(env, v.normalized);
      if (!raw) return { ok: false, error: "Username or Key is incorrect." };
      let profile;
      try {
        profile = JSON.parse(raw);
      } catch {
        return { ok: false, error: "Username or Key is incorrect." };
      }
      // Memoized only after a successful PBKDF2 verification, in this
      // isolate's memory, for a few minutes -- see
      // verifyCreatorKeyMemoized (02_http-and-creator-utils.js) for why
      // that is not a weakening of the check. A wrong key still costs a
      // full PBKDF2 run every single time.
      const valid = await verifyCreatorKeyMemoized(creatorKey || "", profile.keyHash, v.normalized);
      if (!valid) return { ok: false, error: "Username or Key is incorrect." };
      // Fire-and-forget, not awaited -- see touchCreatorLastSeen's own
      // comment for why this is throttled and safe to never wait on.
      touchCreatorLastSeen(env, v.normalized);
      return { ok: true, username: v.normalized, displayName: profile.displayName };
    }

    // Every failure path above returns the exact same generic message
    // deliberately -- "that name doesn't exist" vs "that key is wrong"
    // would let someone enumerate which creator names are already taken
    // just by trying to restore them.

    // Handles a single "this just started playing" ping from the
    // /:config/subtitles/... route (25_api-catalog-routes.js) -- see
    // buildManifest's comment for the full mechanism. Never throws back
    // to the caller (that route already responded before this runs, via
    // ctx.waitUntil), so every failure path below just records a
    // diagnostic and returns quietly instead.
    //
    // An episode gets marked watched outright: if you're playing it,
    // you're caught up to it -- a discrete, already-aired unit with
    // nothing ambiguous about it. A movie ping gets treated the same way
    // here, marked watched immediately, which is a deliberate
    // simplification versus where this idea started (a similar reference
    // implementation treats a movie ping as merely "in progress," since
    // one ping at the start doesn't prove you finished a 2-hour movie the
    // way starting an episode implies you're caught up to that episode).
    // This addon's Watch History has no in-progress state to put a movie
    // into, only watched/not-watched, so there isn't a cleanly analogous
    // middle ground to preserve that distinction with.
    function detectClientApp(request) {
      if (!request) return "Streaming App";
      const ua = (request.headers.get("user-agent") || "").toLowerCase();
      const referer = (request.headers.get("referer") || "").toLowerCase();
      const origin = (request.headers.get("origin") || "").toLowerCase();
      const appHeader = (request.headers.get("x-app-name") || request.headers.get("x-client-name") || request.headers.get("x-application") || "").toLowerCase();

      if (appHeader.includes("nuvio") || ua.includes("nuvio") || referer.includes("nuvio") || origin.includes("nuvio")) {
        return "Nuvio";
      }
      if (appHeader.includes("stremio") || ua.includes("stremio") || referer.includes("stremio") || origin.includes("stremio") || ua.includes("smarttv") || ua.includes("stremio-streaming-server")) {
        return "Stremio";
      }
      if (appHeader.includes("wako") || ua.includes("wako") || referer.includes("wako") || origin.includes("wako")) {
        return "Wako";
      }
      if (ua.includes("dart") || ua.includes("flutter")) {
        return "Nuvio";
      }
      if (ua.includes("cfnetwork") || (ua.includes("darwin") && !ua.includes("stremio"))) {
        return "Wako / iOS Player";
      }
      if (ua.includes("okhttp") && !ua.includes("stremio")) {
        return "Nuvio";
      }
      return "Streaming App";
    }

    async function handleSubtitlesTrack(configParam, stremioType, id, env, request) {
      if (!env || !env.CONFIGS) return;

      let track, trackCreatorName, trackCreatorKey, tmdbKey;
      try {
        ({ track, trackCreatorName, trackCreatorKey, tmdbKey } = await resolveConfig(configParam, env));
      } catch {
        return;
      }
      if (!trackCreatorName || !trackCreatorKey) return;
      if (!track) {
        // Auto-track Playback resolved to off for this install link. This
        // can happen even when the user sees the toggle on in Settings, if
        // their install link is stale (see the config staleness note on
        // resolveConfig / Configure -> Update) -- write a diagnostic so
        // "nothing showed up" is visible and traceable instead of silent.
        const diagnosticsKey = `creatortrack:${trackCreatorName.toLowerCase()}`;
        await env.CONFIGS.put(diagnosticsKey, JSON.stringify({
          lastPingAt: Date.now(),
          lastPingId: `${stremioType}:${id}`,
          matched: "no (Auto-track Playback is off for this install link -- go to Configure, re-enable it, then Update your install link)",
        }));
        return;
      }

      const auth = await authenticateCreator(trackCreatorName, trackCreatorKey);
      const diagnosticsKey = `creatortrack:${auth.ok ? auth.username : String(trackCreatorName).toLowerCase()}`;
      const pingId = `${stremioType}:${id}`;

      if (!auth.ok) {
        await env.CONFIGS.put(diagnosticsKey, JSON.stringify({
          lastPingAt: Date.now(),
          lastPingId: pingId,
          matched: "error: this install's Profile credentials no longer authenticate -- re-generate the install link from Settings.",
        }));
        return;
      }

      const effectiveTmdbKey = tmdbKey || TMDB_API_KEY;
      // Already running inside the caller's ctx.waitUntil (see
      // handleSubtitlesTrack's own call site), so no extra waitUntil
      // needed here -- see trackSharedApiUse in 05_catalog-core.js for
      // the same pattern elsewhere.
      if (!tmdbKey) bumpStat(env, "apiuse:tmdb");
      let cleanId = String(id || "").trim();
      let imdbId = "";
      let season = null;
      let episode = null;

      if (cleanId.startsWith("tmdb:")) {
        const rest = cleanId.slice("tmdb:".length);
        const tmdbParts = rest.split(":");
        imdbId = "tmdb:" + tmdbParts[0];
        if (tmdbParts.length >= 3) {
          season = Number(tmdbParts[1]);
          episode = Number(tmdbParts[2]);
        } else if (tmdbParts.length === 2) {
          season = Number(tmdbParts[0]);
          episode = Number(tmdbParts[1]);
        }
      } else if (cleanId.startsWith("kitsu:")) {
        const rest = cleanId.slice("kitsu:".length);
        const kParts = rest.split(":");
        imdbId = "kitsu:" + kParts[0];
        if (kParts.length >= 2) {
          season = 1;
          episode = Number(kParts[1]);
        }
      } else {
        const parts = cleanId.split(":");
        imdbId = parts[0];
        if (parts.length >= 3) {
          season = Number(parts[1]);
          episode = Number(parts[2]);
        } else if (parts.length === 2) {
          season = 1;
          episode = Number(parts[1]);
        }
      }
      let matched = "no";

      try {
        await ensureTrackingMigrated(env, auth.username);
        const syncKey = `creatorsynctracking:${auth.username}`;

        // Resolve what we're actually recording (TMDB lookups) exactly
        // once, before touching KV at all -- these are the slow, expensive
        // part and don't need to be repeated if the KV write below has to
        // retry.
        let recordEpisode = null; // { epIdStr, episodeEntry, showTitle }
        let recordMovie = null; // { movieId, movieEntry, movieTitle }

        if (stremioType === "series" || (season != null && episode != null)) {
          if (season == null || episode == null || !Number.isFinite(season) || !Number.isFinite(episode)) {
            matched = "no (unrecognized episode id format)";
          } else {
            const seasonData = await fetchTmdbSeasonDetails(imdbId, season, effectiveTmdbKey, null, env, ctx);
            let ep = seasonData && seasonData.episodes ? seasonData.episodes.find((e) => e.episode_number === episode) : null;
            if (!ep && seasonData && Array.isArray(seasonData.episodes) && seasonData.episodes.length > 0) {
              ep = seasonData.episodes[episode - 1] || seasonData.episodes[0];
            }
            if (!ep) {
              matched = "no (could not look up this episode on TMDB)";
            } else {
              const showDetails = await fetchTmdbItemDetails(imdbId, effectiveTmdbKey, "series", "", false, env, ctx).catch(() => null);
              const showGenres = (showDetails && showDetails.genres) || [];
              const showYear = (showDetails && (showDetails.releaseYear || showDetails.year || (showDetails.releaseDate && showDetails.releaseDate.slice(0, 4)))) || null;
              ctx.waitUntil(recordPlaybackTelemetry(env, "episode", showGenres, showYear));
              if (showDetails && showDetails.title) {
                ctx.waitUntil(recordTrackedEvent(env, "watched", imdbId, showDetails.title, "series"));
              }
              const epIdStr = String(ep.id || `${imdbId}:${season}:${episode}`);
              recordEpisode = {
                epIdStr,
                showTitle: (showDetails && showDetails.title) || imdbId,
                episodeEntry: {
                  id: epIdStr,
                  type: "episode",
                  name: ep.name || ("Episode " + episode),
                  poster: ep.still_path ? (ep.still_path.startsWith("http") ? ep.still_path : "https://image.tmdb.org/t/p/w500" + ep.still_path) : ((showDetails && showDetails.poster) || ""),
                  showId: imdbId,
                  showTitle: (showDetails && showDetails.title) || "",
                  showPoster: (showDetails && showDetails.poster) || "",
                  seasonNum: season,
                  episodeNum: episode,
                },
              };
            }
          }
        } else if (stremioType === "movie") {
          const details = await fetchTmdbItemDetails(imdbId, effectiveTmdbKey, "movie", "", false, env, ctx).catch(() => null);
          const movieGenres = (details && details.genres) || [];
          const movieYear = (details && (details.releaseYear || details.year || (details.releaseDate && details.releaseDate.slice(0, 4)))) || null;
          ctx.waitUntil(recordPlaybackTelemetry(env, "movie", movieGenres, movieYear));
          if (details && details.title) {
            ctx.waitUntil(recordTrackedEvent(env, "watched", imdbId, details.title, "movie"));
          }
          const movieTitle = (details && details.title) || imdbId;
          recordMovie = {
            movieId: imdbId,
            movieTitle,
            movieEntry: {
              id: imdbId,
              type: "movie",
              name: movieTitle,
              poster: (details && details.poster) || "",
            },
          };
        } else {
          matched = "no (unrecognized id format)";
        }

        // Read-modify-write the shared per-account blob, with a bounded
        // retry: two scrobble pings for the same account (e.g. Nuvio
        // auto-advancing to the next episode and firing another ping
        // moments later, or a player re-probing subtitles mid-playback)
        // both run as independent ctx.waitUntil invocations with no
        // coordination between them, and Cloudflare KV has no
        // compare-and-swap -- if both read the blob before either writes,
        // whichever writes second silently discards whatever the first
        // one added. Re-reading fresh on each attempt and re-checking
        // alreadyWatched against that fresh copy (rather than reusing the
        // blob read at the top of this function) is what makes a retry
        // actually fix the collision instead of just moving it later.
        if (recordEpisode || recordMovie) {
          const MAX_ATTEMPTS = 3;
          let alreadyWatched = false;
          for (let attempt = 0; attempt < MAX_ATTEMPTS; attempt++) {
            const raw = await env.CONFIGS.get(syncKey);
            let blob = null;
            if (raw) {
              try {
                blob = JSON.parse(raw);
              } catch {
                blob = null;
              }
            }
            if (!blob || typeof blob !== "object") {
              blob = { watchHistory: [], continueWatching: [], fullyWatchedShowIds: [], dismissedContinueWatching: {}, trackPlayback: false };
            }
            blob.watchHistory = Array.isArray(blob.watchHistory) ? blob.watchHistory : [];
            blob.continueWatching = Array.isArray(blob.continueWatching) ? blob.continueWatching : [];
            blob.fullyWatchedShowIds = Array.isArray(blob.fullyWatchedShowIds) ? blob.fullyWatchedShowIds : [];
            blob.dismissedContinueWatching = blob.dismissedContinueWatching && typeof blob.dismissedContinueWatching === "object" ? blob.dismissedContinueWatching : {};
            blob.watchlist = Array.isArray(blob.watchlist) ? blob.watchlist : [];

            const beforeWrite = raw || "";

            if (recordEpisode) {
              const { epIdStr, episodeEntry } = recordEpisode;
              blob.watchHistory = blob.watchHistory.filter((it) => !(String(it.id) === epIdStr || (it.showId === imdbId && it.seasonNum === season && it.episodeNum === episode)));
              blob.watchHistory.unshift({ ...episodeEntry, watchedAt: Date.now() });
              // Recompute this show's Continue Watching the same way the
              // cron does (checkForNewEpisodes, 07_source-fetchers-tmdb-
              // simkl.js) -- if this ping's episode happens to be the
              // latest watched one, this naturally finds and queues
              // whatever airs next.
              const oldCwItems = blob.continueWatching.filter((it) => it.showId === imdbId);
              blob.continueWatching = blob.continueWatching.filter((it) => it.showId !== imdbId);
              const watchedEps = blob.watchHistory.filter((it) => it.type === "episode" && it.showId === imdbId && it.seasonNum != null && it.episodeNum != null);
              if (watchedEps.length) {
                const latest = watchedEps.reduce((best, e) => {
                  const eS = Number(e.seasonNum);
                  const eE = Number(e.episodeNum);
                  const bS = Number(best.seasonNum);
                  const bE = Number(best.episodeNum);
                  if (eS > bS) return e;
                  if (eS === bS && eE > bE) return e;
                  return best;
                }, watchedEps[0]);
                const dismissed = blob.dismissedContinueWatching[imdbId];
                const stillDismissed = !!(dismissed && dismissed.seasonNum === latest.seasonNum && dismissed.episodeNum === latest.episodeNum);
                if (!stillDismissed) {
                  const next = await findNextAiredEpisodeForShow(imdbId, latest.seasonNum, latest.episodeNum, effectiveTmdbKey, env).catch(() => null);
                  if (next) {
                    blob.continueWatching.unshift({
                      id: String(next.episode.id),
                      type: "episode",
                      name: next.episode.name,
                      // Show poster, not episode still -- see the matching
                      // comment on the cron's own continueWatching.unshift.
                      poster: latest.showPoster || "",
                      showId: imdbId,
                      showTitle: latest.showTitle || "",
                      showPoster: latest.showPoster || "",
                      seasonNum: next.seasonNum,
                      episodeNum: next.episode.episode_number,
                    });
                    blob.fullyWatchedShowIds = blob.fullyWatchedShowIds.filter((s) => s !== imdbId);
                  } else if (!blob.fullyWatchedShowIds.includes(imdbId)) {
                    // TMDB either had no next episode (show is finished) OR the fetch failed (rate limit/timeout).
                    // If it was a network failure, we don't want to completely lose the show from Continue Watching,
                    // so we restore the old state just in case. If it truly is finished, it will stay in the old state
                    // (which is fine, the user can manually dismiss it) or they will naturally fall off.
                    if (oldCwItems && oldCwItems.length > 0) {
                      blob.continueWatching = [...oldCwItems, ...blob.continueWatching];
                    } else {
                      blob.fullyWatchedShowIds.push(imdbId);
                    }
                  }
                }
              }
            } else if (recordMovie) {
              const { movieId, movieEntry } = recordMovie;
              blob.watchHistory = blob.watchHistory.filter((it) => String(it.id) !== movieId);
              blob.watchHistory.unshift({ ...movieEntry, watchedAt: Date.now() });
            }

            if (blob.watchlist.length) {
              blob.watchlist = blob.watchlist.filter((it) => it && String(it.id || it.imdbId) !== imdbId && String(it.showId || '') !== imdbId);
            }

            blob.updatedAt = Date.now();
            const serializedBlob = JSON.stringify(blob);

            // Verify nothing else wrote to this key between our read and
            // now before committing -- if it changed, another ping (or
            // the client's own autosave) won the race for this attempt,
            // so retry against a fresh read rather than clobber it.
            const stillCurrent = await env.CONFIGS.get(syncKey);
            if ((stillCurrent || "") !== beforeWrite && attempt < MAX_ATTEMPTS - 1) {
              continue;
            }
            await env.CONFIGS.put(syncKey, serializedBlob);

            // Also write a tiny dedicated scrobble-queue key.
            // Cloudflare KV is eventually consistent -- a write from one edge
            // location (where Nuvio's request lands) can take up to 60 seconds
            // to be readable from another edge (where the browser's save-tracking
            // or load request lands). By writing the just-scrobbled items to a
            // second, separate small key, save-tracking and load can always merge
            // from it as an independent read that's unaffected by the big blob's
            // propagation lag. Keep only the most recent 20 items to stay tiny.
            try {
              const queueKey = `creatorscrobblequeue:${auth.username}`;
              const queueRaw = await env.CONFIGS.get(queueKey);
              let qObj = { watchHistory: [], continueWatching: [] };
              if (queueRaw) {
                try {
                  const parsed = JSON.parse(queueRaw);
                  if (Array.isArray(parsed)) {
                    qObj.watchHistory = parsed;
                  } else if (parsed && typeof parsed === "object") {
                    qObj.watchHistory = Array.isArray(parsed.watchHistory) ? parsed.watchHistory : [];
                    qObj.continueWatching = Array.isArray(parsed.continueWatching) ? parsed.continueWatching : [];
                  }
                } catch {}
              }
              if (recordEpisode) {
                const { epIdStr, episodeEntry } = recordEpisode;
                qObj.watchHistory = qObj.watchHistory.filter((it) => it && String(it.id) !== epIdStr);
                qObj.watchHistory.unshift({ ...episodeEntry, watchedAt: Date.now() });
              } else if (recordMovie) {
                const { movieId, movieEntry } = recordMovie;
                qObj.watchHistory = qObj.watchHistory.filter((it) => it && String(it.id) !== movieId);
                qObj.watchHistory.unshift({ ...movieEntry, watchedAt: Date.now() });
              }
              if (blob.continueWatching && blob.continueWatching.length > 0) {
                const latestCw = blob.continueWatching[0];
                qObj.continueWatching = qObj.continueWatching.filter((it) => it && String(it.showId || it.id) !== String(latestCw.showId || latestCw.id));
                qObj.continueWatching.unshift(latestCw);
              }
              qObj.watchHistory = qObj.watchHistory.slice(0, 20);
              qObj.continueWatching = qObj.continueWatching.slice(0, 20);
              await env.CONFIGS.put(queueKey, JSON.stringify(qObj));
            } catch {}

            break;
          }

          if (recordEpisode) {
            const epLabel = recordEpisode.showTitle;
            matched = alreadyWatched
              ? `yes (already watched: ${epLabel} S${season}E${episode})`
              : `yes (${epLabel} S${season}E${episode})`;
          } else if (recordMovie) {
            matched = alreadyWatched ? `yes (already watched: ${recordMovie.movieTitle})` : `yes (${recordMovie.movieTitle})`;
          }
        }

        // Auto-remove watched item from user's Creator Watchlist if present.
        //
        // This used to enumerate the account's whole creatorlist: prefix and
        // then GET every single list, on EVERY playback ping, just to find
        // the one named "Watchlist" -- so the cost of a ping scaled with how
        // many lists the person owns. The enumeration also had no cursor, so
        // past a thousand lists it silently stopped looking.
        //
        // The watchlist has a canonical key: /api/creator/sync/save-tracking
        // writes creatorlist:{user}:watchlist directly, and slugifyServer
        // turns any list actually named "Watchlist" into that same slug. So
        // the common path is one GET. The scan survives only as a fallback
        // for the shapes the old loop also accepted (an isWatchlist flag, or
        // a name that slugified differently), and is now paged and bounded
        // rather than silently truncating.
        try {
          const removeWatchedFrom = async (key, rawList) => {
            if (!rawList) return;
            const l = JSON.parse(rawList);
            if (!Array.isArray(l.items) || !l.items.length) return;
            const initLen = l.items.length;
            l.items = l.items.filter((it) => it && String(it.id || it.imdbId) !== imdbId && String(it.showId || '') !== imdbId);
            if (l.items.length !== initLen) {
              l.updatedAt = Date.now();
              await env.CONFIGS.put(key, JSON.stringify(l));
            }
          };

          const canonicalKey = `creatorlist:${auth.username}:watchlist`;
          const canonicalRaw = await env.CONFIGS.get(canonicalKey);
          if (canonicalRaw) {
            await removeWatchedFrom(canonicalKey, canonicalRaw);
          } else {
            const listKeys = await listAllKeys(env.CONFIGS, `creatorlist:${auth.username}:`, 200);
            for (const k of (listKeys.keys || [])) {
              const rawList = await env.CONFIGS.get(k.name);
              if (!rawList) continue;
              const l = JSON.parse(rawList);
              const isWatchlist = l.slug === 'watchlist' || (l.name && l.name.toLowerCase() === 'watchlist') || l.isWatchlist;
              if (isWatchlist) await removeWatchedFrom(k.name, rawList);
            }
          }
        } catch {}
      } catch (err) {
        matched = "error: " + (err && err.message ? err.message : String(err));
      }

      const clientApp = detectClientApp(request);
      await env.CONFIGS.put(diagnosticsKey, JSON.stringify({
        lastPingAt: Date.now(),
        lastPingId: pingId,
        lastServer: clientApp,
        matched: matched,
      }));
    }

    // Handles incoming webhooks from Plex, Jellyfin, and Emby media servers
    // Automatically marks watched episodes/movies and advances Continue Watching
    async function handleMediaServerScrobble(request, url, env, ctx) {
      if (!env || !env.CONFIGS) {
        return json({ ok: false, error: "Cloudflare KV storage (CONFIGS) not configured." }, 500);
      }

      // 1. Identify user / config
      const configParam = url.searchParams.get("config") || url.searchParams.get("token") || "";
      const queryCreator = url.searchParams.get("creator") || url.searchParams.get("user") || "";
      const queryKey = url.searchParams.get("key") || "";

      let authUser = null;
      let effectiveTmdbKey = TMDB_API_KEY;

      if (configParam) {
        try {
          const resolved = await resolveConfig(configParam, env);
          if (resolved && resolved.trackCreatorName && resolved.trackCreatorKey) {
            const auth = await authenticateCreator(resolved.trackCreatorName, resolved.trackCreatorKey);
            if (auth.ok) {
              authUser = auth.username;
              if (resolved.tmdbKey) effectiveTmdbKey = resolved.tmdbKey;
            }
          }
        } catch {}
      }

      if (!authUser && queryCreator && queryKey) {
        const auth = await authenticateCreator(queryCreator, queryKey);
        if (auth.ok) authUser = auth.username;
      }

      if (!authUser) {
        return json({ ok: false, error: "Unauthorized: Invalid or missing user credentials / config parameter." }, 401);
      }
      await ensureTrackingMigrated(env, authUser);

      if (!effectiveTmdbKey && authUser && env && env.CONFIGS) {
        try {
          const rawSync = await env.CONFIGS.get(`creatorsync:${authUser}`);
          if (rawSync) {
            const syncObj = JSON.parse(rawSync);
            if (syncObj && syncObj.keys && syncObj.keys.tmdbKey) {
              effectiveTmdbKey = String(syncObj.keys.tmdbKey).trim();
            }
          }
        } catch {}
      }
      if (!effectiveTmdbKey) {
        effectiveTmdbKey = (env && env.TMDB_API_KEY) || TMDB_API_KEY || "";
      }

      // 2. Parse payload from Plex, Jellyfin, or Emby
      const contentType = request.headers.get("content-type") || "";
      let payload = null;

      if (contentType.includes("multipart/form-data")) {
        try {
          const formData = await request.formData();
          const rawPayload = formData.get("payload");
          if (rawPayload && typeof rawPayload === "string") {
            payload = JSON.parse(rawPayload);
          }
        } catch {}
      } else {
        try {
          payload = await request.json();
        } catch {
          try {
            const text = await request.text();
            payload = JSON.parse(text);
          } catch {}
        }
      }

      if (!payload || typeof payload !== "object") {
        return json({ ok: false, error: "Invalid payload format. Expected JSON or multipart form." }, 400);
      }

      // 3. Detect Media Server Type & Event
      let server = "Media Server";
      let eventType = "";
      let mediaType = "movie"; // "movie" or "series"
      let mediaServerUser = ""; // username who triggered the event
      let imdbId = "";
      let tmdbId = "";
      let title = "";
      let showTitle = "";
      let season = null;
      let episode = null;
      let year = null;
      let isPlayed = false;

      // A. Plex Webhook format
      if (payload.Metadata || payload.event) {
        server = "Plex";
        eventType = String(payload.event || "").toLowerCase();
        isPlayed = eventType === "media.scrobble" || eventType === "media.play" || eventType === "media.stop" || eventType === "media.resume";
        
        let pUser = (payload.Account && (payload.Account.title || payload.Account.name || payload.Account.id)) ||
                    (payload.User && (payload.User.title || payload.User.name || payload.User.Name)) ||
                    payload.username || payload.user_name || payload.account || "";
        if (typeof pUser !== "string" && typeof pUser !== "number") pUser = "";
        pUser = String(pUser).trim();
        if (pUser === "true" || pUser === "false" || pUser === "null" || pUser === "undefined") pUser = "";
        mediaServerUser = pUser;

        const meta = payload.Metadata || {};
        mediaType = meta.type === "episode" ? "series" : "movie";
        title = meta.title || "";
        showTitle = meta.grandparentTitle || meta.parentTitle || "";
        season = meta.parentIndex != null ? Number(meta.parentIndex) : null;
        episode = meta.index != null ? Number(meta.index) : null;
        year = meta.year || null;

        const guids = [
          ...(meta.grandparentGuid ? [{ id: meta.grandparentGuid }] : []),
          ...(meta.parentGuid ? [{ id: meta.parentGuid }] : []),
          ...(Array.isArray(meta.Guid) ? meta.Guid : (meta.guid ? [{ id: meta.guid }] : []))
        ];
        for (const g of guids) {
          const gid = String(g.id || "");
          if (gid.includes("imdb://tt")) {
            const m = gid.match(/tt\d+/);
            if (m && !imdbId) imdbId = m[0];
          } else if (gid.includes("tmdb://")) {
            const m = gid.match(/tmdb:\/\/(\d+)/);
            if (m && !tmdbId) tmdbId = m[1];
          } else if (gid.startsWith("tt") && !imdbId) {
            imdbId = gid;
          }
        }
      }
      // B. Jellyfin Webhook format
      else if (payload.NotificationType || payload.ItemType || payload.ServerId) {
        server = "Jellyfin";
        eventType = String(payload.NotificationType || payload.Event || "").toLowerCase();
        isPlayed = eventType.includes("playback") || eventType.includes("userdata") || eventType.includes("scrobble") || payload.Played === true;
        
        let jUser = payload.NotificationUsername || payload.UserName || payload.Username || (payload.User && (payload.User.Name || payload.User.name)) || payload.user || "";
        if (typeof jUser !== "string" && typeof jUser !== "number") jUser = "";
        jUser = String(jUser).trim();
        if (jUser === "true" || jUser === "false" || jUser === "null" || jUser === "undefined") jUser = "";
        mediaServerUser = jUser;
        
        mediaType = (payload.ItemType === "Episode" || payload.SeriesName) ? "series" : "movie";
        title = payload.Name || payload.ItemName || "";
        showTitle = payload.SeriesName || "";
        season = payload.SeasonNumber != null ? Number(payload.SeasonNumber) : null;
        episode = payload.EpisodeNumber != null ? Number(payload.EpisodeNumber) : null;
        year = payload.Year || null;

        const sPIds = payload.SeriesProviderIds || (payload.Item && payload.Item.SeriesProviderIds) || {};
        const pIds = payload.ProviderIds || (payload.Item && payload.Item.ProviderIds) || {};
        imdbId = sPIds.Imdb || sPIds.imdb || payload.SeriesImdbId || pIds.Imdb || pIds.imdb || payload.Provider_imdb || "";
        tmdbId = sPIds.Tmdb || sPIds.tmdb || payload.SeriesTmdbId || pIds.Tmdb || pIds.tmdb || payload.Provider_tmdb || "";
      }
      // C. Emby Webhook format
      else if (payload.Item || (payload.Event && String(payload.Event).startsWith("playback."))) {
        server = "Emby";
        eventType = String(payload.Event || "").toLowerCase();
        isPlayed = eventType.includes("scrobble") || eventType.includes("playback.start") || eventType.includes("playback.stop") || eventType.includes("markplayed");
        
        let eUser = (payload.User && (payload.User.Name || payload.User.name || payload.User.Id || payload.User.id)) || payload.UserName || payload.Username || payload.user || "";
        if (typeof eUser !== "string" && typeof eUser !== "number") eUser = "";
        eUser = String(eUser).trim();
        if (eUser === "true" || eUser === "false" || eUser === "null" || eUser === "undefined") eUser = "";
        mediaServerUser = eUser;

        const item = payload.Item || payload;
        mediaType = (item.Type === "Episode" || item.SeriesName) ? "series" : "movie";
        title = item.Name || "";
        showTitle = item.SeriesName || "";
        season = item.ParentIndexNumber != null ? Number(item.ParentIndexNumber) : null;
        episode = item.IndexNumber != null ? Number(item.IndexNumber) : null;

        const sPIds = item.SeriesProviderIds || {};
        const pIds = item.ProviderIds || {};
        imdbId = sPIds.Imdb || sPIds.imdb || pIds.Imdb || pIds.imdb || "";
        tmdbId = sPIds.Tmdb || sPIds.tmdb || pIds.Tmdb || pIds.tmdb || "";
      }

      // 4a. Record this username in the seen-users list
      if (mediaServerUser) {
        const recordUserTask = async () => {
          try {
            const seenKey = `scrobbleseenusers:${authUser}`;
            const raw = await env.CONFIGS.get(seenKey);
            const seen = raw ? JSON.parse(raw) : {};
            seen[mediaServerUser] = { server, lastSeen: Date.now() };
            // 90-day TTL — stale accounts from old servers quietly expire
            await env.CONFIGS.put(seenKey, JSON.stringify(seen), { expirationTtl: 60 * 60 * 24 * 90 });
          } catch {}
        };
        if (ctx && typeof ctx.waitUntil === "function") {
          ctx.waitUntil(recordUserTask());
        } else {
          await recordUserTask();
        }
      }

      // 4b. Apply user filter (URL param first, fallback to user's saved account settings in KV)
      let filterEnabled = false;
      let allowedUsersParam = (url.searchParams.get("allowedUsers") || "").trim();
      let blockAnon = url.searchParams.get("blockAnon") === "1";

      if (url.searchParams.has("filterUsers")) {
        filterEnabled = url.searchParams.get("filterUsers") === "1";
      } else if (allowedUsersParam) {
        filterEnabled = true;
      }

      if (authUser) {
        try {
          let trackingRaw = await env.CONFIGS.get(`creatorsynctracking:${authUser}`);
          if (!trackingRaw) {
            trackingRaw = await env.CONFIGS.get(`creatorsync:${authUser}`);
          }
          if (trackingRaw) {
            const trackingObj = JSON.parse(trackingRaw);
            if (trackingObj.scrobbleFilterUsers === true || trackingObj.scrobbleFilterUsers === "1" || trackingObj.scrobbleFilterUsers === 1) {
              filterEnabled = true;
            } else if (trackingObj.scrobbleFilterUsers === false || trackingObj.scrobbleFilterUsers === "0" || trackingObj.scrobbleFilterUsers === 0) {
              filterEnabled = false;
            } else if (trackingObj.scrobbleAllowedUsers) {
              filterEnabled = true;
            }
            if (trackingObj.scrobbleAllowedUsers !== undefined && !url.searchParams.has("allowedUsers")) {
              allowedUsersParam = String(trackingObj.scrobbleAllowedUsers || "").trim();
            }
            if (trackingObj.scrobbleBlockAnonymous && !url.searchParams.has("blockAnon")) {
              blockAnon = true;
            }
          }
        } catch {}
      }

      if (filterEnabled) {
        const allowed = allowedUsersParam.split(",").map((s) => s.trim().toLowerCase()).filter(Boolean);
        if (!mediaServerUser) {
          if (blockAnon || allowed.length > 0) {
            const ignoredMsg = "No username in payload and user filtering is active.";
            const diagnosticsKey = `creatortrack:${authUser}`;
            await env.CONFIGS.put(diagnosticsKey, JSON.stringify({
              lastPingAt: Date.now(),
              lastPingId: pingId || "unknown",
              lastServer: server,
              lastUser: null,
              matched: `ignored (${ignoredMsg})`,
            }));
            return json({ ok: true, ignored: ignoredMsg });
          }
        } else if (!allowed.includes(mediaServerUser.toLowerCase())) {
          const ignoredMsg = `User '${mediaServerUser}' is not in the allowed list.`;
          const diagnosticsKey = `creatortrack:${authUser}`;
          await env.CONFIGS.put(diagnosticsKey, JSON.stringify({
            lastPingAt: Date.now(),
            lastPingId: pingId || mediaServerUser,
            lastServer: server,
            lastUser: mediaServerUser,
            matched: `ignored (${ignoredMsg})`,
          }));
          return json({ ok: true, ignored: ignoredMsg });
        }
      }

      if (!isPlayed) {
        return json({ ok: true, ignored: `Event '${eventType}' is not a scrobble/play event.` });
      }

      // 4. Resolve IDs via TMDB if needed
      if (!imdbId && tmdbId) {
        try {
          const tmdbType = mediaType === "series" ? "tv" : "movie";
          const tmdbRes = await fetch(`https://api.themoviedb.org/3/${tmdbType}/${tmdbId}?api_key=${effectiveTmdbKey}&append_to_response=external_ids`);
          if (tmdbRes.ok) {
            const d = await tmdbRes.json();
            imdbId = (d.external_ids && d.external_ids.imdb_id) || d.imdb_id || "";
          }
        } catch {}
      }

      let searchFoundPoster = "";
      if (!imdbId && (showTitle || title)) {
        try {
          let q = showTitle || title;
          if (mediaType === "series") {
            q = String(q)
              .replace(/[\s._-]+[sS]\d+[\s._-]*[eE]\d+.*$/i, "")
              .replace(/[\s._-]+\d+x\d+.*$/i, "")
              .replace(/[\s._-]+season[\s._-]*\d+.*$/i, "")
              .replace(/[\s._-]+episode[\s._-]*\d+.*$/i, "")
              .replace(/\s*\(\d{4}\).*$/, "")
              .trim();
          }
          const searchType = mediaType === "series" ? "tv" : "movie";
          const searchRes = await fetch(`https://api.themoviedb.org/3/search/${searchType}?api_key=${effectiveTmdbKey}&query=${encodeURIComponent(q)}&page=1`);
          if (searchRes.ok) {
            const sd = await searchRes.json();
            if (sd.results && sd.results.length) {
              const first = sd.results[0];
              tmdbId = String(first.id);
              if (first.poster_path) {
                searchFoundPoster = `https://image.tmdb.org/t/p/w500${first.poster_path}`;
              }
              const extRes = await fetch(`https://api.themoviedb.org/3/${searchType}/${first.id}?api_key=${effectiveTmdbKey}&append_to_response=external_ids`);
              if (extRes.ok) {
                const ed = await extRes.json();
                imdbId = (ed.external_ids && ed.external_ids.imdb_id) || ed.imdb_id || "";
              }
            }
          }
        } catch {}
      }

      const pingId = mediaType === "series" ? `${imdbId || tmdbId}:${season || 1}:${episode || 1}` : (imdbId || tmdbId || title);

      // 5. Execute Watch Record
      let matched = "no";
      try {
        const syncKey = `creatorsynctracking:${authUser}`;
        const raw = await env.CONFIGS.get(syncKey);
        let blob = null;
        if (raw) {
          try { blob = JSON.parse(raw); } catch {}
        }
        if (!blob || typeof blob !== "object") {
          blob = { watchHistory: [], continueWatching: [], fullyWatchedShowIds: [], dismissedContinueWatching: {}, trackPlayback: true };
        }
        blob.watchHistory = Array.isArray(blob.watchHistory) ? blob.watchHistory : [];
        blob.continueWatching = Array.isArray(blob.continueWatching) ? blob.continueWatching : [];
        blob.fullyWatchedShowIds = Array.isArray(blob.fullyWatchedShowIds) ? blob.fullyWatchedShowIds : [];
        blob.dismissedContinueWatching = blob.dismissedContinueWatching && typeof blob.dismissedContinueWatching === "object" ? blob.dismissedContinueWatching : {};

        if (mediaType === "series") {
          const seasonNum = season != null ? season : 1;
          const episodeNum = episode != null ? episode : 1;
          
          let epName = title;
          let epPoster = "";
          let sTitle = showTitle || title;
          let sPoster = "";

          const cleanShowName = String(showTitle || title)
            .replace(/[\s._-]+[sS]\d+[\s._-]*[eE]\d+.*$/i, "")
            .replace(/[\s._-]+\d+x\d+.*$/i, "")
            .replace(/[\s._-]+season[\s._-]*\d+.*$/i, "")
            .replace(/[\s._-]+episode[\s._-]*\d+.*$/i, "")
            .replace(/\s*\(\d{4}\).*$/, "")
            .trim();

          const lookupShowId = imdbId || (tmdbId ? `tmdb:${tmdbId}` : "") || cleanShowName || showTitle || title;

          let epIdStr = "";
          if (lookupShowId) {
            const seasonData = await fetchTmdbSeasonDetails(lookupShowId, seasonNum, effectiveTmdbKey, tmdbId, env, ctx).catch(() => null);
            const ep = seasonData && seasonData.episodes ? seasonData.episodes.find((e) => e.episode_number === episodeNum) : null;
            if (ep) {
              epName = ep.name || title;
              epPoster = ep.still_path ? (ep.still_path.startsWith("http") ? ep.still_path : `https://image.tmdb.org/t/p/w500${ep.still_path}`) : "";
              if (ep.id) epIdStr = String(ep.id);
            }
            const showDetails = await fetchTmdbItemDetails(lookupShowId, effectiveTmdbKey, "series", "", false, env, ctx).catch(() => null);
            if (showDetails) {
              sTitle = showDetails.title || sTitle;
              sPoster = showDetails.poster || searchFoundPoster || "";
              if (!imdbId && showDetails.id && showDetails.id.startsWith("tt")) {
                imdbId = showDetails.id;
              }
              if (!tmdbId && showDetails.tmdbId) {
                tmdbId = String(showDetails.tmdbId);
              }
            }
            if (!sPoster && imdbId && imdbId.startsWith("tt")) {
              sPoster = `https://images.metahub.space/poster/medium/${imdbId}/img`;
            }
          }

          const resolvedShowId = imdbId || (tmdbId ? `tmdb:${tmdbId}` : "") || sTitle;
          const itemKey = epIdStr || `${resolvedShowId}:${seasonNum}:${episodeNum}`;
          const finalEpisodePoster = epPoster || sPoster || (imdbId && imdbId.startsWith("tt") ? `https://images.metahub.space/poster/medium/${imdbId}/img` : "");
          const finalShowPoster = sPoster || (imdbId && imdbId.startsWith("tt") ? `https://images.metahub.space/poster/medium/${imdbId}/img` : "") || epPoster;
          
          // Re-watching or newly watching an episode always brings it to the top of Watch History
          blob.watchHistory = blob.watchHistory.filter((it) => !((it.showId === resolvedShowId || it.showTitle === sTitle) && it.seasonNum === seasonNum && it.episodeNum === episodeNum));
          blob.watchHistory.unshift({
            id: itemKey,
            type: "episode",
            name: epName,
            poster: finalEpisodePoster,
            showId: resolvedShowId,
            showTitle: sTitle,
            showPoster: finalShowPoster,
            seasonNum: seasonNum,
            episodeNum: episodeNum,
            watchedAt: Date.now(),
          });

          // Recompute Continue Watching for this show
          const oldCwItems = blob.continueWatching.filter((it) => it.showId === resolvedShowId || (imdbId && it.showId === imdbId) || (sTitle && it.showId === sTitle));
          blob.continueWatching = blob.continueWatching.filter((it) => it.showId !== resolvedShowId && it.showId !== (imdbId || sTitle));
          if (resolvedShowId) {
            const watchedEps = blob.watchHistory.filter((it) => it.type === "episode" && (it.showId === resolvedShowId || (sTitle && it.showTitle === sTitle)) && it.seasonNum != null && it.episodeNum != null);
            let latestSeason = seasonNum;
            let latestEpisode = episodeNum;
            if (watchedEps.length) {
              const latest = watchedEps.reduce((best, e) => {
                const eS = Number(e.seasonNum);
                const eE = Number(e.episodeNum);
                const bS = Number(best.seasonNum);
                const bE = Number(best.episodeNum);
                if (eS > bS) return e;
                if (eS === bS && eE > bE) return e;
                return best;
              }, watchedEps[0]);
              latestSeason = Number(latest.seasonNum);
              latestEpisode = Number(latest.episodeNum);
            }
            const next = await findNextAiredEpisodeForShow(resolvedShowId, latestSeason, latestEpisode, effectiveTmdbKey, env, ctx).catch(() => null);
            if (next) {
              blob.continueWatching.unshift({
                id: next.episode.id ? String(next.episode.id) : `${resolvedShowId}:${next.seasonNum}:${next.episode.episode_number}`,
                type: "episode",
                name: next.episode.name,
                poster: finalShowPoster,
                showId: resolvedShowId,
                showTitle: sTitle,
                showPoster: finalShowPoster,
                seasonNum: next.seasonNum,
                episodeNum: next.episode.episode_number,
              });
              blob.fullyWatchedShowIds = blob.fullyWatchedShowIds.filter((s) => s !== resolvedShowId && s !== imdbId);
            } else if (!blob.fullyWatchedShowIds.includes(resolvedShowId)) {
              if (oldCwItems && oldCwItems.length > 0) {
                blob.continueWatching = [...oldCwItems, ...blob.continueWatching];
              } else {
                blob.fullyWatchedShowIds.push(resolvedShowId);
              }
            }
          }
          matched = `yes (${server}: ${sTitle} S${seasonNum}E${episodeNum})`;
        } else {
          // Movie
          let movieTitle = title;
          let moviePoster = "";
          const lookupMovieId = imdbId || (tmdbId ? `tmdb:${tmdbId}` : "") || title;
          if (lookupMovieId) {
            const details = await fetchTmdbItemDetails(lookupMovieId, effectiveTmdbKey, "movie", "", false, env, ctx).catch(() => null);
            if (details) {
              movieTitle = details.title || movieTitle;
              moviePoster = details.poster || searchFoundPoster || "";
              if (!imdbId && details.id && details.id.startsWith("tt")) {
                imdbId = details.id;
              }
              if (!tmdbId && details.tmdbId) {
                tmdbId = String(details.tmdbId);
              }
            }
            if (!moviePoster && imdbId && imdbId.startsWith("tt")) {
              moviePoster = `https://images.metahub.space/poster/medium/${imdbId}/img`;
            }
          }
          const resolvedMovieId = imdbId || (tmdbId ? `tmdb:${tmdbId}` : "") || movieTitle;
          const finalMoviePoster = moviePoster || (imdbId && imdbId.startsWith("tt") ? `https://images.metahub.space/poster/medium/${imdbId}/img` : "");
          
          blob.watchHistory = blob.watchHistory.filter((it) => !(String(it.id) === resolvedMovieId || String(it.id) === imdbId || it.name === movieTitle));
          blob.watchHistory.unshift({
            id: resolvedMovieId,
            type: "movie",
            name: movieTitle,
            poster: finalMoviePoster,
            watchedAt: Date.now(),
          });
          matched = `yes (${server}: ${movieTitle})`;
        }

        // Clean from watchlist if present
        if (Array.isArray(blob.watchlist)) {
          blob.watchlist = blob.watchlist.filter((it) => it && String(it.id || it.imdbId) !== imdbId && String(it.showId || "") !== imdbId);
        }

        blob.updatedAt = Date.now();
        await env.CONFIGS.put(syncKey, JSON.stringify(blob));

        // Also write to creatorscrobblequeue to protect against KV propagation lag
        try {
          const queueKey = `creatorscrobblequeue:${authUser}`;
          const queueRaw = await env.CONFIGS.get(queueKey);
          let qObj = { watchHistory: [], continueWatching: [] };
          if (queueRaw) {
            try {
              const parsed = JSON.parse(queueRaw);
              if (Array.isArray(parsed)) {
                qObj.watchHistory = parsed;
              } else if (parsed && typeof parsed === "object") {
                qObj.watchHistory = Array.isArray(parsed.watchHistory) ? parsed.watchHistory : [];
                qObj.continueWatching = Array.isArray(parsed.continueWatching) ? parsed.continueWatching : [];
              }
            } catch {}
          }
          if (blob.watchHistory.length > 0) {
            const latestItem = blob.watchHistory[0];
            qObj.watchHistory = qObj.watchHistory.filter((it) => it && String(it.id) !== String(latestItem.id));
            qObj.watchHistory.unshift({ ...latestItem });
          }
          if (blob.continueWatching.length > 0) {
            const latestCw = blob.continueWatching[0];
            qObj.continueWatching = qObj.continueWatching.filter((it) => it && String(it.showId || it.id) !== String(latestCw.showId || latestCw.id));
            qObj.continueWatching.unshift(latestCw);
          }
          qObj.watchHistory = qObj.watchHistory.slice(0, 20);
          qObj.continueWatching = qObj.continueWatching.slice(0, 20);
          await env.CONFIGS.put(queueKey, JSON.stringify(qObj));
        } catch {}
      } catch (err) {
        matched = `error (${server}): ` + (err && err.message ? err.message : String(err));
      }

      // Update diagnostics
      const diagnosticsKey = `creatortrack:${authUser}`;
      await env.CONFIGS.put(diagnosticsKey, JSON.stringify({
        lastPingAt: Date.now(),
        lastPingId: pingId,
        lastServer: server,
        lastUser: mediaServerUser || null,
        matched: matched,
      }));

      return json({
        ok: true,
        server: server,
        user: mediaServerUser || null,
        event: eventType,
        matched: matched,
      });
    }

    // /api/creator/track-status  (POST)  { creatorName, creatorKey } ->
    // { ok, lastPingAt, lastPingId, matched } -- powers the "last ping"
    // status line on the Settings page's Auto-track playback panel, same
    // idea as the reference implementation's ping diagnostics. Kept in its
    // own creatortrack:{username} KV key rather than folded into the
    // creatorsync:{username} blob, since that blob gets wholesale-
    // overwritten by the browser's own background sync (pushCreatorSync)
    // on a timer -- storing this there would mean it kept getting quietly
    // wiped out by the very next sync from any signed-in device.
    if (path === "/api/creator/track-status" && request.method === "POST") {
      let body;
      try {
        body = await request.json();
      } catch {
        return json({ ok: false, error: "Invalid JSON body." }, 400);
      }
      const auth = await authenticateCreator(body.creatorName, body.creatorKey);
      if (!auth.ok) return json({ ok: false, error: auth.error === "no-kv" ? "no-kv" : "Username or Key is incorrect." }, auth.error === "no-kv" ? 500 : 401);
      const raw = await env.CONFIGS.get(`creatortrack:${auth.username}`);
      let status = { lastPingAt: null, lastPingId: null, lastServer: null, lastUser: null, matched: null };
      if (raw) {
        try {
          status = JSON.parse(raw);
        } catch {
          // leave status as the empty default
        }
      }
      return json({ ok: true, ...status });
    }

    // /api/creator/scrobble-seen-users  (POST)  { creatorName, creatorKey } ->
    // { ok, users: { "James": { server: "Plex", lastSeen: 1234567890 }, ... } }
    // Returns all media server usernames ever seen in webhook events for this account.
    // Populated automatically by handleMediaServerScrobble whenever a username is
    // present in the incoming payload. Used by the settings page to show checkboxes
    // for user filtering without requiring manual name entry.
    if (path === "/api/creator/scrobble-seen-users" && request.method === "POST") {
      let body;
      try {
        body = await request.json();
      } catch {
        return json({ ok: false, error: "Invalid JSON body." }, 400);
      }
      const auth = await authenticateCreator(body.creatorName, body.creatorKey);
      if (!auth.ok) return json({ ok: false, error: auth.error === "no-kv" ? "no-kv" : "Username or Key is incorrect." }, auth.error === "no-kv" ? 500 : 401);
      const raw = await env.CONFIGS.get(`scrobbleseenusers:${auth.username}`);
      let users = {};
      if (raw) {
        try { users = JSON.parse(raw); } catch {}
      }
      // If scrobbleseenusers is empty, check if creatortrack diagnostics has a lastUser
      if (!Object.keys(users).length) {
        try {
          const diagRaw = await env.CONFIGS.get(`creatortrack:${auth.username}`);
          if (diagRaw) {
            const diag = JSON.parse(diagRaw);
            if (diag && diag.lastUser) {
              users[diag.lastUser] = { server: diag.lastServer || "Media Server", lastSeen: diag.lastPingAt || Date.now() };
            }
          }
        } catch {}
      }
      return json({ ok: true, users });
    }

    // /api/creator/create  (POST)  { creatorName, displayName?, recoveryAnswer? }
    //   -> { ok, creatorName, displayName, creatorKey }
    // Rate limited to one new profile per minute per IP, tracked via a
    // short-lived KV key rather than anything more elaborate -- this add-on
    // has no user-identity system to rate-limit against besides the
    // requester's own IP.
    if (path === "/api/creator/create" && request.method === "POST") {
      if (!env || !env.CONFIGS) return json({ ok: false, error: "no-kv" });
      const ip = clientIpKey(request);
      if (!ip) return json({ ok: false, error: "Could not process this request." }, 400);
      const rateLimitKey = `ratelimit:creatorcreate:${ip}`;
      if (await env.CONFIGS.get(rateLimitKey)) {
        return json({ ok: false, error: "Please wait a moment before creating another Profile." }, 429);
      }
      let body;
      try {
        body = await request.json();
      } catch {
        return json({ ok: false, error: "Invalid JSON body." }, 400);
      }
      const v = validateCreatorUsername(body.creatorName);
      if (!v.ok) return json({ ok: false, error: v.error });
      const dn = normalizeCreatorDisplayName(body.displayName, v.normalized);
      if (!dn.ok) return json({ ok: false, error: dn.error }, 400);
      const displayName = dn.displayName;
      // Reserve the rate-limit slot before the uniqueness check, not after
      // -- otherwise two requests landing at nearly the same instant could
      // both pass the "is it taken" check before either has written
      // anything, and both succeed.
      await env.CONFIGS.put(rateLimitKey, "1", { expirationTtl: 60 });
      const existing = await getCreator(env, v.normalized);
      if (existing) {
        return json({ ok: false, error: "That username is already taken." });
      }
      const creatorKey = generateCreatorKey();
      const keyHash = await hashCreatorKey(creatorKey);
      // Recovery answer is optional and, unlike the Creator Key itself,
      // chosen by the person rather than generated -- normalized
      // (trimmed + lowercased) before hashing so a small casing slip
      // months later at reset time doesn't lock them out over nothing.
      // Same PBKDF2 hash-only storage as the key: this value is never
      // recoverable, only checkable, and it's never shown to an admin --
      // self-service reset (/api/creator/reset-key) is the only thing
      // that ever reads it.
      const recoveryAnswerRaw = String(body.recoveryAnswer || "").trim();
      // Optional -- but if one is given it has to be long enough to be worth
      // hashing. It is lowercased before hashing and it can replace the
      // Creator Key outright via /api/creator/reset-key, so a three-character
      // answer is a three-character password on the whole account. Rejected
      // rather than silently accepted, since the person setting it is the
      // only one who can pick a better one. Existing short answers are
      // untouched; the per-account failure budget on reset-key is what
      // protects those.
      if (recoveryAnswerRaw && recoveryAnswerRaw.length < RECOVERY_ANSWER_MIN_LENGTH) {
        return json({
          ok: false,
          error: `Recovery Answer must be at least ${RECOVERY_ANSWER_MIN_LENGTH} characters -- it can reset your key, so treat it like a password.`,
        }, 400);
      }
      const recoveryAnswerHash = recoveryAnswerRaw ? await hashCreatorKey(recoveryAnswerRaw.toLowerCase()) : null;
      const nowMs = Date.now();
      const profileObj = { displayName, keyHash, recoveryAnswerHash, createdAt: nowMs };
      
      // KV is written ALWAYS, D1 only additionally. This used to write to
      // D1 *instead of* KV whenever DB was bound, which made the single
      // D1 row the only copy of the account in existence -- if that row
      // was ever lost, or the D1 binding was removed, or a query failed
      // after creation, the account was unrecoverable: the key hash lived
      // nowhere else. It also meant KV and D1 disagreed about which
      // accounts exist, which is what the read-side fallbacks in
      // getCreator/getCreatorList have to cope with.
      //
      // KV is the store every other creator key path already writes
      // unconditionally, so making creation match keeps one consistent
      // source of truth and lets D1 stay a pure accelerator that can be
      // added, removed, or rebuilt at any time without data loss.
      await env.CONFIGS.put(`creator:${v.normalized}`, JSON.stringify(profileObj));
      if (env.DB) {
        try {
          await env.DB.prepare(
            "INSERT INTO creators (username, display_name, key_hash, recovery_answer_hash, created_at) VALUES (?, ?, ?, ?, ?)"
          ).bind(v.normalized, displayName, keyHash, recoveryAnswerHash, nowMs).run();
        } catch (dbErr) {
          // Non-fatal: KV above already holds the authoritative record, so
          // the account is fully usable. D1 will pick it up on the next
          // /admin/api/migrate-d1 run.
          console.error("D1 write error (creator create), KV holds the record:", dbErr);
        }
      }
      
      try {
        const countRaw = await env.CONFIGS.get("stats:creator_count");
        const count = parseInt(countRaw || "0", 10) + 1;
        await env.CONFIGS.put("stats:creator_count", String(count));
      } catch (err) {}

      // The Creator Key is returned exactly once, right here -- it's never
      // stored anywhere (only its hash is), so this is the only moment it
      // will ever exist outside whoever's holding onto it themselves.
      return json({ ok: true, creatorName: v.normalized, displayName, creatorKey });
    }

    // /api/creator/reset-key  (POST)  { username, recoveryAnswer } -> { ok, creatorKey }
    // Public, self-service. This is the reason recoveryAnswerHash exists
    // at all: someone who's lost their Creator Key but still knows the
    // recovery answer they set at signup can get a working key back
    // without ever filing a Feedback ticket or needing an admin. Same
    // reset-not-recovery shape as /admin/api/reset-creator-key -- a new
    // key is generated and the old one stops working immediately -- the
    // only difference is what proves the requester is allowed to do this
    // (a matching recovery answer here, an authenticated admin there).
    // The recovery answer itself is intentionally NOT rotated on a
    // successful reset: unlike a single-use recovery code, this is a
    // chosen, memorized answer meant to keep working for next time too,
    // the same way a security question's answer would.
    if (path === "/api/creator/reset-key" && request.method === "POST") {
      if (!env || !env.CONFIGS) return json({ ok: false, error: "no-kv" });
      let body;
      try {
        body = await request.json();
      } catch {
        return json({ ok: false, error: "Invalid JSON body." }, 400);
      }
      const ip = clientIpKey(request);
      if (!ip) return json({ ok: false, error: "Could not process this request." }, 400);
      const rateLimitKey = `resetkeyrate:${ip}:${statsToday()}`;
      const rateCountRaw = await env.CONFIGS.get(rateLimitKey);
      const rateCount = parseInt(rateCountRaw, 10) || 0;
      if (rateCount >= 10) {
        return json({ ok: false, error: "Too many attempts today -- please try again tomorrow, or reach out via Feedback & Support." });
      }
      await env.CONFIGS.put(rateLimitKey, String(rateCount + 1), { expirationTtl: 86400 });

      const v = validateCreatorUsername(body.username);
      const answer = String(body.recoveryAnswer || "").trim();
      // Generic error for every failure case below (unknown username, no
      // recovery answer on file, wrong answer) -- distinguishing them
      // would let this endpoint be used to enumerate which usernames
      // exist and which have a recovery answer set at all.
      const genericError = "That username and recovery answer don't match, or no recovery answer is set for this account.";
      if (!v.ok || !answer) return json({ ok: false, error: genericError });
      const raw = await getCreator(env, v.normalized);
      if (!raw) return json({ ok: false, error: genericError });
      let profile;
      try {
        profile = JSON.parse(raw);
      } catch {
        return json({ ok: false, error: genericError });
      }
      if (!profile.recoveryAnswerHash) return json({ ok: false, error: genericError });

      // Per-ACCOUNT failure budget, on top of the per-IP one above. The IP
      // counter alone did not defend this endpoint at all: rotating source
      // addresses is free, so it bought an attacker unlimited guesses at one
      // account's recovery answer -- a secret weak enough to fall in a
      // handful of tries, in exchange for a working Creator Key. See
      // RESET_KEY_ACCOUNT_MAX_FAILURES (00_constants.js).
      //
      // Checked here, after the profile is known to exist and to have a
      // recovery answer set, so a wrong or unknown username can never spend
      // (or create a counter for) an account budget. Still before the
      // PBKDF2 verification below, so a throttled attempt costs nothing.
      const resetDay = statsToday();
      const resetScope = `reset:${v.normalized}`;
      if (await readAuthFailureCount(env, resetScope, resetDay) >= RESET_KEY_ACCOUNT_MAX_FAILURES) {
        // Same generic message as every other failure path here, so this
        // does not become a way to ask whether an account exists.
        return json({ ok: false, error: genericError });
      }

      const matches = await verifyCreatorKey(answer.toLowerCase(), profile.recoveryAnswerHash);
      if (!matches) {
        // Failures only: answering correctly must never consume the budget
        // that protects you.
        await noteAuthFailure(env, resetScope, resetDay);
        return json({ ok: false, error: genericError });
      }

      const creatorKey = generateCreatorKey();
      const keyHash = await hashCreatorKey(creatorKey);
      // The previous key must stop working on a warm isolate the instant
      // it is rotated -- see invalidateCreatorAuthMemo's own comment.
      invalidateCreatorAuthMemo();
      
      if (env.DB) {
        try {
          // meta.changes, not merely "did not throw". A D1 UPDATE that
          // matches ZERO rows succeeds -- so for any account that exists
          // in KV but was never migrated into D1 (i.e. every account
          // created before /admin/api/migrate-d1 was first run), this used
          // to report success, skip the KV write below, and rotate
          // nothing at all: the caller got a brand-new key that would
          // never work while the OLD key kept working forever. Exactly
          // backwards for a credential rotation someone is performing
          // because their key leaked.
          const d1Res = await env.DB.prepare(
            "UPDATE creators SET key_hash = ? WHERE username = ?"
          ).bind(keyHash, v.normalized).run();
          if (!(d1Res && d1Res.meta && d1Res.meta.changes > 0)) {
            // Row absent from D1 (never migrated). Not an error -- the
            // unconditional KV write below is the source of truth here --
            // but worth surfacing, because it means this account is not
            // in D1 and /admin/api/migrate-d1 has not been run for it.
            console.warn("D1 key rotation matched no row for", v.normalized, "-- KV updated");
          }
        } catch (dbErr) {
          console.error("D1 write error (creator reset):", dbErr);
        }
      }

      // Written unconditionally, not only when D1 missed. getCreator()
      // prefers D1 and falls back to KV, so leaving KV holding an older
      // key_hash than D1 means two different valid passwords for one
      // account depending on which store answers. Both stores always get
      // the same hash.
      await env.CONFIGS.put(
        `creator:${v.normalized}`,
        JSON.stringify({ ...profile, keyHash })
      );
      return json({ ok: true, creatorName: v.normalized, displayName: profile.displayName, creatorKey });
    }

    // /admin/api/reset-creator-key  (POST)  { username } -> { ok, creatorKey }
    // Admin-only. There's no email or password on a Creator Profile (see
    // authenticateCreator's own comment above), so a lost key can never be
    // recovered -- only a hash of it is ever stored. This is a reset, not
    // a recovery: it generates a brand-new key the same way signup does,
    // overwrites the stored hash, and hands the plaintext key back exactly
    // once, same as /api/creator/create does. The old key stops working
    // the instant this runs -- anywhere it was in use (other devices,
    // scrobble webhook URLs that embed it) breaks until updated with the
    // new one. This endpoint has no way to confirm the requester actually
    // is the creator in question; that verification is left entirely to
    // the admin using it, out of band, before calling it.
    if (path === "/admin/api/reset-creator-key" && request.method === "POST") {
      const authed = await isAdminRequest(request, env);
      if (!authed) return json({ ok: false, error: "Not authorized." }, 401);
      if (!env || !env.CONFIGS) return json({ ok: false, error: "no-kv" });
      let body;
      try {
        body = await request.json();
      } catch {
        return json({ ok: false, error: "Invalid JSON body." }, 400);
      }
      const v = validateCreatorUsername(body.username);
      if (!v.ok) return json({ ok: false, error: "Unknown creator." });
      const raw = await getCreator(env, v.normalized);
      if (!raw) return json({ ok: false, error: "Unknown creator." });
      let profile;
      try {
        profile = JSON.parse(raw);
      } catch {
        return json({ ok: false, error: "Could not read that creator's profile." });
      }
      const creatorKey = generateCreatorKey();
      const keyHash = await hashCreatorKey(creatorKey);
      // The previous key must stop working on a warm isolate the instant
      // it is rotated -- see invalidateCreatorAuthMemo's own comment.
      invalidateCreatorAuthMemo();
      
      if (env.DB) {
        try {
          // meta.changes, not merely "did not throw". A D1 UPDATE that
          // matches ZERO rows succeeds -- so for any account that exists
          // in KV but was never migrated into D1 (i.e. every account
          // created before /admin/api/migrate-d1 was first run), this used
          // to report success, skip the KV write below, and rotate
          // nothing at all: the caller got a brand-new key that would
          // never work while the OLD key kept working forever. Exactly
          // backwards for a credential rotation someone is performing
          // because their key leaked.
          const d1Res = await env.DB.prepare(
            "UPDATE creators SET key_hash = ? WHERE username = ?"
          ).bind(keyHash, v.normalized).run();
          if (!(d1Res && d1Res.meta && d1Res.meta.changes > 0)) {
            // Row absent from D1 (never migrated). Not an error -- the
            // unconditional KV write below is the source of truth here --
            // but worth surfacing, because it means this account is not
            // in D1 and /admin/api/migrate-d1 has not been run for it.
            console.warn("D1 key rotation matched no row for", v.normalized, "-- KV updated");
          }
        } catch (dbErr) {
          console.error("D1 write error (admin creator reset):", dbErr);
        }
      }

      // Written unconditionally, not only when D1 missed. getCreator()
      // prefers D1 and falls back to KV, so leaving KV holding an older
      // key_hash than D1 means two different valid passwords for one
      // account depending on which store answers. Both stores always get
      // the same hash.
      await env.CONFIGS.put(
        `creator:${v.normalized}`,
        JSON.stringify({ ...profile, keyHash })
      );
      return json({ ok: true, creatorKey });
    }

    // /api/creator/restore  (POST)  { creatorName, creatorKey } -> { ok, creatorName, displayName }
    if (path === "/api/creator/restore" && request.method === "POST") {
      if (!env || !env.CONFIGS) return json({ ok: false, error: "no-kv" });
      const ip = clientIpKey(request);
      if (!ip) return json({ ok: false, error: "Could not process this request." }, 400);
      const rateLimitKey = `ratelimit:creatorrestore:${ip}`;
      const attempts = parseInt((await env.CONFIGS.get(rateLimitKey)) || "0", 10);
      // More generous than profile creation (this is a normal, repeatable
      // action -- someone restoring on a new device isn't abuse), but still
      // capped well below what's useful for guessing a ~60-bit key.
      if (attempts >= 20) {
        return json({ ok: false, error: "Too many attempts. Please wait a minute and try again." }, 429);
      }
      await env.CONFIGS.put(rateLimitKey, String(attempts + 1), { expirationTtl: 60 });
      let body;
      try {
        body = await request.json();
      } catch {
        return json({ ok: false, error: "Invalid JSON body." }, 400);
      }
      const auth = await authenticateCreator(body.creatorName, body.creatorKey);
      if (!auth.ok) return json({ ok: false, error: auth.error === "no-kv" ? "no-kv" : "Username or Key is incorrect." }, auth.error === "no-kv" ? 500 : 401);
      return json({ ok: true, creatorName: auth.username, displayName: auth.displayName });
    }

    // /api/creator/lists  (POST)  { creatorName, creatorKey } -> { ok, displayName, lists }
    // The Dashboard's data source -- every list this creator owns (public
    // AND private, since this is an authenticated request only the owner
    // can make), in their own persisted order.
    if (path === "/api/creator/lists" && request.method === "POST") {
      let body;
      try {
        body = await request.json();
      } catch {
        return json({ ok: false, error: "Invalid JSON body." }, 400);
      }
      const auth = await authenticateCreator(body.creatorName, body.creatorKey);
      if (!auth.ok) return json({ ok: false, error: auth.error === "no-kv" ? "no-kv" : "Username or Key is incorrect." }, auth.error === "no-kv" ? 500 : 401);
      const orderRaw = await env.CONFIGS.get(`creatorlistorder:${auth.username}`);
      let order = [];
      try {
        order = orderRaw ? JSON.parse(orderRaw).order || [] : [];
      } catch {
        order = [];
      }
      const lists = (
        await Promise.all(
          order.map(async (slug) => {
            const raw = await getCreatorList(env, auth.username, slug);
            if (!raw) return null;
            try {
              const data = JSON.parse(raw);
              return {
                slug,
                name: data.name,
                type: data.type,
                items: data.items || [],
                itemCount: (data.items || []).length,
                likes: data.likes || 0,
                visibility: effectiveListVisibility(data.visibility),
                url: `${url.origin}/lists/${auth.username}/${slug}`,
              };
            } catch {
              return null;
            }
          })
        )
      ).filter(Boolean);

      const hasWatchlistInLists = lists.some(l => l && l.slug === "watchlist");
      if (!hasWatchlistInLists) {
        const wlRaw = await getCreatorList(env, auth.username, "watchlist");
        if (wlRaw) {
          try {
            const data = JSON.parse(wlRaw);
            lists.unshift({
              slug: "watchlist",
              name: data.name || "Watchlist",
              type: data.type || "mixed",
              items: data.items || [],
              itemCount: (data.items || []).length,
              likes: data.likes || 0,
              visibility: effectiveListVisibility(data.visibility),
              url: `${url.origin}/lists/${auth.username}/watchlist`,
            });
          } catch {}
        } else {
          const trackingRaw = await env.CONFIGS.get(`creatorsynctracking:${auth.username}`);
          if (trackingRaw) {
            try {
              const tb = JSON.parse(trackingRaw);
              if (Array.isArray(tb.watchlist) && tb.watchlist.length > 0) {
                lists.unshift({
                  slug: "watchlist",
                  name: "Watchlist",
                  type: "mixed",
                  items: tb.watchlist,
                  itemCount: tb.watchlist.length,
                  likes: 0,
                  visibility: "private",
                  url: `${url.origin}/lists/${auth.username}/watchlist`,
                });
              }
            } catch {}
          }
        }
      }

      // Content version + conditional response.
      //
      // This endpoint returns the FULL items array for every list the
      // account owns, and renderCreatorDashboard calls it on every render --
      // after a save, after a delete, on a tab switch, after a background
      // sync adopts server state. For anyone with large Custom Lists that
      // was megabytes down the wire and a megabytes-sized JSON.parse on the
      // main thread, over and over, almost always producing exactly the
      // data the browser already had.
      //
      // So the browser now sends back the version it last received, and
      // when nothing has changed it gets a few dozen bytes instead of the
      // whole payload and keeps using the copy it already holds.
      //
      // The version is a hash of the actual response body rather than a
      // separately-maintained counter. That costs a hash of a string this
      // endpoint had to build anyway, and in exchange it cannot drift: there
      // is no bump-on-write to forget in some future list-mutating route,
      // and any change to any list, its order, or the display name changes
      // the version by construction. Note it deliberately does NOT save the
      // KV reads above -- the lists still have to be read to know whether
      // they changed. What it removes is the transfer and the parse, which
      // is where the stall the person actually feels comes from.
      const listsPayload = { ok: true, displayName: auth.displayName, lists, order };
      let listsVersion = "";
      try {
        const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(JSON.stringify(listsPayload)));
        listsVersion = [...new Uint8Array(digest)].slice(0, 10).map((b) => b.toString(16).padStart(2, "0")).join("");
      } catch {
        // No digest available -- fall through with an empty version, which
        // can never match what a client sends, so it always gets the full
        // response. Degrades to the previous behaviour rather than to a
        // browser that stops seeing its own list changes.
      }
      if (listsVersion && body.knownVersion && body.knownVersion === listsVersion) {
        return json({ ok: true, unchanged: true, version: listsVersion });
      }
      return json({ ...listsPayload, version: listsVersion });
    }

    // /api/creator/lists/save  (POST)
    // { creatorName, creatorKey, slug (optional -- present means "update
    //   this existing list", absent means "create a new one"), name, type,
    //   items, visibility } -> { ok, slug, url }
    if (path === "/api/creator/lists/save" && request.method === "POST") {
      let body;
      try {
        body = await request.json();
      } catch {
        return json({ ok: false, error: "Invalid JSON body." }, 400);
      }
      const auth = await authenticateCreator(body.creatorName, body.creatorKey);
      if (!auth.ok) return json({ ok: false, error: auth.error === "no-kv" ? "no-kv" : "Username or Key is incorrect." }, auth.error === "no-kv" ? 500 : 401);

      const type = (body.type === "series" || body.type === "mixed") ? body.type : (body.type === "movie" ? "movie" : null);
      const items = Array.isArray(body.items) ? body.items : [];
      const visibility = normalizeListVisibility(body.visibility);
      const name = String(body.name || "").trim();
      if (!name) return json({ ok: false, error: "Missing a list name." }, 400);
      if (!type) return json({ ok: false, error: "Missing or invalid list type." }, 400);

      const orderRaw = await env.CONFIGS.get(`creatorlistorder:${auth.username}`);
      let order = [];
      try {
        order = orderRaw ? JSON.parse(orderRaw).order || [] : [];
      } catch {
        order = [];
      }

      const editingSlug = body.slug && order.includes(body.slug) ? body.slug : null;
      let slug;
      if (editingSlug) {
        // Editing keeps its existing URL even if the name changed --
        // re-slugging on every rename would break links people already
        // have to it.
        slug = editingSlug;
      } else {
        // New list -- slug uniqueness only needs to hold within this
        // creator's own namespace (see the spec: jack/top-10 and
        // someone-else/top-10 are unrelated), so the collision check and
        // auto-increment only look at this creator's own list keys.
        const baseSlug = slugifyServer(name) || "list";
        slug = baseSlug;
        for (let attempt = 2; attempt <= 500; attempt++) {
          if (!order.includes(slug)) break;
          slug = `${baseSlug}-${attempt}`;
        }
      }

      const now = Date.now();
      const existingRaw = editingSlug ? await getCreatorList(env, auth.username, slug) : null;
      let createdAt = now;
      let likes = 0;
      if (existingRaw) {
        try {
          const existing = JSON.parse(existingRaw);
          createdAt = existing.createdAt || now;
          likes = existing.likes || 0;
        } catch {
          createdAt = now;
        }
      }
      if (env.DB) {
        try {
          const listId = `${auth.username}:${slug}`;
          const itemsJson = JSON.stringify(items || []);
          await env.DB.prepare(
            "INSERT INTO creator_lists (id, username, name, type, visibility, items_json, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?) ON CONFLICT(id) DO UPDATE SET name=excluded.name, type=excluded.type, visibility=excluded.visibility, items_json=excluded.items_json, updated_at=excluded.updated_at"
          ).bind(listId, auth.username, name, type, visibility, itemsJson, createdAt, now).run();
        } catch (dbErr) {
          console.error("D1 write error (creatorlist put):", dbErr);
        }
      }
      
      // Unconditional -- KV must not be allowed to hold a stale copy of a
      // list that D1 has since updated, because the public read paths
      // (/lists/:user/:slug, the directory, search) all read KV.
      await env.CONFIGS.put(
        `creatorlist:${auth.username}:${slug}`,
        JSON.stringify({ name, slug, type, items, visibility, likes, createdAt, updatedAt: now })
      );
      if (!order.includes(slug)) {
        order.push(slug);
        await env.CONFIGS.put(`creatorlistorder:${auth.username}`, JSON.stringify({ order }));
      }

      // Keep the directory index in step with this save. A list turned
      // private is removed rather than updated, otherwise unpublishing would
      // leave it listed publicly.
      ctx.waitUntil(updatePublicListIndex(
        env,
        `c:${auth.username}:${slug}`,
        isPublicListVisibility(visibility) ? {
          isCreator: true,
          username: auth.username,
          creatorName: auth.displayName || auth.username,
          slug,
          name,
          type: type || "mixed",
          itemCount: Array.isArray(items) ? items.length : 0,
          likes: likes || 0,
          updatedAt: now,
        } : null
      ));
      return json({ ok: true, slug, url: `${url.origin}/lists/${auth.username}/${slug}` });
    }

    // /api/creator/lists/delete  (POST)  { creatorName, creatorKey, slug }
    if (path === "/api/creator/lists/delete" && request.method === "POST") {
      let body;
      try {
        body = await request.json();
      } catch {
        return json({ ok: false, error: "Invalid JSON body." }, 400);
      }
      const auth = await authenticateCreator(body.creatorName, body.creatorKey);
      if (!auth.ok) return json({ ok: false, error: auth.error === "no-kv" ? "no-kv" : "Username or Key is incorrect." }, auth.error === "no-kv" ? 500 : 401);
      const slug = String(body.slug || "");
      if (!slug) return json({ ok: false, error: "Missing slug." }, 400);
      if (env.DB) {
        try {
          await env.DB.prepare("DELETE FROM creator_lists WHERE id = ?").bind(`${auth.username}:${slug}`).run();
        } catch (dbErr) {
          console.error("D1 write error (creatorlist delete):", dbErr);
        }
      }

      // Unconditional, for the same reason as the key rotation above: a
      // DELETE matching zero D1 rows still "succeeds", and skipping the KV
      // delete on that basis left the list live in KV -- a delete that
      // reported ok:true and deleted nothing.
      await env.CONFIGS.delete(`creatorlist:${auth.username}:${slug}`);
      ctx.waitUntil(updatePublicListIndex(env, `c:${auth.username}:${slug}`, null));
      const orderRaw = await env.CONFIGS.get(`creatorlistorder:${auth.username}`);
      let order = [];
      try {
        order = orderRaw ? JSON.parse(orderRaw).order || [] : [];
      } catch {
        order = [];
      }
      order = order.filter((s) => s !== slug);
      await env.CONFIGS.put(`creatorlistorder:${auth.username}`, JSON.stringify({ order }));
      return json({ ok: true });
    }

    // /api/creator/lists/reorder  (POST)  { creatorName, creatorKey, order: [slug, ...] }
    if (path === "/api/creator/lists/reorder" && request.method === "POST") {
      let body;
      try {
        body = await request.json();
      } catch {
        return json({ ok: false, error: "Invalid JSON body." }, 400);
      }
      const auth = await authenticateCreator(body.creatorName, body.creatorKey);
      if (!auth.ok) return json({ ok: false, error: auth.error === "no-kv" ? "no-kv" : "Username or Key is incorrect." }, auth.error === "no-kv" ? 500 : 401);
      const newOrder = Array.isArray(body.order) ? body.order.map(String).filter(s => /^[a-zA-Z0-9_.:-]+$/.test(s)) : [];
      await env.CONFIGS.put(`creatorlistorder:${auth.username}`, JSON.stringify({ order: newOrder }));
      return json({ ok: true, order: newOrder });
    }

    // /api/creator/account/reset  (POST)  { creatorName, creatorKey, confirm }
    //   -> { ok, cleared: { lists, keys } }
    // Empties an account back to how it looked the moment it was created,
    // WITHOUT deleting the account itself: the creator record, its key hash
    // and its recovery answer are all left alone, so the same Creator Name
    // and Key keep working and the person stays signed in.
    //
    // Distinct from /api/creator/delete-account below, which removes the
    // profile outright. Worth noting while looking at the two together: that
    // one deletes `creatorprofile:`, `creatortrack:`, `creatorpresets:` and
    // `creatorchannels:`, which are old key names this codebase no longer
    // writes -- the live data is under `creator:`, `creatorsynctracking:`,
    // `creatorsyncpresets:` and `creatorsyncchannels:`. So it currently
    // leaves most of an account's data behind. Not changed here because
    // deleting more on that path deserves its own decision, but this reset
    // uses the names actually in use, plus the legacy ones for good measure.
    if (path === "/api/creator/account/reset" && request.method === "POST") {
      if (!env || !env.CONFIGS) return json({ ok: false, error: "Database not configured." }, 500);
      let body;
      try {
        body = await request.json();
      } catch {
        return json({ ok: false, error: "Invalid JSON body." }, 400);
      }
      const auth = await authenticateCreator(body.creatorName, body.creatorKey);
      if (!auth.ok) return json({ ok: false, error: auth.error === "no-kv" ? "no-kv" : "Username or Key is incorrect." }, 401);

      // A second, explicit confirmation carried in the request itself. The
      // key alone is enough to authenticate, but this is irreversible and
      // there is no undo, so it should not be reachable by a stray request.
      if (String(body.confirm || "") !== "RESET") {
        return json({ ok: false, error: "Missing confirmation." }, 400);
      }

      // Same sweep as delete-account, minus the identity -- see
      // purgeCreatorData (02_http-and-creator-utils.js). Keeping both
      // callers on one function is what stops the two from drifting apart
      // again the way they had.
      const purged = await purgeCreatorData(env, auth.username, { deleteIdentity: false });

      return json({ ok: true, cleared: { lists: purged.listsCleared, keys: purged.keysCleared } });
    }

    // /api/creator/delete-account  (POST)  { creatorName, creatorKey } -> { ok }
    // Permanently removes the creator profile, their published lists, order, and sync data
    if (path === "/api/creator/delete-account" && request.method === "POST") {
      if (!env || !env.CONFIGS) return json({ ok: false, error: "Database not configured." }, 500);
      let body;
      try {
        body = await request.json();
      } catch {
        return json({ ok: false, error: "Invalid JSON body." }, 400);
      }
      const auth = await authenticateCreator(body.creatorName, body.creatorKey);
      if (!auth.ok) return json({ ok: false, error: auth.error === "no-kv" ? "no-kv" : "Username or Key is incorrect." }, 401);

      // A second, explicit confirmation carried in the request itself,
      // matching /api/creator/account/reset. The key alone authenticates,
      // but this is irreversible and there is no undo, so it must not be
      // reachable by a stray or replayed request.
      if (String(body.confirm || "") !== "DELETE") {
        return json({ ok: false, error: "Missing confirmation." }, 400);
      }

      // deleteIdentity: true is the whole difference from account/reset --
      // the profile, the D1 row, and the last-seen marker go too, so the
      // key stops authenticating and the username becomes reclaimable.
      const purged = await purgeCreatorData(env, auth.username, { deleteIdentity: true });
      return json({ ok: true, cleared: { lists: purged.listsCleared, keys: purged.keysCleared } });
    }

    // --- Site-wide account sync ---------------------------------------------
    //
    // A Creator Profile started out scoped to just publishing/managing
    // Custom Lists (the block above). This extends the same account to the
    // rest of the builder page too: the person's full list of source rows
    // and their order, their saved presets, which panels they'd left
    // collapsed, and which lists they'd liked -- so signing in on another
    // device or browser picks up where they left off instead of starting
    // from a blank page. Still no email/password: the same Creator Name +
    // Creator Key from above is all that's needed.
    //
    // Deliberately a single wholesale blob rather than four separate
    // endpoints -- the client always has the complete current picture of
    // all four in memory already (collectEntries(), the presets map, the
    // collapsed-panel state, and the liked-lists set), so there's no
    // partial-update case that actually needs a smaller request, and one
    // key is simpler to reason about than keeping four in sync with each
    // other.
    if (path === "/api/creator/sync/save" && request.method === "POST") {
      let body;
      try {
        body = await request.json();
      } catch {
        return json({ ok: false, error: "Invalid JSON body." }, 400);
      }
      const auth = await authenticateCreator(body.creatorName, body.creatorKey);
      if (!auth.ok) return json({ ok: false, error: auth.error === "no-kv" ? "no-kv" : "Username or Key is incorrect." }, auth.error === "no-kv" ? 500 : 401);

      // Same one-time forward migration, this time for tracking data
      // (watchHistory/continueWatching/fullyWatchedShowIds/
      // dismissedContinueWatching/trackPlayback) -- see
      // ensureTrackingMigrated's own comment. Critical to run here
      // specifically: this endpoint is the most frequent write to
      // creatorsync:{username} of any of them (any routine autosave), and
      // the blob built below no longer includes tracking fields at all --
      // without migrating first, the very next autosave after this
      // shipped would silently erase anyone's tracking data before
      // save-tracking ever got a chance to run for them.
      await ensureTrackingMigrated(env, auth.username);

      // One-time forward migration: presets used to live embedded in this
      // same blob, but as of this endpoint no longer accepts them here at
      // all (see /api/creator/sync/save-presets below) -- an updated client
      // never sends body.presets/presetsB64 anymore. Without this check,
      // the very first autosave after updating would overwrite this blob
      // with no presets embedded, and since nothing would have copied the
      // old embedded presets into the dedicated key yet either, they'd be
      // gone. Only runs once per account: after the dedicated key exists
      // (whether from this migration or a real preset save), this block is
      // skipped on every subsequent save.
      const existingPresetsKey = await env.CONFIGS.get(`creatorsyncpresets:${auth.username}`);
      if (existingPresetsKey === null) {
        const oldRaw = await env.CONFIGS.get(`creatorsync:${auth.username}`);
        if (oldRaw) {
          try {
            const oldBlob = JSON.parse(oldRaw);
            if (oldBlob.presetsB64 || (oldBlob.presets && Object.keys(oldBlob.presets).length)) {
              await env.CONFIGS.put(`creatorsyncpresets:${auth.username}`, JSON.stringify({
                presets: (oldBlob.presets && typeof oldBlob.presets === "object") ? oldBlob.presets : {},
                presetsB64: oldBlob.presetsB64 || null,
              }));
            }
          } catch {
            // Old blob was unreadable -- nothing to migrate; whatever's
            // already in the dedicated key (or lack of one) stands as-is.
          }
        }
      }

      // Conflict guard -- this endpoint used to always blindly overwrite
      // creatorsync:{username} with whatever this request's snapshot was,
      // no matter how stale. Two tabs/devices autosaving around the same
      // time meant whichever PUT landed last in KV won completely, silently
      // discarding the other one's edits with no error anywhere.
      //
      // An updated client now sends expectedUpdatedAt: the updatedAt it
      // last actually saw (from a prior /sync/load or /sync/save response)
      // -- i.e. the version its current edits are built on top of. If the
      // record in KV has moved past that, another device saved in between;
      // rather than clobber that write, this responds 409 and leaves KV
      // untouched. The client's own pending edits aren't lost either: they
      // stay in its DOM/localStorage and go up on the very next autosave,
      // now against the correct baseline. An older client that doesn't
      // send expectedUpdatedAt at all gets exactly its previous behavior
      // (last-write-wins) -- this is purely additive, not a breaking
      // change to the request shape.
      const expectedUpdatedAt = Number.isFinite(body.expectedUpdatedAt) ? body.expectedUpdatedAt : null;
      if (expectedUpdatedAt !== null) {
        const currentRaw = await env.CONFIGS.get(`creatorsync:${auth.username}`);
        if (currentRaw) {
          try {
            const current = JSON.parse(currentRaw);
            if (Number(current.updatedAt) > expectedUpdatedAt) {
              // Purely for visibility -- this was previously invisible even
              // to us; now it's at least countable on the admin dashboard.
              ctx.waitUntil(bumpStat(env, "sync_conflict"));
              return json({ ok: false, error: "conflict", conflict: true, updatedAt: current.updatedAt }, 409);
            }
          } catch {
            // Existing blob unreadable -- nothing coherent to protect
            // against; fall through and write normally.
          }
        }
      }

      const blob = {
        config: Array.isArray(body.config) ? body.config : [],
        keys: body.keys && typeof body.keys === "object" ? body.keys : {},
        collapsedPanels: body.collapsedPanels && typeof body.collapsedPanels === "object" ? body.collapsedPanels : {},
        likedLists: Array.isArray(body.likedLists) ? body.likedLists.map(String) : [],
        hiddenLists: Array.isArray(body.hiddenLists) ? body.hiddenLists.map(String) : [],
        hiddenMyListsSections: Array.isArray(body.hiddenMyListsSections) ? body.hiddenMyListsSections.map(String) : [],
        updatedAt: Date.now(),
      };
      const serialized = JSON.stringify(blob);
      // Workers KV hard-caps a value at 25MB. Presets/Channels and tracking
      // data (watchHistory/continueWatching/etc) no longer live in this
      // blob at all (see above), so this is now just a defensive backstop
      // rather than the main thing it used to guard against.
      if (serialized.length > 24 * 1024 * 1024) {
        return json({ ok: false, error: "This account's saved data is too large to store (over the 25MB limit)." });
      }
      try {
        await env.CONFIGS.put(`creatorsync:${auth.username}`, serialized);
      } catch (e) {
        // A real KV failure (rate limit, transient error, etc.) previously
        // surfaced to the client as nothing more than a failed fetch --
        // this at least tells the person something specific went wrong
        // server-side rather than leaving "check your connection" as the
        // only explanation, which is misleading when the connection was
        // never the problem.
        return json({ ok: false, error: "Could not save to storage right now. Please try again in a moment." }, 500);
      }
      // updatedAt lets the client advance its own baseline without a
      // separate /sync/meta round trip -- see expectedUpdatedAt above.
      return json({ ok: true, updatedAt: blob.updatedAt });
    }

    // /api/creator/sync/save-tracking  (POST)  { creatorName, creatorKey,
    // watchHistory, continueWatching, fullyWatchedShowIds,
    // dismissedContinueWatching, trackPlayback } -> { ok }
    // The dedicated, lightweight sibling of /api/creator/sync/save for
    // Watch History / Continue Watching tracking data -- split out for the
    // same reason presets were (see save-presets' own comment just below):
    // watchHistory in particular can grow into the thousands of items for
    // an active account (e.g. a bulk "mark as watched" import), and it used
    // to ride along in the same blob as config/collapsedPanels/likedLists,
    // making EVERY routine autosave -- and every single Auto-Track Playback
    // ping (handleSubtitlesTrack, further down this file), which fires on
    // every video play -- re-send and re-process the whole thing. Also read
    // by the Continue Watching cron (checkForNewEpisodes) and
    // fetchAutoTrackedCatalog (what Stremio/wako actually see for the
    // Watch History/Continue Watching catalog rows) -- if this never
    // successfully saves (e.g. it silently failed under the old combined
    // blob's size), those rows show "No items found" even though the
    // browser's own local copy looks complete.
    if (path === "/api/creator/sync/save-tracking" && request.method === "POST") {
      let body;
      try {
        body = await request.json();
      } catch {
        return json({ ok: false, error: "Invalid JSON body." }, 400);
      }
      const auth = await authenticateCreator(body.creatorName, body.creatorKey);
      if (!auth.ok) return json({ ok: false, error: auth.error === "no-kv" ? "no-kv" : "Username or Key is incorrect." }, auth.error === "no-kv" ? 500 : 401);
      const watchlistUpdatedAt = Number(body.watchlistUpdatedAt) || Date.now();

      // Guard against a narrow but real race: handleSubtitlesTrack and
      // handleMediaServerScrobble both read-modify-write this same KV key
      // directly and outside of any request this browser initiated, so a
      // scrobble can land *between* this browser's last load and this
      // push. Since this endpoint's whole design is "always the full
      // current list" (see pushTrackingSync's own comment -- deliberate,
      // so Clear Watch History and per-item removal both work by just
      // sending a shorter array), a stale client push would otherwise
      // silently erase whatever a scrobble just added.
      //
      // Rather than merging the *entire* history (which would make Clear
      // Watch History and per-item removal impossible to ever fully commit
      // -- the deleted item would just come back on the next autosave),
      // only rescue items added by a scrobble ping inside a short recency
      // window right before this push, and skip the rescue entirely when
      // the client flags this push as an intentional removal (Clear Watch
      // History, deleting a single item) -- see pushTrackingSync's
      // intentionalRemoval comment. That's the one case a stale client
      // snapshot can plausibly be missing something real; anything older
      // than that the client's own load would already have picked up.
      // Always merge server KV state with incoming client state to preserve
      // any scrobbles written by handleSubtitlesTrack or handleMediaServerScrobble
      // that landed between this browser's last load and this push.
      //
      // We cannot gate this on the diagnostic timestamp because handleSubtitlesTrack
      // runs inside ctx.waitUntil (async after the response is sent), so the
      // diagnostic write may arrive AFTER save-tracking has already run -- which
      // was silently wiping every scrobble.
      //
      // Strategy: read KV directly, find any watchHistory items with a watchedAt
      // timestamp newer than body.watchHistory's newest item (i.e. added by the
      // server after the client's last load) and prepend them. Same for
      // continueWatching: show IDs in KV but not in the incoming body are
      // preserved at the front. Skip the merge only for intentionalRemoval.
      let rescuedCount = 0;
      if (!body.intentionalRemoval) {
        try {
          const existingRaw = await env.CONFIGS.get(`creatorsynctracking:${auth.username}`);
          if (existingRaw) {
            const existingBlob = JSON.parse(existingRaw);

            // Watch History: find server items not present in the incoming payload
            const incomingIds = new Set(
              (Array.isArray(body.watchHistory) ? body.watchHistory : []).map((it) => String(it && it.id))
            );
            const serverOnlyItems = (Array.isArray(existingBlob.watchHistory) ? existingBlob.watchHistory : [])
              .filter((it) => it && it.id && !incomingIds.has(String(it.id)));
            if (serverOnlyItems.length) {
              // Sort server-only items newest-first and prepend them
              serverOnlyItems.sort((a, b) => (b.watchedAt || 0) - (a.watchedAt || 0));
              body.watchHistory = [...serverOnlyItems, ...(Array.isArray(body.watchHistory) ? body.watchHistory : [])];
              rescuedCount = serverOnlyItems.length;
            }

            // Continue Watching: when scrobbles occur on the server (Nuvio / Plex),
            // the server computes the next episode and updates existingBlob.continueWatching.
            // If the server has a show in continueWatching, its version must take precedence
            // over the client's stale incoming item for that same show!
            const serverCwList = Array.isArray(existingBlob.continueWatching) ? existingBlob.continueWatching : [];
            if (serverCwList.length) {
              const incomingCwList = Array.isArray(body.continueWatching) ? body.continueWatching : [];
              const mergedCw = [];
              const handledShows = new Set();
              
              // Server's updated Continue Watching items come first
              for (const sItem of serverCwList) {
                if (sItem && (sItem.showId || sItem.id)) {
                  const sKey = String(sItem.showId || sItem.id);
                  mergedCw.push(sItem);
                  handledShows.add(sKey);
                }
              }
              // Add any client-only Continue Watching shows that aren't on the server
              for (const cItem of incomingCwList) {
                if (cItem && (cItem.showId || cItem.id)) {
                  const cKey = String(cItem.showId || cItem.id);
                  if (!handledShows.has(cKey)) {
                    mergedCw.push(cItem);
                    handledShows.add(cKey);
                  }
                }
              }
              body.continueWatching = mergedCw;
            }

            // Airing Next and the Discover recommendations are DERIVED
            // lists: a browser only has them once it has computed them
            // (refreshAiringNext, and opening the Discover tab). A browser
            // that has not done that yet still pushes the full tracking
            // payload on its first autosave, with those two fields empty
            // -- and since this endpoint is "always the full current
            // list", that empty array used to overwrite a perfectly good
            // one another browser had already computed. The catalog row
            // reading it (fetchAutoTrackedCatalog / fetchCuratedCatalog)
            // then served nothing, which is what "No items found" in the
            // Live Preview actually was.
            //
            // So: an empty incoming derived list never replaces a
            // non-empty stored one. Deliberately shrinking one still
            // works -- a real change sends a non-empty array, and an
            // intentional clear (Clear Watch History) sets
            // intentionalRemoval and skips this whole block.
            if ((!Array.isArray(body.airingNext) || !body.airingNext.length) &&
                Array.isArray(existingBlob.airingNext) && existingBlob.airingNext.length) {
              body.airingNext = existingBlob.airingNext;
            }
            const incomingRecs = body.curatedRecommendations;
            const incomingRecsEmpty = !incomingRecs || typeof incomingRecs !== "object" ||
              ((!Array.isArray(incomingRecs.movies) || !incomingRecs.movies.length) &&
               (!Array.isArray(incomingRecs.shows) || !incomingRecs.shows.length));
            const storedRecs = existingBlob.curatedRecommendations;
            const storedRecsPresent = storedRecs && typeof storedRecs === "object" &&
              ((Array.isArray(storedRecs.movies) && storedRecs.movies.length) ||
               (Array.isArray(storedRecs.shows) && storedRecs.shows.length));
            if (incomingRecsEmpty && storedRecsPresent) {
              body.curatedRecommendations = storedRecs;
            }

            // fullyWatchedShowIds: union
            if (Array.isArray(existingBlob.fullyWatchedShowIds) && existingBlob.fullyWatchedShowIds.length) {
              const incomingFW = new Set(Array.isArray(body.fullyWatchedShowIds) ? body.fullyWatchedShowIds.map(String) : []);
              for (const sid of existingBlob.fullyWatchedShowIds) {
                if (!incomingFW.has(String(sid))) {
                  body.fullyWatchedShowIds = body.fullyWatchedShowIds || [];
                  body.fullyWatchedShowIds.push(sid);
                }
              }
            }
          }
        } catch {
          // Merge is best-effort -- never block the save over it.
        }

        // SECONDARY MERGE: always read the dedicated scrobble-queue key.
        // This is written by handleSubtitlesTrack immediately after each
        // scrobble and is tiny (≤20 items), so it propagates faster and
        // independently from the large tracking blob. This catches the case
        // where the large blob hasn't propagated across Cloudflare edges yet.
        try {
          const queueRaw = await env.CONFIGS.get(`creatorscrobblequeue:${auth.username}`);
          if (queueRaw) {
            const queue = JSON.parse(queueRaw);
            let queueWh = [];
            let queueCw = [];
            if (Array.isArray(queue)) {
              queueWh = queue;
            } else if (queue && typeof queue === "object") {
              queueWh = Array.isArray(queue.watchHistory) ? queue.watchHistory : [];
              queueCw = Array.isArray(queue.continueWatching) ? queue.continueWatching : [];
            }
            if (queueWh.length) {
              const currentIds = new Set(
                (Array.isArray(body.watchHistory) ? body.watchHistory : []).map((it) => String(it && it.id))
              );
              const queueOnly = queueWh.filter((it) => it && it.id && !currentIds.has(String(it.id)));
              if (queueOnly.length) {
                queueOnly.sort((a, b) => (b.watchedAt || 0) - (a.watchedAt || 0));
                body.watchHistory = [...queueOnly, ...(Array.isArray(body.watchHistory) ? body.watchHistory : [])];
                rescuedCount += queueOnly.length;
              }
            }
            if (queueCw.length) {
              const mergedCw = [];
              const handledShows = new Set();
              for (const qItem of queueCw) {
                if (qItem && (qItem.showId || qItem.id)) {
                  mergedCw.push(qItem);
                  handledShows.add(String(qItem.showId || qItem.id));
                }
              }
              for (const bItem of (Array.isArray(body.continueWatching) ? body.continueWatching : [])) {
                if (bItem && (bItem.showId || bItem.id)) {
                  const bKey = String(bItem.showId || bItem.id);
                  if (!handledShows.has(bKey)) {
                    mergedCw.push(bItem);
                    handledShows.add(bKey);
                  }
                }
              }
              body.continueWatching = mergedCw;
            }
          }
        } catch {
          // Best-effort
        }
      }

      const blob = {
        watchHistory: Array.isArray(body.watchHistory) ? body.watchHistory : [],
        continueWatching: Array.isArray(body.continueWatching) ? body.continueWatching : [],
        watchlist: Array.isArray(body.watchlist) ? body.watchlist : [],
        watchlistUpdatedAt: watchlistUpdatedAt,
        // Airing Next -- unlike watchHistory/continueWatching, this is
        // purely derived (recomputed client-side against TMDB on a timer,
        // see refreshAiringNext, 21_client-custom-list-builder.js), so
        // there's nothing to migrate from an older creatorsync: blob the
        // way ensureTrackingMigrated handles the other tracking fields --
        // it just starts empty on an account that hasn't pushed one yet,
        // same as a brand new field always would.
        airingNext: Array.isArray(body.airingNext) ? body.airingNext : [],
        // The Discover tab's Recommended Movies/Shows lists, exactly as
        // that tab rendered them. Pushed rather than recomputed for the
        // same reason airingNext is: fetchCuratedCatalog
        // (05_catalog-core.js) cannot see the browser-side inputs the
        // card is built from, so the only way the catalog row and the
        // card can hold the same items is for the browser to hand the
        // server the list it actually showed.
        curatedRecommendations: (body.curatedRecommendations && typeof body.curatedRecommendations === "object")
          ? {
              movies: Array.isArray(body.curatedRecommendations.movies) ? body.curatedRecommendations.movies : [],
              shows: Array.isArray(body.curatedRecommendations.shows) ? body.curatedRecommendations.shows : [],
              updatedAt: Number(body.curatedRecommendations.updatedAt) || Date.now(),
            }
          : null,
        fullyWatchedShowIds: Array.isArray(body.fullyWatchedShowIds) ? body.fullyWatchedShowIds.map(String) : [],
        dismissedContinueWatching: body.dismissedContinueWatching && typeof body.dismissedContinueWatching === "object" ? body.dismissedContinueWatching : {},
        trackPlayback: typeof body.trackPlayback === "boolean" ? body.trackPlayback : false,
        removeWatchedFromWatchlist: typeof body.removeWatchedFromWatchlist === "boolean" ? body.removeWatchedFromWatchlist : true,
        scrobbleFilterUsers: typeof body.scrobbleFilterUsers === "boolean" ? body.scrobbleFilterUsers : false,
        scrobbleAllowedUsers: typeof body.scrobbleAllowedUsers === "string" ? body.scrobbleAllowedUsers : "",
        scrobbleBlockAnonymous: typeof body.scrobbleBlockAnonymous === "boolean" ? body.scrobbleBlockAnonymous : false,
        updatedAt: Date.now(),
      };
      const serialized = JSON.stringify(blob);
      if (serialized.length > 24 * 1024 * 1024) {
        return json({ ok: false, error: "Your Watch History is too large to store (over the 25MB limit)." });
      }
      try {
        await env.CONFIGS.put(`creatorsynctracking:${auth.username}`, serialized);
        if (Array.isArray(body.watchlist)) {
          const wlRaw = await getCreatorList(env, auth.username, "watchlist");
          let wlObj = null;
          if (wlRaw) {
            try {
              wlObj = JSON.parse(wlRaw);
            } catch {}
          }
          if (!wlObj) {
            wlObj = {
              name: "Watchlist",
              slug: "watchlist",
              type: "mixed",
              isWatchlist: true,
              visibility: "private",
              createdAt: Date.now(),
            };
          }
          wlObj.items = body.watchlist;
          wlObj.updatedAt = watchlistUpdatedAt;
          
          if (env.DB) {
            try {
              const listId = `${auth.username}:watchlist`;
              const itemsJson = JSON.stringify(wlObj.items || []);
              await env.DB.prepare(
                "INSERT INTO creator_lists (id, username, name, type, visibility, items_json, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?) ON CONFLICT(id) DO UPDATE SET name=excluded.name, type=excluded.type, visibility=excluded.visibility, items_json=excluded.items_json, updated_at=excluded.updated_at"
              ).bind(listId, auth.username, wlObj.name, wlObj.type, wlObj.visibility, itemsJson, wlObj.createdAt, wlObj.updatedAt).run();
            } catch (dbErr) {
              console.error("D1 write error (creatorlist watchlist):", dbErr);
            }
          }
          
          // Unconditional -- see the creatorlist put above.
          await env.CONFIGS.put(`creatorlist:${auth.username}:watchlist`, JSON.stringify(wlObj));

          const orderRaw = await env.CONFIGS.get(`creatorlistorder:${auth.username}`);
          let order = [];
          try { order = orderRaw ? JSON.parse(orderRaw).order || [] : []; } catch {}
          if (!order.includes("watchlist")) {
            order.unshift("watchlist");
            await env.CONFIGS.put(`creatorlistorder:${auth.username}`, JSON.stringify({ order }));
          }
        }
      } catch (e) {
        return json({ ok: false, error: "Could not save to storage right now. Please try again in a moment." }, 500);
      }
      return json({ ok: true, rescuedFromScrobble: rescuedCount });
    }

    // /api/creator/sync/save-presets  (POST)  { creatorName, creatorKey,
    // presets?, presetsB64? } -> { ok }
    // The dedicated, lightweight sibling of /api/creator/sync/save just for
    // presets -- split out because presets are the one piece of synced
    // state that can genuinely grow large (a TV Channel's "url" is its
    // entire episode list, see collectEntries' comment,
    // 21_client-custom-list-builder.js, and a preset stores a full copy of
    // everything in it), while everything else in the main blob
    // (config/watchHistory/collapsedPanels/etc) changes far more often but
    // stays small. Before this split, EVERY autosave -- not just an
    // explicit "save preset" -- re-sent and re-processed the entire,
    // ever-growing presets payload alongside that small, frequent state,
    // which is what could tip a request over Cloudflare's free-plan 10ms
    // CPU budget (PBKDF2 verification below plus a large JSON parse/
    // stringify) and fail with no useful error. This endpoint only gets
    // called when presets actually change (see schedulePresetsSync,
    // 24_client-backup-restore-presets.js), and does no deep JSON work of
    // its own -- presetsB64 is already gzip-compressed client-side into an
    // opaque string, so storing it here is close to a raw pass-through.
    if (path === "/api/creator/sync/save-presets" && request.method === "POST") {
      let body;
      try {
        body = await request.json();
      } catch {
        return json({ ok: false, error: "Invalid JSON body." }, 400);
      }
      const auth = await authenticateCreator(body.creatorName, body.creatorKey);
      if (!auth.ok) return json({ ok: false, error: auth.error === "no-kv" ? "no-kv" : "Username or Key is incorrect." }, auth.error === "no-kv" ? 500 : 401);
      const presetsBlob = {
        presets: body.presets && typeof body.presets === "object" ? body.presets : {},
        presetsB64: body.presetsB64 || null,
        updatedAt: Date.now(),
      };
      const serialized = JSON.stringify(presetsBlob);
      if (serialized.length > 24 * 1024 * 1024) {
        return json({ ok: false, error: "Your saved presets are too large to store (over the 25MB limit) \u2014 likely from several TV Channels with a lot of episodes. Try removing an older preset or a large Channel." });
      }
      try {
        await env.CONFIGS.put(`creatorsyncpresets:${auth.username}`, serialized);
      } catch (e) {
        return json({ ok: false, error: "Could not save to storage right now. Please try again in a moment." }, 500);
      }
      return json({ ok: true });
    }

    // /api/creator/sync/save-channels (POST) { creatorName, creatorKey, channels, mergedChannels }
    if (path === "/api/creator/sync/save-channels" && request.method === "POST") {
      let body;
      try {
        body = await request.json();
      } catch {
        return json({ ok: false, error: "Invalid JSON body." }, 400);
      }
      const auth = await authenticateCreator(body.creatorName, body.creatorKey);
      if (!auth.ok) return json({ ok: false, error: auth.error === "no-kv" ? "no-kv" : "Username or Key is incorrect." }, auth.error === "no-kv" ? 500 : 401);
      const channelsBlob = {
        channels: body.channels && typeof body.channels === "object" ? body.channels : {},
        mergedChannels: body.mergedChannels && typeof body.mergedChannels === "object" ? body.mergedChannels : {},
        updatedAt: Date.now(),
      };
      const serialized = JSON.stringify(channelsBlob);
      if (serialized.length > 24 * 1024 * 1024) {
        return json({ ok: false, error: "Your saved channels are too large to store (over the 25MB limit)." });
      }
      try {
        await env.CONFIGS.put(`creatorsyncchannels:${auth.username}`, serialized);
      } catch (e) {
        return json({ ok: false, error: "Could not save to storage right now. Please try again in a moment." }, 500);
      }
      return json({ ok: true });
    }

    // /api/creator/sync/meta  (POST)  { creatorName, creatorKey }
    //   -> { ok, config, tracking, presets, channels }
    // A deliberately tiny sibling of /api/creator/sync/load below, holding
    // nothing but the four updatedAt stamps that tell a browser whether
    // anything it cares about has actually changed.
    //
    // It exists because the dashboard polls for multi-device changes on a
    // timer while it is simply open (see handleForegroundResumeSync,
    // 22_client-creator-profile.js), and that poll used to call sync/load
    // itself -- which reads six KV keys, JSON-parses a watchHistory that
    // can run to thousands of items, re-serializes all of it, and ships
    // the whole thing back down the wire. For an active account that was
    // megabytes of response, several times a minute, almost always to
    // conclude that nothing had changed at all.
    //
    // Two things keep this cheap. The four reads run concurrently rather
    // than one after another, and each updatedAt is pulled straight out of
    // the raw stored string (see readUpdatedAtFromRaw) instead of parsing
    // the blob -- so a 4MB tracking record costs a substring scan here,
    // not a full parse. The response is a few dozen bytes either way.
    //
    // Deliberately derived from the same keys sync/load reads rather than
    // from a separate "last changed" record: a dedicated key would have to
    // be updated by every write path that touches any of these blobs, and
    // a single missed write there would silently stop a device from ever
    // syncing again. Reading the real thing cannot drift.
    if (path === "/api/creator/sync/meta" && request.method === "POST") {
      let body;
      try {
        body = await request.json();
      } catch {
        return json({ ok: false, error: "Invalid JSON body." }, 400);
      }
      const auth = await authenticateCreator(body.creatorName, body.creatorKey);
      if (!auth.ok) return json({ ok: false, error: auth.error === "no-kv" ? "no-kv" : "Username or Key is incorrect." }, auth.error === "no-kv" ? 500 : 401);

      // Pulls "updatedAt": <number> out of a stored blob without parsing
      // it. Every blob these keys hold writes updatedAt as a plain number
      // at the top level, and lastIndexOf finds the last (top-level) one
      // rather than any nested occurrence inside an item. A miss returns 0,
      // which reads as "older than anything the client has" and simply
      // causes a normal full load -- never a skipped one.
      function readUpdatedAtFromRaw(raw) {
        if (!raw) return 0;
        const marker = '"updatedAt":';
        const at = raw.lastIndexOf(marker);
        if (at === -1) return 0;
        const num = parseInt(raw.slice(at + marker.length, at + marker.length + 20).replace(/[^0-9].*$/, ""), 10);
        return Number.isFinite(num) ? num : 0;
      }

      let configRaw = null, trackingRaw = null, presetsRaw = null, channelsRaw = null;
      try {
        [configRaw, trackingRaw, presetsRaw, channelsRaw] = await Promise.all([
          env.CONFIGS.get(`creatorsync:${auth.username}`),
          env.CONFIGS.get(`creatorsynctracking:${auth.username}`),
          env.CONFIGS.get(`creatorsyncpresets:${auth.username}`),
          env.CONFIGS.get(`creatorsyncchannels:${auth.username}`),
        ]);
      } catch {
        // A read failure must not look like "nothing changed" -- returning
        // ok:false makes the client fall back to a full sync/load.
        return json({ ok: false, error: "Could not read sync state right now." }, 500);
      }

      return json({
        ok: true,
        exists: configRaw !== null || trackingRaw !== null,
        config: readUpdatedAtFromRaw(configRaw),
        tracking: readUpdatedAtFromRaw(trackingRaw),
        presets: readUpdatedAtFromRaw(presetsRaw),
        channels: readUpdatedAtFromRaw(channelsRaw),
      });
    }

    // /api/creator/sync/load -> { ok, data: blob | null }
    // null specifically (rather than an empty blob) distinguishes "this
    // account has never synced from any device" from "this account synced
    // an empty state" -- the client uses that to decide whether to adopt
    // what's already on this browser and push it up as this account's
    // first save, versus overwriting this browser with what the account
    // already has.
    if (path === "/api/creator/sync/load" && request.method === "POST") {
      let body;
      try {
        body = await request.json();
      } catch {
        return json({ ok: false, error: "Invalid JSON body." }, 400);
      }
      const auth = await authenticateCreator(body.creatorName, body.creatorKey);
      if (!auth.ok) return json({ ok: false, error: auth.error === "no-kv" ? "no-kv" : "Username or Key is incorrect." }, auth.error === "no-kv" ? 500 : 401);
      await ensureTrackingMigrated(env, auth.username);
      // These five reads are independent of one another, and were awaited
      // one after the next -- so this endpoint paid five sequential KV
      // round trips before it could start assembling anything. Issuing them
      // together turns that into one. (ensureTrackingMigrated above still
      // runs first on purpose: it can WRITE the tracking key, so reading it
      // concurrently with that would be a race.)
      const [raw, presetsRawInit, channelsRawInit, trackingRawInit, orderRawInit] = await Promise.all([
        env.CONFIGS.get(`creatorsync:${auth.username}`),
        env.CONFIGS.get(`creatorsyncpresets:${auth.username}`),
        env.CONFIGS.get(`creatorsyncchannels:${auth.username}`),
        env.CONFIGS.get(`creatorsynctracking:${auth.username}`),
        env.CONFIGS.get(`creatorlistorder:${auth.username}`),
      ]);
      let data = null;
      if (raw) {
        try {
          data = JSON.parse(raw);
        } catch {
          data = null;
        }
      }
      // Presets live in their own key now (see save-presets above) -- merge
      // them back in here so the client's loadCreatorSync doesn't need to
      // know or care that this is two KV reads instead of one; it still
      // just reads data.presets/data.presetsB64 exactly like before.
      let presetsRaw = presetsRawInit;
      let presetsBlob = null;
      if (presetsRaw) {
        try {
          presetsBlob = JSON.parse(presetsRaw);
        } catch {
          presetsBlob = null;
        }
      }

      // Extract presets safely regardless of storage format
      let dedicatedPresets = {};
      let dedicatedPresetsB64 = null;
      let dedicatedUpdatedAt = 0;

      if (presetsBlob) {
        if (presetsBlob.presetsB64 && typeof presetsBlob.presetsB64 === "string") {
          dedicatedPresetsB64 = presetsBlob.presetsB64;
        }
        if (presetsBlob.presets && typeof presetsBlob.presets === "object" && !Array.isArray(presetsBlob.presets)) {
          dedicatedPresets = { ...presetsBlob.presets };
        } else if (typeof presetsBlob === "object" && !Array.isArray(presetsBlob)) {
          Object.keys(presetsBlob).forEach((k) => {
            if (k !== "presets" && k !== "presetsB64" && k !== "updatedAt" && presetsBlob[k] && typeof presetsBlob[k] === "object") {
              dedicatedPresets[k] = presetsBlob[k];
            }
          });
        } else if (Array.isArray(presetsBlob)) {
          presetsBlob.forEach((p) => {
            if (p && p.name) dedicatedPresets[p.name] = p;
          });
        }
        if (presetsBlob.updatedAt) dedicatedUpdatedAt = presetsBlob.updatedAt;
      }

      const dedicatedHasPresets = !!(dedicatedPresetsB64 || Object.keys(dedicatedPresets).length > 0);
      const mainHasPresets = !!(data && (data.presetsB64 || (data.presets && typeof data.presets === 'object' && Object.keys(data.presets).length > 0)));

      if (!dedicatedHasPresets && mainHasPresets) {
        let adoptedMap = {};
        if (data.presets && typeof data.presets === "object" && !Array.isArray(data.presets)) {
          adoptedMap = { ...data.presets };
        } else if (Array.isArray(data.presets)) {
          data.presets.forEach((p) => { if (p && p.name) adoptedMap[p.name] = p; });
        }
        dedicatedPresets = adoptedMap;
        dedicatedPresetsB64 = data.presetsB64 || null;
        dedicatedUpdatedAt = Date.now();
        try {
          await env.CONFIGS.put(`creatorsyncpresets:${auth.username}`, JSON.stringify({
            presets: dedicatedPresets,
            presetsB64: dedicatedPresetsB64,
            updatedAt: dedicatedUpdatedAt,
          }));
        } catch {}
      }

      if (!data) {
        data = { config: [], collapsedPanels: {}, likedLists: [], updatedAt: Date.now() };
      }
      data.presets = dedicatedPresets;
      data.presetsB64 = dedicatedPresetsB64;
      data.presetsUpdatedAt = dedicatedUpdatedAt;
      // Channels & merged channels live in their own key -- merge them back in for signed-in sync across browsers.
      const channelsRaw = channelsRawInit;
      if (channelsRaw) {
        let channelsBlob = null;
        try {
          channelsBlob = JSON.parse(channelsRaw);
        } catch {
          channelsBlob = null;
        }
        if (channelsBlob) {
          if (!data) {
            data = { config: [], collapsedPanels: {}, likedLists: [], updatedAt: Date.now() };
          }
          data.channels = channelsBlob.channels || {};
          data.mergedChannels = channelsBlob.mergedChannels || {};
          data.channelsUpdatedAt = channelsBlob.updatedAt || 0;
        }
      }
      // Tracking data (Watch History/Continue Watching/etc) also lives in
      // its own key now -- see save-tracking's own comment above for why.
      // Same merge pattern as presets: the client's loadCreatorSync still
      // just reads data.watchHistory/data.continueWatching/etc exactly
      // like before, unaware this is a third KV read.
      const trackingRaw = trackingRawInit;
      if (trackingRaw) {
        let trackingBlob = null;
        try {
          trackingBlob = JSON.parse(trackingRaw);
        } catch {
          trackingBlob = null;
        }
        if (trackingBlob) {
          if (!data) {
            data = { config: [], collapsedPanels: {}, likedLists: [], updatedAt: Date.now() };
          }
          data.watchHistory = Array.isArray(trackingBlob.watchHistory) ? trackingBlob.watchHistory : [];
          data.continueWatching = Array.isArray(trackingBlob.continueWatching) ? trackingBlob.continueWatching : [];
          data.watchlist = Array.isArray(trackingBlob.watchlist) ? trackingBlob.watchlist : [];
          data.watchlistUpdatedAt = Number(trackingBlob.watchlistUpdatedAt) || 0;
          // Airing Next and the Discover recommendations were stored by
          // save-tracking but never handed back here, so loadCreatorSync's
          // own restore branches for them (22_client-creator-profile.js)
          // could never fire. A browser that signed in fresh therefore had
          // no copy of either, and its first autosave pushed empty arrays
          // straight back over the account's real ones -- see
          // save-tracking's derived-list guard above for the other half of
          // this fix.
          data.airingNext = Array.isArray(trackingBlob.airingNext) ? trackingBlob.airingNext : [];
          data.curatedRecommendations = (trackingBlob.curatedRecommendations && typeof trackingBlob.curatedRecommendations === "object")
            ? trackingBlob.curatedRecommendations
            : null;
          data.trackingUpdatedAt = trackingBlob.updatedAt || 0;
          data.fullyWatchedShowIds = Array.isArray(trackingBlob.fullyWatchedShowIds) ? trackingBlob.fullyWatchedShowIds : [];
          data.dismissedContinueWatching = trackingBlob.dismissedContinueWatching && typeof trackingBlob.dismissedContinueWatching === "object" ? trackingBlob.dismissedContinueWatching : {};
          data.trackPlayback = typeof trackingBlob.trackPlayback === "boolean" ? trackingBlob.trackPlayback : false;
          data.removeWatchedFromWatchlist = typeof trackingBlob.removeWatchedFromWatchlist === "boolean" ? trackingBlob.removeWatchedFromWatchlist : true;
          data.scrobbleFilterUsers = typeof trackingBlob.scrobbleFilterUsers === "boolean" ? trackingBlob.scrobbleFilterUsers : false;
          data.scrobbleAllowedUsers = typeof trackingBlob.scrobbleAllowedUsers === "string" ? trackingBlob.scrobbleAllowedUsers : "";
          data.scrobbleBlockAnonymous = typeof trackingBlob.scrobbleBlockAnonymous === "boolean" ? trackingBlob.scrobbleBlockAnonymous : false;
        }
      }
      // Merge dedicated scrobble-queue key into watchHistory so that recent
      // scrobbles are always visible even if the large tracking blob hasn't
      // propagated across Cloudflare edges yet (KV eventual consistency).
      try {
        const sqRaw = await env.CONFIGS.get(`creatorscrobblequeue:${auth.username}`);
        if (sqRaw) {
          const sq = JSON.parse(sqRaw);
          let queueWh = [];
          let queueCw = [];
          if (Array.isArray(sq)) {
            queueWh = sq;
          } else if (sq && typeof sq === "object") {
            queueWh = Array.isArray(sq.watchHistory) ? sq.watchHistory : [];
            queueCw = Array.isArray(sq.continueWatching) ? sq.continueWatching : [];
          }
          if (queueWh.length || queueCw.length) {
            if (!data) data = { config: [], collapsedPanels: {}, likedLists: [], updatedAt: Date.now() };
            if (queueWh.length) {
              const existingWhIds = new Set((Array.isArray(data.watchHistory) ? data.watchHistory : []).map((it) => String(it && it.id)));
              const queueWhOnly = queueWh.filter((it) => it && it.id && !existingWhIds.has(String(it.id)));
              if (queueWhOnly.length) {
                queueWhOnly.sort((a, b) => (b.watchedAt || 0) - (a.watchedAt || 0));
                data.watchHistory = [...queueWhOnly, ...(Array.isArray(data.watchHistory) ? data.watchHistory : [])];
              }
            }
            if (queueCw.length) {
              const mergedCw = [];
              const handledShows = new Set();
              for (const qItem of queueCw) {
                if (qItem && (qItem.showId || qItem.id)) {
                  mergedCw.push(qItem);
                  handledShows.add(String(qItem.showId || qItem.id));
                }
              }
              for (const dItem of (Array.isArray(data.continueWatching) ? data.continueWatching : [])) {
                if (dItem && (dItem.showId || dItem.id)) {
                  const dKey = String(dItem.showId || dItem.id);
                  if (!handledShows.has(dKey)) {
                    mergedCw.push(dItem);
                    handledShows.add(dKey);
                  }
                }
              }
              data.continueWatching = mergedCw;
            }
          }
        }
      } catch {}
      const orderRaw = orderRawInit;
      if (orderRaw) {
        try {
          const orderBlob = JSON.parse(orderRaw);
          if (Array.isArray(orderBlob.order)) {
            if (!data) data = { config: [], collapsedPanels: {}, likedLists: [], updatedAt: Date.now() };
            data.dashboardListOrder = orderBlob.order;
          }
        } catch {}
      }
      return json({ ok: true, data });
    }

    // /api/creator/sync/like  (POST)  { creatorName, creatorKey, usernameSlug, liked } -> { ok }
    // A narrower sibling of sync/save above, just for the likedLists piece
    // of the blob -- exists because the standalone public list page
    // (/lists/:username/:listname below) has its own tiny like button but
    // no access to the rest of a signed-in creator's state (their current
    // list config, presets, panel layout aren't loaded there, and
    // shouldn't need to be just to record a like). It reads the same
    // Creator Name/Key straight out of localStorage as the builder page
    // does, since both live on the same origin -- if this browser was
    // signed in on the builder, that list page can tell, without any
    // separate login of its own. Read-modify-write against whatever's
    // already saved (or a fresh blob if this account has never synced)
    // rather than requiring the caller to send the full state, unlike
    // sync/save.
    if (path === "/api/creator/sync/like" && request.method === "POST") {
      let body;
      try {
        body = await request.json();
      } catch {
        return json({ ok: false, error: "Invalid JSON body." }, 400);
      }
      const auth = await authenticateCreator(body.creatorName, body.creatorKey);
      if (!auth.ok) return json({ ok: false, error: auth.error === "no-kv" ? "no-kv" : "Username or Key is incorrect." }, auth.error === "no-kv" ? 500 : 401);
      const usernameSlug = String(body.usernameSlug || "").trim();
      if (!usernameSlug) return json({ ok: false, error: "Missing list reference." }, 400);
      const key = `creatorsync:${auth.username}`;
      const raw = await env.CONFIGS.get(key);
      let blob = { config: [], presets: {}, collapsedPanels: {}, likedLists: [], watchHistory: [], continueWatching: [], fullyWatchedShowIds: [], dismissedContinueWatching: {} };
      if (raw) {
        try {
          blob = JSON.parse(raw);
        } catch {
          blob = { config: [], presets: {}, collapsedPanels: {}, likedLists: [], watchHistory: [], continueWatching: [], fullyWatchedShowIds: [], dismissedContinueWatching: {} };
        }
      }
      const set = new Set(Array.isArray(blob.likedLists) ? blob.likedLists : []);
      if (body.liked) set.add(usernameSlug);
      else set.delete(usernameSlug);
      blob.likedLists = [...set];
      blob.updatedAt = Date.now();
      await env.CONFIGS.put(key, JSON.stringify(blob));
      return json({ ok: true });
    }

    // /api/creator/sync/share-tracking  (POST)
    //   { creatorName, creatorKey, slug, shared } -> { ok, shared: {...} }
    //   { creatorName, creatorKey } (no slug)     -> { ok, shared: {...} }  (read current state)
    //
    // Owner-controlled opt-in for exposing Watchlist / Watch History /
    // Continue Watching at the public /lists/:username/:slug address.
    // Those three come out of the private `creatorsynctracking:` blob,
    // so they are NOT public by default and there is no way to make them
    // public except by an authenticated call here (see the gate in the
    // /lists/:username/:listname handler). Stored as its own small key
    // rather than inside the tracking blob itself, so that the frequent,
    // high-churn tracking writes (playback pings, scrobbles, the cron)
    // can never accidentally clobber a privacy setting in a
    // read-modify-write race.
    if (path === "/api/creator/sync/share-tracking" && request.method === "POST") {
      if (!env || !env.CONFIGS) return json({ ok: false, error: "no-kv" }, 500);
      let body;
      try {
        body = await request.json();
      } catch {
        return json({ ok: false, error: "Invalid JSON body." }, 400);
      }
      const auth = await authenticateCreator(body.creatorName, body.creatorKey);
      if (!auth.ok) return json({ ok: false, error: auth.error === "no-kv" ? "no-kv" : "Username or Key is incorrect." }, 401);

      const shareKey = `creatorshare:${auth.username}`;
      let shared = {};
      try {
        const raw = await env.CONFIGS.get(shareKey);
        if (raw) shared = JSON.parse(raw) || {};
      } catch {
        shared = {};
      }

      // No slug -> read-only query of the current settings.
      const slug = String(body.slug || "").trim().toLowerCase();
      if (!slug) {
        return json({
          ok: true,
          shared: {
            "watchlist": shared["watchlist"] === true,
            "watch-history": shared["watch-history"] === true,
            "continue-watching": shared["continue-watching"] === true,
          },
        }, 200, { "Cache-Control": "no-store" });
      }

      const ALLOWED_SHARE_SLUGS = new Set(["watchlist", "watch-history", "continue-watching"]);
      if (!ALLOWED_SHARE_SLUGS.has(slug)) {
        return json({ ok: false, error: "That list cannot be shared this way." }, 400);
      }

      // Coerced to a real boolean -- the read side checks === true, so
      // anything else stored here would silently mean "not shared".
      shared[slug] = body.shared === true;
      await env.CONFIGS.put(shareKey, JSON.stringify(shared));

      return json({
        ok: true,
        shared: {
          "watchlist": shared["watchlist"] === true,
          "watch-history": shared["watch-history"] === true,
          "continue-watching": shared["continue-watching"] === true,
        },
      }, 200, { "Cache-Control": "no-store" });
    }

    // /api/search-published-lists?q=...
    // -> powers the "Search Lists" panel including this Worker's own
    // published Custom Lists -- both anonymously published ones (see
    // /api/publish-list) and public Creator-owned ones (see
    // /api/creator/lists/save) -- alongside the existing mdblist.com/Trakt
    // results. Private Creator lists are filtered out entirely here, per
    // the spec ("Not appear in search or browse pages"). KV's list() only
    // returns keys, not values, so this fetches each candidate's stored
    // data to filter/display by name -- capped at 50 keys per prefix per
    // search to keep this fast even once a lot of lists have been
    // published.
    if (path === "/api/search-published-lists") {
      if (!env || !env.CONFIGS) return json({ ok: true, lists: [] });
      const rawQ = url.searchParams.get("q") || "";
      const q = rawQ.toLowerCase().trim();

      // Check if query is targeting My Lists platform lists and extract any username/term
      const isMyListsSentinel = (q === "my lists" || q === "mylists" || q === "my list" || q === "mylist" || q.includes("my list") || q.includes("mylist"));
      const userTerm = q
        .replace(/\bmy\s+lists\b/gi, "")
        .replace(/\bmylists\b/gi, "")
        .replace(/\bmy\s+list\b/gi, "")
        .replace(/\bmylist\b/gi, "")
        .replace(/@+/g, "")
        .trim();

      const isMyListsSearch = isMyListsSentinel || !userTerm;

      try {
        // Same index as /lists/public.json: searching used to scan at most
        // 80-250 keys, so lists outside that lexicographic window were
        // unfindable no matter what the user typed. The index also carries
        // the display fields, which removes the per-list getCreator lookup
        // that made this route's subrequest count scale with result size.
        const searchIndex = await getPublicListIndex(env, ctx);
        if (searchIndex) {
          const targetFilterIdx = (userTerm || (isMyListsSentinel ? "" : q)).replace(/@+/g, "").trim();
          const tokensIdx = targetFilterIdx.split(/\s+/).filter(Boolean);
          const matchesIdx = searchIndex
            .filter((e) => (e.itemCount || 0) > 0)
            .filter((e) => {
              if (!targetFilterIdx || !tokensIdx.length) return true;
              const fullText = `${e.name || ""} ${e.creatorName || ""} ${e.username || ""}`.toLowerCase();
              if (fullText.includes(targetFilterIdx)) return true;
              return tokensIdx.every((tok) => fullText.includes(tok));
            })
            .map((e) => ({
              name: e.name,
              type: e.type,
              items: e.itemCount || 0,
              likes: e.likes || 0,
              creatorName: e.isCreator ? (e.creatorName || e.username) : "Anonymous",
              username: e.isCreator ? e.username : "user",
              url: `${url.origin}/lists/${e.isCreator ? e.username : "user"}/${e.slug}`,
              source: "My Lists Addon",
            }))
            .sort((a, b) => {
              const likesDiff = (b.likes || 0) - (a.likes || 0);
              if (likesDiff !== 0) return likesDiff;
              return (b.items || 0) - (a.items || 0);
            });
          // Response shape is identical to the scan path below: key is
          // `lists`, entries carry `source`, and only the non-"my lists"
          // search is capped at 50.
          return json({ ok: true, lists: isMyListsSearch ? matchesIdx : matchesIdx.slice(0, 50) });
        }

        const fetchLimit = isMyListsSearch ? 250 : 80;
        const [anonResult, creatorResult] = await Promise.all([
          env.CONFIGS.list({ prefix: "publishedlist:user:", limit: fetchLimit }),
          env.CONFIGS.list({ prefix: "creatorlist:", limit: fetchLimit }),
        ]);
        const anonCandidates = await Promise.all(
          anonResult.keys.map(async (k) => {
            const raw = await env.CONFIGS.get(k.name);
            if (!raw) return null;
            try {
              const data = JSON.parse(raw);
              await stampListVisibilityIfNeeded(env, k.name, data);
              if (!isPublicListVisibility(data.visibility)) return null;
              const listSlug = k.name.slice("publishedlist:user:".length);
              const itemCount = (data.items || []).length;
              if (itemCount === 0) return null; // Never display lists with 0 items
              return {
                name: data.name,
                type: data.type,
                items: itemCount,
                likes: data.likes || 0,
                creatorName: "Anonymous",
                username: "user",
                url: `${url.origin}/lists/user/${listSlug}`,
              };
            } catch {
              return null;
            }
          })
        );
        const creatorCandidates = await Promise.all(
          creatorResult.keys.map(async (k) => {
            const raw = await env.CONFIGS.get(k.name);
            if (!raw) return null;
            try {
              const data = JSON.parse(raw);
              await stampListVisibilityIfNeeded(env, k.name, data);
              if (!isPublicListVisibility(data.visibility)) return null;
              const itemCount = (data.items || []).length;
              if (itemCount === 0) return null; // Never display lists with 0 items
              // key shape is creatorlist:{username}:{slug}
              const rest = k.name.slice("creatorlist:".length);
              const sep = rest.indexOf(":");
              if (sep === -1) return null;
              const username = rest.slice(0, sep);
              const listSlug = rest.slice(sep + 1);
              let creatorName = username;
              try {
                const profileRaw = await getCreator(env, username);
                if (profileRaw) creatorName = JSON.parse(profileRaw).displayName || username;
              } catch {
                // fall back to the raw username slug
              }
              return {
                name: data.name,
                type: data.type,
                items: itemCount,
                likes: data.likes || 0,
                creatorName,
                username,
                url: `${url.origin}/lists/${username}/${listSlug}`,
              };
            } catch {
              return null;
            }
          })
        );
        const targetFilter = (userTerm || (isMyListsSentinel ? "" : q)).replace(/@+/g, "").trim();
        const tokens = targetFilter.split(/\s+/).filter(Boolean);
        const matches = [...anonCandidates, ...creatorCandidates]
          .filter(Boolean)
          .filter((l) => (l.items || 0) > 0)
          .filter((l) => {
            if (!targetFilter || !tokens.length) return true;
            const fullText = `${l.name || ""} ${l.creatorName || ""} ${l.username || ""} ${l.url || ""}`.toLowerCase();
            if (fullText.includes(targetFilter)) return true;
            return tokens.every((tok) => fullText.includes(tok));
          })
          .map((l) => ({ ...l, source: "My Lists Addon" }))
          .sort((a, b) => {
            const likesDiff = (b.likes || 0) - (a.likes || 0);
            if (likesDiff !== 0) return likesDiff;
            return (b.items || 0) - (a.items || 0);
          });
        return json({ ok: true, lists: isMyListsSearch ? matches : matches.slice(0, 50) });
      } catch (err) {
        return json({ ok: false, error: safeErrorMessage(err) });
      }
    }

    // /lists/:username/:listname[.json]  (GET)
    // -> the public, shareable page/feed for a Custom List -- either
    // published anonymously (/api/publish-list, always under the literal
    // "user" namespace) or owned by a Creator Profile (/api/creator/lists/
    // save, under that creator's own username). A browser gets a small
    // landing page; the .json variant (or anything that isn't a browser
    // navigation -- see isBrowserNavigation) gets the raw list data.
    // Either way this reads straight from KV; it never round-trips through
    // fetchCatalog itself (that's only for *other* configs pointing at
    // Clean external list paths: /lists/mdblist/:user/:slug, /lists/trakt/:user/:slug, /lists/tmdb/:id
    m = path.match(/^\/lists\/mdblist\/([^/]+)\/([^/]+)(?:\.json)?$/i);
    if (m) {
      const mdblistUser = m[1];
      const mdblistSlug = m[2];
      const targetUrl = `https://mdblist.com/lists/${mdblistUser}/${mdblistSlug}`;
      ctx.waitUntil(bumpStat(env, "pageviews"));
      // Validator-based caching instead of no-store -- see
      // htmlPageResponse (02_http-and-creator-utils.js). These shared list
      // pages are the ones people follow links to and press back from, and
      // each was resending ~1.6MB every time with nothing for the browser to
      // revalidate against. The ETag hashes the exact bytes returned, so a
      // 304 can only happen when the browser already holds this list.
      return await htmlPageResponse(
        request,
        renderBuilder(url.origin, {
          deepLinkList: {
            name: deslugifyServer(mdblistSlug),
            type: "movie",
            url: targetUrl,
            creatorName: mdblistUser,
            maybeMore: true,
          },
        }),
        { ...corsHeaders() }
      );
    }

    m = path.match(/^\/lists\/trakt\/([^/]+)\/([^/]+)(?:\.json)?$/i);
    if (m) {
      const traktUser = m[1];
      const traktSlug = m[2];
      const targetUrl = `https://trakt.tv/users/${traktUser}/lists/${traktSlug}`;
      ctx.waitUntil(bumpStat(env, "pageviews"));
      // Validator-based caching instead of no-store -- see
      // htmlPageResponse (02_http-and-creator-utils.js). These shared list
      // pages are the ones people follow links to and press back from, and
      // each was resending ~1.6MB every time with nothing for the browser to
      // revalidate against. The ETag hashes the exact bytes returned, so a
      // 304 can only happen when the browser already holds this list.
      return await htmlPageResponse(
        request,
        renderBuilder(url.origin, {
          deepLinkList: {
            name: deslugifyServer(traktSlug),
            type: "movie",
            url: targetUrl,
            creatorName: traktUser,
            maybeMore: true,
          },
        }),
        { ...corsHeaders() }
      );
    }

    m = path.match(/^\/lists\/tmdb\/collection\/([0-9]+)(?:-([a-z0-9_-]+))?(?:\.json)?$/i);
    if (m) {
      const tmdbId = m[1];
      const targetUrl = `https://www.themoviedb.org/collection/${tmdbId}`;
      const name = m[2] ? deslugifyServer(m[2]) : `TMDB Collection ${tmdbId}`;
      ctx.waitUntil(bumpStat(env, "pageviews"));
      // Validator-based caching instead of no-store -- see
      // htmlPageResponse (02_http-and-creator-utils.js). These shared list
      // pages are the ones people follow links to and press back from, and
      // each was resending ~1.6MB every time with nothing for the browser to
      // revalidate against. The ETag hashes the exact bytes returned, so a
      // 304 can only happen when the browser already holds this list.
      return await htmlPageResponse(
        request,
        renderBuilder(url.origin, {
          deepLinkList: {
            name,
            type: "movie",
            url: targetUrl,
            creatorName: "TMDB",
            maybeMore: true,
          },
        }),
        { ...corsHeaders() }
      );
    }

    m = path.match(/^\/lists\/tmdb\/([0-9]+)(?:-([a-z0-9_-]+))?(?:\.json)?$/i);
    if (m) {
      const tmdbId = m[1];
      const targetUrl = `https://www.themoviedb.org/list/${tmdbId}`;
      const name = m[2] ? deslugifyServer(m[2]) : `TMDB List ${tmdbId}`;
      ctx.waitUntil(bumpStat(env, "pageviews"));
      // Validator-based caching instead of no-store -- see
      // htmlPageResponse (02_http-and-creator-utils.js). These shared list
      // pages are the ones people follow links to and press back from, and
      // each was resending ~1.6MB every time with nothing for the browser to
      // revalidate against. The ETag hashes the exact bytes returned, so a
      // 304 can only happen when the browser already holds this list.
      return await htmlPageResponse(
        request,
        renderBuilder(url.origin, {
          deepLinkList: {
            name,
            type: "movie",
            url: targetUrl,
            creatorName: "TMDB",
            maybeMore: true,
          },
        }),
        { ...corsHeaders() }
      );
    }

    m = path.match(/^\/lists\/([^/]+)\/([^/]+?)(?:\.json)?$/i);
    if (m) {
      let rawUser = m[1];
      let rawList = m[2];
      let decodedUser = rawUser;
      let decodedList = rawList;
      try {
        decodedUser = decodeURIComponent(rawUser);
        decodedList = decodeURIComponent(rawList);
      } catch {}
      const username = decodedUser.toLowerCase();
      const listName = decodedList.toLowerCase();
      if (!env || !env.CONFIGS) {
        return json({ ok: false, error: "This Worker has no CONFIGS KV namespace bound, so nothing is published here." }, 404);
      }
      let listData = null;
      let isCreatorList = false;
      const keysToTry = [
        `creatorlist:${username}:${listName}`,
        `creatorlist:${rawUser}:${rawList}`,
        `publishedlist:${username}:${listName}`,
        `publishedlist:${rawUser}:${rawList}`,
      ];
      for (const k of keysToTry) {
        if (listData) break;
        const raw = await env.CONFIGS.get(k);
        if (raw) {
          try {
            const parsed = JSON.parse(raw);
            if (parsed) {
              await stampListVisibilityIfNeeded(env, k, parsed);
              if (isPublicListVisibility(parsed.visibility)) {
                listData = parsed;
                isCreatorList = k.startsWith("creatorlist:");
              }
            }
          } catch {}
        }
      }
      // Watchlist / Watch History / Continue Watching are NOT ordinary
      // published lists -- they live in `creatorsynctracking:{username}`,
      // which is the account's PRIVATE sync blob, written only by the
      // authenticated /api/creator/sync/save-tracking. This route has no
      // authentication at all (it's the public share-a-list page), so
      // reading that blob here used to hand any anonymous caller the
      // complete viewing history of any account whose username they knew
      // -- and usernames are published by /lists/public.json for every
      // shared list, so they didn't even need guessing.
      //
      // The blob has no `visibility` field to check (it isn't a list), so
      // there is nothing here that could have failed closed on its own.
      // Sharing is now strictly opt-in per slug, recorded in
      // `creatorshare:{username}` by the owner via
      // /api/creator/sync/share-tracking. Absent key, unparseable key, or
      // a slug not explicitly set to boolean true => not shared, and this
      // block does nothing at all (the request then 404s below exactly as
      // it does for any other unknown list).
      if (listName === "watchlist" || listName === "watch-history" || listName === "continue-watching") {
        let sharedSlugs = {};
        try {
          const shareRaw = await env.CONFIGS.get(`creatorshare:${username}`);
          if (shareRaw) sharedSlugs = JSON.parse(shareRaw) || {};
        } catch {
          sharedSlugs = {};
        }
        // Strict === true: a truthy string/number from a hand-edited or
        // legacy value must not be enough to expose someone's history.
        if (sharedSlugs[listName] === true) {
          const trackingRaw = await env.CONFIGS.get(`creatorsynctracking:${username}`);
          if (trackingRaw) {
            try {
              const tracking = JSON.parse(trackingRaw);
              const items = tracking[listName === "watch-history" ? "watchHistory" : (listName === "continue-watching" ? "continueWatching" : "watchlist")] || [];
              if (Array.isArray(items)) {
                if (!listData && items.length > 0) {
                  listData = {
                    name: listName === "watch-history" ? "Watch History" : (listName === "continue-watching" ? "Continue Watching" : "Watchlist"),
                    slug: listName,
                    type: "mixed",
                    visibility: "public",
                    items: items,
                    updatedAt: tracking.updatedAt || Date.now()
                  };
                  isCreatorList = true;
                } else if (listData && Array.isArray(items) && items.length > 0 && (!listData.items || listData.items.length === 0)) {
                  // A genuine published Custom List that happens to be
                  // named "Watchlist" and is currently empty gets its
                  // items filled in from tracking. Also gated -- this
                  // path copies the same private data into a public
                  // response, so it cannot be allowed without opt-in
                  // either.
                  listData.items = items;
                }
              }
            } catch {}
          }
        }
      }
      if (!listData) {
        return json({ ok: false, error: "No list found at that address." }, 404);
      }
      let creatorDisplayName = "Anonymous";
      if (isCreatorList) {
        creatorDisplayName = username;
        try {
          const profileRaw = await getCreator(env, username);
          if (profileRaw) creatorDisplayName = JSON.parse(profileRaw).displayName || username;
        } catch {
          // fall back to the raw username slug
        }
      }
      const likes = listData.likes || 0;
      const wantsJson = path.endsWith(".json") || (request.headers.get("Accept") || "").includes("application/json") || !isBrowserNavigation(request);
      if (wantsJson) {
        const cleanItems = (listData.items || []).map((it) => {
          const itId = it.imdbId || (String(it.id || '').startsWith('tt') ? it.id : (it.id ? ('tt' + it.id) : ''));
          let poster = it.poster || it.showPoster || "";
          if (!poster && itId && itId.startsWith("tt")) {
            poster = `https://images.metahub.space/poster/medium/${itId}/img`;
          }
          const itemTitle = it.name || it.title || '';
          const itemType = it.type || (it.showId ? 'series' : (listData.type === 'mixed' ? 'movie' : (listData.type || 'movie')));
          return {
            id: itId || it.id,
            imdb_id: it.imdbId || (String(it.id || '').startsWith('tt') ? it.id : null),
            imdbId: it.imdbId || (String(it.id || '').startsWith('tt') ? it.id : null),
            tmdb_id: it.tmdbId || it.tmdb_id || null,
            tmdbId: it.tmdbId || it.tmdb_id || null,
            title: itemTitle,
            name: itemTitle,
            year: it.year || null,
            type: itemType,
            poster: poster || null,
            overview: it.overview || null,
            genres: it.genres || null,
            rating: it.rating || null
          };
        });

        // If client specifically requests format=object or format=meta
        if (url.searchParams.get("format") === "object" || url.searchParams.get("meta") === "1") {
          return json({
            ok: true,
            name: listData.name,
            slug: listName,
            creator: creatorDisplayName,
            type: listData.type,
            visibility: "public",
            itemCount: cleanItems.length,
            likes: likes,
            updatedAt: listData.updatedAt || listData.createdAt || null,
            url: `${url.origin}/lists/${username}/${listName}`,
            jsonUrl: `${url.origin}/lists/${username}/${listName}.json`,
            items: cleanItems
          }, 200, { "Cache-Control": "public, max-age=300", ...corsHeaders() });
        }

        // Standard JSON Array for Cinephage, Kometa, Jellyfin, and external list scrapers
        return json(cleanItems, 200, { "Cache-Control": "public, max-age=300", ...corsHeaders() });
      }
      ctx.waitUntil(bumpStat(env, "pageviews"));
      const shareUrl = `${url.origin}/lists/${username}/${listName}`;
      // Validator-based caching instead of no-store -- see
      // htmlPageResponse (02_http-and-creator-utils.js). These shared list
      // pages are the ones people follow links to and press back from, and
      // each was resending ~1.6MB every time with nothing for the browser to
      // revalidate against. The ETag hashes the exact bytes returned, so a
      // 304 can only happen when the browser already holds this list.
      return await htmlPageResponse(
        request,
        renderBuilder(url.origin, {
          deepLinkList: {
            name: listData.name,
            type: listData.type,
            url: shareUrl,
            creatorName: creatorDisplayName,
            likes: likes,
            sample: (listData.items || []).map((it) => {
              const itId = it.imdbId || (String(it.id || '').startsWith('tt') ? it.id : (it.id ? `tt${it.id}` : ''));
              let poster = it.poster || it.showPoster || "";
              if (!poster && itId && itId.startsWith("tt")) {
                poster = `https://images.metahub.space/poster/medium/${itId}/img`;
              }
              return {
                id: itId || (it.tmdb_id ? String(it.tmdb_id) : String(it.id || "")),
                name: it.title || it.name || "Item",
                poster: poster,
                year: it.year || it.releaseInfo || "",
                type: it.type || listData.type || "movie",
              };
            }),
            maybeMore: false,
          },
        }),
        { ...corsHeaders() }
      );
    }

    // --- Admin dashboard (page views / install links generated) -----------
    //
    // Locked behind ADMIN_KEY, a secret set via `wrangler secret put
    // ADMIN_KEY` (or the Cloudflare dashboard) -- never lives in this file.
    // A correct key gets a signed, HttpOnly, Secure, SameSite=Strict cookie
    // scoped to /admin (see makeAdminCookieValue/isValidAdminCookie above),
    // not a bare ?key=... in the URL that would sit around in browser
    // history/logs.
    if (path === "/admin" && request.method === "GET") {

      const authed = await isAdminRequest(request, env);
      if (!authed) {
        return new Response(renderAdminLoginPage(), { headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store" } });
      }
      const html = await renderAdminDashboard(env);
      return new Response(html, { headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store" } });
    }

    // /admin/api/leaderboard?type=watched|list-add&window=today|7|30|90|alltime&mediaType=movie|series
    // -> { ok, entries } -- backs the Trending Data tab's dropdown, computed
    // on demand rather than eagerly for every window/type combo on every
    // page load (see computeLeaderboard's own comment on why this can fan
    // out to a meaningful number of KV reads). mediaType is optional --
    // omitted or anything else means both movies and shows together.
    if (path === "/admin/api/leaderboard" && request.method === "GET") {
      const authed = await isAdminRequest(request, env);
      if (!authed) return json({ ok: false, error: "Not authorized." }, 401);
      const eventType = url.searchParams.get("type") === "list-add" ? "list-add" : "watched";
      const allowedWindows = new Set(["today", "7", "30", "90", "alltime"]);
      const window = allowedWindows.has(url.searchParams.get("window")) ? url.searchParams.get("window") : "7";
      const mediaTypeParam = url.searchParams.get("mediaType");
      const mediaType = mediaTypeParam === "movie" || mediaTypeParam === "series" ? mediaTypeParam : null;
      const entries = await computeLeaderboard(env, eventType, window, mediaType);
      // no-store -- json()'s own default (max-age=3600) would otherwise
      // have the browser silently reuse an hour-old leaderboard on the
      // next tab switch/refresh instead of hitting the network again (see
      // /admin/api/feedback's own comment, which is where this was first
      // caught).
      return json({ ok: true, entries }, 200, { "Cache-Control": "no-store" });
    }

    // /admin/api/backfill-trending  (POST) -> { ok, done, accountsThisCall, titlesThisCall }
    // Seeds the All Time trending leaderboards (see backfillTitleCount's
    // own comment on why all-time-only) from data that already existed
    // before trending tracking shipped -- each creator account's Watch
    // History (aggregated to distinct shows/movies, dedupe-by-showId same
    // as the live tracking does) and their own Custom Lists' current
    // items. Processes exactly one account per call, capped to a handful
    // of titles from each source, to stay comfortably under Cloudflare's
    // per-request subrequest limit -- the admin dashboard's "Backfill
    // Existing Data" button calls this repeatedly until it reports
    // done:true, so this only needs to make forward progress each call,
    // not finish everything at once. Resumes via a cursor stored at
    // backfilltrending:cursor (same list()-cursor pattern
    // checkForNewEpisodes already uses for its own account sweep);
    // starting the sweep over from the top once every account has been
    // visited is intentional, so an account created after the last full
    // pass eventually gets covered too, and running this again later
    // picks up anyone whose history grew since the first pass -- entries
    // just accumulate (each backfill run adds its own snapshot on top of
    // whatever's already there, same as any other watch/list-add event
    // would), it doesn't overwrite.
    if (path === "/admin/api/backfill-trending" && request.method === "POST") {
      const authed = await isAdminRequest(request, env);
      if (!authed) return json({ ok: false, error: "Not authorized." }, 401);
      if (!env || !env.CONFIGS) return json({ ok: true, done: true, accountsThisCall: 0, titlesThisCall: 0 });

      const WATCHED_TITLE_CAP = 6;
      const LIST_ITEM_CAP = 6;

      const cursorRaw = await env.CONFIGS.get("backfilltrending:cursor");
      const listOpts = { prefix: "creator:", limit: 1 };
      if (cursorRaw) listOpts.cursor = cursorRaw;
      const listResult = await env.CONFIGS.list(listOpts);

      if (!listResult.keys.length) {
        // Reached the end of the account list (or there are no accounts
        // at all) -- reset to the top so a later run starts fresh rather
        // than permanently reporting "done" against a stale cursor.
        await env.CONFIGS.put("backfilltrending:cursor", "");
        return json({ ok: true, done: true, accountsThisCall: 0, titlesThisCall: 0 });
      }
      await env.CONFIGS.put("backfilltrending:cursor", listResult.list_complete ? "" : (listResult.cursor || ""));

      const username = listResult.keys[0].name.slice("creator:".length);
      let titlesThisCall = 0;

      // Watch History -> "watched", aggregated to distinct shows/movies
      // (episodes collapse to their show, same as live tracking).
      try {
        const trackingRaw = await env.CONFIGS.get(`creatorsynctracking:${username}`);
        if (trackingRaw) {
          const tracking = JSON.parse(trackingRaw);
          const watchHistory = Array.isArray(tracking.watchHistory) ? tracking.watchHistory : [];
          const counts = new Map(); // id -> { title, mediaType, count }
          watchHistory.forEach((it) => {
            const id = it.showId || it.id;
            if (!id) return;
            const title = it.showTitle || it.name || "";
            const mediaType = it.type === "movie" ? "movie" : "series";
            const existing = counts.get(id);
            if (existing) existing.count++;
            else counts.set(id, { title, mediaType, count: 1 });
          });
          const topTitles = [...counts.entries()].slice(0, WATCHED_TITLE_CAP);
          for (const [id, info] of topTitles) {
            const ok = await backfillTitleCount(env, "watched", id, info.title, info.mediaType, info.count);
            if (ok) titlesThisCall++;
          }
        }
      } catch (e) {
        // Skip this account's Watch History on any read/parse error --
        // still worth trying its Custom Lists below, and the account
        // will simply be revisited on a future full pass.
      }

      // Custom Lists -> "list-add", using each list's current items
      // (there's no historical "added at" timestamp to work from, only
      // present membership -- see this endpoint's own comment on why
      // that's fine for an all-time-only count). Lists directly, by this
      // account's own creatorlist: prefix, rather than going through
      // creatorlistorder:{username} (which tracks display order for
      // reordering specifically, not guaranteed to be a complete
      // inventory of every list the account has).
      try {
        const listsResult = await env.CONFIGS.list({ prefix: `creatorlist:${username}:`, limit: 20 });
        let itemsSeen = 0;
        for (const listKey of listsResult.keys) {
          if (itemsSeen >= LIST_ITEM_CAP) break;
          const listRaw = await env.CONFIGS.get(listKey.name);
          if (!listRaw) continue;
          const list = JSON.parse(listRaw);
          const items = Array.isArray(list.items) ? list.items : [];
          for (const it of items) {
            if (itemsSeen >= LIST_ITEM_CAP) break;
            const id = it.imdbId || it.id;
            if (!id) continue;
            const ok = await backfillTitleCount(env, "list-add", id, it.title || it.name || "", list.type === "series" ? "series" : "movie", 1);
            if (ok) titlesThisCall++;
            itemsSeen++;
          }
        }
      } catch (e) {
        // Skip this account's Custom Lists on any read/parse error.
      }

      return json({ ok: true, done: false, accountsThisCall: 1, titlesThisCall, username });
    }

    // /admin/api/migrate-d1 (POST) -> { ok, done, results, thisCall, scanned }
    // Backfills creators, creator_lists, published-list visibility stamps,
    // source_groups and the stats counters from KV to D1.
    //
    // ONE BOUNDED CHUNK PER CALL, not the whole sweep: a KV read plus a D1
    // write per key both count against Cloudflare's 1,000-subrequest limit,
    // and the previous single-pass version simply aborted partway through on
    // any site large enough to actually need migrating -- backfilling a
    // prefix of the data and reporting ok. See MIGRATE_D1_* (00_constants.js)
    // for why that particular half-finished state is dangerous rather than
    // merely incomplete.
    //
    // Keep calling until `done` is true; runMigrateD1 (03_admin.js) does that
    // loop. `results` is cumulative across the whole run, `thisCall` is just
    // this chunk. Still safe to run repeatedly from scratch: every write here
    // is idempotent.
    if (path === "/admin/api/migrate-d1" && request.method === "POST") {
      const authed = await isAdminRequest(request, env);
      if (!authed) return json({ ok: false, error: "Not authorized." }, 401);
      if (!env || !env.DB || !env.CONFIGS) return json({ ok: false, error: "No D1 or KV binding." }, 500);

      // Every KV read/write and every D1 statement goes through these, so the
      // budget reflects what was actually spent rather than a guess.
      let ops = 0;
      const spent = () => ops >= MIGRATE_D1_OPS_PER_RUN;
      const countedKv = {
        get: (...a) => { ops++; return env.CONFIGS.get(...a); },
        put: (...a) => { ops++; return env.CONFIGS.put(...a); },
        delete: (...a) => { ops++; return env.CONFIGS.delete(...a); },
        list: (...a) => { ops++; return env.CONFIGS.list(...a); },
      };
      // stampListVisibilityIfNeeded writes through env.CONFIGS itself.
      const countedEnv = { ...env, CONFIGS: countedKv };
      const d1Run = (stmt) => { ops++; return stmt.run(); };

      ops++;
      const stateRaw = await env.CONFIGS.get(MIGRATE_D1_STATE_KEY);
      let state = null;
      try {
        state = stateRaw ? JSON.parse(stateRaw) : null;
      } catch {
        state = null;
      }
      // Anything unparseable or from an older shape restarts the sweep rather
      // than resuming into the middle of it. Restarting is cheap here because
      // every write is idempotent.
      if (!state || state.v !== 1 || typeof state.phase !== "number" || !Array.isArray(state.pending) || !state.results) {
        state = {
          v: 1,
          phase: 0,
          cursor: "",
          pending: [],
          scanned: 0,
          results: { creators: 0, lists: 0, published: 0, sourcegroups: 0, stats: 0, errors: [] },
        };
      }
      const results = state.results;
      const thisCall = { creators: 0, lists: 0, published: 0, sourcegroups: 0, stats: 0 };
      const noteError = (msg) => {
        if (results.errors.length < MIGRATE_D1_ERROR_CAP) results.errors.push(msg);
      };

      async function migrateKey(phase, keyName) {
        // 0. Creators
        if (phase === 0) {
          const username = keyName.slice("creator:".length);
          const raw = await countedKv.get(keyName);
          if (!raw) return;
          try {
            const data = JSON.parse(raw);
            await d1Run(env.DB.prepare(
              "INSERT INTO creators (username, display_name, key_hash, recovery_answer_hash, created_at) VALUES (?, ?, ?, ?, ?) ON CONFLICT(username) DO NOTHING"
            ).bind(username, data.displayName || username, data.keyHash || "", data.recoveryAnswerHash || null, data.createdAt || 0));
            results.creators++; thisCall.creators++;
          } catch (e) {
            noteError(`Creator ${username}: ` + e.message);
          }
          return;
        }

        // 1. Creator Lists
        if (phase === 1) {
          // Two capture groups, so they are match[1] and match[2]. The old
          // `[, , u, slug]` skipped one element too many: slug came out
          // undefined, the `if (u && slug)` guard below rejected every key,
          // and the migration silently reported "lists: 0" while claiming ok.
          const [, u, slug] = keyName.match(/^creatorlist:([^:]+):(.+)$/) || [];
          if (!u || !slug) return;
          const raw = await countedKv.get(keyName);
          if (!raw) return;
          try {
            const data = JSON.parse(raw);
            await stampListVisibilityIfNeeded(countedEnv, keyName, data);
            const listId = `${u}:${slug}`;
            const itemsJson = JSON.stringify(data.items || []);
            const vis = isPublicListVisibility(data.visibility) ? "public" : "private";
            // `likes` is carried across too. KV holds the authoritative
            // count, so a migration that omitted it would silently reset
            // every list to zero in D1. Visibility is rewritten as well
            // so the fail-closed public index doesn't hide legacy lists
            // that were served as public because they had no enum value.
            await d1Run(env.DB.prepare(
              "INSERT INTO creator_lists (id, username, name, type, visibility, items_json, likes, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?) ON CONFLICT(id) DO UPDATE SET likes=excluded.likes, visibility=excluded.visibility"
            ).bind(listId, u, data.name || "List", data.type || "mixed", vis, itemsJson, Number(data.likes) || 0, data.createdAt || 0, data.updatedAt || 0));
            results.lists++; thisCall.lists++;
          } catch (e) {
            noteError(`List ${u}:${slug}: ` + e.message);
          }
          return;
        }

        // 2. Anonymous published lists live only in KV. Stamp missing /
        // garbage visibility the same way as creator lists so the inverted
        // public-read checks don't hide currently-served lists.
        if (phase === 2) {
          const raw = await countedKv.get(keyName);
          if (!raw) return;
          try {
            const data = JSON.parse(raw);
            await stampListVisibilityIfNeeded(countedEnv, keyName, data);
            results.published++; thisCall.published++;
          } catch (e) {
            noteError(`Published ${keyName}: ` + e.message);
          }
          return;
        }

        // 3. Source Groups
        if (phase === 3) {
          if (!keyName.endsWith(":total")) return;
          const groupName = keyName.slice("stats:sourcegroup:".length, -":total".length);
          const raw = await countedKv.get(keyName);
          const count = parseInt(raw || "0", 10);
          try {
            await d1Run(env.DB.prepare(
              "INSERT INTO source_groups (id, name, install_count) VALUES (?, ?, ?) ON CONFLICT(id) DO UPDATE SET install_count = excluded.install_count"
            ).bind(groupName, groupName, count));
            results.sourcegroups++; thisCall.sourcegroups++;
          } catch (e) {
            noteError(`Sourcegroup ${groupName}: ` + e.message);
          }
          return;
        }

        // 4. Counters (stats:{kind}:{total|YYYY-MM-DD} -> the stats table)
        //
        // Until these are copied across, each counter falls back to its KV
        // value rather than reporting zero (see readStatCount, 03_admin.js),
        // so a dashboard's history never visibly vanishes just because D1 got
        // bound. After this runs, D1 is authoritative and the KV copies are
        // inert.
        //
        // DO NOTHING on conflict, not "n = n + excluded.n": this endpoint is
        // safe to run more than once (the admin button can be pressed again,
        // and every other section is idempotent too), and an additive upsert
        // here would double every counter on the second run. sourcegroup: is
        // skipped -- phase 3 above already migrated it into its own table,
        // and copying it here too would count it twice in the Installed
        // Catalogs panel, which sums both.
        const rest = keyName.slice("stats:".length);
        const sep = rest.lastIndexOf(":");
        if (sep === -1) return;
        const kind = rest.slice(0, sep);
        const bucket = rest.slice(sep + 1);
        if (!kind || !bucket) return;
        if (kind.startsWith("sourcegroup:") || kind === "sourcegroup") return;
        // Only the numeric counters. stats:genres:alltime and
        // stats:decades:alltime are JSON blobs, and
        // stats:genredecade:migrated is a sentinel -- none of them belong
        // in an integer column.
        if (bucket !== "total" && !/^\d{4}-\d{2}-\d{2}$/.test(bucket)) return;
        const raw = await countedKv.get(keyName);
        const n = parseInt(raw, 10);
        if (!Number.isFinite(n)) return;
        try {
          await d1Run(env.DB.prepare(
            "INSERT INTO stats (kind, day, n) VALUES (?, ?, ?) ON CONFLICT(kind, day) DO NOTHING"
          ).bind(kind, bucket, n));
          results.stats++; thisCall.stats++;
        } catch (e) {
          noteError(`Stat ${keyName}: ` + e.message);
        }
      }

      let scannedThisCall = 0;
      while (state.phase < MIGRATE_D1_PREFIXES.length && !spent()) {
        if (!state.pending.length) {
          if (state.cursor === null) {
            state.phase++;
            state.cursor = "";
            continue;
          }
          const listOpts = { prefix: MIGRATE_D1_PREFIXES[state.phase], limit: MIGRATE_D1_PAGE };
          if (state.cursor) listOpts.cursor = state.cursor;
          const listRes = await countedKv.list(listOpts);
          state.pending = (listRes.keys || []).map((k) => k.name);
          state.cursor = (listRes.list_complete || !listRes.cursor) ? null : listRes.cursor;
          if (!state.pending.length) continue;
        }
        // shift() as we go, so whatever is left in `pending` when the budget
        // runs out is exactly what this run still owes.
        while (state.pending.length && !spent()) {
          const keyName = state.pending.shift();
          await migrateKey(state.phase, keyName);
          scannedThisCall++;
        }
      }

      state.scanned = (state.scanned || 0) + scannedThisCall;
      const done = state.phase >= MIGRATE_D1_PREFIXES.length;
      if (done) {
        try {
          await env.CONFIGS.delete(MIGRATE_D1_STATE_KEY);
        } catch {
          // A stranded state key only costs the next run a restart, and
          // every write in the sweep is idempotent.
        }
      } else {
        await env.CONFIGS.put(MIGRATE_D1_STATE_KEY, JSON.stringify(state));
      }

      return json({ ok: true, done, results, thisCall, scanned: state.scanned });
    }

    // /admin/api/rebuild-public-index  (POST) -> { ok, done, count, scanned, ms }
    // Drives a rebuild of index:publiclists (see getPublicListIndex/
    // rebuildPublicListIndex, 02_http-and-creator-utils.js) on demand
    // instead of waiting for it to happen lazily. Without this, a fresh
    // deployment -- or the index key being lost some other way -- serves
    // every visitor of /lists/public.json and list search a truncated,
    // lexicographically-biased result (capped at 150/250/80 keys) until
    // the build finishes. scheduled() below drives the same build
    // automatically whenever the index is found missing (self-healing
    // without any admin action), so this endpoint is for an immediate,
    // verifiable seed right after a fresh deploy rather than the only way
    // it happens.
    //
    // ONE CHUNK PER CALL, not a full rebuild: the scan is bounded by
    // Cloudflare's 1,000-subrequest limit and a large deployment needs
    // several passes. Keep calling until `done` is true -- exactly like
    // /admin/api/migrate-day-counts, and runRebuildPublicIndex (03_admin.js)
    // does that loop for you. A chunk here gets a bigger op budget than the
    // cron's, since this request has the invocation to itself. Safe to run
    // any time, repeatedly: progress is idempotent and the live index is
    // only replaced once the final chunk lands.
    if (path === "/admin/api/rebuild-public-index" && request.method === "POST") {
      const authed = await isAdminRequest(request, env);
      if (!authed) return json({ ok: false, error: "Not authorized." }, 401);
      if (!env || !env.CONFIGS) return json({ ok: false, error: "no-kv" });
      const started = Date.now();
      try {
        const res = await rebuildPublicListIndex(env, { opBudget: PUBLIC_INDEX_BUILD_OPS_ADMIN });
        return json({
          ok: true,
          done: !!res.done,
          count: res.entriesSoFar,
          scanned: res.scanned,
          ms: Date.now() - started,
        });
      } catch (e) {
        return json({ ok: false, error: "Rebuild failed: " + (e && e.message ? e.message : String(e)) }, 500);
      }
    }

    // /admin/api/migrate-day-counts  (POST) -> { ok, done, keysMigratedThisCall }
    // One-time migration for the switch (see recordTrackedEvent's own
    // comment) from one KV key per (eventType/query, id, day) to one JSON
    // blob per (eventType/query, id) holding every day's count. Old
    // per-day keys are still sitting in KV from before that switch --
    // this reads them, folds each into the corresponding new blob (merging
    // with whatever's already there from live tracking since the switch,
    // never overwriting), and deletes the old key once it's safely folded
    // in. Deleting as it goes is what makes this safe to run repeatedly:
    // a second run finds nothing left to migrate and reports done
    // immediately, the same idempotent shape backfill-trending above has.
    // Same paginated-cursor pattern as that endpoint too, for the same
    // reason -- covers three prefixes in sequence (evtcount:watched:,
    // evtcount:list-add:, searchquery:), storing which prefix and how far
    // into its key list this run has reached in migratedaycounts:state so
    // repeated calls make forward progress without redoing work.
    if (path === "/admin/api/migrate-day-counts" && request.method === "POST") {
      const authed = await isAdminRequest(request, env);
      if (!authed) return json({ ok: false, error: "Not authorized." }, 401);
      if (!env || !env.CONFIGS) return json({ ok: true, done: true, keysMigratedThisCall: 0 });

      const PREFIXES = ["evtcount:watched:", "evtcount:list-add:", "searchquery:"];
      const BATCH_LIMIT = 100;

      let state;
      try {
        const stateRaw = await env.CONFIGS.get("migratedaycounts:state");
        state = stateRaw ? JSON.parse(stateRaw) : { prefixIndex: 0, cursor: null };
      } catch {
        state = { prefixIndex: 0, cursor: null };
      }

      if (state.prefixIndex >= PREFIXES.length) {
        return json({ ok: true, done: true, keysMigratedThisCall: 0 });
      }

      const prefix = PREFIXES[state.prefixIndex];
      const listOpts = { prefix, limit: BATCH_LIMIT };
      if (state.cursor) listOpts.cursor = state.cursor;
      const listResult = await env.CONFIGS.list(listOpts);

      // Old per-day keys only -- the running total (:alltime) and the
      // new blob format itself (:days) share this same prefix and would
      // otherwise get misread as if "alltime" or "days" were date strings.
      const dayKeyPattern = /^\d{4}-\d{2}-\d{2}$/;
      const oldDayKeys = listResult.keys.filter((k) => {
        const rest = k.name.slice(prefix.length);
        const lastColon = rest.lastIndexOf(":");
        if (lastColon === -1) return false;
        return dayKeyPattern.test(rest.slice(lastColon + 1));
      });

      // Group by id first so a title/query with many old day-keys in this
      // batch costs one blob read-modify-write, not one per day.
      const byId = new Map(); // id -> { day: count, ... } (partial, this batch only)
      oldDayKeys.forEach((k) => {
        const rest = k.name.slice(prefix.length);
        const lastColon = rest.lastIndexOf(":");
        const id = rest.slice(0, lastColon);
        const day = rest.slice(lastColon + 1);
        if (!byId.has(id)) byId.set(id, {});
        byId.get(id)[day] = k.name; // stash the real key name for the read pass below
      });

      let keysMigratedThisCall = 0;
      await Promise.all(
        [...byId.entries()].map(async ([id, dayKeyNames]) => {
          const days = Object.keys(dayKeyNames);
          const [oldValues, existingBlobRaw] = await Promise.all([
            Promise.all(days.map((d) => env.CONFIGS.get(dayKeyNames[d]))),
            env.CONFIGS.get(`${prefix}${id}:days`),
          ]);
          let blob;
          try {
            blob = existingBlobRaw ? JSON.parse(existingBlobRaw) : {};
          } catch {
            blob = {};
          }
          days.forEach((d, i) => {
            const oldCount = parseInt(oldValues[i], 10) || 0;
            if (oldCount <= 0) return;
            // Additive, not overwrite -- if live tracking already wrote
            // something for this exact id+day since the format switch,
            // that count is just as real as the migrated one.
            blob[d] = (blob[d] || 0) + oldCount;
          });
          const dayKeysSorted = Object.keys(blob).sort();
          if (dayKeysSorted.length > 95) {
            dayKeysSorted.slice(0, dayKeysSorted.length - 95).forEach((k) => delete blob[k]);
          }
          await env.CONFIGS.put(`${prefix}${id}:days`, JSON.stringify(blob), { expirationTtl: TELEMETRY_DAY_TTL_SEC });
          await Promise.all(days.map((d) => env.CONFIGS.delete(dayKeyNames[d])));
          keysMigratedThisCall += days.length;
        })
      );

      const prefixDone = listResult.list_complete || !listResult.cursor;
      const nextState = prefixDone
        ? { prefixIndex: state.prefixIndex + 1, cursor: null }
        : { prefixIndex: state.prefixIndex, cursor: listResult.cursor };
      await env.CONFIGS.put("migratedaycounts:state", JSON.stringify(nextState));

      const done = nextState.prefixIndex >= PREFIXES.length;
      return json({ ok: true, done, keysMigratedThisCall, prefix, prefixDone });
    }

    // /admin/api/feedback -> { ok, entries } -- backs the Feedback tab,
    // newest first. Keys sort chronologically (see /api/feedback), so
    // list() is oldest-first: walk pages keeping a rolling tail, then
    // GET only the newest FEEDBACK_ADMIN_GET_CAP. Getting every thread
    // used to grow without bound (no TTL, no prune).
    if (path === "/admin/api/feedback" && request.method === "GET") {
      const authed = await isAdminRequest(request, env);
      if (!authed) return json({ ok: false, error: "Not authorized." }, 401);
      if (!env || !env.CONFIGS) return json({ ok: true, entries: [] }, 200, { "Cache-Control": "no-store" });
      let newestKeys = [];
      let cursor = undefined;
      let listComplete = false;
      let pages = 0;
      let sawMore = false;
      while (!listComplete && pages < 30) {
        const listResult = await env.CONFIGS.list({ prefix: "feedback:", limit: 1000, cursor });
        newestKeys.push(...(listResult.keys || []));
        if (newestKeys.length > FEEDBACK_ADMIN_GET_CAP) {
          newestKeys = newestKeys.slice(-FEEDBACK_ADMIN_GET_CAP);
          sawMore = true;
        }
        pages++;
        if (listResult.list_complete || !listResult.cursor) {
          listComplete = true;
        } else {
          cursor = listResult.cursor;
        }
      }
      const truncated = !listComplete || sawMore;
      const keys = newestKeys.slice().reverse();
      const entries = await Promise.all(
        keys.map(async (k) => {
          try {
            const raw = await env.CONFIGS.get(k.name);
            if (!raw) return null;
            const entry = JSON.parse(raw);
            if (!Array.isArray(entry.messages) || !entry.messages.length) {
              entry.messages = [{
                id: `msg_init`,
                sender: "user",
                senderName: entry.creatorName || "User",
                text: entry.message || "(Initial message)",
                timestamp: entry.createdAt || Date.now()
              }];
            }
            return entry;
          } catch {
            return null;
          }
        })
      );
      return json({ ok: true, entries: entries.filter(Boolean), truncated: !!truncated }, 200, { "Cache-Control": "no-store" });
    }

    // /admin/api/feedback/reply  (POST)  { id, message } -> { ok, entry }
    // Allows admin to send a threaded reply back to the user.
    if (path === "/admin/api/feedback/reply" && request.method === "POST") {
      const authed = await isAdminRequest(request, env);
      if (!authed) return json({ ok: false, error: "Not authorized." }, 401);
      if (!env || !env.CONFIGS) return json({ ok: false, error: "Feedback storage isn't configured on this deployment." });
      let body;
      try {
        body = await request.json();
      } catch {
        return json({ ok: false, error: "Invalid JSON body." }, 400);
      }
      const id = String(body.id || "").trim();
      const message = String(body.message || "").trim();
      if (!id) return json({ ok: false, error: "Missing thread id." }, 400);
      if (!message) return json({ ok: false, error: "Reply message can't be empty." }, 400);

      const key = `feedback:${id}`;
      const raw = await env.CONFIGS.get(key);
      if (!raw) return json({ ok: false, error: "Feedback thread not found." }, 404);
      let entry;
      try {
        entry = JSON.parse(raw);
      } catch {
        return json({ ok: false, error: "Could not parse feedback thread." }, 500);
      }

      if (!Array.isArray(entry.messages) || !entry.messages.length) {
        // sender here mirrors renderFeedbackList's own fallback logic
        // (isSelfLogged ? 'admin' : 'user') -- this used to be hardcoded
        // to "user" unconditionally, which meant a self-logged "Log
        // something yourself" entry's original message would flip to
        // showing as if a user had written it the moment it got its
        // first reply, instead of staying attributed to the admin.
        entry.messages = [{
          id: `msg_init`,
          sender: entry.creatorName === "admin" ? "admin" : "user",
          senderName: entry.creatorName === "admin" ? "Admin" : (entry.creatorName || "User"),
          text: entry.message || "(Initial message)",
          timestamp: entry.createdAt || Date.now()
        }];
      }

      const replyMsg = {
        id: `msg_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`,
        sender: "admin",
        senderName: "Developer",
        text: message,
        timestamp: Date.now()
      };
      entry.messages.push(replyMsg);
      entry.updatedAt = Date.now();
      entry.status = "replied";
      entry.completed = false;

      try {
        await putFeedbackThread(env, key, entry);
      } catch (e) {
        return json({ ok: false, error: "Could not save reply." }, 500);
      }
      return json({ ok: true, entry }, 200, { "Cache-Control": "no-store" });
    }

    // /admin/api/feedback/status  (POST)  { id, completed } -> { ok }
    // Toggles the "completed" flag on one feedback entry -- id here is the
    // entry's own id field (the part of the KV key after "feedback:"), not
    // the full key name, so the client never needs to know the storage
    // layout to mark something done.
    if (path === "/admin/api/feedback/status" && request.method === "POST") {
      const authed = await isAdminRequest(request, env);
      if (!authed) return json({ ok: false, error: "Not authorized." }, 401);
      if (!env || !env.CONFIGS) return json({ ok: false, error: "Feedback storage isn't configured on this deployment." });
      let body;
      try {
        body = await request.json();
      } catch {
        return json({ ok: false, error: "Invalid JSON body." }, 400);
      }
      const id = String(body.id || "").trim();
      if (!id) return json({ ok: false, error: "Missing id." }, 400);
      const key = `feedback:${id}`;
      const raw = await env.CONFIGS.get(key);
      if (!raw) return json({ ok: false, error: "That feedback entry no longer exists." }, 404);
      let entry;
      try {
        entry = JSON.parse(raw);
      } catch {
        return json({ ok: false, error: "Could not read that feedback entry." }, 500);
      }
      entry.completed = !!body.completed;
      try {
        await putFeedbackThread(env, key, entry);
      } catch (e) {
        return json({ ok: false, error: "Could not save that change. Please try again." }, 500);
      }
      return json({ ok: true }, 200, { "Cache-Control": "no-store" });
    }

    // /admin/api/feedback/edit  (POST)  { id, message, category } -> { ok, entry }
    // Allows the admin to edit the message or category of any feedback entry.
    if (path === "/admin/api/feedback/edit" && request.method === "POST") {
      const authed = await isAdminRequest(request, env);
      if (!authed) return json({ ok: false, error: "Not authorized." }, 401);
      if (!env || !env.CONFIGS) return json({ ok: false, error: "Feedback storage isn't configured on this deployment." });
      let body;
      try {
        body = await request.json();
      } catch {
        return json({ ok: false, error: "Invalid JSON body." }, 400);
      }
      const id = String(body.id || "").trim();
      if (!id) return json({ ok: false, error: "Missing id." }, 400);
      const key = `feedback:${id}`;
      const raw = await env.CONFIGS.get(key);
      if (!raw) return json({ ok: false, error: "That feedback entry no longer exists." }, 404);
      let entry;
      try {
        entry = JSON.parse(raw);
      } catch {
        return json({ ok: false, error: "Could not read that feedback entry." }, 500);
      }
      if (typeof body.message === "string" && body.message.trim()) {
        const trimmedMessage = body.message.trim().slice(0, 4000);
        entry.message = trimmedMessage;
        // Once a reply has landed on this entry (self-logged or not), the
        // dashboard list renders from entry.messages[...] instead of the
        // top-level entry.message that this edit form actually posts (see
        // renderFeedbackList's own fallback: it only synthesizes a single
        // message from entry.message when entry.messages is empty).
        // Editing only entry.message left it invisible on any entry that
        // already had a thread -- the save genuinely succeeded, nothing
        // in the list ever reflected it. Keeping the first message in the
        // thread (the original log/report) in sync fixes that regardless
        // of which shape a given entry happens to be in.
        if (Array.isArray(entry.messages) && entry.messages.length && entry.messages[0]) {
          entry.messages[0].text = trimmedMessage;
        }
      }
      if (typeof body.category === "string" && ["bug", "improvement", "idea", "other"].includes(body.category.trim())) {
        entry.category = body.category.trim();
      }
      entry.updatedAt = Date.now();
      try {
        await putFeedbackThread(env, key, entry);
        return json({ ok: true, entry }, 200, { "Cache-Control": "no-store" });
      } catch (e) {
        return json({ ok: false, error: "Could not save edits. Please try again." }, 500);
      }
    }

    // /admin/api/feedback/delete (POST) { id } -> { ok }
    // Allows the admin to permanently delete a feedback entry from KV storage.
    if (path === "/admin/api/feedback/delete" && request.method === "POST") {
      const authed = await isAdminRequest(request, env);
      if (!authed) return json({ ok: false, error: "Not authorized." }, 401);
      if (!env || !env.CONFIGS) return json({ ok: false, error: "Feedback storage isn't configured on this deployment." });
      let body;
      try {
        body = await request.json();
      } catch {
        return json({ ok: false, error: "Invalid JSON body." }, 400);
      }
      const id = String(body.id || "").trim();
      if (!id) return json({ ok: false, error: "Missing id." }, 400);
      const key = `feedback:${id}`;
      try {
        await env.CONFIGS.delete(key);
        return json({ ok: true }, 200, { "Cache-Control": "no-store" });
      } catch (e) {
        return json({ ok: false, error: "Could not delete feedback entry. Please try again." }, 500);
      }
    }

    // /admin/api/analytics?section=search|catalogs_lists|audience&window=...
    // Backs the Search, Catalogs & Lists, and Playback & Audience tabs in the admin dashboard.
    if (path === "/admin/api/analytics" && request.method === "GET") {
      const authed = await isAdminRequest(request, env);
      if (!authed) return json({ ok: false, error: "Not authorized." }, 401);
      const section = url.searchParams.get("section") || "search";
      if (section === "search") {
        const windowParam = url.searchParams.get("window") || "7";
        const searches = await computeSearchLeaderboard(env, windowParam);
        return json({ ok: true, searches }, 200, { "Cache-Control": "no-store" });
      }
      if (section === "catalogs_lists") {
        const data = await computeCatalogAndCommunityLeaderboards(env, ctx);
        return json({ ok: true, ...data }, 200, { "Cache-Control": "no-store" });
      }
      if (section === "audience") {
        const data = await computeAudienceAnalytics(env);
        return json({ ok: true, ...data }, 200, { "Cache-Control": "no-store" });
      }
      return json({ ok: false, error: "Invalid section." }, 400);
    }

    // /admin/api/apiusage -> { ok, keys: [{ name, label, configured, last24h,
    // last7d, last30d, limit }] } -- backs the API Usage tab. Only counts
    // requests that used one of this Worker's own shared keys (the
    // fallback used when a visitor hasn't supplied a personal one, see
    // trackSharedApiUse in 05_catalog-core.js and its call sites) -- a
    // visitor's own key is never counted here since only they can exhaust
    // its rate limit. Day-bucketed the same way as every other stat in
    // this file (see bumpStat/loadStatsByDay), so "last 24h" really means
    // "today's Eastern-calendar-day bucket", same as the Trending tab's
    // "Today" window.
    if (path === "/admin/api/apiusage" && request.method === "GET") {
      const authed = await isAdminRequest(request, env);
      if (!authed) return json({ ok: false, error: "Not authorized." }, 401);
      const defs = [
        { name: "tmdb", label: "TMDB (TMDB_API_KEY)", envVar: "TMDB_API_KEY", limit: "~40 req/sec per IP -- no published daily cap" },
        { name: "trakt", label: "Trakt (TRAKT_CLIENT_ID)", envVar: "TRAKT_CLIENT_ID", limit: "1,000 GET calls / 5 min" },
        { name: "simkl", label: "Simkl (SIMKL_CLIENT_ID)", envVar: "SIMKL_CLIENT_ID", limit: "10 req/sec (GET)" },
        { name: "mdblist", label: "MDBList (MDBLIST_API_KEY)", envVar: "MDBLIST_API_KEY", limit: "1,000/day (free tier -- higher on paid plans)" },
        { name: "mdblistpopular", label: "MDBList Popular Lists (MDBLIST_POPULAR_KEY)", envVar: "MDBLIST_POPULAR_KEY", limit: "1,000/day (free tier -- higher on paid plans)" },
      ];
      const nowMs = Date.now();
      const keys = await Promise.all(defs.map(async (d) => {
        const byDay = await loadStatsByDay(env, `apiuse:${d.name}`);
        let last24h = 0, last7d = 0, last30d = 0;
        for (let i = 0; i < 30; i++) {
          const count = byDay[easternDateKey(new Date(nowMs - i * 86400000))] || 0;
          if (i < 1) last24h += count;
          if (i < 7) last7d += count;
          last30d += count;
        }
        return { name: d.name, label: d.label, configured: !!(env && env[d.envVar]), last24h, last7d, last30d, limit: d.limit };
      }));
      // no-store -- see /admin/api/feedback's own comment on why every
      // admin JSON endpoint needs this (json()'s default lets the browser
      // silently reuse an hour-old response instead of refetching).
      return json({ ok: true, keys }, 200, { "Cache-Control": "no-store" });
    }

    // /admin/api/netflix-preview?region=US&providerId=8 -> { ok, region,
    // providerId, movies: { total, items }, shows: { total, items } } --
    // lets the admin see roughly how big a TMDB-discover-based shelf for
    // ANY watch provider would be, and what it'd actually contain, before
    // wiring a tmdb:chart:X entry into Quick Add for real. providerId
    // defaults to 8 (Netflix) but accepts any TMDB provider id -- pair
    // this with /admin/api/provider-lookup below to find the right id for
    // a given service by name first, since TMDB is known to have more
    // than one entry for some providers (e.g. two separate "Disney Plus"
    // ids) and guessing wrong fails silently -- it just quietly shows the
    // wrong catalog under the right label. Deliberately NOT the same code
    // path as a real catalog fetch (fetchTmdbChart/fetchTmdbPagedResults)
    // -- this only needs TMDB's own title/poster/total_results for a
    // quick look, not a resolved IMDb id per item (that's a separate TMDB
    // call per title, and this is meant to be a cheap one-shot preview,
    // not something that has to walk the whole list).
    async function fetchNetflixPreviewTmdb(kind, region, apiKey, providerId) {
      const src = `https://api.themoviedb.org/3/discover/${kind}?api_key=${encodeURIComponent(apiKey)}` +
        `&with_watch_providers=${encodeURIComponent(providerId)}&watch_region=${encodeURIComponent(region)}` +
        `&with_watch_monetization_types=flatrate&sort_by=popularity.desc&page=1`;
      const res = await fetch(src, {
        headers: { "User-Agent": `my-lists-addon/${ADDON_VERSION}` },
        cf: { cacheTtl: 3600, cacheEverything: true },
      });
      if (!res.ok) throw new Error(`TMDB request failed (HTTP ${res.status}).`);
      const data = await res.json();
      const items = (data.results || []).slice(0, 24).map((it) => ({
        id: it.id,
        title: it.title || it.name || "Untitled",
        poster: it.poster_path ? `https://image.tmdb.org/t/p/w300${it.poster_path}` : null,
        date: (it.release_date || it.first_air_date || "").slice(0, 4),
      }));
      return { total: data.total_results || 0, items };
    }

    if (path === "/admin/api/netflix-preview" && request.method === "GET") {
      const authed = await isAdminRequest(request, env);
      if (!authed) return json({ ok: false, error: "Not authorized." }, 401);
      if (!TMDB_API_KEY) return json({ ok: false, error: "TMDB_API_KEY isn't configured on this Worker." });
      // Same normalization TMDB itself expects -- just the two-letter
      // country code, not a locale like "en-US".
      const region = (url.searchParams.get("region") || "US").trim().toUpperCase().slice(0, 2) || "US";
      const providerIdParam = (url.searchParams.get("providerId") || "8").trim();
      const providerId = /^\d+$/.test(providerIdParam) ? providerIdParam : "8";
      try {
        const [movies, shows] = await Promise.all([
          fetchNetflixPreviewTmdb("movie", region, TMDB_API_KEY, providerId),
          fetchNetflixPreviewTmdb("tv", region, TMDB_API_KEY, providerId),
        ]);
        // Always the shared key -- 2 TMDB calls per preview load.
        ctx.waitUntil(bumpStatBy(env, "apiuse:tmdb", 2));
        return json({ ok: true, region, providerId, movies, shows }, 200, { "Cache-Control": "no-store" });
      } catch (err) {
        return json({ ok: false, error: safeErrorMessage(err) });
      }
    }

    // /admin/api/provider-lookup?query=disney&region=US -> { ok, results:
    // [{ id, name }] } -- pulls TMDB's own official watch-provider list
    // (the actual source of truth /admin/api/netflix-preview's providerId
    // gets checked against) so a provider's real numeric id can be
    // confirmed by name before it's wired into anything. Queries both the
    // movie and tv provider lists and merges them, since a given service's
    // presence can differ slightly between the two; de-duplicated by id
    // and, when a region is given, ordered by that region's own
    // display_priority (TMDB's closest thing to "which of these is the
    // one people actually mean" -- relevant since some providers, like
    // Disney Plus, have more than one id and only one is the one that
    // actually turns up in region-filtered discover results).
    if (path === "/admin/api/provider-lookup" && request.method === "GET") {
      const authed = await isAdminRequest(request, env);
      if (!authed) return json({ ok: false, error: "Not authorized." }, 401);
      if (!TMDB_API_KEY) return json({ ok: false, error: "TMDB_API_KEY isn't configured on this Worker." });
      const region = (url.searchParams.get("region") || "US").trim().toUpperCase().slice(0, 2) || "US";
      const query = (url.searchParams.get("query") || "").trim().toLowerCase();
      try {
        const [movieRes, tvRes] = await Promise.all([
          fetch(`https://api.themoviedb.org/3/watch/providers/movie?api_key=${encodeURIComponent(TMDB_API_KEY)}&watch_region=${encodeURIComponent(region)}`, {
            headers: { "User-Agent": `my-lists-addon/${ADDON_VERSION}` },
            cf: { cacheTtl: 86400, cacheEverything: true },
          }),
          fetch(`https://api.themoviedb.org/3/watch/providers/tv?api_key=${encodeURIComponent(TMDB_API_KEY)}&watch_region=${encodeURIComponent(region)}`, {
            headers: { "User-Agent": `my-lists-addon/${ADDON_VERSION}` },
            cf: { cacheTtl: 86400, cacheEverything: true },
          }),
        ]);
        if (!movieRes.ok || !tvRes.ok) throw new Error("TMDB request failed.");
        const [movieData, tvData] = await Promise.all([movieRes.json(), tvRes.json()]);
        ctx.waitUntil(bumpStatBy(env, "apiuse:tmdb", 2));

        const byId = new Map();
        [...(movieData.results || []), ...(tvData.results || [])].forEach((p) => {
          if (byId.has(p.provider_id)) return;
          const priorities = p.display_priorities || {};
          const priority = priorities[region] != null ? priorities[region] : (p.display_priority != null ? p.display_priority : 9999);
          byId.set(p.provider_id, { id: p.provider_id, name: p.provider_name, priority });
        });
        let results = [...byId.values()];
        if (query) results = results.filter((p) => p.name.toLowerCase().includes(query));
        results.sort((a, b) => a.priority - b.priority);
        results = results.slice(0, 40).map((p) => ({ id: p.id, name: p.name }));
        return json({ ok: true, results }, 200, { "Cache-Control": "no-store" });
      } catch (err) {
        return json({ ok: false, error: safeErrorMessage(err) });
      }
    }

    if (path === "/admin/login" && request.method === "POST") {
      if (!env || !env.ADMIN_KEY) {
        return new Response(
          renderAdminLoginPage("This Worker has no ADMIN_KEY secret set -- run `wrangler secret put ADMIN_KEY` (or set it in the Cloudflare dashboard) first."),
          { status: 500, headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store" } }
        );
      }
      // Every other credential-bearing endpoint in this app (creator
      // create/restore/reset-key) rate-limits guesses by IP -- this one
      // never did, despite guarding the one secret that can rotate any
      // creator's key via /admin/api/reset-creator-key with no other
      // verification. Same pattern as /api/creator/restore: a per-IP
      // counter with a 60s window. Skipped entirely (not failed closed)
      // when CONFIGS isn't bound, matching every other KV-optional
      // feature in this app -- login by ADMIN_KEY alone still works.
      // Failed closed when CONFIGS IS bound but CF-Connecting-IP is
      // missing, same as restore, because there is no other safe
      // per-client identity to key a shared bucket on.
      if (env.CONFIGS) {
        const ip = clientIpKey(request);
        if (!ip) {
          return new Response(renderAdminLoginPage("Could not process this request."), {
            status: 400,
            headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store" },
          });
        }
        const rateLimitKey = `ratelimit:adminlogin:${ip}`;
        const attempts = parseInt((await env.CONFIGS.get(rateLimitKey)) || "0", 10);
        if (attempts >= 10) {
          return new Response(renderAdminLoginPage("Too many attempts. Please wait a minute and try again."), {
            status: 429,
            headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store" },
          });
        }
        await env.CONFIGS.put(rateLimitKey, String(attempts + 1), { expirationTtl: 60 });
      }
      let submittedKey = "";
      try {
        const form = await request.formData();
        submittedKey = String(form.get("key") || "");
      } catch {
        // falls through with an empty key, which will fail the compare below
      }
      if (!timingSafeEqualHex(submittedKey, env.ADMIN_KEY)) {
        return new Response(renderAdminLoginPage("Incorrect key."), {
          status: 401,
          headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store" },
        });
      }
      const cookieValue = await makeAdminCookieValue(env);
      return new Response(null, {
        status: 302,
        headers: {
          "Location": "/admin",
          // Path=/ (not /admin) -- this cookie needs to ride along on
          // fetch() calls the admin dashboard makes to endpoints outside
          // /admin too, e.g. /api/feedback for "Log something yourself"
          // (see isAdminRequest's call there). A browser withholds a
          // cookie entirely from any request whose path doesn't fall
          // under Path, silently, with no error surfaced anywhere --
          // isAdminRequest just always saw no cookie and treated every
          // one of those requests as anonymous, which is what made the
          // public rate limit apply to admin submissions too.
          "Set-Cookie": `${ADMIN_COOKIE_NAME}=${cookieValue}; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=${Math.floor(ADMIN_SESSION_MS / 1000)}`,
        },
      });
    }

    if (path === "/admin/logout") {
      return new Response(null, {
        status: 302,
        headers: {
          "Location": "/admin",
          // Path must match the cookie's own Path exactly for this to
          // actually clear it -- a Set-Cookie with a different Path is
          // treated as a distinct cookie, not an overwrite of the
          // original.
          "Set-Cookie": `${ADMIN_COOKIE_NAME}=; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=0`,
        },
      });
    }

    // /api/bulk-resolve
    // Resolves an array of {title, year} objects to TMDB/IMDB IDs
    // Used by the Letterboxd CSV import
    if (path === "/api/bulk-resolve" && request.method === "POST") {
      // Parsed separately from the work below so a malformed body returns
      // the same 400 + generic message every other route uses, instead of
      // falling into the catch and echoing the raw SyntaxError (which
      // included the caller's own payload) back at HTTP 500.
      let bulkBody;
      try {
        bulkBody = await request.json();
      } catch {
        return json({ ok: false, error: "Invalid JSON body." }, 400);
      }
      if (!bulkBody || !Array.isArray(bulkBody.items)) {
        return json({ ok: false, error: "Expected an `items` array." }, 400);
      }
      // Unauthenticated, and unlike every other TMDB route here this one
      // has no per-user key override at all -- it ALWAYS spends the Worker
      // owner's shared TMDB_API_KEY (see the comment on tmdbCallCount
      // below). Two things were missing:
      //
      // 1. A bound on `items`. The loop below issues up to two TMDB calls
      //    per item, so a single request with a few thousand items blew
      //    straight past Cloudflare's per-invocation subrequest limit --
      //    which meant large Letterboxd imports were already failing here
      //    -- while spending the owner's TMDB quota on the way.
      // 2. A rate limit, so the same request cannot simply be repeated.
      //
      // The cap rejects rather than truncates: silently resolving the
      // first N films of an import and dropping the rest is exactly the
      // kind of quiet data loss this audit was about. The client chunks
      // its own requests to this size (see resolveViaBulkResolve,
      // 18_client-copy-and-trakt-export.js), so a real import of any size
      // still completes -- it just arrives as several bounded calls.
      const bulkIp = clientIpKey(request);
      if (!bulkIp) return json({ ok: false, error: "Could not resolve those titles." }, 400);
      if (bulkBody.items.length > BULK_RESOLVE_ITEMS_MAX) {
        return json({ ok: false, error: `Too many titles in one request (limit ${BULK_RESOLVE_ITEMS_MAX}).` }, 413);
      }
      if (await consumeRateLimit(env, ctx, "bulkresolve", bulkIp, 20)) {
        return json({ ok: false, error: "Too many lookups just now. Please wait a minute and try again." }, 429);
      }
      try {
        const body = bulkBody;
        const items = body.items || [];
        const resolved = [];
        // Always the shared TMDB_API_KEY -- no per-user override on this
        // endpoint. Counted precisely (not just items.length) since a
        // search miss skips the second (external-ids) call.
        let tmdbCallCount = 0;
        // Process in small batches (e.g., 10 at a time) to stay within subrequest limits
        const BATCH_SIZE = 10;
        for (let i = 0; i < items.length; i += BATCH_SIZE) {
          const batch = items.slice(i, i + BATCH_SIZE);
          const promises = batch.map(async (item) => {
            const q = (item.title || "").trim();
            const y = item.year ? parseInt(item.year, 10) : null;
            if (!q) return null;
            
            // Step 1: Search TMDB
            const searchSrc = `https://api.themoviedb.org/3/search/movie?api_key=${encodeURIComponent(TMDB_API_KEY)}&query=${encodeURIComponent(q)}&include_adult=false${y ? '&primary_release_year=' + y : ''}`;
            tmdbCallCount++;
            const searchRes = await fetch(searchSrc, {
              headers: { "User-Agent": `my-lists-addon/${ADDON_VERSION}` },
              cf: { cacheTtl: 86400, cacheEverything: true },
            });
            if (!searchRes.ok) return null;
            const searchData = await searchRes.json();
            const match = (searchData.results || [])[0];
            if (!match) return null;
            
            // Step 2: Get External IDs to find IMDB id
            const extSrc = `https://api.themoviedb.org/3/movie/${match.id}/external_ids?api_key=${encodeURIComponent(TMDB_API_KEY)}`;
            tmdbCallCount++;
            const extRes = await fetch(extSrc, {
              headers: { "User-Agent": `my-lists-addon/${ADDON_VERSION}` },
              cf: { cacheTtl: 86400, cacheEverything: true },
            });
            if (!extRes.ok) return null;
            const extData = await extRes.json();
            
            if (extData.imdb_id) {
              return {
                title: match.title || match.original_title || item.title,
                year: match.release_date ? match.release_date.substring(0, 4) : item.year,
                imdbId: extData.imdb_id,
              };
            }
            return null;
          });
          
          const results = await Promise.all(promises);
          for (const res of results) {
            if (res) resolved.push(res);
          }
        }
        if (tmdbCallCount) ctx.waitUntil(bumpStatBy(env, "apiuse:tmdb", tmdbCallCount));
        return json({ ok: true, resolved });
      } catch (e) {
        // Logged, not returned -- the message can carry upstream URLs and
        // internal detail that the caller has no business seeing.
        console.error("bulk-resolve failed:", e);
        return json({ ok: false, error: "Could not resolve those titles." }, 500);
      }
    }

    return new Response("Not found", { status: 404 });
}

// The actual Worker export. Delegates to handleFetch (25_api-catalog-
// routes.js) for everything, then runs the response back through
// withSecurityHeaders (02_http-and-creator-utils.js) before it goes out --
// see handleFetch's own opening comment for why it's split this way.
export default {
  async fetch(request, env, ctx) {
    const response = await handleFetch(request, env, ctx);
    return withSecurityHeaders(response);
  },

  // Runs on whatever schedule this Worker's owner configured under
  // Triggers -> Cron Triggers in the Cloudflare dashboard (recommended:
  // every 6 minutes with "*/6 * * * *") -- refreshes and pre-warms shared
  // Trakt, TMDB, Simkl, and MDBList charts into KV storage and sweeps newly-aired episodes for Continue Watching.
  async scheduled(event, env, ctx) {
    ctx.waitUntil(
      Promise.all([
        checkForNewEpisodes(env),
        prewarmSharedCatalogs(env, ctx),
        // Cheap when index:publiclists already exists (one KV get, no-op).
        // When it doesn't -- a fresh deployment, or the index key lost
        // some other way -- this is what keeps a self-hoster who never
        // visits /admin from serving every visitor a truncated,
        // lexicographically-biased directory/search result indefinitely,
        // instead of relying on whichever live request happens to hit the
        // cold index first.
        //
        // One bounded chunk per tick, not a whole rebuild (see
        // rebuildPublicListIndex): a small deployment is done on the first
        // tick, a large one converges over the following few hours. That is
        // the point -- the previous single-pass version simply threw and
        // rebuilt nothing at all once there were more than ~500 lists.
        // /admin/api/rebuild-public-index drives the same chunks back to
        // back for an immediate seed right after a fresh deploy.
        getPublicListIndex(env, ctx),
      ])
    );
  },
};
